#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ADS1115 I2C address when ADDR pin is tied to GND */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config register bits (16-bit, big-endian on the wire):
 *   Bit 15: OS      = 1 (begin single conversion)
 *   Bits 14:12 MUX   = 100 (AIN0 single-ended)
 *   Bits 11:9  PGA    = 001 (+/-4.096V)
 *   Bit  8:   MODE   = 1 (single-shot)
 *   Bits 7:5  DR     = 100 (128 SPS)
 *   Bit  4:   COMP_MODE = 0
 *   Bit  3:   COMP_POL  = 0
 *   Bit  2:   COMP_LAT  = 0
 *   Bits 1:0  COMP_QUE = 11 (disable comparator)
 */
#define ADS1115_CONFIG_BASE 0x8483

/* MLX91219 sensitivity: 40 mV/A */
#define MLX91219_SENSITIVITY 0.040f

/* ADS1115 PGA full-scale range: +/-4.096V */
#define ADS1115_PGA_FULL_SCALE 4.096f

/* ADS1115 16-bit signed ADC full-scale: 32767 */
#define ADS1115_ADC_FULL_SCALE 32767.0f

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends the register address followed by the data
 * bytes in the order specified by the ADS1115 (big-endian on the wire).
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteI2CBlockData(handle, reg, buf, 2);
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData returns the number of bytes read,
 * and stores the data in the provided buffer.
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (bytes_read != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion on AIN0 and read the result.
 * Returns 0 on success, -1 on I2C error.
 */
static int ads1115_read_ain0(int handle, float *voltage) {
    uint16_t config = ADS1115_CONFIG_BASE;
    uint16_t raw;

    /* Write config to start a single conversion */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }

    /* Wait for conversion to complete (128 SPS -> ~7.8ms, use 10ms for safety) */
    gpioDelay(10000);

    /* Read conversion result */
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) < 0) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion register.\n");
        return -1;
    }

    /* Convert raw 16-bit signed value to voltage */
    int16_t signed_raw = (int16_t)raw;
    *voltage = (signed_raw * ADS1115_PGA_FULL_SCALE) / ADS1115_ADC_FULL_SCALE;

    return 0;
}

/*
 * Convert voltage to current using MLX91219 formula.
 * Assumes the sensor is connected to AIN0 and the supply voltage is 5V.
 */
static float voltage_to_current(float voltage) {
    /* MLX91219 zero-current output is mid-supply (2.5V) */
    float zero_current_voltage = 2.5f;
    return (voltage - zero_current_voltage) / MLX91219_SENSITIVITY;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C bus 1 at ADS1115 address */
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X.\n", ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    printf("MLX91219 Current Sensor Reader\n");
    printf("ADS1115 at I2C address 0x%02X, AIN0 connected to MLX91219 output.\n", ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (1) {
        float voltage;

        if (ads1115_read_ain0(i2c_handle, &voltage) == 0) {
            float current = voltage_to_current(voltage);
            printf("Voltage: %.3f V, Current: %.3f A\n", voltage, current);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Check wiring and sensor presence.\n");
        }

        /* Wait 500ms between readings */
        gpioDelay(500000);
    }

    /* Cleanup (unreachable due to infinite loop, but kept for completeness) */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

