#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000  // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200  // ±4.096V
#define ADS1115_CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003  // Disable comparator
#define TEMP_THRESHOLD 60.0f
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000
#define ADC_MAX_VALUE 32767.0f
#define ADC_VREF 4.096f
#define ADC_V_PER_C 0.01f
#define ADC_C_OFFSET 20.0f

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event = 0;
static volatile uint32_t last_flame_tick = 0;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 0) {  // Falling edge = flame detected
        uint32_t elapsed = tick - last_flame_tick;
        if (elapsed >= (uint32_t)(DEBOUNCE_MS * 1000)) {
            flame_event = 1;
            last_flame_tick = tick;
        }
    }
}

static int read_ads1115(int handle, float *temperature) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) >> 8;
    config[2] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE) & 0xFF;

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config\n");
        return -1;
    }

    // Wait for conversion (~8.5ms for 128 SPS)
    gpioDelay(10000);

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register\n");
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion\n");
        return -1;
    }

    int16_t raw = (buf[0] << 8) | buf[1];
    float voltage = (raw / ADC_MAX_VALUE) * ADC_VREF;
    *temperature = ADC_C_OFFSET + (voltage / ADC_V_PER_C);
    return 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open fire_log.txt for appending\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for flame sensor\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame = (gpioRead(FLAME_SENSOR_GPIO) == 0);
        float temperature = 0.0f;
        int temp_ok = (read_ads1115(i2c_handle, &temperature) == 0);

        if (flame && temp_ok && temperature > TEMP_THRESHOLD) {
            log_event("Fire detected!");
            gpioWrite(BUZZER_GPIO, 1);
            gpioDelay(BUZZER_DURATION_US);
            gpioWrite(BUZZER_GPIO, 0);
        } else if (flame) {
            log_event("Flame detected!");
        } else if (temp_ok && temperature > TEMP_THRESHOLD) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temperature);
            log_event(msg);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

