#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Calibration parameters (example values, needs calibration)
#define CO_MIN_RAW 1000
#define CO_MAX_RAW 3000
#define CO_MIN_PPM 400.0
#define CO_MAX_PPM 1000.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *raw_co);
double convert_to_ppm(int raw_co);
int log_data(double ppm_co);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the ADC (simulated for this example)
int read_sensor_data(int *raw_co) {
    // Simulate reading from an ADS1115 ADC via I2C
    // In a real implementation, this would read the 16-bit ADC value from the ADC
    // For this example, we read a random value between CO_MIN_RAW and CO_MAX_RAW
    *raw_co = (rand() % (CO_MAX_RAW - CO_MIN_RAW + 1)) + CO_MIN_RAW;
    return 0;
}

// Convert raw sensor data to PPM using a logarithmic curve
double convert_to_ppm(int raw_co) {
    // Logarithmic conversion: PPM = A * log(raw) + B
    // Example parameters: A = 100, B = 500
    double A = 100.0;
    double B = 500.0;
    double ppm = A * log10((double)raw_co) + B;
    // Clamp PPM to valid range
    if (ppm < CO_MIN_PPM) ppm = CO_MIN_PPM;
    if (ppm > CO_MAX_PPM) ppm = CO_MAX_PPM;
    return ppm;
}

// Log data to file
int log_data(double ppm_co) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f PPM\n", timestamp, ppm_co);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Seed random number generator
    srand(time(NULL));

    // Main loop
    while (!terminate) {
        int raw_co;
        if (read_sensor_data(&raw_co) == 0) {
            double ppm_co = convert_to_ppm(raw_co);
            if (log_data(ppm_co) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();
    return 0;
}

