#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel for flame sensor
#define FLAME_SENSOR_CHANNEL 0

// Define temperature range
#define TEMP_MIN 10.0
#define TEMP_MAX 40.0

// Define ADC range (10-bit)
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor(void);
int read_adc(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup(void);

// Function to read the flame sensor
int read_flame_sensor(void) {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature
float convert_adc_to_temperature(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range (%d)\n", adc_value);
        return -1.0;
    }

    return TEMP_MIN + ((float)(adc_value - ADC_MIN) / (ADC_MAX - ADC_MIN)) * (TEMP_MAX - TEMP_MIN);
}

// Function to log data to a CSV file
int log_data(int flame_detected, float temperature) {
    FILE *fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open flame_data.csv for writing\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: Could not get local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fclose(fp);
