#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x68
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *ox, int *red);
float calculate_co_ppm(int ox, int red);
void log_co_level(float co_ppm);
void check_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
int read_sensor_data(int *ox, int *red) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // MICS-4514 outputs 16-bit ADC values
    *ox = (buf[0] << 8) | buf[1];
    *red = (buf[2] << 8) | buf[3];

    return 0;
}

// Calculate CO level in PPM from sensor readings
float calculate_co_ppm(int ox, int red) {
    // Placeholder linear calibration (requires sensor calibration)
    // In a real application, this would be calibrated against known CO concentrations
    // and environmental conditions.
    float co_ppm = (float)ox * 0.1 + (float)red * 0.05;
    return co_ppm;
}

// Log CO level to file
void log_co_level(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
}

// Check if CO level exceeds threshold and log alert
void check_alert(float co_ppm) {
    if (co_ppm > CO_THRESHOLD) {
        FILE *fp = fopen(ALERT_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening alert log file: %s\n", ALERT_LOG_FILE);
            return;
        }

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(fp, "%s, ALERT: CO level %.2f PPM exceeds threshold %.2f PPM\n", timestamp, co_ppm, CO_THRESHOLD);
        fclose(fp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int ox, red;
        if (read_sensor_data(&ox, &red) == 0) {
            float co_ppm = calculate_co_ppm(ox, red);
            log_co_level(co_ppm);
            check_alert(co_ppm);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying in %d seconds...\n", READ_INTERVAL_SEC);
        }

        // Sleep for 5 seconds, checking terminate flag periodically
        for (int i = 0; i < READ_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    // Cleanup
    cleanup();
    return 0;
}

