#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define MIC_REG 0x00
#define SAMPLE_INTERVAL_US 100000 // 100ms
#define SENSITIVITY_DBV_PER_PA -38.0
#define REFERENCE_PRESSURE 20e-6
#define ERROR_VALUE -999.0

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_mic_data(int handle);
double calculate_sound_pressure_level(int raw_data);
void log_data(double pressure1, double pressure2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    gpioTerminate();
}

// Initializes the I2C interface for a specific microphone
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Reads raw data from the microphone via I2C
int read_mic_data(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, MIC_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (int16_t)((buf[0] << 8) | buf[1]);
    return (int)raw_data;
}

// Calculates the sound pressure level in dB from the raw data
double calculate_sound_pressure_level(int raw_data) {
    if (raw_data == -1) {
        return ERROR_VALUE;
    }
    double voltage = (double)raw_data * 3.3 / 32768.0; // Assuming 16-bit ADC, Vref = 3.3V
    double pressure = pow(10.0, (voltage - 0.5) / 0.005); // Assuming linear relationship
    double sound_pressure_level = 20.0 * log10(pressure / REFERENCE_PRESSURE);
    return sound_pressure_level;
}

// Logs the timestamped sound pressure levels to a file
void log_data(double pressure1, double pressure2) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f, %.2f\n", timestamp, pressure1, pressure2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C for both microphones
    i2c_handle1 = initialize_i2c(I2C_BUS, MIC1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, MIC2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw data from both microphones
        int raw_data1 = read_mic_data(i2c_handle1);
        int raw_data2 = read_mic_data(i2c_handle2);

        // Calculate sound pressure levels
        double pressure1 = calculate_sound_pressure_level(raw_data1);
        double pressure2 = calculate_sound_pressure_level(raw_data2);

        // Log the data
        log_data(pressure1, pressure2);

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

