#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 0.7
#define SAMPLE_WINDOW_MS 100
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * 1000) // 1000 samples per ms
#define ADC_MAX_VALUE 1023.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
double calculate_rms(int *samples, int num_samples);
void control_led(int state);
void log_data(double rms1, double rms2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    control_led(0); // Turn off LED
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008 channel (0-7)
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    tx_buf[0] = 0x01;
    tx_buf[1] = (0x80 | (channel << 4));
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    // rx_buf[1] contains the two most significant bits
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double normalized = (double)samples[i] / ADC_MAX_VALUE;
        sum_of_squares += normalized * normalized;
    }
    return sqrt(sum_of_squares / num_samples);
}

