    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    control_led(0); // Ensure LED is off initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int mic1_samples[NUM_SAMPLES];
        int mic2_samples[NUM_SAMPLES];

        // Sample audio data
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_adc(0); // Mic 1 on ADC channel 0
            mic2_samples[i] = read_adc(1); // Mic 2 on ADC channel 1

            if (mic1_samples[i] < 0 || mic2_samples[i] < 0) {
                fprintf(stderr, "Error reading ADC values at sample %d\n", i);
                cleanup();
                return 1;
            }

            gpioDelay(1000); // Delay for 1 ms (pigpio uses microseconds)
        }

        // Calculate RMS values
        double rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
        double rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Log data
        log_data(rms1, rms2);

        // Check threshold and control LED
        if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500000); // Keep LED on for 500 ms
            control_led(0); // Turn off LED
        }
    }

    // Cleanup and exit
    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

