#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define OVERCURRENT_THRESHOLD 50.0 // Amps
#define SAMPLE_INTERVAL_US 100000 // 100ms
#define ADC_RESOLUTION 4096.0
#define ADC_VREF 4.096
#define SENSOR_VOUT_MIN 0.5
#define SENSOR_VOUT_MAX 4.5
#define SENSOR_CURRENT_MIN 0.0
#define SENSOR_CURRENT_MAX 100.0

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: Single-shot, AIN0, +/-4.096V, 128 SPS, Disable comparator
#define ADS1115_CONFIG_BASE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_COMP_DISABLE 0x0003

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void check_overcurrent(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication with ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115 channel A0
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char reg;
    char data[2];
    int result;

    // Write config register to start conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_DISABLE) >> 8;
    config[2] = (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_DISABLE) & 0xFF;

    result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing config to ADS1115: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion register
    reg = ADS1115_REG_CONVERSION;
    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error selecting conversion register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading conversion data: %d\n", result);
        return -1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to current (Amps)
float convert_to_current(int16_t raw_value) {
    float voltage = (raw_value / ADC_RESOLUTION) * ADC_VREF;
    float current = (voltage - SENSOR_VOUT_MIN) * (SENSOR_CURRENT_MAX - SENSOR_CURRENT_MIN) / (SENSOR_VOUT_MAX - SENSOR_VOUT_MIN) + SENSOR_CURRENT_MIN;
    return current;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Check if the average current exceeds the overcurrent threshold
void check_overcurrent(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
        printf("Overcurrent detected! Average current: %.2f A\n", average_current);
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize circular buffer
    current_buffer.head = 0;
    current_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int16_t raw_value;
        float current;

        // Read sensor data
        if (read_ads1115(&raw_value) == 0) {
            current = convert_to_current(raw_value);

            // Add current reading to buffer
            add_to_buffer(&current_buffer, current);

            // Calculate average current
            float average_current = calculate_average(&current_buffer);

            // Check for overcurrent
            check_overcurrent(average_current);

            // Print current reading
            printf("Current: %.2f A\n", current);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100000); // Wait before retrying
            continue;
        }

        // Delay for sample interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

