#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TCS34725 I2C address (ADDR pin tied to GND) */
#define TCS34725_ADDR 0x29

/* TCS34725 registers */
#define TCS34725_ENABLE  0x00
#define TCS34725_ATIME   0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

/* Expected ID for TCS34725 (lower 4 bits) */
#define TCS34725_ID_VALUE 0x44

/* Configuration */
#define I2C_BUS        1
#define LOG_FILE       "color_log.csv"
#define SAMPLE_PERIOD  1.0          /* seconds */
#define MAX_CONSEC_ERR 3

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe subset only                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register                               */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register                              */
/* Returns 0 on success and stores value in *out, -1 on error          */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair (low byte at reg, high at reg+1)*/
/* Returns 0 on success and stores value in *out, -1 on error          */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    /* pigpio returns word as (high << 8) | low, which matches TCS34725 */
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725 sensor                                      */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int handle)
{
    uint8_t id = 0;

    /* Verify sensor identity */
    if (tcs34725_read_reg(handle, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "[ERROR] Cannot read TCS34725 ID register.\n");
        return -1;
    }
    if ((id & 0x0F) != TCS34725_ID_VALUE) {
        fprintf(stderr, "[ERROR] TCS34725 ID mismatch: got 0x%02X, expected 0x%02X.\n",
                id & 0x0F, TCS34725_ID_VALUE);
        return -1;
    }
    printf("[INFO] TCS34725 detected (ID=0x%02X).\n", id & 0x0F);

    /* Power on (PON=1) and enable ADC (AEN=1) */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, 0x01 | 0x02) < 0)
        return -1;

    /* Integration time: 0xFF = 2.4 ms (max for 256-cycle mode) */
    if (tcs34725_write_reg(handle, TCS34725_ATIME, 0xFF) < 0)
        return -1;

    /* Gain: 0x01 = 4x */
    if (tcs34725_write_reg(handle, TCS34725_CONTROL, 0x01) < 0)
        return -1;

    /* Wait for first integration cycle to complete (2.4 ms + margin) */
    gpioDelay(3000); /* microseconds */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four color channels from the TCS34725                      */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int tcs34725_read_all(int handle, uint16_t *clear, uint16_t *red,
                            uint16_t *green, uint16_t *blue)
{
    if (tcs34725_read_reg16(handle, TCS34725_CDATA, clear) < 0)
        return -1;
    if (tcs34725_read_reg16(handle, TCS34725_RDATA, red)   < 0)
        return -1;
    if (tcs34725_read_reg16(handle, TCS34725_GDATA, green) < 0)
        return -1;
    if (tcs34725_read_reg16(handle, TCS34725_BDATA, blue)  < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped color row to the CSV file                      */
/* Returns 0 on success, -1 on error                                   */
/* ------------------------------------------------------------------ */
static int log_color_data(FILE *fp, uint16_t clear, uint16_t red,
                          uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "[ERROR] strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush failed on log file.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, TCS34725_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] TCS34725 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append mode); write header if file is empty */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,clear,red,green,blue\n") < 0) {
            fprintf(stderr, "[FATAL] Cannot write CSV header.\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; will not respond to Ctrl+C.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed.\n");
    }

    printf("[INFO] Logging color data to '%s' every %.1f s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* Main sampling loop */
    while (g_running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_all(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            if (log_color_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "[ERROR] Failed to log color data.\n");
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "[WARN] Color read failed (%d consecutive).\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "[FATAL] %d consecutive I2C failures — aborting.\n",
                        consecutive_errors);
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

