#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    motor_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(motor_line, "motor_shutdown", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        motor_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", retry + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }

    fprintf(stderr, "SPI transfer failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static float adc_to_current(int adc_value) {
    float voltage = (float)adc_value * 3.3f / 1023.0f;
    return (voltage - OFFSET) / SENSITIVITY;
}

static int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected! Current: %.3f A\n", current);
        if (gpiod_line_set_value(motor_line, 0) < 0) {
            fprintf(stderr, "Failed to set motor shutdown pin LOW: %s\n", strerror(errno));
        } else {
            printf("Motor shutdown pin set LOW\n");
        }

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log overcurrent event\n");
        }

        sleep(1);

        if (gpiod_line_set_value(motor_line, 1) < 0) {
            fprintf(stderr, "Failed to set motor shutdown pin HIGH: %s\n", strerror(errno));
        } else {
            printf("Motor shutdown pin set HIGH\n");
        }
    }
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        if (fprintf(log_fp, "Timestamp,Current (A)\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_fp);
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        printf("Current: %.3f A\n", current);

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current reading\n");
        }

        check_overcurrent(current);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

