    float voltage = (float)adc_value * 3.3f / 1023.0f;
    return (voltage - OFFSET) / SENSITIVITY;
}

static int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_fp, "%s,%.3f\n", timestamp, current) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected! Current: %.3f A\n", current);
        if (gpiod_line_set_value(motor_line, 0) < 0) {
            fprintf(stderr, "Failed to set motor shutdown pin LOW: %s\n", strerror(errno));
        } else {
            printf("Motor shutdown pin set LOW\n");
        }

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log overcurrent event\n");
        }

        sleep(1);

        if (gpiod_line_set_value(motor_line, 1) < 0) {
            fprintf(stderr, "Failed to set motor shutdown pin HIGH: %s\n", strerror(errno));
        } else {
            printf("Motor shutdown pin set HIGH\n");
        }
    }
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        if (fprintf(log_fp, "Timestamp,Current (A)\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_fp);
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        printf("Current: %.3f A\n", current);

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current reading\n");
        }

        check_overcurrent(current);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

