#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        1
#define MLX90817_ADDR  0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit pressure from the MLX90817                              */
/* Returns 0 on success (raw_out set), -1 on I2C error                 */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, uint16_t *raw_out)
{
    int rc;

    rc = i2cReadWordData(handle, PRESSURE_REG);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n",
                PRESSURE_REG, rc);
        return -1;
    }

    /* pigpio returns the word as (msb << 8) | lsb, which matches the
     * MLX90817 16-bit big-endian register layout. */
    *raw_out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit ADC value to kPa                                 */
/* ------------------------------------------------------------------ */
static float raw_to_kpa(uint16_t raw)
{
    return ((float)raw / 65535.0f) * 500.0f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log                         */
/* ------------------------------------------------------------------ */
static int log_pressure(FILE *fp, float pressure_kPa)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "[ERROR] gmtime_r() failed\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int  rc;
    int  consecutive_failures = 0;
    const int max_consecutive_failures = 10;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed: %d\n", rc);
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MLX90817_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file once (header) ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "[ERROR] Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    printf("[INFO] Logging MLX90817 pressure to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t raw;
        float    pressure_kPa;

        if (read_pressure(g_i2c_handle, &raw) == 0) {
            consecutive_failures = 0;
            pressure_kPa = raw_to_kpa(raw);

            if (log_pressure(g_log_file, pressure_kPa) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            } else {
                printf("[%s] Pressure: %.2f kPa\n",
                       "now", pressure_kPa);
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "[WARN] Read failure #%d/%d\n",
                    consecutive_failures, max_consecutive_failures);

            if (consecutive_failures >= max_consecutive_failures) {
                fprintf(stderr, "[ERROR] %d consecutive I2C failures — "
                                "sensor may be absent or bus stuck. Exiting.\n",
                        consecutive_failures);
                break;
            }
        }

        /* Sleep 1 second, but wake early on signal */
        gpioDelay(SAMPLE_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

