#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0 // kPa
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: AIN0 single-ended, gain 2/3, 128 SPS, continuous
#define ADS1115_CONFIG_BASE 0x4000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_2_3 0x0200
#define ADS1115_CONFIG_MODE_CONT 0x0000
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_OS_BEGIN 0x8000

// Calibration constants (example values, adjust based on sensor datasheet)
#define PRESSURE_MIN_VOLTAGE 0.0
#define PRESSURE_MAX_VOLTAGE 5.0
#define PRESSURE_MIN_KPA 0.0
#define PRESSURE_MAX_KPA 400.0
#define TEMP_MIN_VOLTAGE 1.0
#define TEMP_MAX_VOLTAGE 2.0
#define TEMP_MIN_C 0.0
#define TEMP_MAX_C 100.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_ads1115_channel(int channel);
float convert_to_pressure(int adc_value);
float convert_to_temperature(int adc_value);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read a single-ended channel from the ADS1115
int read_ads1115_channel(int channel) {
    if (channel < 0 || channel > 3) {
        fprintf(stderr, "Invalid ADS1115 channel: %d\n", channel);
        return -1;
    }

    // Configure ADS1115 for single-shot conversion on the specified channel
    uint16_t mux_config = (channel == 0) ? ADS1115_CONFIG_MUX_AIN0 : (channel == 1) ? ADS1115_CONFIG_MUX_AIN1 : (channel == 2) ? ADS1115_CONFIG_MUX_AIN2 : ADS1115_CONFIG_MUX_AIN3;
    uint16_t config = ADS1115_CONFIG_BASE | mux_config | ADS1115_CONFIG_PGA_2_3 | ADS1115_CONFIG_MODE_CONT | ADS1115_CONFIG_DR_128 | ADS1115_CONFIG_CQUE_NONE | ADS1115_CONFIG_OS_BEGIN;

    // Write config to ADS1115
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion result
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error setting ADS1115 conversion register pointer\n");
        return -1;
    }

    char data_buf[2];
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion result\n");
        return -1;
    }

    // Convert to signed 16-bit integer
    int16_t raw = (data_buf[0] << 8) | data_buf[1];
    return (int)raw;
}

// Convert ADC value to pressure (kPa)
float convert_to_pressure(int adc_value) {
    float voltage = (float)adc_value * 6.144 / 32768.0; // 2/3 gain, 16-bit signed
    float pressure = (voltage - PRESSURE_MIN_VOLTAGE) * (PRESSURE_MAX_KPA - PRESSURE_MIN_KPA) / (PRESSURE_MAX_VOLTAGE - PRESSURE_MIN_VOLTAGE) + PRESSURE_MIN_KPA;
    return pressure;
}

// Convert ADC value to temperature (°C)
float convert_to_temperature(int adc_value) {
    float voltage = (float)adc_value * 6.144 / 32768.0; // 2/3 gain, 16-bit signed
    float temperature = (voltage - TEMP_MIN_VOLTAGE) * (TEMP_MAX_C - TEMP_MIN_C) / (TEMP_MAX_VOLTAGE - TEMP_MIN_VOLTAGE) + TEMP_MIN_C;
    return temperature;
}

// Control the warning LED based on pressure threshold
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int pressure_adc_value = -1;
        int temperature_adc_value = -1;
        int retries = 0;

        // Read pressure ADC value with retries
        while (pressure_adc_value == -1 && retries < MAX_RETRIES) {
            pressure_adc_value = read_ads1115_channel(0);
            if (pressure_adc_value == -1) {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000); // Wait 100ms before retry
                }
            }
        }

        // Read temperature ADC value with retries
        retries = 0;
        while (temperature_adc_value == -1 && retries < MAX_RETRIES) {
            temperature_adc_value = read_ads1115_channel(1);
            if (temperature_adc_value == -1) {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000); // Wait 100ms before retry
                }
            }
        }

        if (pressure_adc_value != -1 && temperature_adc_value != -1) {
            // Convert ADC values to pressure and temperature
            float pressure = convert_to_pressure(pressure_adc_value);
            float temperature = convert_to_temperature(temperature_adc_value);

            // Display pressure and temperature
            printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

            // Control LED based on pressure threshold
            control_led(pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        // Wait for 1 second
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Pressure monitoring stopped.\n");

    return 0;
}

