#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ALARM_GPIO 4
#define CO_THRESHOLD_VOLTAGE 2.5
#define VREF 3.3
#define ADC_MAX 1023.0
#define LOG_FILE "co_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed: returned %d\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / ADC_MAX) * VREF;
}

static void control_alarm(int state) {
    if (gpioWrite(ALARM_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write alarm GPIO %d\n", ALARM_GPIO);
    }
}

static void log_data(float voltage) {
