#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* Mode 0, active-low CE */
#define ADC_CHANNEL    0        /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023     /* 10-bit ADC */
#define PPM_MAX        5000.0f  /* Sensor full-scale PPM */
#define LEAK_THRESHOLD 1000.0f  /* PPM */
#define LOG_FILE       "methane_log.txt"
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7) via SPI                      */
/* Returns 0-1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI command (3 bytes):
     *   tx[0] = 0x01                 Start bit
     *   tx[1] = (0x08 | channel) << 4 Single-ended + channel select
     *   tx[2] = 0x00                 Dummy for clocking data out
     *
     * Response (3 bytes):
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower 2 bits
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to PPM                                            */
/* ------------------------------------------------------------------ */
static float adc_to_ppm(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX) * PPM_MAX;
}

/* ------------------------------------------------------------------ */
/* Log a reading with ISO-8601 timestamp                               */
/* ------------------------------------------------------------------ */
static void log_reading(float ppm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Methane monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error already reported; skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        float ppm = adc_to_ppm(adc_value);
        log_reading(ppm);

        if (ppm > LEAK_THRESHOLD) {
            fprintf(stderr, "*** LEAK DETECTED: %.2f PPM ***\n", ppm);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

