#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define PRESSURE_OFFSET 0.5f
#define PRESSURE_SENSITIVITY 0.1f
#define MIN_PRESSURE 0.0f
#define MAX_PRESSURE 100.0f
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(void);
int read_ads1115(int16_t *raw_value);
float convert_to_pressure(int16_t raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char conversion[2];
    int16_t config_word;

    // Configure ADS1115 for single-shot conversion on AIN0
    config_word = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (config_word >> 8) & 0xFF;
    config[2] = config_word & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register\n");
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion result
    if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_CONVERSION, conversion, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register\n");
        return -1;
    }

    *raw_value = (int16_t)((conversion[0] << 8) | conversion[1]);
    return 0;
}

// Convert raw ADC value to pressure (kPa)
float convert_to_pressure(int16_t raw_value) {
    // ADS1115 PGA = +/-4.096V, 16-bit signed, 1 bit = 125uV
    // Sensor output: 0.5V at 0 kPa, 0.1 V/kPa sensitivity
    float voltage = (raw_value * 4.096f) / 32768.0f;
    float pressure = (voltage - PRESSURE_OFFSET) / PRESSURE_SENSITIVITY;
    return pressure;
}

// Log pressure reading with timestamp
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        float pressure;

        if (read_ads1115(&raw_value) == 0) {
            pressure = convert_to_pressure(raw_value);

            if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure reading\n");
                }
            } else {
                fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading from ADS1115\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("\nPressure monitoring stopped.\n");
    cleanup();
    return 0;
}

