#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define ADC_CHANNEL_HUMIDITY 0
#define ADC_CHANNEL_THERMISTOR 1
#define ADC_RESOLUTION 4095.0
#define SUPPLY_VOLTAGE 5.0
#define BETA 3950.0
#define R0 10000.0 // 10kΩ at 25°C

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void send_email_alert(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read from MCP3208 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3208 SPI command format: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 12-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x0F) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate relative humidity from ADC value
float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / ADC_RESOLUTION * SUPPLY_VOLTAGE;
    float humidity = (voltage - 0.824) / 0.0315;

    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return humidity;
}

// Function to calculate temperature from ADC value using Beta parameter equation
float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / ADC_RESOLUTION * SUPPLY_VOLTAGE;
    float resistance = (SUPPLY_VOLTAGE / voltage - 1.0) * R0;
    float temperature = (BETA / (log(resistance / R0))) - 273.15;
    return temperature;
}

// Function to send email alert using ssmtp
void send_email_alert(float humidity) {
    char command[256];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity exceeds threshold: %.2f%%\" | ssmtp recipient@example.com",
             humidity);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Failed to send email alert: %d\n", result);
    }
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values
        int adc_humidity = read_adc(ADC_CHANNEL_HUMIDITY);
        int adc_thermistor = read_adc(ADC_CHANNEL_THERMISTOR);

        if (adc_humidity < 0 || adc_thermistor < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            sleep(1);
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_humidity);
        float temperature = calculate_temperature(adc_thermistor);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        // Print data to console
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5); // Wait 5 seconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Humidity monitoring stopped.\n");
    return 0;
}

