    uint8_t tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx_buf[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    // Assert CS (active low)
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1); // Deassert CS on error
        return -1;
    }

    // Deassert CS
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    // Extract 12-bit ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0f) * VREF;
}

// Convert voltage to temperature (Celsius) using TMP36 formula
float voltage_to_temperature(float voltage) {
    return (voltage - 0.5f) / 0.01f;
}

// Log temperature to CSV file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main(void) {
    // Initialize libgpiod for manual CS control
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8); // GPIO8 is SPI0 CE0
    if (cs_line == NULL) {
        fprintf(stderr, "Error getting GPIO line 8: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3208_cs", 1) < 0) { // Initially high
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "timestamp,temperature_celsius\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_file);
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = mcp3208_read(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float temperature = voltage_to_temperature(voltage);

        // Validate temperature range (TMP36: -40C to 125C)
        if (temperature < -40.0f || temperature > 125.0f) {
            fprintf(stderr, "Warning: Temperature out of range: %.2f C\n", temperature);
        }

        if (log_temperature(temperature) != 0) {
            fprintf(stderr, "Error logging temperature\n");
        }

        printf("Temperature: %.2f C\n", temperature);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

