#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define VREF 3.3
#define ADC_MAX 1023.0
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, tx, rx, 3);
    gpioWrite(CS_PIN, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static double adc_to_voltage(int adc_value) {
    return (adc_value / ADC_MAX) * VREF;
}

static double voltage_to_acceleration(double voltage) {
    return (voltage - 1.65) * 3.0;
}

static double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

static void log_data(double x, double y, double z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file);

    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_x = read_adc(ADC_CHANNEL_X);
        int adc_y = read_adc(ADC_CHANNEL_Y);
        int adc_z = read_adc(ADC_CHANNEL_Z);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double voltage_x = adc_to_voltage(adc_x);
        double voltage_y = adc_to_voltage(adc_y);
        double voltage_z = adc_to_voltage(adc_z);

        double x = voltage_to_acceleration(voltage_x);
        double y = voltage_to_acceleration(voltage_y);
        double z = voltage_to_acceleration(voltage_z);

        double magnitude = calculate_magnitude(x, y, z);

        log_data(x, y, z, magnitude);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

