#define SI1172_CMD_READ_FIFO 0x03

/* Error codes */
#define ERROR_OK 0
#define ERROR_I2C_READ 1
#define ERROR_SENSOR_ABSENT 2

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_sensor_data(uint16_t *ir_value, uint16_t *red_value);
static int log_data(uint16_t ir_value, uint16_t red_value, int error_code);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Initializes the I2C interface */
static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", SI1172_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    /*
     * Reset the sensor.
     * In a real application, this would be a command sent to the Si1172
     * command register (0xC0) with the appropriate reset command.
     * Here we write a dummy byte to the command register to verify communication.
     */
    if (i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, 0x00) < 0) {
        fprintf(stderr, "Warning: Failed to write to command register during reset\n");
    }

    return 0;
}

/* Reads raw IR and RED ADC values from the Si1172 sensor */
static int read_sensor_data(uint16_t *ir_value, uint16_t *red_value) {
    int result;

    /*
     * Trigger a measurement.
     * In a real application, this would be a command sent to the Si1172
     * command register (0xC0) with the appropriate start measurement command.
     * Here we write a dummy byte to the command register to simulate a measurement.
     */
    result = i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_CMD_START_MEASUREMENT);
    if (result < 0) {
        fprintf(stderr, "Error writing to command register: %d\n", result);
        return ERROR_I2C_READ;
    }

    /*
     * Wait for the measurement to complete.
     * In a real application, this would be a delay based on the measurement time.
     * Here we use a short delay to ensure the sensor has time to process the command.
     */
    gpioDelay(10000); /* 10ms delay */

    /*
     * Read the raw IR and RED ADC values from the FIFO data registers.
     * In a real application, this would be a command sent to the Si1172
     * command register (0xC0) with the appropriate read FIFO command.
     * Here we read the data directly from the FIFO data registers.
     */
    result = i2cReadWordData(i2c_handle, SI1172_REG_FIFO_DATA);
    if (result < 0) {
        fprintf(stderr, "Error reading IR data: %d\n", result);
        return ERROR_I2C_READ;
    }
    *ir_value = (uint16_t)result;

    result = i2cReadWordData(i2c_handle, SI1172_REG_FIFO_DATA_RED);
    if (result < 0) {
        fprintf(stderr, "Error reading RED data: %d\n", result);
        return ERROR_I2C_READ;
    }
    *red_value = (uint16_t)result;

    return ERROR_OK;
}

/* Logs the data to a CSV file */
static int log_data(uint16_t ir_value, uint16_t red_value, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (error_code == ERROR_OK) {
        fprintf(log_file, "%ld,%u,%u,%d\n", (long)rawtime, ir_value, red_value, error_code);
    } else {
        fprintf(log_file, "%ld,ERROR,%d\n", (long)rawtime, error_code);
    }

    fflush(log_file);
    return 0;
}

int main(void) {
    uint16_t ir_value, red_value;
    int error_code;

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    /* Write the header row if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IR_Value,RED_Value,Error_Code\n");
        fflush(log_file);
    }

    /* Main loop */
    while (!terminate) {
        error_code = read_sensor_data(&ir_value, &red_value);

        if (error_code == ERROR_OK) {
            /*
             * Note: The Si1172 requires a proprietary algorithm to convert
             * raw PPG samples to HR/SpO2. This implementation logs the raw
             * ADC values as proxy values for HR and SpO2.
             */
            if (log_data(ir_value, red_value, error_code) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            if (log_data(0, 0, error_code) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        sleep(1); /* Sample once per second */
    }

    /* Cleanup and exit */
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

