#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x67
#define MEASURE_CMD_HIGH_PRECISION 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (cmd >> 8) & 0xFF, cmd & 0xFF };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_icp10125(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    uint32_t raw_pressure, raw_temperature;
    uint8_t crc_p, crc_t;
    uint32_t p_poly = 0x3D290000;
    uint32_t t_poly = 0x3D290000;
    int32_t p_off, p_sens, t_off, t_sens;
    int32_t p_comp, t_comp;

    if (i2c_write_cmd(fd, MEASURE_CMD_HIGH_PRECISION) < 0) {
        return -1;
    }

    usleep(10000); // Wait 10ms for conversion

    if (i2c_read_bytes(fd, data, 6) < 0) {
        return -1;
    }

    // Verify CRC for pressure (bytes 0-1, CRC byte 2)
    crc_p = data[2];
    uint32_t crc_calc = 0xFFFF;
    for (int i = 0; i < 2; i++) {
        crc_calc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calc & 0x8000) {
                crc_calc = (crc_calc << 1) ^ 0x3D65;
            } else {
                crc_calc <<= 1;
            }
        }
    }
    crc_calc &= 0xFF;
    if (crc_calc != crc_p) {
        fprintf(stderr, "Pressure CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc_calc, crc_p);
        return -1;
    }

    // Verify CRC for temperature (bytes 3-4, CRC byte 5)
    crc_t = data[5];
    crc_calc = 0xFFFF;
    for (int i = 3; i < 5; i++) {
        crc_calc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calc & 0x8000) {
                crc_calc = (crc_calc << 1) ^ 0x3D65;
            } else {
                crc_calc <<= 1;
            }
        }
    }
    crc_calc &= 0xFF;
    if (crc_calc != crc_t) {
        fprintf(stderr, "Temperature CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc_calc, crc_t);
        return -1;
    }

    raw_pressure = ((uint32_t)data[0] << 8) | data[1];
    raw_temperature = ((uint32_t)data[3] << 8) | data[4];

    // Read calibration data from EEPROM (0x00-0x07)
    uint8_t cal_buf[8];
    if (i2c_write_cmd(fd, 0x0000) < 0) return -1;
    usleep(1000);
    if (i2c_read_bytes(fd, cal_buf, 8) < 0) return -1;

    p_off = (cal_buf[0] << 8) | cal_buf[1];
    p_sens = (cal_buf[2] << 8) | cal_buf[3];
    t_off = (cal_buf[4] << 8) | cal_buf[5];
    t_sens = (cal_buf[6] << 8) | cal_buf[7];

    // Apply calibration formulas
    p_comp = (int32_t)raw_pressure - p_off;
    t_comp = (int32_t)raw_temperature - t_off;

    *pressure = (float)p_comp * (float)p_sens / 65536.0f;
    *temperature = (float)t_comp * (float)t_sens / 65536.0f;

    return 0;
}

int log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", CSV_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
        fflush(log_file);
    }

    float temperature, pressure;

    while (running) {
        if (read_icp10125(i2c_fd, &temperature, &pressure) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
            if (log_data(log_file, temperature, pressure) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    return 0;
}

