#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define DEFAULT_GAIN 1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    double gain = DEFAULT_GAIN;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0) {
            fprintf(stderr, "Error: Gain must be a positive number\n");
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Sampling audio from MP23ABS1 microphones via MCP3008 ADC...\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc1 = read_adc(ADC_CHANNEL_1);
        int adc2 = read_adc(ADC_CHANNEL_2);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            break;
        }

        int16_t audio1 = (int16_t)adc1;
        int16_t audio2 = (int16_t)adc2;
        int16_t noise_canceled = (int16_t)(audio1 - (audio2 * gain));

        printf("%d,%d,%d\n", audio1, audio2, noise_canceled);
        fflush(stdout);

        gpioDelay(10000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return 0;
}

