#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define BUZZER_GPIO_LINE 18
#define BUZZER_CHIP "gpiochip4"

#define FLAME_THRESHOLD_VOLTAGE 1.0
#define DEFAULT_TEMPERATURE 25.0
#define TEMPERATURE_COMPENSATION_FACTOR 0.001
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static int spi_fd = -1;
static struct gpiod_chip *buzzer_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen("ambient_temp.txt", "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open ambient_temp.txt: %s. Using default %.1f°C.\n", strerror(errno), DEFAULT_TEMPERATURE);
        return (int)(DEFAULT_TEMPERATURE * 10.0);
    }
    int temp_int;
    if (fscanf(fp, "%d", &temp_int) != 1) {
        fprintf(stderr, "Warning: Invalid temperature in ambient_temp.txt. Using default %.1f°C.\n", DEFAULT_TEMPERATURE);
        temp_int = (int)(DEFAULT_TEMPERATURE * 10.0);
    }
    fclose(fp);
    return temp_int;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d.\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                return -1;
            }
            return adc_value;
        }
        fprintf(stderr, "Error: SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float calculate_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

static float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - DEFAULT_TEMPERATURE) * TEMPERATURE_COMPENSATION_FACTOR;
}

static int detect_flame(float compensated_voltage) {
    return (compensated_voltage > FLAME_THRESHOLD_VOLTAGE) ? 1 : 0;
}

static void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.1f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
