#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/etc/msmtprc"
#define LOG_FILE "plant_data.txt"
#define SPI_SPEED 500000
#define SPI_FLAGS 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d (must be 0-7)\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Error: Invalid calibration range (%d, %d)\n", min_raw, max_raw);
        return -1.0f;
    }
    float pct = 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0f;
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

static int send_email_alert(float moisture_percentage, const char *recipient_email, const char *msmtp_config_file) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nMoisture level is below threshold (%.2f%%).\" | msmtp -C %s %s",
             moisture_percentage, msmtp_config_file, recipient_email);

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("Error executing msmtp via popen");
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("Error closing msmtp pipe");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }

    fprintf(stderr, "Error: msmtp exited with status %d\n", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_raw = DEFAULT_MIN_RAW;
    int max_raw = DEFAULT_MAX_RAW;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
    char recipient_email[256] = DEFAULT_RECIPIENT_EMAIL;
    char msmtp_config_file[256] = DEFAULT_MSMTP_CONFIG_FILE;

    int opt;
    while ((opt = getopt(argc, argv, "s:c:m:M:t:f:e:r:")) != -1) {
        switch (opt) {
            case 's': spi_channel = atoi(optarg); break;
            case 'c': adc_channel = atoi(optarg); break;
            case 'm': min_raw = atoi(optarg); break;
            case 'M': max_raw = atoi(optarg); break;
            case 't': moisture_threshold = atoi(optarg); break;
            case 'f': logging_frequency = atoi(optarg); break;
            case 'e': strncpy(recipient_email, optarg, sizeof(recipient_email) - 1); recipient_email[sizeof(recipient_email) - 1] = '\0'; break;
            case 'r': strncpy(msmtp_config_file, optarg, sizeof(msmtp_config_file) - 1); msmtp_config_file[sizeof(msmtp_config_file) - 1] = '\0'; break;
            default:
                fprintf(stderr, "Usage: %s [-s spi_channel] [-c adc_channel] [-m min_raw] [-M max_raw] [-t moisture_threshold] [-f logging_frequency] [-e recipient_email] [-r msmtp_config_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant moisture monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, logging_frequency);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_mcp3008(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value, min_raw, max_raw);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error calculating moisture percentage, retrying in %d seconds...\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Error logging data, retrying in %d seconds...\n", logging_frequency);
        }

        if (moisture_percentage < moisture_threshold) {
            printf("Moisture level below threshold (%.2f%%). Sending email alert...\n", moisture_percentage);
            if (send_email_alert(moisture_percentage, recipient_email, msmtp_config_file) != 0) {
                fprintf(stderr, "Error sending email alert.\n");
            }
        }

        sleep(logging_frequency);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

