#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define DEFAULT_SAMPLE_INTERVAL 1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     * tx[0] = 0x01 (start bit)
     * tx[1] = (0x08 | channel) << 4 (single-ended + channel)
     * tx[2] = 0x00 (don't care)
     * Result: bits 9..0 in rx[1] (lower 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    /* Clamp to valid 10-bit range */
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* KY-036: dry soil -> high ADC, wet soil -> low ADC
     * Map 0-1023 to 100-0 (inverted)
     */
    return 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ADC: %d, Moisture: %.2f%%\n",
            timestamp, adc_value, moisture_percentage);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sample_interval = DEFAULT_SAMPLE_INTERVAL;

    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval '%s'. Using default %d seconds.\n",
                    argv[1], DEFAULT_SAMPLE_INTERVAL);
            sample_interval = DEFAULT_SAMPLE_INTERVAL;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Logging to '%s' every %d seconds.\n",
           LOG_FILE, sample_interval);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(adc_value, moisture_percentage);
            printf("ADC: %4d  Moisture: %5.2f%%\n", adc_value, moisture_percentage);
        }

