#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 300
#define MOISTURE_THRESHOLD_HIGH 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 5000000

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to pump GPIO %d\n", PUMP_GPIO);
    }
}

static void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        return;
    }

    circular_buffer[buffer_index].timestamp = now;
    circular_buffer[buffer_index].moisture_level = moisture_level;
    circular_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }

    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&circular_buffer[idx].timestamp);
        if (tm_info != NULL) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str) - 1);
            time_str[sizeof(time_str) - 1] = '\0';
        }
        printf("Timestamp: %s, Moisture: %d, Pump: %s\n",
               time_str,
               circular_buffer[idx].moisture_level,
               circular_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n\n");
}

static void timer_callback(void *user_data) {
    (void)user_data;

    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }

    static int pump_state = 0;
    if (moisture_level < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
        control_pump(1);
        pump_state = 1;
        printf("Moisture level low (%d). Turning pump ON.\n", moisture_level);
    } else if (moisture_level > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
        control_pump(0);
        pump_state = 0;
        printf("Moisture level high (%d). Turning pump OFF.\n", moisture_level);
    }

    log_data(moisture_level, pump_state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US / 1000, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up timer\n");
        control_pump(0);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

