// MAX30102 I2C address
#define MAX30102_ADDR 0x57

// MAX30102 register addresses
#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR   0x02
#define REG_OVF_COUNTER   0x03
#define REG_FIFO_RD_PTR   0x04
#define REG_FIFO_DATA     0x07
#define REG_FIFO_CONFIG   0x08
#define REG_MODE_CONFIG   0x09
#define REG_SPO2_CONFIG   0x0A
#define REG_LED1_PA       0x0C
#define REG_LED2_PA       0x0D
#define REG_PART_ID       0xFF

// Expected Part ID for MAX30102
#define MAX30102_PART_ID 0x15

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102(void);
int read_fifo_data(uint32_t *red, uint32_t *ir);
float calculate_spo2(uint32_t red, uint32_t ir);
float calculate_heart_rate(uint32_t *ir_buffer, int buffer_size);
void log_health_data(float spo2, float heart_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the MAX30102 sensor
int init_max30102(void) {
    // Verify sensor presence by reading Part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
