    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset to complete

