        return -1;
    }

    // Configure FIFO: Sample averaging 1, FIFO rollover disabled, FIFO almost full at 17 samples
    if (i2cWriteByteData(i2c_handle, REG_FIFO_CONFIG, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to configure FIFO\n");
        return -1;
    }

    // Configure mode: SpO2 mode (Red and IR LEDs enabled)
    if (i2cWriteByteData(i2c_handle, REG_MODE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to set SpO2 mode\n");
        return -1;
    }

