#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define RELAY_GPIO     17
#define DOOR_SENSOR_GPIO 27
#define LOG_FILE       "/var/log/door_events.log"
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_DELAY_MS 50
#define POLL_INTERVAL_MS 200
#define RELAY_HOLD_MS  3000
#define ADC_MAX        32767.0f
#define ADC_MIN        -32768.0f
#define ADC_VREF       4.096f
#define ADC_PGA        6.144f
#define ADC_RESOLUTION (ADC_PGA / 32768.0f)
#define ADC_OFFSET     0.0f

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *door_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[64];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 3) return -1;
    uint16_t config = 0x8000 | (channel << 12) | 0x4000 | 0x0100 | 0x0080;
    if (i2c_write_reg16(fd, 0x01, config) < 0) return -1;
    usleep(10000);
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x00, &raw) < 0) return -1;
    int16_t signed_raw = (int16_t)raw;
    return (int)((signed_raw * ADC_RESOLUTION) + ADC_OFFSET);
}

static int calibrate_sensor(int fd) {
    int sum = 0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        int val = read_adc(fd, 0);
        if (val < 0) {
            log_event("Error: Failed to read ADC during calibration");
            return -1;
        }
        sum += val;
        usleep(BASELINE_DELAY_MS * 1000);
    }
    int avg = sum / NUM_BASELINE_SAMPLES;
    int threshold = (int)(avg * 0.8f);
    printf("Calibration complete. Average: %d, Threshold: %d\n", avg, threshold);
    return threshold;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (door_line) {
        gpiod_line_release(door_line);
        door_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        fprintf(stderr, "Failed to request relay GPIO as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    door_line = gpiod_chip_get_line(chip, DOOR_SENSOR_GPIO);
    if (!door_line) {
        fprintf(stderr, "Failed to get door sensor GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(door_line, "door_sensor") < 0) {
        fprintf(stderr, "Failed to request door sensor GPIO as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    int threshold = calibrate_sensor(i2c_fd);
    if (threshold < 0) {
        log_event("Error: Sensor calibration failed");
        cleanup();
        return 1;
    }

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = read_adc(i2c_fd, 0);
        if (val < 0) {
            log_event("Error: Failed to read ADC");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val < threshold) {
            printf("Proximity detected! Releasing door lock.\n");
            log_event("Proximity detected, releasing door lock");
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                log_event("Error: Failed to energize relay");
            } else {
                usleep(RELAY_HOLD_MS * 1000);
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    log_event("Error: Failed to de-energize relay");
                }
            }

            int door_state = gpiod_line_get_value(door_line);
            if (door_state < 0) {
                log_event("Error: Failed to read door sensor");
            } else {
                if (door_state == 0) {
                    printf("Door opened.\n");
                    log_event("Door opened");
                } else {
                    printf("Door not opened.\n");
                    log_event("Door not opened");
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

