#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, ret);
        gpioDelay(100000);
    }
    return -1;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1.0f;
    float pct = 100.0f - ((float)(adc_value - DRY_RAW) / (float)(WET_RAW - DRY_RAW)) * 100.0f;
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", PUMP_GPIO);
        return;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "activated" : "deactivated");
    log_event(msg);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Threshold must be between 0 and 100\n");
                    return 1;
                }
                break;
            case 'd':
                duration = atoi(optarg);
                if (duration <= 0) {
                    fprintf(stderr, "Duration must be positive\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation system started. Threshold: %d%%, Duration: %d s, Sleep: %d s\n",
           threshold, duration, sleep_interval);
    log_event("System started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value, skipping irrigation cycle");
            sleep(sleep_interval);
            continue;
        }

        float moisture = calculate_moisture_percentage(adc_value);
        if (moisture < 0.0f) {
            log_event("Error calculating moisture percentage, skipping irrigation cycle");
            sleep(sleep_interval);
            continue;
        }

        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
        log_event(log_msg);

        if (moisture < threshold) {
            printf("Moisture below threshold (%.2f%% < %d%%), activating pump for %d seconds\n",
                   moisture, threshold, duration);
            control_pump(1);
            sleep(duration);
            control_pump(0);
        }

        sleep(sleep_interval);
    }

    printf("\nShutting down...\n");
    log_event("System shutting down");
    cleanup();
    return 0;
}

