        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Peak detected: %d\n", timestamp, value) < 0) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

