#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define SAMPLE_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single sample from the PCF8591.
 * The PCF8591 returns the result of the *previous* conversion on the
 * first read after a control byte write.  We send a dummy control byte
 * to trigger a conversion, then discard the stale byte, then read
 * the current conversion result.
 */
static int pcf8591_read_sample(int fd, uint8_t *out)
{
    uint8_t ctrl = 0x00;  /* single-ended, AIN0, analog output off */
    uint8_t dummy;

    /* Trigger a conversion by writing the control byte */
    if (write(fd, &ctrl, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Discard the stale conversion result */
    if (read(fd, &dummy, 1) != 1) {
        fprintf(stderr, "I2C read (dummy) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Read the current conversion result */
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read (sample) failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring PCF8591 AIN0 on %s (addr 0x%02X)...\n", I2C_BUS, PCF8591_ADDR);
    fflush(stdout);

    /* Main sampling loop */
    while (g_running) {
        uint8_t sample;

        if (pcf8591_read_sample(fd, &sample) == 0) {
            printf("AIN0: %u\n", sample);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading sample, exiting.\n");
            goto cleanup;
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

