#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_PGA_4_096V_VREF 4.096
#define ADS1115_PGA_4_096V_MAX 32767.0
#define GPIO_SHUTDOWN 27
#define BUFFER_SIZE 10
#define MAGNETIC_FIELD_THRESHOLD 500.0
#define SAMPLE_INTERVAL_US 1000000
#define VCC 3.3
#define SS49E_ZERO_FIELD_V 2.5
#define SS49E_SENSITIVITY_MV_PER_G 1.4

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer field_buffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_ads1115(void) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config");
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        syslog(LOG_ERR, "Failed to set ADS1115 conversion register");
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion");
        return -1;
    }
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float convert_to_voltage(int16_t raw) {
    return (raw * ADS1115_PGA_4_096V_VREF) / ADS1115_PGA_4_096V_MAX;
}

static float convert_to_gauss(float voltage) {
    if (voltage < 0.0 || voltage > VCC) {
        syslog(LOG_ERR, "Invalid voltage reading: %.3f V", voltage);
        return NAN;
    }
    return (voltage - SS49E_ZERO_FIELD_V) * 1000.0 / SS49E_SENSITIVITY_MV_PER_G;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

static void control_shutdown(float average_field) {
    if (average_field > MAGNETIC_FIELD_THRESHOLD) {
        gpioWrite(GPIO_SHUTDOWN, 1);
        syslog(LOG_WARNING, "Shutdown triggered: average field %.2f Gauss > %.2f Gauss",
               average_field, MAGNETIC_FIELD_THRESHOLD);
    }
}

int main(void) {
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X", ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    field_buffer.head = 0;
    field_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Magnetic field monitor started");

    while (!terminate) {
        int16_t raw;
        if (read_ads1115(&raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = convert_to_voltage(raw);
        float field = convert_to_gauss(voltage);

        if (isnan(field)) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        add_to_buffer(&field_buffer, field);
        float avg = calculate_average(&field_buffer);

        syslog(LOG_INFO, "Raw: %d, Voltage: %.3f V, Field: %.2f Gauss, Avg: %.2f Gauss",
               raw, voltage, field, avg);

        control_shutdown(avg);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(GPIO_SHUTDOWN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

