    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X", ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

    field_buffer.head = 0;
    field_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Magnetic field monitor started");

    while (!terminate) {
        int16_t raw;
        if (read_ads1115(&raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = convert_to_voltage(raw);
        float field = convert_to_gauss(voltage);

        if (isnan(field)) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        add_to_buffer(&field_buffer, field);
        float avg = calculate_average(&field_buffer);

        syslog(LOG_INFO, "Raw: %d, Voltage: %.3f V, Field: %.2f Gauss, Avg: %.2f Gauss",
               raw, voltage, field, avg);

        control_shutdown(avg);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(GPIO_SHUTDOWN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

