    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Potentiometer-controlled motor started.\n");
    printf("SPI0 CE0, MCP3008 ch0, PWM GPIO18 @ %d Hz, range 0-%d.\n",
           PWM_FREQ, PWM_RANGE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* Transient SPI error: keep motor at last safe state, retry next cycle */
            gpioPWM(PWM_PIN, 0);
            gpioDelay(SAMPLE_US);
            continue;
        }

        /* Map 0-1023 ADC value to 0-1023 PWM duty cycle */
        int duty = adc_value;

        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
        }

        printf("ADC: %4d  PWM: %4d\n", adc_value, duty);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);   /* Stop motor */
    spiClose(spi_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

