#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define ADC_PGA_GAIN 4.096
#define ADC_RESOLUTION 32768.0
#define ADC_VREF 3.3
#define ADC_SENSITIVITY 0.001
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_PERIOD_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ads1115(int handle, int16_t *raw) {
    char config[3];
    char data[2];

    config[0] = 0x01;
    config[1] = 0xC0;
    config[2] = 0x83;

    if (i2cWriteDevice(handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115\n");
        return -1;
    }

    gpioDelay(10000);

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115\n");
        return -1;
    }

    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static double convert_to_gauss(int16_t raw) {
    double voltage = (raw * ADC_VREF) / ADC_RESOLUTION;
    double gauss = (voltage - 1.65) / ADC_SENSITIVITY;
    return gauss;
}

static void blink_led(int gpio, int duration_us) {
    gpioWrite(gpio, 1);
    gpioDelay(BLINK_HALF_PERIOD_US);
    gpioWrite(gpio, 0);
    gpioDelay(BLINK_HALF_PERIOD_US);
    gpioDelay(duration_us - 2 * BLINK_HALF_PERIOD_US);
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Threshold must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.2f Gauss). Press Ctrl+C to exit.\n", threshold);

    while (running) {
        int16_t raw;
        if (read_ads1115(i2c_handle, &raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double gauss = convert_to_gauss(raw);
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            blink_led(LED_GPIO, BLINK_DURATION_US);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

