#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define SAMPLE_INTERVAL_SEC 60
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
                return -1;
            }
            return adc_value;
        }
        syslog(LOG_WARNING, "SPI transfer failed (attempt %d/%d): %d", attempt + 1, MAX_SPI_RETRIES, ret);
        gpioDelay(10000);
    }
    syslog(LOG_ERR, "SPI transfer failed after %d attempts", MAX_SPI_RETRIES);
    return -1;
}

static int calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0) return -1;
    int moisture = 100 - (int)(((float)adc_value / 1023.0f) * 100.0f);
    if (moisture < 0) moisture = 0;
    if (moisture > 100) moisture = 100;
    return moisture;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
    } else {
        pump_state = state;
        syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    }
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC_PUMP_CONTROL, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(rc));
        }
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(result));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0 && message->payload) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        syslog(LOG_INFO, "Received message on topic '%s': %s", message->topic, payload);
        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                control_relay(1);
            } else if (strcmp(payload, "pump_off") == 0) {
                control_relay(0);
            }
        }
    }
}

static void publish_moisture(int moisture) {
    if (!mosq) return;
    char payload[16];
    snprintf(payload, sizeof(payload), "%d", moisture);
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC_SOIL_MOISTURE, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture: %s", mosquitto_strerror(rc));
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    control_relay(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    control_relay(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create Mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, skipping cycle");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int moisture = calculate_moisture_percentage(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Invalid moisture percentage, skipping cycle");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        syslog(LOG_INFO, "Moisture: %d%% (ADC: %d)", moisture, adc_value);
        publish_moisture(moisture);

        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_relay(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_relay(0);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

