        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value, skipping cycle");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int moisture = calculate_moisture_percentage(adc_value);
        if (moisture < 0) {
            syslog(LOG_ERR, "Invalid moisture percentage, skipping cycle");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        syslog(LOG_INFO, "Moisture: %d%% (ADC: %d)", moisture, adc_value);
        publish_moisture(moisture);

        if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
            control_relay(1);
        } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
            control_relay(0);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

