#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_FILE "sensor_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (returned %d)\n", channel, result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

float adc_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

int log_data(float voltages[], int num_channels) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s", timestamp);
    for (int i = 0; i < num_channels; i++) {
        fprintf(fp, ",%.3f", voltages[i]);
    }
    fprintf(fp, "\n");

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Could not close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register SIGINT handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register SIGTERM handler: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting data logging to %s every %d seconds. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float voltages[NUM_CHANNELS];
        int error_flag = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value from channel %d\n", i);
                error_flag = 1;
                break;
            }
            voltages[i] = adc_to_voltage(adc_value);
        }

        if (!error_flag) {
            if (log_data(voltages, NUM_CHANNELS) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

