#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int read_moisture_level(void);
void control_pump(int state);
void log_data(int moisture_level);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    control_pump(0); // Ensure pump is off
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

// Read analog value from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008 single-ended mode
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Read moisture level with retry logic
int read_moisture_level(void) {
    int moisture_level = -1;
    int retries = 0;

    while (retries < MAX_RETRIES && moisture_level < 0) {
        moisture_level = read_mcp3008(0); // Read from channel 0
        if (moisture_level < 0) {
            fprintf(stderr, "Error reading moisture level, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(1);
            }
        }
    }

    if (moisture_level < 0) {
        fprintf(stderr, "Error: Failed to read moisture level after %d retries\n", MAX_RETRIES);
        return -1;
    }

    return moisture_level;
}

// Control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Log data to console
void log_data(int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture Level: %d\n", timestamp, moisture_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output and ensure it's off initially
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
