#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 = channel */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_moisture(int channel) {
    int adc = read_mcp3008(channel);
    if (adc < 0) {
        return -1;
    }
    /* VH400: dry soil -> low ADC, wet soil -> high ADC */
    return adc;
}

static int calculate_valve_position(int avg_moisture) {
    /* Inverse mapping: dry (low ADC) -> high opening (100%), wet (high ADC) -> low opening (0%) */
    int pos = 100 - (avg_moisture * 100) / 1023;
    if (pos < 0) pos = 0;
    if (pos > 100) pos = 100;
    return pos;
}

static void set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    int pwm_value = (position * PWM_RANGE) / 100;
    if (gpioPWM(VALVE_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO%d\n", VALVE_GPIO);
    }
}

static void log_data(int sensor_values[], int avg_moisture, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor0: %d, Sensor1: %d, Sensor2: %d, Average: %d, Valve Position: %d%%\n",
            timestamp, sensor_values[0], sensor_values[1], sensor_values[2],
            avg_moisture, valve_position);
    fflush(log_file);
}

static void cleanup(void) {
    set_valve_position(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel=%d, speed=%d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_values[NUM_SENSORS];
        int valid_count = 0;
        int sum = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int moisture = read_soil_moisture(i);
            if (moisture >= 0) {
                sensor_values[i] = moisture;
                sum += moisture;
                valid_count++;
            } else {
                sensor_values[i] = -1;
            }
        }

        if (valid_count == 0) {
            fprintf(stderr, "All sensor readings failed; skipping cycle\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int avg_moisture = sum / valid_count;
        int valve_position = calculate_valve_position(avg_moisture);
        set_valve_position(valve_position);
        log_data(sensor_values, avg_moisture, valve_position);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

