#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

#define PWM_CHIP 0
#define PWM_CHANNEL 0

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000

#define MIN_FREQ 220
#define MAX_FREQ 880

#define CONFIG_FILE "theremin_config.txt"

volatile sig_atomic_t program_running = 1;

struct gpiod_chip *chip = NULL;
struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;

int spi_fd = -1;

float min_distance = 10.0;
float max_distance = 400.0;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_adc(int channel) {
    if (spi_fd < 0) return -1;
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float read_distance() {
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;
    struct timeval start, end;
    long long start_us, end_us;
    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0) {
        if (timeout++ > 10000) return -1.0;
        usleep(1);
    }
    gettimeofday(&start, NULL);
    start_us = start.tv_sec * 1000000LL + start.tv_usec;
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1) {
        if (timeout++ > 10000) return -1.0;
        usleep(1);
    }
    gettimeofday(&end, NULL);
    end_us = end.tv_sec * 1000000LL + end.tv_usec;
    long long diff = end_us - start_us;
    if (diff <= 0) return -1.0;
    float distance = (diff * 34300.0) / 2000000.0;
    if (distance < 2.0 || distance > 400.0) return -1.0;
    return distance;
}

int map_distance_to_frequency(float distance) {
    if (distance < 0) return -1;
    if (distance < min_distance) distance = min_distance;
    if (distance > max_distance) distance = max_distance;
    return (int)(MIN_FREQ + (distance - min_distance) * (MAX_FREQ - MIN_FREQ) / (max_distance - min_distance));
}

int set_pwm_frequency(int frequency) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open period");
        return -1;
    }
    char buf[16];
    int period_ns = 1000000000 / frequency;
    snprintf(buf, sizeof(buf), "%d", period_ns);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write period");
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open duty_cycle");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", period_ns / 2);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write duty_cycle");
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open enable");
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        perror("Failed to enable PWM");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return -1;
    if (fscanf(fp, "%f %f", &min_distance, &max_distance) != 2) {
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int save_config() {
