    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 || ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(unsigned int){SPI_SPEED}) < 0) {
        perror("Failed to configure SPI");
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    load_config();

    float last_valid_distance = -1.0;
    int last_valid_frequency = -1;

    while (program_running) {
        float distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            adc_value = 512;
        }

        float volume = (float)adc_value / 1023.0;
        if (volume < 0.1) volume = 0.1;
        if (volume > 1.0) volume = 1.0;

        int frequency = map_distance_to_frequency(distance);
        if (frequency < 0) {
            fprintf(stderr, "Frequency mapping error\n");
            frequency = last_valid_frequency;
        } else {
            last_valid_frequency = frequency;
        }

        set_pwm_frequency(frequency);

        usleep(10000);
    }

    set_pwm_frequency(0);
    save_config();

    if (spi_fd >= 0) close(spi_fd);
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);

    return 0;
}

