    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        int success = 0;

        // Retry loop for SPI read
        while (retries < MAX_RETRIES && !success) {
            adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value >= 0) {
                success = 1;
