#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define MCP3008_CHANNEL 0
#define ALCOHOL_THRESHOLD_HIGH 50.0
#define ALCOHOL_THRESHOLD_LOW 20.0
#define LOG_FILE "alcohol_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((channel << 4) | 0x80), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

const char* classify_alcohol(float ppm) {
    if (ppm > ALCOHOL_THRESHOLD_HIGH) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < ALCOHOL_THRESHOLD_LOW) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

int log_data(float ppm, const char* classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting UTC time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_fp, "%s, %.2f PPM, %s\n", timestamp, ppm, classification) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() != 0) {
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && !read_ok) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                read_ok = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "SPI read failed (attempt %d/%d), retrying...\n", retries, MAX_RETRIES);
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!read_ok) {
            fprintf(stderr, "Failed to read ADC value after %d retries. Skipping sample.\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC reading at extreme (%d) - sensor may be absent or disconnected.\n", adc_value);
        }

        float ppm = adc_to_ppm(adc_value);
        const char* classification = classify_alcohol(ppm);

        if (log_data(ppm, classification) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("PPM: %.2f, Classification: %s\n", ppm, classification);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

