// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel: %d\n", spi_handle);
        return -1;
    }

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    spiClose(spi_handle);

    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor using logarithmic function
float map_pot_to_speed(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Error: Invalid potentiometer value: %d\n", pot_value);
        return 0.0f;
    }

    // Logarithmic mapping: 0-1023 -> 0.0-1.0
    float log_value = log10f((float)pot_value + 1.0f);
    float speed_factor = log_value / log10f(1024.0f);

    // Clamp to valid range
    if (speed_factor < 0.0f) speed_factor = 0.0f;
    if (speed_factor > 1.0f) speed_factor = 1.0f;

    return speed_factor;
}

