// Define GPIO pins
#define LED_PIN 17
#define SPI_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0

// Define calibration parameters
#define CALIBRATION_DURATION 5
#define NOISE_THRESHOLD_PERCENT 10

// Define debounce parameters
#define DEBOUNCE_DELAY_MS 10

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void calibrate_noise(int *ambient_level);
void check_sound_level(int ambient_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate noise level
void calibrate_noise(int *ambient_level) {
    printf("Calibrating noise level...\n");
    time_t start_time = time(NULL);
    long sum = 0;
    int sample_count = 0;

    while (time(NULL) - start_time < CALIBRATION_DURATION) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value >= 0) {
            sum += adc_value;
            sample_count++;
        } else {
            fprintf(stderr, "Error: Failed to read ADC during calibration\n");
        }
        gpioDelay(10000); // 10 ms delay
    }

    if (sample_count > 0) {
        *ambient_level = (int)(sum / sample_count);
        printf("Calibration complete. Ambient level: %d\n", *ambient_level);
    } else {
        fprintf(stderr, "Error: No valid samples during calibration\n");
        program_running = 0;
    }
}

// Function to check sound level and trigger LED
void check_sound_level(int ambient_level) {
    int adc_value = read_mcp3008(0); // Read from channel 0
    if (adc_value < 0) {
        fprintf(stderr, "Error: Failed to read ADC\n");
        return;
    }

    int noise_threshold = (ambient_level * NOISE_THRESHOLD_PERCENT) / 100;

    if (adc_value > (ambient_level + noise_threshold)) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Calibrate noise level
    int ambient_level = 0;
    calibrate_noise(&ambient_level);

    // Main loop
    while (program_running) {
        check_sound_level(ambient_level);
        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    spiClose(spi_handle); // Close SPI channel
    gpioTerminate(); // Terminate pigpio

    return 0;
}

