#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0       // CE0
#define SPI_SPEED 1000000   // 1 MHz
#define MCP3008_CHANNEL 0   // Single-ended channel 0
#define VREF 3.3            // Reference voltage
#define LOG_FILE "gas_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second
#define RETRY_DELAY_US 100000      // 100 ms

// Global variables for cleanup
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_ppm(float voltage);
int log_data(float voltage, float ppm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel configuration (channel << 4)
    // Byte 2: Don't care (0x00)
    unsigned char spi_tx_buf[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char spi_rx_buf[3] = {0};

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buf[1] contains the two most significant bits in its lower 2 bits
    // rx_buf[2] contains the 8 least significant bits
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | spi_rx_buf[2];
    return adc_value;
}

