    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Propane Leak Detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in 100ms...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to PPM
        float ppm = voltage_to_ppm(voltage);

        // Log data
        if (log_data(voltage, ppm) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        // Print data to console
        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);

        // Wait for next sample interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

