#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI mode 0
#define CS_PIN 8          // GPIO8 for MCP3008 CS
#define ADC_CHANNELS 3    // X, Y, Z
#define ADC_RESOLUTION 1024.0
#define ADC_VREF 3.3
#define ADXL335_SENSITIVITY 0.3 // 300mV/g
#define ADXL335_ZERO_G 1.5      // V
#define SAMPLE_RATE 10.0       // Hz
#define SAMPLE_PERIOD (1.0 / SAMPLE_RATE)

// Kalman filter parameters
#define Q 0.01
#define R 0.01

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Kalman filter state structures
typedef struct {
    float x;
    float P;
} KalmanState;

KalmanState kalman_x = {0.0, 1.0};
KalmanState kalman_y = {0.0, 1.0};
KalmanState kalman_z = {0.0, 1.0};

// Function prototypes
int initialize_spi(void);
int read_adc(int channel);
float convert_to_g(int adc_value);
float kalman_filter(KalmanState *state, float measurement);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Initialize SPI interface
int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008 via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: start bit (1), single-ended mode (1), channel select (3 bits)
    unsigned char tx_buffer[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx_buffer[3] = {0};

    gpioWrite(CS_PIN, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d: %d\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to acceleration in g
float convert_to_g(int adc_value) {
    float voltage = (adc_value / ADC_RESOLUTION) * ADC_VREF;
    float acceleration = (voltage - ADXL335_ZERO_G) / ADXL335_SENSITIVITY;
    return acceleration;
}

// Kalman filter implementation
float kalman_filter(KalmanState *state, float measurement) {
    // Prediction
    state->x = state->x;
    state->P = state->P + Q;

    // Update
    float K = state->P / (state->P + R);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1 - K) * state->P;

    return state->x;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output and ensure it is high
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 Kalman Filtered Acceleration (10 Hz)\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values for all three axes
        int adc_x_value = read_adc(0);
        int adc_y_value = read_adc(1);
        int adc_z_value = read_adc(2);

        if (adc_x_value < 0 || adc_y_value < 0 || adc_z_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC values, retrying...\n");
            gpioDelay(100000); // 100ms delay before retrying
            continue;
        }

        // Convert ADC values to acceleration in g
        float x_acceleration = convert_to_g(adc_x_value);
        float y_acceleration = convert_to_g(adc_y_value);
        float z_acceleration = convert_to_g(adc_z_value);

        // Apply Kalman filter to each axis
        float filtered_x = kalman_filter(&kalman_x, x_acceleration);
        float filtered_y = kalman_filter(&kalman_y, y_acceleration);
        float filtered_z = kalman_filter(&kalman_z, z_acceleration);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x, filtered_y, filtered_z);

        // Delay for the specified sample period
        gpioDelay((int)(SAMPLE_PERIOD * 1000000)); // Convert seconds to microseconds
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

