#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define VCC 3.3f
#define V_QUIESCENT (VCC / 2.0f)
#define SENSITIVITY 0.025f
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static float read_sensor(struct gpiod_line *line, int pin) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO%d: %s\n", pin, strerror(errno));
        return -1.0f;
    }
    float voltage = (value == 1) ? VCC : 0.0f;
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    if (magnetic_field < -100.0f || magnetic_field > 100.0f) {
        fprintf(stderr, "Warning: Sensor on GPIO%d reading %.2f mT out of range\n", pin, magnetic_field);
    }
    return magnetic_field;
}

static int log_data(float s1, float s2, float s3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_sensor") < 0) {
            fprintf(stderr, "Error requesting GPIO %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        float s1 = read_sensor(lines[0], SENSOR1_PIN);
        float s2 = read_sensor(lines[1], SENSOR2_PIN);
        float s3 = read_sensor(lines[2], SENSOR3_PIN);

        if (s1 >= 0.0f && s2 >= 0.0f && s3 >= 0.0f) {
            if (log_data(s1, s2, s3) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Skipping log entry due to sensor read error.\n");
