#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30 // Percentage
#define LOG_FILE "watering.log"
#define ADC_CHANNEL 0

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid ADC channel");
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        log_event("Error: SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        log_event("Error: Failed to write to pump GPIO");
    } else {
        char log_message[64];
        snprintf(log_message, sizeof(log_message), "Pump %s", state ? "ON" : "OFF");
        log_event(log_message);
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, message);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Program terminated by signal");
    control_pump(0); // Ensure pump is off
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (program_running) {
        // Read moisture level
        int moisture_level = read_mcp3008(ADC_CHANNEL);
        if (moisture_level < 0) {
            log_event("Error reading moisture level, skipping pump control");
        } else {
            // Calculate moisture percentage (0-100%)
            int moisture_percentage = (moisture_level * 100) / 1023;

            // Control pump based on moisture level
            if (moisture_percentage < MOISTURE_THRESHOLD) {
                control_pump(1); // Turn on pump
            } else {
                control_pump(0); // Turn off pump
            }

            // Log moisture level
            char log_message[64];
            snprintf(log_message, sizeof(log_message), "Moisture level: %d%%", moisture_percentage);
            log_event(log_message);
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup (should not reach here due to signal handler)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

