    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() != 0) {
        return 1;
    }

    csv_fp = fopen(CSV_FILE, "a");
    if (csv_fp == NULL) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", CSV_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(csv_fp, "# timestamp,ch0,ch1,ch2\n");
    fflush(csv_fp);

    printf("Soil moisture monitoring started. Press Ctrl+C to stop.\n");

    while (keep_running) {
        int ch0 = read_mcp3008(0);
        int ch1 = read_mcp3008(1);
        int ch2 = read_mcp3008(2);

        if (ch0 < 0 || ch1 < 0 || ch2 < 0) {
            fprintf(stderr, "Error reading ADC values. Exiting.\n");
            break;
        }

        if (log_data(csv_fp, ch0, ch1, ch2) != 0) {
            fprintf(stderr, "Error logging data. Exiting.\n");
            break;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

