#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret;

    /* Register signal handlers for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        perror("Failed to get sound sensor line (GPIO17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Get the alarm LED line */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        perror("Failed to get alarm LED line (GPIO18)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request sound sensor line as input */
    ret = gpiod_line_request_input(sound_line, "sound-sensor");
    if (ret < 0) {
        perror("Failed to request sound sensor line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request alarm LED line as output, initially low */
    ret = gpiod_line_request_output(led_line, "alarm-led", 0);
    if (ret < 0) {
        perror("Failed to request alarm LED line as output");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sound_level = gpiod_line_get_value(sound_line);
        if (sound_level < 0) {
            perror("Failed to read sound sensor value");
            break;
        }

        printf("Sound Level: %d\n", sound_level);

        if (sound_level == 0) {
            /* Sound detected: blink LED for 1 second */
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to turn on alarm LED");
                break;
            }
            usleep(BLINK_DURATION_US);

            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to turn off alarm LED");
                break;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up: turn off LED and release lines */
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(sound_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

