#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define READ_INTERVAL_SEC 5
#define LM35_MV_PER_C 10.0f
#define MCP3008_VREF 3.3f
#define MCP3008_MAX_VALUE 1023.0f

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_celsius(int adc_value) {
    return ((float)adc_value / MCP3008_MAX_VALUE) * MCP3008_VREF * 1000.0f / LM35_MV_PER_C;
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static int write_buffer_to_file(const float *buffer, int buffer_size, const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t elements_written = fwrite(buffer, sizeof(float), (size_t)buffer_size, fp);
    if (elements_written != (size_t)buffer_size) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }

    return 0;
}

int main(void) {
    float temperature_buffer[BUFFER_SIZE];
    int buffer_index = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping this sample\n");
        } else {
            float temperature = adc_to_celsius(adc_value);
            log_temperature(temperature);
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            if (write_buffer_to_file(temperature_buffer, BUFFER_SIZE, LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to write buffer to file\n");
            }
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

