// Configuration
#define SPI_CHANNEL 0       // CE0
#define SPI_SPEED 1000000   // 1 MHz
#define SLEEP_INTERVAL 60   // seconds
#define NUM_SENSORS 3
#define ADC_MAX 1023.0

// Global variables for cleanup
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void log_data(float moisture_levels[]);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format: start bit (1), single-ended mode (1), channel select (3 bits), then don't care
    unsigned char tx_buffer[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buffer[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 3) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to moisture percentage (0% = dry, 100% = wet)
float convert_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value %d out of range\n", adc_value);
        return -1.0;
    }
    return (1.0 - (adc_value / ADC_MAX)) * 100.0;
}

// Log moisture levels to file
void log_data(float moisture_levels[]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor 1: %.2f%%, Sensor 2: %.2f%%, Sensor 3: %.2f%%\n",
            timestamp, moisture_levels[0], moisture_levels[1], moisture_levels[2]);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float moisture_levels[NUM_SENSORS];
        int valid_readings = 0;

        // Read moisture levels from all sensors
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                moisture_levels[i] = convert_to_moisture(adc_value);
                if (moisture_levels[i] >= 0) {
                    valid_readings++;
                } else {
                    fprintf(stderr, "Error: Failed to convert ADC value for sensor %d\n", i + 1);
                }
            } else {
                fprintf(stderr, "Error: Failed to read ADC value for sensor %d\n", i + 1);
            }
        }

        // Log data only if all sensors were read successfully
        if (valid_readings == NUM_SENSORS) {
            log_data(moisture_levels);
        } else {
            fprintf(stderr, "Warning: Skipping log due to sensor read errors\n");
        }

        // Sleep for the specified interval
        gpioDelay(SLEEP_INTERVAL * 1000000); // pigpio delay is in microseconds
    }

    // Cleanup
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

