#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// BCM GPIO pins for the four relays (active-high modules)
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Number of relays
#define NUM_RELAYS 4

// GPIO chip device (Raspberry Pi 3 Model B+)
#define GPIO_CHIP "/dev/gpiochip0"

// Global pointers for cleanup in signal handler
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

// Signal handler: set flag to stop main loop, deactivate relays, release lines
void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
    // Deactivate all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
        }
    }
    // Release GPIO lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Initialize GPIO lines as outputs, initially LOW (inactive)
int init_gpio(void) {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            return -1;
        }

        int ret = gpiod_line_request_output(relay_lines[i], "relay_sequencer", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request output for GPIO line %d\n", pins[i]);
            return -1;
        }
    }

    return 0;
}

// Activate a relay for a given duration (seconds)
void activate_relay(struct gpiod_line *line, int duration_sec) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to activate relay");
        return;
    }
    sleep(duration_sec);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to deactivate relay");
    }
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    // Main loop: sequentially activate and deactivate relays
    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!keep_running) break;
            activate_relay(relay_lines[i], 1);
            if (i < NUM_RELAYS - 1) {
                sleep(1);
            }
        }
    }

    // Cleanup (should not reach here normally due to signal handler)
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

