    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    // Main loop: sequentially activate and deactivate relays
    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (!keep_running) break;
            activate_relay(relay_lines[i], 1);
            if (i < NUM_RELAYS - 1) {
                sleep(1);
            }
        }
    }

    // Cleanup (should not reach here normally due to signal handler)
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

