#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// GPIO pins for L298N motor driver
#define IN1 17
#define IN2 18
#define ENA 27

// SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  // 1 MHz
#define SPI_MODE 0

// Rain sensor channel on MCP3008
#define RAIN_SENSOR_CHANNEL 0

// Rain level threshold (0 = dry, 10 = heaviest rain)
#define RAIN_THRESHOLD 5

// Motor PWM range and speed
#define PWM_RANGE 255
#define PWM_SPEED 150

// Motor run duration in microseconds
#define MOTOR_RUN_DURATION_US 3000000  // 3 seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor(int channel);
int calculate_rain_level(int adc_value);
void control_motor(int direction);
void log_rain_data(int rain_level);
void signal_handler(int signal);
void cleanup();

// Function to read rain sensor value from MCP3008 ADC
int read_rain_sensor(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];

    // MCP3008 single-ended read command: start bit, single-ended mode, channel select
    tx[0] = 0x01;  // Start bit
    tx[1] = (0x08 | channel) << 4;  // Single-ended mode, channel select
    tx[2] = 0x00;  // Don't care

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value: bits 1-0 of rx[1] are high bits, rx[2] is low byte
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to calculate rain level from ADC value (0 = dry, 10 = heaviest rain)
int calculate_rain_level(int adc_value) {
    // Invert: higher ADC value means drier, so map 1023 to 0, 0 to 10
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the motor direction and speed
void control_motor(int direction) {
    // direction: 1 = forward (close window), -1 = reverse (open window), 0 = stop
    if (direction == 1) {
        gpioWrite(IN1, 1);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, PWM_SPEED);
    } else if (direction == -1) {
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 1);
        gpioPWM(ENA, PWM_SPEED);
    } else {
        gpioWrite(IN1, 0);
        gpioWrite(IN2, 0);
        gpioPWM(ENA, 0);
    }
}

// Function to log rain data to a file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    control_motor(0);  // Stop motor
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(ENA, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read rain sensor
        int adc_value = read_rain_sensor(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading rain sensor, skipping cycle\n");
            gpioDelay(1000000);  // Wait 1 second before retrying
            continue;
        }

        // Calculate rain level
        int rain_level = calculate_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            printf("Rain detected! Closing window...\n");
            control_motor(1);  // Close window
            gpioDelay(MOTOR_RUN_DURATION_US);
            control_motor(0);  // Stop motor
        } else {
            printf("No rain detected! Opening window...\n");
            control_motor(-1);  // Open window
            gpioDelay(MOTOR_RUN_DURATION_US);
            control_motor(0);  // Stop motor
        }

        // Wait before next reading
        gpioDelay(1000000);  // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

