#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define THRESHOLD 700
#define LED_ON_TIME_MS 500
#define DEBOUNCE_MS 50
#define SAMPLE_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    int ret;

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts off */
    ret = gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d)\n", LED_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(LED_GPIO, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW (code %d)\n", LED_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure microphone GPIO as input */
    ret = gpioSetMode(MIC_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d)\n", MIC_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: failed to install SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool led_on = false;
    uint32_t last_trigger_tick = 0;

    while (running) {
        int adc_value = gpioRead(MIC_GPIO);
        if (adc_value < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d (code %d)\n", MIC_GPIO, adc_value);
            break;
        }

        /* Convert 10-bit ADC value to raw voltage (0-3.3V) */
        float voltage = (float)adc_value * 3.3f / 1023.0f;

        /* Simple clap detection: threshold is 0.7V (approx 700/1023) */
        if (adc_value > THRESHOLD) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;

            if (!led_on && (elapsed > DEBOUNCE_MS * 1000)) {
                /* Turn LED on */
                ret = gpioWrite(LED_GPIO, 1);
                if (ret != 0) {
