static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    int ret;

    /* Initialize pigpio */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts off */
    ret = gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d)\n", LED_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(LED_GPIO, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW (code %d)\n", LED_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure microphone GPIO as input */
    ret = gpioSetMode(MIC_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d)\n", MIC_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

