#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define PROXIMITY_THRESHOLD 200.0
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int gpio_export(int pin) {
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open export file: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        fprintf(stderr, "Failed to write pin %d to export: %s\n", pin, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_unexport(int pin) {
    FILE *fp = fopen("/sys/class/gpio/unexport", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open unexport file: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", pin) < 0) {
        fprintf(stderr, "Failed to write pin %d to unexport: %s\n", pin, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open direction file for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", direction) < 0) {
        fprintf(stderr, "Failed to set direction for pin %d: %s\n", pin, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int gpio_read_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open value file for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    int value = fgetc(fp);
    fclose(fp);
    if (value == EOF) {
        fprintf(stderr, "Failed to read value from pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return (value == '1') ? 1 : 0;
}

float voltage_to_distance(float voltage) {
    return 26.0 / voltage + -6.0;
}

int log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        fprintf(stderr, "Failed to get local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

int main() {
    if (gpio_export(GPIO_PIN) != 0) {
        return EXIT_FAILURE;
    }
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        gpio_unexport(GPIO_PIN);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        gpio_unexport(GPIO_PIN);
        return EXIT_FAILURE;
    }

    printf("Pet feeder system started. Press Ctrl+C to exit.\n");

    while (running) {
        int value = gpio_read_value(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value, retrying in 1 second...\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        float voltage = (value == 1) ? 3.3 : 0.0;
        float distance = voltage_to_distance(voltage);

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance, continuing...\n");
        }

        if (distance < PROXIMITY_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    gpio_unexport(GPIO_PIN);
    printf("Pet feeder system stopped.\n");
    return EXIT_SUCCESS;
}

