int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_data(float moisture_percentage, int pump_state);
void signal_handler(int signal);
void cleanup(void);

// Initialize SPI interface
int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode (mode 0)
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set bits per word (8 bits)
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO using libgpiod
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO_LINE);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    int ret = gpiod_line_request_output(pump_line, "soil_moisture", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        pump_line = NULL;
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008 channel (single-ended)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3008 command: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01;  // Start bit
    tx_buf[1] = (0x08 | channel) << 4;  // Single-ended mode + channel
    tx_buf[2] = 0x00;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate moisture percentage from ADC value
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }

    // Clamp ADC value to valid range
    if (adc_value < WET_ADC_VALUE) adc_value = WET_ADC_VALUE;
    if (adc_value > DRY_ADC_VALUE) adc_value = DRY_ADC_VALUE;

    // Linear interpolation: 100% at DRY_ADC_VALUE, 0% at WET_ADC_VALUE
    float moisture_percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE)) * 100.0;
    return moisture_percentage;
}

// Control pump relay (active-high)
void control_pump(int state) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, state);
    }
}

// Log data to file
void log_data(float moisture_percentage, int pump_state) {
    if (!log_file) return;

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n",
            timestamp, moisture_percentage, pump_state ? "ON" : "OFF");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (pump_line) {
        gpiod_line_set_value(pump_line, 0);  // Turn off pump
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0) {
            fprintf(stderr, "Failed to calculate moisture percentage. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Control pump based on moisture threshold
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            control_pump(1);  // Turn on pump
        } else {
            control_pump(0);  // Turn off pump
        }

        // Log data
        int pump_state = gpiod_line_get_value(pump_line);
        if (pump_state < 0) {
            fprintf(stderr, "Failed to read pump state.\n");
        } else {
            log_data(moisture_percentage, pump_state);
        }

        printf("Moisture: %.2f%%, Pump: %s\n", moisture_percentage, pump_state ? "ON" : "OFF");

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

