#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0          // SPI0 CE0 (GPIO 8)
#define SPI_SPEED 1000000      // 1 MHz
#define LED_GPIO 21            // GPIO21
#define FIELD_THRESHOLD 10.0   // mT
#define VCC 3.3                // Volts
#define SENSITIVITY_MV_PER_MT 1.65 // mV/mT at 3.3 V
#define ADC_MAX 1023           // 10-bit ADC
#define LOG_FILE "magnetic_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_field(float voltage);
void log_data(float field);
void control_led(float field);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Read 10-bit value from MCP3008 single-ended channel (0-7)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit result: bits 1-2 of rx_buf[1] are high bits, rx_buf[2] is low byte
    int adc_value = ((rx_buf[1] & 3) << 8) | rx_buf[2];
    return adc_value;
}

// Convert ADC voltage to magnetic field strength in mT
float voltage_to_field(float voltage) {
    // DRV5055VA ratiometric: field = (V - VCC/2) * 1000 / sensitivity_mV_per_mT
    return (voltage - VCC / 2.0) * 1000.0 / SENSITIVITY_MV_PER_MT;
}

// Log timestamped field reading to file
void log_data(float field) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f mT\n", timestamp, field);
    fclose(fp);
}

// Control LED based on field threshold
void control_led(float field) {
