int read_mcp3008(int channel);
float voltage_to_field(float voltage);
void log_data(float field);
void control_led(float field);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Read 10-bit value from MCP3008 single-ended channel (0-7)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
