    if (init_gpio() != 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting current monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) != 0) {
            fprintf(stderr, "Logging error, continuing...\n");
        }

        printf("Current: %.4f A\n", current);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

