#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/*
 * Raspberry Pi Zero W - MLX91211 Current Sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V  (Pin 2)
 *   MCP3008 VREF -> Pi 5V  (Pin 2)
 *   MCP3008 AGND -> Pi GND (Pin 6)
 *   MCP3008 DGND -> Pi GND (Pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MLX91211 ratiometric output: 2.5V (VDD/2) at 0A, 5.0V (VDD) at +50A.
 * Current = (voltage - 2.5) * (50.0 / 2.5)
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 VREF tied to Pi 5V */
#define MLX_VDD        5.0        /* MLX91211 supply voltage */
#define MLX_ZERO_A     2.5        /* Voltage at 0A */
#define MLX_FULL_A     5.0        /* Voltage at +50A */
#define MLX_MAX_A      50.0       /* Full-scale current */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on SPI error.                          */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       Start bit
     *   tx[1] = 0x80 | (channel << 4)      Single-ended + channel select
     *   tx[2] = 0x00                       Don't care
     * Result:
     *   rx[1] bits 1:0  -> bits 9:8 of ADC result
     *   rx[2]          -> bits 7:0 of ADC result
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC code to current (A)                                     */
/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value)
{
    float voltage = ((float)adc_value / (float)ADC_MAX) * VREF;

    if (voltage < 0.0f || voltage > MLX_VDD) {
        fprintf(stderr, "Warning: voltage %.3f V out of range [0, %.1f]\n",
                voltage, MLX_VDD);
        return 0.0f;
    }

    float current = (voltage - MLX_ZERO_A) * (MLX_MAX_A / (MLX_FULL_A - MLX_ZERO_A));
    return current;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current sensor logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error already reported; skip this sample */
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

