#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NUMBER 0
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(struct gpiod_line *line) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line\n");
            return -1;
        }
        sum += val;
        usleep(DEBOUNCE_DELAY_US);
    }
    return (sum < DEBOUNCE_SAMPLES / 2) ? 1 : 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_number(GPIO_CHIP_NUMBER);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("Failed to get GPIO line 4");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("Failed to get GPIO line 17");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-sensor1") < 0) {
        perror("Failed to request GPIO line 4 as input");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-sensor2") < 0) {
        perror("Failed to request GPIO line 17 as input");
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO4 and GPIO17. Press Ctrl+C to exit.\n");

    while (program_running) {
        int s1 = read_sensor(line1);
        int s2 = read_sensor(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        printf("Sensor 1: %d, Sensor 2: %d\n", s1, s2);

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

