#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <syslog.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define DEBOUNCE_DELAY_US 200000 /* 200 ms */
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_QUALITY 85
#define CAPTURE_DIR "/home/pi/security_cam"
#define MAX_PATH_LEN 512

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/*
 * Generate an ISO 8601 timestamp string (local time, no milliseconds).
 * Returns 0 on success, -1 on failure.
 */
static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        syslog(LOG_ERR, "time() failed");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return -1;
    }
    if (strftime(buf, len, "%Y%m%dT%H%M%S", &timeinfo) == 0) {
        syslog(LOG_ERR, "strftime() failed: buffer too small");
        return -1;
    }
    return 0;
}

/*
 * Build a safe path for the captured image.
 * Returns 0 on success, -1 on failure.
 */
static int build_image_path(char *path, size_t len, const char *timestamp) {
    if (snprintf(path, len, "%s/motion_%s.jpg", CAPTURE_DIR, timestamp) >= (int)len) {
        syslog(LOG_ERR, "Image path truncated");
        return -1;
    }
    return 0;
}

/*
 * Capture a JPEG image using libcamera-still.
 * Returns 0 on success, -1 on failure.
 */
static int capture_image(const char *path) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed");
        return -1;
    }

    if (pid == 0) {
        /* Child process */
        char width_str[16], height_str[16], quality_str[16];
        snprintf(width_str, sizeof(width_str), "%d", IMAGE_WIDTH);
        snprintf(height_str, sizeof(height_str), "%d", IMAGE_HEIGHT);
        snprintf(quality_str, sizeof(quality_str), "%d", IMAGE_QUALITY);

        char *argv[] = {
            "libcamera-still",
            "-o", (char *)path,
            "--width", width_str,
            "--height", height_str,
            "--quality", quality_str,
            "--nopreview",
            NULL
        };

        execvp("libcamera-still", argv);

        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execvp(libcamera-still) failed");
        _exit(127);
    }

    /* Parent process */
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid() failed");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still exited with status %d",
           WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

/*
 * Ensure the capture directory exists.
 * Returns 0 on success, -1 on failure.
 */
static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        syslog(LOG_ERR, "%s exists but is not a directory", CAPTURE_DIR);
        return -1;
    }

    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "Failed to create directory %s", CAPTURE_DIR);
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure PIR GPIO as input with pull-down */
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    /* Ensure capture directory exists */
    if (ensure_capture_dir() != 0) {
        syslog(LOG_ERR, "Capture directory not available; exiting");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on BCM GPIO%d, %dx%d JPEG)",
           PIR_GPIO, IMAGE_WIDTH, IMAGE_HEIGHT);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO%d", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state != last_state) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            int confirmed_state = gpioRead(PIR_GPIO);
            if (confirmed_state < 0) {
                syslog(LOG_ERR, "Debounce gpioRead failed on GPIO%d", PIR_GPIO);
                last_state = current_state;
                continue;
            }

            if (confirmed_state == current_state) {
                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);

                    char timestamp[32];
                    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                        syslog(LOG_ERR, "Failed to generate timestamp");
                        last_state = current_state;
                        continue;
                    }

                    char image_path[MAX_PATH_LEN];
                    if (build_image_path(image_path, sizeof(image_path), timestamp) != 0) {
                        syslog(LOG_ERR, "Failed to build image path");
                        last_state = current_state;
                        continue;
                    }

                    syslog(LOG_INFO, "Capturing image: %s", image_path);

                    if (capture_image(image_path) == 0) {
                        syslog(LOG_INFO, "Image captured successfully: %s", image_path);
                    } else {
                        syslog(LOG_ERR, "Failed to capture image: %s", image_path);
                    }
                }
                last_state = current_state;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Security camera shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

