#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS 4
#define OUTPUT_FILE "image.jpg"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        return -1;
    }
    if (fmt.fmt.pix.width != IMAGE_WIDTH || fmt.fmt.pix.height != IMAGE_HEIGHT) {
        fprintf(stderr, "Device did not accept exact resolution: %ux%u\n",
                fmt.fmt.pix.width, fmt.fmt.pix.height);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }
    return 0;
}

static int init_mmap(int fd, struct v4l2_buffer *buffers, size_t *buf_size) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF failed");
            return -1;
        }
        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap failed");
            return -1;
        }
    }
    *buf_size = buffers[0].length;
    return 0;
}

static int start_streaming(int fd, struct v4l2_buffer *buffers) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF failed");
            return -1;
        }
    }
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }
    return 0;
}

static int capture_image(int fd, struct v4l2_buffer *buffers, size_t buf_size, FILE *fp) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) {
            fprintf(stderr, "Timeout waiting for frame\n");
            return -1;
        }
        perror("VIDIOC_DQBUF failed");
        return -1;
    }
    if (buf.index >= NUM_BUFFERS) {
        fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
        return -1;
    }
    if (buf.bytesused == 0) {
        fprintf(stderr, "Empty frame received\n");
        return -1;
    }
    if (buf.bytesused > buf_size) {
        fprintf(stderr, "Frame size exceeds buffer size: %u > %zu\n", buf.bytesused, buf_size);
        return -1;
    }
    if (fwrite(buffers[buf.index].start, 1, buf.bytesused, fp) != buf.bytesused) {
        perror("fwrite failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }
    return 0;
}

static void cleanup(int fd, struct v4l2_buffer *buffers, int buffers_mapped) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF failed");
        }
    }
    if (buffers_mapped) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i].start != NULL && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
    }
}

int main(void) {
    int fd = -1;
    struct v4l2_buffer buffers[NUM_BUFFERS];
    size_t buf_size = 0;
    int buffers_mapped = 0;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    memset(buffers, 0, sizeof(buffers));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT) failed");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM) failed");
        goto cleanup;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ") failed");
        goto cleanup;
    }

    if (init_camera(fd) < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        goto cleanup;
    }

    if (init_mmap(fd, buffers, &buf_size) < 0) {
        fprintf(stderr, "MMAP initialization failed\n");
        goto cleanup;
    }
    buffers_mapped = 1;

    if (start_streaming(fd, buffers) < 0) {
        fprintf(stderr, "Streaming start failed\n");
        goto cleanup;
    }

    fp = fopen(OUTPUT_FILE, "wb");
    if (fp == NULL) {
        perror("fopen(" OUTPUT_FILE ") failed");
        goto cleanup;
    }

    printf("Capturing image from %s to %s...\n", DEVICE_NAME, OUTPUT_FILE);
    if (capture_image(fd, buffers, buf_size, fp) < 0) {
        fprintf(stderr, "Image capture failed\n");
        goto cleanup;
    }

    printf("Image saved successfully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    cleanup(fd, buffers, buffers_mapped);
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

