#define PWM_PERIOD_NS 20000000  /* 20 ms = 50 Hz */
#define MIN_PULSE_NS 1000000    /* 1 ms */
#define MAX_PULSE_NS 2000000    /* 2 ms */
#define MIN_DUTY 50
#define MAX_DUTY 1000
#define MID_DUTY 750
