#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75
#define SELECT_TIMEOUT_SEC 2

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static volatile sig_atomic_t stop_flag = 0;
static int fd = -1;
static buffer_t *buffers = NULL;
static unsigned int n_buffers = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Camera does not support YUYV format\n");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        fd = -1;
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        fd = -1;
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            buffers[n_buffers].start = NULL;
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    return 0;

cleanup:
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    free(buffers);
    buffers = NULL;
    n_buffers = 0;
    close(fd);
    fd = -1;
    return -1;
}

static int capture_frame(unsigned char *yuyv_frame) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = SELECT_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= n_buffers) {
        fprintf(stderr, "Invalid buffer index\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    memcpy(yuyv_frame, buffers[buf.index].start, buf.bytesused);

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int y = yuyv[i * width * 2 + j * 2];
            int u = yuyv[i * width * 2 + j * 2 + 1] - 128;
            int v = yuyv[i * width * 2 + j * 2 + 3] - 128;

            int r = y + (v * 454) / 1000;
            int g = y - (u * 88) / 1000 - (v * 183) / 1000;
            int b = y + (u * 454) / 1000;

            if (r < 0) r = 0; if (r > 255) r = 255;
            if (g < 0) g = 0; if (g > 255) g = 255;
            if (b < 0) b = 0; if (b > 255) b = 255;

            rgb[(i * width + j) * 3] = (unsigned char)r;
            rgb[(i * width + j) * 3 + 1] = (unsigned char)g;
            rgb[(i * width + j) * 3 + 2] = (unsigned char)b;
        }
    }
}

static void apply_blur(const unsigned char *src, unsigned char *dst, int width, int height) {
    int radius = BLUR_RADIUS;
    int kernel_size = (2 * radius + 1);
    int kernel_sum = kernel_size * kernel_size;

    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            int sum_r = 0, sum_g = 0, sum_b = 0;
            int count = 0;

            for (int k = -radius; k <= radius; ++k) {
                for (int l = -radius; l <= radius; ++l) {
                    int x = j + l;
                    int y = i + k;

                    if (x >= 0 && x < width && y >= 0 && y < height) {
                        int idx = (y * width + x) * 3;
                        sum_r += src[idx];
                        sum_g += src[idx + 1];
                        sum_b += src[idx + 2];
                        count++;
                    }
                }
            }

            int idx = (i * width + j) * 3;
            dst[idx] = (unsigned char)(sum_r / count);
            dst[idx + 1] = (unsigned char)(sum_g / count);
            dst[idx + 2] = (unsigned char)(sum_b / count);
        }
    }
}

static int save_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)(rgb + cinfo.next_scanline * width * 3);
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

static void cleanup_camera(void) {
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);

        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
        buffers = NULL;
        n_buffers = 0;

        close(fd);
        fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera() != 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    unsigned char *yuyv_frame = malloc(WIDTH * HEIGHT * 2);
    unsigned char *rgb_frame = malloc(WIDTH * HEIGHT * 3);
    unsigned char *blurred_rgb = malloc(WIDTH * HEIGHT * 3);

    if (!yuyv_frame || !rgb_frame || !blurred_rgb) {
        fprintf(stderr, "Memory allocation failed\n");
        free(yuyv_frame);
        free(rgb_frame);
        free(blurred_rgb);
        cleanup_camera();
        return 1;
    }

    printf("Capturing frame...\n");

    if (capture_frame(yuyv_frame) != 0) {
        fprintf(stderr, "Frame capture failed\n");
        free(yuyv_frame);
        free(rgb_frame);
        free(blurred_rgb);
        cleanup_camera();
        return 1;
    }

    yuyv_to_rgb24(yuyv_frame, rgb_frame, WIDTH, HEIGHT);
    apply_blur(rgb_frame, blurred_rgb, WIDTH, HEIGHT);

    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

