static void print_frame_sizes(int fd)
{
    struct v4l2_frmsizeenum fsize;
    memset(&fsize, 0, sizeof(fsize));
    fsize.index = 0;
    fsize.pixel_format = V4L2_PIX_FMT_JPEG;

    printf("Supported frame sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize) == 0) {
        if (fsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %ux%u\n", fsize.discrete.width, fsize.discrete.height);
        } else if (fsize.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  %ux%u - %ux%u (step %u)\n",
                   fsize.stepwise.min_width, fsize.stepwise.min_height,
                   fsize.stepwise.max_width, fsize.stepwise.max_height,
                   fsize.stepwise.step_width);
        }
        fsize.index++;
    }
    if (errno != EINVAL) {
        perror("VIDIOC_ENUM_FRAMESIZES");
    }
}

static void print_frame_intervals(int fd, unsigned int width, unsigned int height)
{
    struct v4l2_frmivalenum fival;
    memset(&fival, 0, sizeof(fival));
    fival.index = 0;
    fival.pixel_format = V4L2_PIX_FMT_JPEG;
    fival.width = width;
    fival.height = height;

    printf("Supported frame intervals for %ux%u:\n", width, height);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fival) == 0) {
        if (fival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("  %u/%u fps\n",
                   fival.discrete.numerator, fival.discrete.denominator);
        } else if (fival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("  %u/%u - %u/%u fps (step %u/%u)\n",
                   fival.stepwise.min.numerator, fival.stepwise.min.denominator,
                   fival.stepwise.max.numerator, fival.stepwise.max.denominator,
                   fival.stepwise.step.numerator, fival.stepwise.step.denominator);
        }
        fival.index++;
    }
    if (errno != EINVAL) {
        perror("VIDIOC_ENUM_FRAMEINTERVALS");
    }
}

static int has_autofocus(int fd)
{
    struct v4l2_queryctrl query;
    memset(&query, 0, sizeof(query));
    query.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &query) == -1) {
        if (errno == EINVAL) {
            return 0;
        }
        perror("VIDIOC_QUERYCTRL (focus)");
        return -1;
    }
    return 1;
}

int main(void)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera capabilities:\n");
    printf("  Card: %s\n", cap.card);
    printf("  Driver: %s\n", cap.driver);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Version: %u.%u.%u\n",
           (cap.version >> 16) & 0xFF,
           (cap.version >> 8) & 0xFF,
           cap.version & 0xFF);

    print_frame_sizes(fd);

    int has_focus = has_autofocus(fd);
    if (has_focus < 0) {
        close(fd);
        return EXIT_FAILURE;
    }
    printf("Autofocus: %s\n", has_focus ? "yes" : "no");

    close(fd);
    return EXIT_SUCCESS;
}

