#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_TIME_MS 2000
#define POLL_INTERVAL_MS 100
#define CAPTURE_DIR "motion_captures"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define MAX_FILENAME_LEN 256
#define MAX_PAYLOAD_LEN 512

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o '%s' --width %d --height %d --quality %d --nopreview",
        filename, CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *server_ip, int server_port, const char *filename,
                     const char *timestamp, int motion_status, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }

    char url[256];
    int ret = snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(url)) {
        fprintf(stderr, "Error: URL buffer too small\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    char payload[MAX_PAYLOAD_LEN];
    ret = snprintf(payload, sizeof(payload),
        "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_status\":%d,\"gpio_pin\":%d}",
        filename, timestamp, motion_status, gpio_pin);
    if (ret < 0 || (size_t)ret >= sizeof(payload)) {
        fprintf(stderr, "Error: payload buffer too small\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "Error: HTTP response code: %ld\n", http_code);
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return (res == CURLE_OK && http_code == 200) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO%d\n", PIR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ensure_directory(CAPTURE_DIR) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        fprintf(stderr, "Error: curl_global_init() failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        curl_global_cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    int last_motion_state = 0;
    uint32_t last_motion_time_ms = 0;

    while (!terminate) {
        int motion_detected = gpioRead(PIR_GPIO);
        if (motion_detected < 0) {
            fprintf(stderr, "Error: Failed to read GPIO%d\n", PIR_GPIO);
            break;
        }

        uint32_t now_ms = gpioTick() / 1000;

        if (motion_detected && !last_motion_state) {
            if (now_ms - last_motion_time_ms >= DEBOUNCE_TIME_MS) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[32];
                char filename[MAX_FILENAME_LEN];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                if (!timeinfo) {
                    perror("localtime");
                    break;
                }

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                snprintf(filename, sizeof(filename), "%s/%s_%06ld.jpg",
                         CAPTURE_DIR, timestamp, (long)(nowtime.tv_nsec / 1000));

                if (capture_image(filename) == 0) {
                    if (send_data(server_ip, server_port, filename, timestamp, 1, PIR_GPIO) != 0) {
                        fprintf(stderr, "Warning: Failed to send data for motion event\n");
                    } else {
                        printf("Motion detected at %s, captured %s\n", timestamp, filename);
                    }
                } else {
                    fprintf(stderr, "Warning: Failed to capture image\n");
                }

                last_motion_time_ms = now_ms;
            }
        }

        last_motion_state = motion_detected;
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
}

