#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static int generate_filename(char *buf, size_t buf_size) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        return -1;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return -1;
    }
    int ms = (int)(ts.tv_nsec / 1000000);
    if (snprintf(buf, buf_size, "%s/%04d%02d%02d_%02d%02d%02d_%03d.jpg",
                 IMAGE_DIR,
                 tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec, ms) >= (int)buf_size) {
        return -1;
    }
    return 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
                       "libcamera-still -o '%s' --width 640 --height 480 -q 85 --timeout %d --nopreview",
                       filename, CAPTURE_TIMEOUT_MS);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion-capture") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    log_event("Motion capture system started.");

    while (program_running) {
        struct timespec ts = { .tv_sec = POLL_TIMEOUT_MS / 1000, .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            log_event("Error waiting for GPIO event.");
            break;
        }
        if (ev == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            log_event("Error reading GPIO event.");
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        struct timespec debounce_ts = { .tv_sec = 0, .tv_nsec = DEBOUNCE_MS * 1000000L };
        nanosleep(&debounce_ts, NULL);

        char filename[256];
        if (generate_filename(filename, sizeof(filename)) != 0) {
            fprintf(stderr, "Failed to generate filename\n");
            log_event("Failed to generate filename.");
            continue;
        }

        printf("Motion detected! Capturing image: %s\n", filename);
        log_event("Motion detected.");

        if (capture_image(filename) == 0) {
            printf("Image saved: %s\n", filename);
            log_event("Image saved.");
        } else {
            fprintf(stderr, "Failed to capture image\n");
            log_event("Failed to capture image.");
        }
    }

    log_event("Motion capture system stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

