        return -1;
    }

    memset(&cap, 0, sizeof(cap));
    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.width != WIDTH || fmt.fmt.pix.height != HEIGHT) {
        fprintf(stderr, "Camera did not accept %dx%d format\n", WIDTH, HEIGHT);
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.index >= NUM_BUFFERS) {
        fprintf(stderr, "Invalid buffer index %u\n", buf.index);
        return -1;
    }

    *buffer = (unsigned char *)buf.m.offset;
    *buffer_size = buf.bytesused;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            return 0;
        }
        perror("select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    return 1;
}

static int crop_and_save(const unsigned char *frame, int width, int height,
                         int crop_x, int crop_y, int crop_width, int crop_height,
                         const char *output_file) {
    FILE *fp = fopen(output_file, "wb");
    if (!fp) {
        perror("fopen(" OUTPUT_FILE ")");
        return -1;
    }

    if (crop_x < 0 || crop_y < 0 || crop_x + crop_width > width || crop_y + crop_height > height) {
        fprintf(stderr, "Crop region out of bounds\n");
        fclose(fp);
        return -1;
    }

    for (int y = crop_y; y < crop_y + crop_height; y++) {
        for (int x = crop_x; x < crop_x + crop_width; x++) {
            int src_offset = (y * width + x) * 2;
            int dst_offset = ((y - crop_y) * crop_width + (x - crop_x)) * 2;
            if (fwrite(frame + src_offset, 2, 1, fp) != 1) {
                perror("fwrite");
                fclose(fp);
                return -1;
            }
        }
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_camera(&fd) != 0) {
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    printf("Capturing frame...\n");

    int rc = capture_frame(fd, &buffer, &buffer_size);
    if (rc == 0) {
        printf("Interrupted by signal\n");
        goto cleanup;
    } else if (rc < 0) {
        goto cleanup;
    }

    printf("Frame captured: %zu bytes\n", buffer_size);

    if (crop_and_save(buffer, WIDTH, HEIGHT, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT, OUTPUT_FILE) != 0) {
        goto cleanup;
    }

    printf("Cropped frame saved to %s\n", OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
        close(fd);
    }
    return ret;
}

