#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define STEP_SIZE 5
#define PWM_FREQUENCY 50
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        keep_running = 0;
    }
}

int angle_to_pulse_width(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) / (MAX_ANGLE - MIN_ANGLE);
}

int set_servo_angle(int gpio, int angle) {
    int pulse_width = angle_to_pulse_width(angle);
    if (pulse_width < 0) {
        return -1;
    }
    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    if (gpioSetMode(PAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PAN_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(TILT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", TILT_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Failed to set PWM frequency on GPIO %d\n", PAN_GPIO);
    }
    if (gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Failed to set PWM frequency on GPIO %d\n", TILT_GPIO);
    }

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Pan-Tilt Camera Control (GPIO%d=Pan, GPIO%d=Tilt)\n", PAN_GPIO, TILT_GPIO);
    printf("Use arrow keys (up, down, left, right) to adjust. Press 'q' to quit.\n");

    while (keep_running) {
        int c = getchar();
        if (c == EOF) {
            break;
        }

        switch (c) {
            case 'q':
                keep_running = 0;
                break;
            case '\n':
                break;
            case '\r':
                break;
            case 65: // Up arrow
                tilt_angle += STEP_SIZE;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set tilt angle\n");
                }
                printf("Tilt: %d degrees\n", tilt_angle);
                break;
            case 66: // Down arrow
                tilt_angle -= STEP_SIZE;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set tilt angle\n");
                }
                printf("Tilt: %d degrees\n", tilt_angle);
                break;
            case 68: // Left arrow
                pan_angle -= STEP_SIZE;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan angle\n");
                }
                printf("Pan: %d degrees\n", pan_angle);
                break;
            case 67: // Right arrow
                pan_angle += STEP_SIZE;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error: Failed to set pan angle\n");
                }
                printf("Pan: %d degrees\n", pan_angle);
                break;
            default:
                printf("Invalid input. Use arrow keys or 'q'.\n");
                break;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    // Cleanup: set servos to neutral position
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

