#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_ON 0x04
#define LCD_OFF 0x00
#define LCD_CLEAR 0x01

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_handle = -1;

// Function prototypes
void signal_handler(int signal);
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulse_count, float time_interval);
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_init();
void lcd_clear();
void lcd_display_data(float flow_rate, float total_volume);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    int *pulse_count = (int *)user_data;
    if (level == 1) { // Rising edge
        (*pulse_count)++;
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulse_count, float time_interval) {
    return (float)pulse_count / PULSES_PER_LITER / (time_interval / 60.0);
}

// Function to send a byte to the LCD
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    gpioWrite(12, bits_high);
    gpioWrite(13, bits_high | LCD_ENABLE);
    gpioDelay(1);
    gpioWrite(13, bits_high & ~LCD_ENABLE);
    gpioDelay(100);

    gpioWrite(12, bits_low);
    gpioWrite(13, bits_low | LCD_ENABLE);
    gpioDelay(1);
    gpioWrite(13, bits_low & ~LCD_ENABLE);
    gpioDelay(100);
}

// Function to send a string to the LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Function to initialize the LCD
void lcd_init() {
    gpioSetMode(12, PI_OUTPUT);
    gpioSetMode(13, PI_OUTPUT);
    gpioDelay(50000); // Wait for LCD to power up

    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD); // 2 lines, 5x8 font
    lcd_byte(0x0C, LCD_CMD); // Display on, cursor off, blink off
    lcd_byte(0x06, LCD_CMD); // Entry mode set
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(2000);
}

// Function to clear the LCD
void lcd_clear() {
    lcd_byte(LCD_CLEAR, LCD_CMD);
    gpioDelay(2000);
}

// Function to display data on the LCD
void lcd_display_data(float flow_rate, float total_volume) {
    char buffer[LCD_WIDTH + 1];

    lcd_clear();
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
    lcd_string(buffer);
    lcd_byte(LCD_LINE_2, LCD_CMD);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    lcd_string(buffer);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    // Initialize I2C for LCD
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    lcd_init();

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pulse count
    int pulse_count = 0;

    // Initialize time variables
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Main loop
    while (program_running) {
        // Read current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate time interval in seconds
        float time_interval = (current_time.tv_sec - start_time.tv_sec) +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count, time_interval);

        // Display data on console
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, (float)pulse_count / PULSES_PER_LITER);

        // Update LCD every 10 seconds
        if (time_interval >= 10.0) {
            lcd_display_data(flow_rate, (float)pulse_count / PULSES_PER_LITER);
            start_time = current_time;
        }

        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    lcd_clear();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

