    lcd_byte(0x28, LCD_CMD); // 2 lines, 5x8 font
    lcd_byte(0x0C, LCD_CMD); // Display on, cursor off, blink off
    lcd_byte(0x06, LCD_CMD); // Entry mode set
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(2000);
}

// Function to clear the LCD
void lcd_clear() {
    lcd_byte(LCD_CLEAR, LCD_CMD);
    gpioDelay(2000);
}

// Function to display data on the LCD
void lcd_display_data(float flow_rate, float total_volume) {
    char buffer[LCD_WIDTH + 1];

    lcd_clear();
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", flow_rate);
    lcd_string(buffer);
    lcd_byte(LCD_LINE_2, LCD_CMD);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    lcd_string(buffer);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    // Initialize I2C for LCD
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    lcd_init();

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pulse count
    int pulse_count = 0;

    // Initialize time variables
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Main loop
    while (program_running) {
        // Read current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate time interval in seconds
        float time_interval = (current_time.tv_sec - start_time.tv_sec) +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count, time_interval);

        // Display data on console
        printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, (float)pulse_count / PULSES_PER_LITER);

        // Update LCD every 10 seconds
        if (time_interval >= 10.0) {
            lcd_display_data(flow_rate, (float)pulse_count / PULSES_PER_LITER);
            start_time = current_time;
        }

        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup
    lcd_clear();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

