/*
 * Wind speed and direction monitor for Raspberry Pi 4 Model B
 * Library: pigpio (no wiringPi)
 *
 * Hardware:
 *   - 16x2 LCD via PCF8574 I2C backpack at address 0x27, bus 1
 *   - Anemometer: 4-wire magnet on GPIO17, rising-edge interrupt
 *   - Wind vane: MCP3008 ADC on SPI0/CE0, channel 0
 *
 * Build: gcc -O2 -Wall -o wind_monitor wind_monitor.c -lpigpio -lrt
 * Run:   sudo ./wind_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define I2C_ADDR             0x27          /* PCF8574 backpack */

#define SPI_CHANNEL          0             /* SPI0 CE0 */
#define SPI_SPEED            1000000       /* 1 MHz */
#define SPI_FLAGS            0             /* Mode 0, active-low CE */

#define ANEMOMETER_GPIO      17
#define PULSES_PER_M_S       0.5f
#define SAMPLE_PERIOD_US     500000        /* 500 ms */

#define LCD_WIDTH            16
#define LCD_HEIGHT           2

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  lcd_init(void);
static void lcd_clear(void);
static void lcd_set_cursor(int col, int row);
static void lcd_print(const char *s);
static void lcd_update(float wind_speed, int wind_direction);
static int  read_wind_vane(void);
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);

/* ----------------------------- Signal handler ---------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- LCD helpers -------------------------------- */

/*
 * PCF8574 bit-bang I2C driver (pigpio bit-banging via bbI2COpen).
 * PCF8574 control byte: [EN][RW][RS][D7][D6][D5][D4][0]
 * EN = 1 for enable pulse, RW = 0 (write), RS = 0 (command), RS = 1 (data).
 */

static int lcd_init(void)
{
    int handle = bbI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "bbI2COpen failed (pigpio error %d): %s\n",
                handle, strerror(errno));
        return -1;
    }
    return handle;
}

static void lcd_clear(void)
{
    /* Command 0x01: clear display, cursor home */
    bbI2CWriteByte(g_lcd_handle, 0x01);
    gpioDelay(2000); /* 2 ms */
}

static void lcd_set_cursor(int col, int row)
{
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    addr += (uint8_t)col;
    bbI2CWriteByte(g_lcd_handle, addr);
}

static void lcd_print(const char *s)
{
    for (int i = 0; s[i] != '\0'; i++) {
        bbI2CWriteByte(g_lcd_handle, (uint8_t)s[i] | 0x01); /* RS=1 */
        gpioDelay(100); /* 100 us */
    }
}

static void lcd_update(float wind_speed, int wind_direction)
{
    char line1[LCD_WIDTH + 1];
    char line2[LCD_WIDTH + 1];

    snprintf(line1, sizeof(line1), "Speed: %.2f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Dir: %3d deg", wind_direction);

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(line1);
    lcd_set_cursor(0, 1);
    lcd_print(line2);
}

/* ----------------------------- Wind vane ---------------------------------- */

/*
 * MCP3008 single-ended read via SPI bit-banging.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_wind_vane(void)
{
    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low 2 bits)
     * Result: bits 9..0 in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | SPI_CHANNEL) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = bbSPIXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "bbSPIXfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];

    /* Sensor-absent / wiring fault detection */
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n",
                adc_value);
        return -1;
    }

    return adc_value;
}

/* ----------------------------- Anemometer ISR ---------------------------- */

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI for MCP3008 --- */
    g_spi_handle = bbSPIOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "bbSPIOpen failed (pigpio error %d): %s\n",
                g_spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C for PCF8574 --- */
    g_lcd_handle = lcd_init();
    if (g_lcd_handle < 0) {
        bbSPIClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure anemometer GPIO --- */
    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", ANEMOMETER_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", ANEMOMETER_GPIO);
        goto cleanup;
    }
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", ANEMOMETER_GPIO);
        goto cleanup;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Main loop --- */
    while (g_running) {
        /* Reset pulse counter for this sample window */
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        /* Read wind vane */
        int adc_value = read_wind_vane();
        int wind_direction = -1;
        if (adc_value >= 0) {
            wind_direction = (int)(((float)adc_value / 1023.0f) * 360.0f);
            if (wind_direction >= 360) wind_direction -= 360;
        }

        /* Compute wind speed */
        float wind_speed = (float)pulses * PULSES_PER_M_S;

        /* Update display */
        lcd_update(wind_speed, wind_direction);

        /* Wait for next sample window */
        gpioDelay(SAMPLE_PERIOD_US);
    }

cleanup:
    /* --- Graceful shutdown --- */
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL); /* unregister ISR */
    lcd_clear();
    lcd_print("Shutting down...");
    gpioDelay(1000000); /* 1 s */

    if (g_lcd_handle >= 0) bbI2CClose(g_lcd_handle);
    if (g_spi_handle >= 0) bbSPIClose(g_spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

