#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 7.5
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define LCD_ENABLE 0x04
#define LCD_ON 0x04
#define LCD_OFF 0x00
#define LCD_CLEAR 0x01

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static int i2c_handle = -1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int col, int row);
void lcd_print_flow_rate(float flow_rate);

// Pulse counter callback function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;
    pulse_count++;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Send byte to LCD
void lcd_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    gpioWrite(12, bits_high);
    gpioWrite(13, bits_high & ~LCD_ENABLE);
    gpioDelay(1);
    gpioWrite(13, bits_high | LCD_ENABLE);
    gpioDelay(100);

    gpioWrite(12, bits_low);
    gpioWrite(13, bits_low & ~LCD_ENABLE);
    gpioDelay(1);
    gpioWrite(13, bits_low | LCD_ENABLE);
    gpioDelay(100);
}

// Send string to LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Initialize LCD
void lcd_init() {
    gpioSetMode(12, PI_OUTPUT);
    gpioSetMode(13, PI_OUTPUT);
    gpioDelay(50000);

    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(2000);
}

// Clear LCD display
void lcd_clear() {
    lcd_byte(LCD_CLEAR, LCD_CMD);
    gpioDelay(2000);
}

// Set cursor position
void lcd_set_cursor(int col, int row) {
    int address = (row == 0) ? LCD_LINE_1 : LCD_LINE_2;
    address += col;
    lcd_byte(address, LCD_CMD);
}

// Print flow rate to LCD
void lcd_print_flow_rate(float flow_rate) {
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string("Flow Rate:");
    lcd_set_cursor(0, 1);
    char buffer[17];
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_string(buffer);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up pulse counter
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    time_t last_time = time(NULL);
    int zero_pulse_count = 0;

    while (running) {
        time_t current_time = time(NULL);
        if (current_time - last_time >= 1) {
            int pulses = pulse_count;
            pulse_count = 0;
            last_time = current_time;

            float flow_rate = (float)pulses / PULSES_PER_LITER * 60.0;

            // Check for sensor-absent condition (no pulses for extended period)
            if (pulses == 0) {
                zero_pulse_count++;
                if (zero_pulse_count > 5) {
                    fprintf(stderr, "Warning: No pulses detected for 5 seconds. Sensor may be disconnected.\n");
                    lcd_clear();
                    lcd_set_cursor(0, 0);
                    lcd_string("Sensor Error");
                    lcd_set_cursor(0, 1);
                    lcd_string("Check wiring");
                    zero_pulse_count = 0; // Reset to avoid repeated warnings
                }
            } else {
                zero_pulse_count = 0;
                lcd_print_flow_rate(flow_rate);
            }
        }
        gpioDelay(100000); // 100ms delay to prevent busy-waiting
    }

