#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SCAN_DELAY_US 800
#define NUM_ROWS 8
#define NUM_COLS 8

// BCM GPIO numbers for rows (anodes) and columns (cathodes)
const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void cleanup_resources(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %d (GPIO%d)\n", i, row_pins[i]);
            cleanup_resources();
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %d as output\n", i);
            cleanup_resources();
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %d (GPIO%d)\n", i, col_pins[i]);
            cleanup_resources();
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led-matrix", 1) < 0) {
            fprintf(stderr, "Failed to request column line %d as output\n", i);
            cleanup_resources();
            return -1;
        }
    }

    return 0;
}

void scan_display(const int pattern[NUM_ROWS][NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        // Turn off all rows
        for (int r = 0; r < NUM_ROWS; r++) {
            gpiod_line_set_value(row_lines[r], 0);
        }
        // Turn on current row (anode HIGH)
        gpiod_line_set_value(row_lines[row], 1);

        // Set column values for this row
        for (int col = 0; col < NUM_COLS; col++) {
            gpiod_line_set_value(col_lines[col], pattern[row][col]);
        }

        usleep(SCAN_DELAY_US);
    }
}

void left_to_right_wave(int pattern[NUM_ROWS][NUM_COLS]) {
    for (int shift = 0; shift < NUM_ROWS; shift++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            for (int col = 0; col < NUM_COLS; col++) {
                pattern[row][col] = (row + shift) % NUM_ROWS == col ? 1 : 0;
            }
        }
        scan_display(pattern);
        if (!keep_running) break;
    }
}

void right_to_left_wave(int pattern[NUM_ROWS][NUM_COLS]) {
    for (int shift = 0; shift < NUM_ROWS; shift++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            for (int col = 0; col < NUM_COLS; col++) {
                pattern[row][col] = (NUM_ROWS - 1 - row + shift) % NUM_ROWS == col ? 1 : 0;
            }
        }
        scan_display(pattern);
        if (!keep_running) break;
    }
}

int main(void) {
    signal(SIGINT, cleanup_and_exit);

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int pattern[NUM_ROWS][NUM_COLS];

    while (keep_running) {
        left_to_right_wave(pattern);
        if (!keep_running) break;
        right_to_left_wave(pattern);
    }

    cleanup_resources();
    return EXIT_SUCCESS;
}

