#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

// GPIO pins for row anodes (common anode)
const int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
// GPIO pins for column cathodes (common cathode)
const int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void cleanup_gpio(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_set_value(row_lines[i], 0);
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_set_value(col_lines[i], 1);
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Set up signal handlers for clean exit
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Open GPIO chip 0 (Raspberry Pi GPIO controller)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request row lines as outputs, initially LOW (all anodes off)
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %d\n", row_pins[i]);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(row_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %d as output\n", row_pins[i]);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
    }

    // Request column lines as outputs, initially HIGH (all cathodes off)
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %d\n", col_pins[i]);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(col_lines[i], "led-matrix", 1) < 0) {
            fprintf(stderr, "Failed to request column line %d as output\n", col_pins[i]);
            cleanup_gpio();
            return EXIT_FAILURE;
        }
    }

    printf("LED matrix wave animation started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Scan columns from left to right
        for (int col = 0; col < NUM_COLS && keep_running; col++) {
            // Clear matrix: set all columns HIGH (cathodes off) and all rows LOW (anodes off)
            for (int i = 0; i < NUM_COLS; i++) {
                gpiod_line_set_value(col_lines[i], 1);
            }
            for (int i = 0; i < NUM_ROWS; i++) {
                gpiod_line_set_value(row_lines[i], 0);
            }

            // Light the current column: set column cathode LOW (active)
            gpiod_line_set_value(col_lines[col], 0);

            // Delay for the specified duration
            usleep(DELAY_MS * 1000);
        }
    }

    // Cleanup
    cleanup_gpio();
    printf("LED matrix wave animation stopped.\n");
    return EXIT_SUCCESS;
}

