#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1145 I2C address (ADDR pin tied to GND) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_REV_ID       0x01
#define SI1145_REG_SEQ_ID       0x02
#define SI1145_REG_INT_CFG      0x03
#define SI1145_REG_IRQ_ENABLE   0x04
#define SI1145_REG_IRQ_MODE1    0x05
#define SI1145_REG_IRQ_MODE2    0x06
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_PS_RATE      0x0A
#define SI1145_REG_PS_LED21     0x0F
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_ALS_IR_DATA1  0x25
#define SI1145_REG_PS1_DATA0    0x26
#define SI1145_REG_PS1_DATA1    0x27
#define SI1145_REG_COMMAND      0x18

/* Si1145 command codes */
#define SI1145_CMD_RESET        0x01
#define SI1145_CMD_PSALS_AUTO   0x0F

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID_EXPECTED 0x45

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a Si1145 register                                   */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a Si1145 register                                  */
/* ------------------------------------------------------------------ */
static int si1145_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X (pigpio rc=%d)\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers    */
/* ------------------------------------------------------------------ */
static int si1145_read_word(int handle, uint8_t reg_low)
{
    int lo = si1145_read_reg(handle, reg_low);
    if (lo < 0)
        return -1;
    int hi = si1145_read_reg(handle, reg_low + 1);
    if (hi < 0)
        return -1;
    return (hi << 8) | lo;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1145 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1145_init(int handle)
{
