#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Si1145 I2C address (ADDR pin tied to GND) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_PS_RATE      0x0A
#define SI1145_REG_PS_LED21     0x0F
#define SI1145_REG_CH_LIST      0x4F
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0    0x18
#define SI1145_REG_PS1_DATA1    0x19
#define SI1145_REG_COMMAND      0x30

/* Si1145 command codes */
#define SI1145_CMD_ALS_FORCE    0x06
#define SI1145_CMD_PS_FORCE     0x07

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID_EXPECTED 0x45

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a Si1145 register; returns 0 on success, -1 on error */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, strerror(errno));
    }
    return rc;
}

/* Read a byte from a Si1145 register; returns value (0-255) on success, -1 on error */
static int si1145_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

/* Initialize the Si1145 sensor; returns 0 on success, -1 on error */
static int si1145_init(int handle) {
    int part_id;

    /* Verify sensor presence by reading PART_ID */
    part_id = si1145_read_reg(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID - sensor may be absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1145 detected (PART_ID = 0x%02X)\n", part_id);

    /* Write HW_KEY to enable the device */
    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        return -1;
    }

    /* Configure measurement rates */
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_PS_RATE, 0x00) < 0) return -1;
    if (si1145_write_reg(handle, SI1145_REG_PS_LED21, 0x03) < 0) return -1;

    /* Enable PS1 and ALS_VIS channels in CH_LIST */
    if (si1145_write_reg(handle, SI1145_REG_CH_LIST, 0x03) < 0) {
        return -1;
    }

    return 0;
}

/* Read proximity (PS1) data; returns 0 on success, -1 on error */
static int si1145_read_proximity(int handle, uint16_t *proximity) {
    int low, high;

    low = si1145_read_reg(handle, SI1145_REG_PS1_DATA0);
    if (low < 0) return -1;

    high = si1145_read_reg(handle, SI1145_REG_PS1_DATA1);
    if (high < 0) return -1;

    *proximity = (uint16_t)((high << 8) | low);
    return 0;
}

/* Read ambient light (ALS_VIS) data; returns 0 on success, -1 on error */
static int si1145_read_ambient_light(int handle, uint16_t *ambient_light) {
    int low, high;

    low = si1145_read_reg(handle, SI1145_REG_ALS_VIS_DATA0);
    if (low < 0) return -1;

    high = si1145_read_reg(handle, SI1145_REG_ALS_VIS_DATA1);
    if (high < 0) return -1;

    *ambient_light = (uint16_t)((high << 8) | low);
    return 0;
}

/* Trigger a forced ALS measurement; returns 0 on success, -1 on error */
static int si1145_trigger_als(int handle) {
    return si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE);
}

/* Trigger a forced PS measurement; returns 0 on success, -1 on error */
static int si1145_trigger_ps(int handle) {
    return si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE);
}

/* Log data to CSV file; returns 0 on success, -1 on error */
static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    uint16_t proximity, ambient_light;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si1145 address */
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize Si1145 sensor */
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Logging Si1145 data to biometric_data.log. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        /* Trigger forced measurements */
        if (si1145_trigger_als(i2c_handle) < 0) {
            fprintf(stderr, "Error triggering ALS measurement\n");
            break;
        }
        if (si1145_trigger_ps(i2c_handle) < 0) {
            fprintf(stderr, "Error triggering PS measurement\n");
            break;
        }

        /* Wait for measurements to complete (typical conversion time ~10ms) */
        gpioDelay(15000); /* 15ms */

        /* Read proximity and ambient light data */
        if (si1145_read_proximity(i2c_handle, &proximity) < 0) {
            fprintf(stderr, "Error reading proximity data\n");
            break;
        }
        if (si1145_read_ambient_light(i2c_handle, &ambient_light) < 0) {
            fprintf(stderr, "Error reading ambient light data\n");
            break;
        }

        /* Log the data */
        if (log_data(log_file, proximity, ambient_light) < 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        /* Wait 1 second before next reading */
        gpioDelay(1000000); /* 1 second */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

