#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define WATERING_THRESHOLD_CM 15.0
#define TIMEOUT_US 30000
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) && strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info)) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
    } else {
        fprintf(log_file, "[unknown-time]: %s\n", message);
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (trigger_line) {
        gpiod_line_set_value(trigger_line, 0);
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_both_edges_events(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line for edge events: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static double measure_distance(void) {
    struct timespec start, end;
    int ret;

    if (trigger_sensor() < 0) {
        return -1.0;
    }

    /* Wait for echo rising edge with timeout */
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, TIMEOUT_US * 1000});
    if (ret < 0) {
        fprintf(stderr, "Error waiting for echo rising edge: %s\n", strerror(errno));
        return -1.0;
    }
    if (ret == 0) {
        log_message("Timeout waiting for echo rising edge (sensor absent or not responding)");
        return -1.0;
    }

    struct gpiod_line_event event;
    if (gpiod_line_event_read(echo_line, &event) < 0) {
        fprintf(stderr, "Error reading echo rising edge: %s\n", strerror(errno));
        return -1.0;
    }
    if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
        log_message("Unexpected event type waiting for rising edge");
        return -1.0;
    }
    start = event.ts;

    /* Wait for echo falling edge with timeout */
    ret = gpiod_line_event_wait(echo_line, &(struct timespec){0, TIMEOUT_US * 1000});
    if (ret < 0) {
        fprintf(stderr, "Error waiting for echo falling edge: %s\n", strerror(errno));
        return -1.0;
    }
    if (ret == 0) {
        log_message("Timeout waiting for echo falling edge (echo stuck high)");
        return -1.0;
    }

    if (gpiod_line_event_read(echo_line, &event) < 0) {
        fprintf(stderr, "Error reading echo falling edge: %s\n", strerror(errno));
        return -1.0;
    }
    if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
        log_message("Unexpected event type waiting for falling edge");
        return -1.0;
    }
    end = event.ts;

    double pulse_seconds = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    double distance = (pulse_seconds * SPEED_OF_SOUND) / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Distance out of range: %.2f cm", distance);
        log_message(msg);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open distance_log.txt: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed");
        cleanup();
        return 1;
    }

    log_message("Plant watering reminder started");

    while (program_running) {
        double distance = measure_distance();

        if (distance >= 0.0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_message(msg);

            if (distance < WATERING_THRESHOLD_CM) {
                log_message("Time to water the plant!");
            }
        }

        /* Sleep in 1-second increments to allow signal handling */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_message("Plant watering reminder stopped");
    cleanup();
    return 0;
}

