#define APDS9960_I2C_ADDR 0x39
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_CDATAL 0x96
#define APDS9960_CDATAH 0x97
#define APDS9960_RDATAL 0x98
#define APDS9960_RDATAH 0x99
#define APDS9960_GDATAL 0x9A
#define APDS9960_GDATAH 0x9B
#define APDS9960_PDATA 0x9C

#define PROXIMITY_THRESHOLD 200
#define I2C_BUS 1
#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *value) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_apds9960(void) {
    uint8_t id;
    if (read_reg(APDS9960_ID, &id) < 0) return -1;
    if (id != 0xAB) {
        fprintf(stderr, "Unexpected APDS9960 ID: 0x%02X (expected 0xAB)\n", id);
        return -1;
    }

    if (write_reg(APDS9960_ENABLE, 0x03) < 0) return -1;
    if (write_reg(APDS9960_ATIME, 0xDB) < 0) return -1;
    if (write_reg(APDS9960_WTIME, 0xF6) < 0) return -1;
    if (write_reg(APDS9960_PPULSE, 0x87) < 0) return -1;
    if (write_reg(APDS9960_CONTROL, 0x03) < 0) return -1;
    if (write_reg(APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    if (read_word(APDS9960_CDATAL, red) < 0) return -1;
    if (read_word(APDS9960_RDATAL, red) < 0) return -1;
    if (read_word(APDS9960_GDATAL, green) < 0) return -1;
    if (read_word(APDS9960_GDATAL, blue) < 0) return -1;
    if (read_reg(APDS9960_PDATA, proximity) < 0) return -1;
    return 0;
}

static void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fprintf(log_file, "# timestamp,red,green,blue,proximity\n");
    fflush(log_file);

    uint16_t red, green, blue;
    uint8_t proximity;

    while (!terminate) {
        if (read_sensor_data(&red, &green, &blue, &proximity) == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                break;
            }
            if (init_apds9960() < 0) {
                fprintf(stderr, "APDS9960 re-initialisation failed\n");
                break;
            }
        }
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

