/*
 * Si1182-A-GMR heart-rate monitor for Raspberry Pi 5 (i2c-dev)
 *
 * Wiring:
 *   Si1182 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   Si1182 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   Si1182 VDD  -> 3.3 V
 *   Si1182 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o heartrate heartrate.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- Si1182 register map (subset) ---- */
#define SI1182_I2C_ADDR        0x5A
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_PS_DATA0    0x24
#define SI1182_REG_PS_DATA1    0x25
#define SI1182_REG_COMMAND     0x47

#define SI1182_PART_ID_EXPECTED 0x82   /* Si1182-A-GMR */
#define SI1182_CMD_RESET        0x01
#define SI1182_CMD_START        0x07   /* PS_EN | ALS_EN | PS_AUTO */

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILE       "heartrate.csv"
#define SAMPLE_PERIOD_MS 100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    if (i2c_smbus_write_byte_data(fd, reg, value) < 0) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        fprintf(stderr, "i2c_read_reg8(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Si1182 initialization ---- */

static int si1182_init(int fd)
{
    uint8_t part_id;

    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }

    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr,
                "Unexpected PART_ID 0x%02X (expected 0x%02X). "
                "Wrong sensor or wrong address.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
