#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER 17
#define I2C_BUS 1
#define LOG_FILE "distance_log.txt"
#define MEASUREMENT_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_SYSRANGE_START 0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to a VL53L0X register; returns 0 on success, -1 on error */
static int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, strerror(errno));
    }
    return rc;
}

/* Read a single byte from a VL53L0X register; returns 0 on success, -1 on error */
static int vl53l0x_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read a block of bytes starting at a VL53L0X register; returns 0 on success, -1 on error */
static int vl53l0x_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (got %d): %s\n",
                len, reg, rc, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the VL53L0X sensor; returns 0 on success, -1 on error */
static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;

    /* Verify sensor presence by reading Model ID register 0xC0 */
    if (vl53l0x_read_byte(handle, 0xC0, &model_id) != 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected Model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    /* Clear any pending interrupt */
    if (vl53l0x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return 0;
}

/* Trigger a single distance measurement; returns 0 on success, -1 on error */
static int vl53l0x_trigger_measurement(int handle) {
    return vl53l0x_write_byte(handle, REG_SYSRANGE_START, 0x01);
}

/* Read and process a single distance measurement; returns distance in mm, or -1 on error */
static int vl53l0x_read_distance(int handle) {
    uint8_t status = 0;
    uint8_t data[14];
    int timeout = 0;

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready) */
    while (timeout < MEASUREMENT_TIMEOUT_MS) {
        if (vl53l0x_read_byte(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
        timeout++;
    }

    if (timeout >= MEASUREMENT_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for measurement data\n");
        return -1;
    }

    /* Read 14-byte result block starting at RESULT_RANGE_STATUS */
    if (vl53l0x_read_block(handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) != 0) {
        return -1;
    }

    /* Extract 16-bit distance from bytes 10-11 (big-endian) */
    int distance = (data[10] << 8) | data[11];

    /* Clear interrupt to allow next measurement */
    if (vl53l0x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return distance;
}

/* Log a timestamped distance reading to the CSV file */
static void log_distance(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO trigger pin */
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        /* Wait for falling edge on trigger pin */
        while (running && gpioRead(GPIO_TRIGGER) == 1) {
            gpioDelay(1000); /* 1 ms */
        }
        if (!running) {
            break;
        }

        /* Trigger measurement */
        if (vl53l0x_trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
            continue;
        }

        /* Read distance */
        int distance = vl53l0x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            continue;
        }

        /* Log distance */
        log_distance(log_file, distance);
        printf("Distance: %d mm\n", distance);

        /* Wait for rising edge to reset trigger */
        while (running && gpioRead(GPIO_TRIGGER) == 0) {
            gpioDelay(1000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

