    /* Clear interrupt to allow next measurement */
    if (vl53l0x_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return distance;
}

/* Log a timestamped distance reading to the CSV file */
static void log_distance(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO trigger pin */
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        /* Wait for falling edge on trigger pin */
        while (running && gpioRead(GPIO_TRIGGER) == 1) {
            gpioDelay(1000); /* 1 ms */
        }
        if (!running) {
            break;
        }

        /* Trigger measurement */
        if (vl53l0x_trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering measurement\n");
            continue;
        }

        /* Read distance */
        int distance = vl53l0x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            continue;
        }

        /* Log distance */
        log_distance(log_file, distance);
        printf("Distance: %d mm\n", distance);

        /* Wait for rising edge to reset trigger */
        while (running && gpioRead(GPIO_TRIGGER) == 0) {
            gpioDelay(1000);
        }
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

