#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_CMD    0x01
#define MEASURE_CMD    0x02
#define READ_CMD       0x03
#define MEASURE_DELAY_US 50000   /* 50 ms */
#define SAMPLE_DELAY_US 200000  /* 200 ms */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the CH101                            */
/* ------------------------------------------------------------------ */
static int ch101_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the 16-bit distance (mm)             */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int handle, uint16_t *distance_mm)
{
    int rc;

    /* Trigger a measurement */
    rc = ch101_write_cmd(handle, TRIGGER_CMD);
    if (rc < 0)
        return -1;

    /* Wait for the conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read the 16-bit distance register */
    rc = ch101_write_cmd(handle, READ_CMD);
    if (rc < 0)
        return -1;

    /* Small delay so the sensor is ready to send data */
    gpioDelay(1000);

    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 2)\n", bytes);
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Generate a timestamp string (thread-safe, fixed-size)               */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Log a distance reading to file and stdout                           */
/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, const char *ts, uint16_t dist)
{
    fprintf(fp, "%s, %u\n", ts, dist);
    fflush(fp);
    printf("%s, %u\n", ts, dist);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to CH101 */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH101 distance logger started. Logging to '%s'. Press Ctrl-C to stop.\n",
           LOG_FILE);

    char ts[32];

    while (g_running) {
        uint16_t distance = 0;

        if (ch101_read_distance(g_i2c_handle, &distance) == 0) {
            get_timestamp(ts, sizeof(ts));
            log_distance(g_log_file, ts, distance);
        } else {
            fprintf(stderr, "[WARN] Measurement failed — will retry next cycle\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 20 && g_running; i++)
            gpioDelay(10000);  /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

