#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_US 100000  // 100 milliseconds

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

void log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s, Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    signal(SIGINT, signal_handler);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value >= 0 && sensor2_value >= 0) {
            log_data(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error reading sensor values, skipping log entry.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

