int init_i2c(void);
int read_distance(float *distance);
int log_distance(float distance);
void control_led(float distance);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;

    // Read 2 bytes from the sensor (distance register 0x00)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the distance (big-endian)
    *distance = (float)((buf[0] << 8) | buf[1]);

    return 0;
}

// Log distance to a file with ISO-8601 timestamp
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    // Write the timestamp and distance to the file
    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);

    // Close the log file
    fclose(fp);

    return 0;
}

// Control the LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0); // Ensure LED is off
    gpioTerminate();
}

int main(void) {
    float distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C and termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Log distance
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Error logging distance.\n");
            }

            // Control LED
            control_led(distance);
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(POLL_INTERVAL_US);
    }

    // Cleanup
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

