#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICU-20201 I2C address
#define ICU20201_ADDR 0x6A

// ICU-20201 register addresses
#define ICU20201_REG_WHO_AM_I 0x00
#define ICU20201_REG_DISTANCE 0x04
#define ICU20201_REG_CONFIG 0x08

// Expected WHO_AM_I value for ICU-20201
#define ICU20201_WHO_AM_I_VAL 0x20

// Default threshold in mm
#define DEFAULT_THRESHOLD 100

// I2C bus
#define I2C_BUS 1

// GPIO pin for LED
#define LED_PIN 17

// Global variables for cleanup
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to initialize the ICU-20201 sensor
int init_sensor(int i2c_handle) {
    // Verify sensor identity
    int who_am_i = i2cReadByteData(i2c_handle, ICU20201_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register (I2C error: %d)\n", who_am_i);
        return -1;
    }
    if (who_am_i != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch. Expected 0x%02X, got 0x%02X\n", ICU20201_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    // Configure sensor: enable continuous measurement mode
    if (i2cWriteByteData(i2c_handle, ICU20201_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write CONFIG register\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the ICU-20201 sensor
int read_distance(int i2c_handle) {
    int distance = i2cReadWordData(i2c_handle, ICU20201_REG_DISTANCE);
    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance register (I2C error: %d)\n", distance);
        return -1;
    }
    // pigpio returns data in little-endian format, swap bytes to get the actual distance
    distance = ((distance & 0xFF) << 8) | ((distance >> 8) & 0xFF);
    return distance;
}

// Function to log data to a file
void log_data(int distance, int threshold) {
    FILE *fp = fopen("tof_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Distance: %d mm, Threshold: %d mm\n", timestamp, distance, threshold);
    fclose(fp);
}

// Function to control the LED
void control_led(int distance, int threshold, int led_pin) {
    if (distance < threshold) {
        gpioWrite(led_pin, 1); // Turn LED on
    } else {
        gpioWrite(led_pin, 0); // Turn LED off
    }
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Error: Threshold must be a positive integer\n");
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (Error code: %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurement. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read distance
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Log data
            log_data(distance, threshold);

            // Control LED
            control_led(distance, threshold, LED_PIN);
        } else {
            fprintf(stderr, "Warning: Failed to read distance, retrying...\n");
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Cleanup
    printf("\nCleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

