#define B5L_LD50_ADDR 0x50
#define INTRUSION_THRESHOLD_MM 1000
#define NUM_SAMPLES 10
#define SAMPLE_DELAY_MS 100
#define MEASUREMENT_DELAY_MS 10
#define LOG_FILE "intrusion_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t buf[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_data(fd, buf, sizeof(buf)) < 0) {
        return -1;
    }

    if (buf[0] != 0x50) {
        fprintf(stderr, "Invalid sensor response header: 0x%02X\n", buf[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)buf[11] << 8) | buf[12];
    return 0;
}

static int detect_intrusion(uint16_t distance_mm) {
    return (distance_mm > 0 && distance_mm < INTRUSION_THRESHOLD_MM);
}

static void log_intrusion(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s - Intrusion detected! Distance: %u mm\n", timestamp, distance_mm);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, B5L_LD50_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                B5L_LD50_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t sum = 0;
        int valid_samples = 0;

        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            uint16_t distance_mm;
            if (read_distance(i2c_fd, &distance_mm) == 0) {
                sum += distance_mm;
                valid_samples++;
            } else {
                fprintf(stderr, "Sensor read failed, skipping sample %d\n", i + 1);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid_samples > 0) {
            uint16_t avg_distance = (uint16_t)(sum / valid_samples);

            if (detect_intrusion(avg_distance)) {
                log_intrusion(avg_distance);
            }
        } else {
            fprintf(stderr, "No valid samples in this cycle.\n");
        }
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

