#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* VL53L0X I2C default address (ADDR pin tied to GND) */
#define VL53L0X_ADDR 0x29

/* VL53L0X register addresses */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_SYSRANGE_START          0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS     0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR  0x0B

#define VL53L0X_EXPECTED_MODEL_ID 0xEE
#define VL53L0X_RANGE_TIMEOUT_MS  100
#define SAMPLE_INTERVAL_US       500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a VL53L0X register; returns 0 on success, -1 on error */
static int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n",
                value, reg, strerror(errno));
    }
    return rc;
}

/* Read a single byte from a VL53L0X register; returns 0 on success, -1 on error */
static int vl53l0x_read_byte(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian value from a VL53L0X register; returns 0 on success, -1 on error */
static int vl53l0x_read_word(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading 2 bytes from register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* Initialize the VL53L0X sensor; returns 0 on success, -1 on error */
static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify sensor identity */
    if (vl53l0x_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);

    /* Clear any pending interrupt */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear initial interrupt.\n");
    }

    return 0;
}

/* Read distance from the VL53L0X sensor; returns distance in mm, or -1 on error */
static int vl53l0x_read_distance(int handle)
{
    uint8_t  status = 0;
    uint16_t distance = 0;
    int      timeout_ms = VL53L0X_RANGE_TIMEOUT_MS;

    /* Start a single-shot ranging measurement */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready) */
    do {
        if (vl53l0x_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (timeout_ms-- <= 0) {
            fprintf(stderr, "Timeout waiting for VL53L0X data ready.\n");
            return -1;
        }
        gpioDelay(1000); /* 1 ms */
    } while ((status & 0x01) == 0);

    /* Read the 16-bit distance result (little-endian) */
    if (vl53l0x_read_word(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &distance) != 0) {
        return -1;
    }

    /* Clear the interrupt to allow the next measurement */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt after measurement.\n");
    }

    return (int)distance;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the VL53L0X default address */
    g_i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n",
                VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the VL53L0X sensor */
    if (vl53l0x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int distance = vl53l0x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            printf("%s Distance: %d mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: failed to read distance.\n");
        }

        /* Wait 500 ms before the next measurement */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

