#define SI1182_REG_IRQ_STATUS 0x25
#define SI1182_REG_PROX_LSB   0x2A
#define SI1182_REG_PROX_MSB   0x2B
#define SI1182_REG_CONFIG     0x18

/* CONFIG register bit 0 enables proximity mode */
#define SI1182_CONFIG_PROX_EN 0x01

/* Polling timeout for data-ready (microseconds) */
#define SI1182_POLL_TIMEOUT_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a Si1182 register; returns 0 on success, -1 on error */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a Si1182 register; returns byte value (0-255) or -1 on error */
static int si1182_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return rc;
}

/* Initialize the Si1182 sensor; returns 0 on success, -1 on error */
static int si1182_init(int handle)
{
    /* Probe the sensor by reading the IRQ status register */
    int probe = si1182_read_reg(handle, SI1182_REG_IRQ_STATUS);
    if (probe < 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X (NACK or bus error)\n",
                SI1182_ADDR);
        return -1;
    }

    /* Enable proximity mode in the CONFIG register */
    if (si1182_write_reg(handle, SI1182_REG_CONFIG, SI1182_CONFIG_PROX_EN) < 0) {
        return -1;
    }

    return 0;
}

/* Read 16-bit proximity data from the Si1182; returns 0 on success, -1 on error */
static int si1182_read_proximity(int handle, uint16_t *proximity)
{
    int lsb, msb;

    /* Poll IRQ status bit 0 until data is ready (max ~100 ms) */
    int timeout = SI1182_POLL_TIMEOUT_US;
    while (timeout > 0) {
        int status = si1182_read_reg(handle, SI1182_REG_IRQ_STATUS);
        if (status < 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
        timeout -= 1000;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for Si1182 proximity data-ready\n");
        return -1;
    }

    /* Read LSB and MSB registers */
    lsb = si1182_read_reg(handle, SI1182_REG_PROX_LSB);
    if (lsb < 0) {
        return -1;
    }

    msb = si1182_read_reg(handle, SI1182_REG_PROX_MSB);
    if (msb < 0) {
        return -1;
    }

    *proximity = (uint16_t)((msb << 8) | lsb);
    return 0;
