        perror("sigaction");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor reader started. Press Ctrl+C to exit.\n");

    /* Main loop: read and print proximity data every 500 ms */
    while (g_running) {
        uint16_t proximity;
        if (si1182_read_proximity(g_i2c_handle, &proximity) == 0) {
            printf("Proximity: %u\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
