#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DISTANCE_REG   0x00
#define SCALE_FACTOR   0.125f   /* mm per count */
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian register from the MLX75030.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_distance_reg(int fd, uint16_t *out)
{
    uint8_t reg = DISTANCE_REG;
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read two bytes (low byte first) */
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto out;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto out;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: try a zero-length read to confirm the device is present */
    uint8_t probe;
    if (read(fd, &probe, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX75030 distance sensor on %s (addr 0x%02X). Press Ctrl-C to exit.\n",
           I2C_BUS, MLX75030_ADDR);

    struct timespec ts = {
        .tv_sec  = POLL_MS / 1000,
        .tv_nsec = (long)(POLL_MS % 1000) * 1000000L
    };

    while (g_running) {
        uint16_t raw;
        if (read_distance_reg(fd, &raw) == 0) {
            float distance_mm = (float)raw * SCALE_FACTOR;
            printf("Distance: %.2f mm\n", distance_mm);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 5 && g_running; i++)
            nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
out:
    return rc;
}

