/*
 * HC-SR04 Ultrasonic Distance Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (modern API, not wiringPi)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kOhm resistor
 *   HC-SR04 VCC  -> 5 V (external supply recommended; 3.3 V Pi GPIO is 5 V tolerant)
 *   HC-SR04 GND  -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

/*
 * HC-SR04 timing constants (microseconds).
 *   TRIGGER_PULSE_US: 10 us trigger pulse.
 *   ECHO_TIMEOUT_US:  200 ms max wait for echo rising edge.
 *   MAX_PULSE_US:     38 ms (HC-SR04 maximum range timeout).
 *   MIN_PULSE_US:     2 us  (HC-SR04 minimum range timeout).
 */
#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   200000   /* 200 ms */
#define MAX_PULSE_US      38000    /* 38 ms  -> 5 m */
#define MIN_PULSE_US      2        /* 2 us   -> ~2 cm */

/* Speed of sound in cm/us at 20 C: 0.0343 cm/us */
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Read distance in cm from the HC-SR04.
 * Returns distance on success, or -1.0 on error.
 */
static float read_distance(void)
{
    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_tick;
    uint32_t elapsed;

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger LOW\n");
        return -1.0f;
    }
    gpioDelay(5);  /* settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger HIGH\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger LOW\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout (no object detected)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout (stuck HIGH)\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    elapsed = end_tick - start_tick;

    /* Sanity check: HC-SR04 range is 2 cm to 400 cm */
    if (elapsed <= MIN_PULSE_US || elapsed >= MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse duration %u us out of range [%u, %u]\n",
                elapsed, MIN_PULSE_US, MAX_PULSE_US);
        return -1.0f;
    }

    /* distance = (pulse_us * speed_cm_per_us) / 2 */
    return (float)elapsed * SOUND_SPEED_CM_PER_US / 2.0f;
}

/*
 * Log a distance reading with a timestamp.
 */
static void log_distance(float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000);  /* 100 ms settle */

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | 10 us pulse | 200 ms timeout\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Note: HC-SR04 operates at 5 V; use a 1 kOhm resistor on echo line.\n");
    fflush(stdout);

    /* Main measurement loop */
    while (g_running) {
        float distance = read_distance();
        if (distance >= 0.0f) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Warning: failed to read distance\n");
        }

        /* Sleep 1 second (interruptible by signals) */
        gpioDelay(1000000);
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

