#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define RANGE_THRESHOLD 1.0f
#define NUM_RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486f
#define DATA_FRAME_SIZE (8 + NUM_RANGE_BINS * 2)
#define LOG_FILE "intrusion_log.csv"

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static const uint8_t MAGIC_WORD[8] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int init_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    return 0;
}

static int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Error getting local time");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f\n", timestamp, distance) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        return 1;
    }

    if (init_gpio(GPIO_LED) != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Radar intrusion detection started. Press Ctrl+C to exit.\n");

    uint8_t buffer[DATA_FRAME_SIZE];
    int bytes_read = 0;
    int sync_state = 0;

    while (running) {
        uint8_t byte;
        ssize_t bytes = read(uart_fd, &byte, 1);

        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("Error reading from UART");
            break;
        } else if (bytes == 0) {
            continue;
        }

        if (sync_state < 8) {
            if (byte == MAGIC_WORD[sync_state]) {
                buffer[sync_state] = byte;
                sync_state++;
            } else {
                sync_state = 0;
            }
            continue;
        }

        buffer[sync_state++] = byte;
        bytes_read++;

        if (bytes_read >= DATA_FRAME_SIZE) {
            sync_state = 0;
            bytes_read = 0;

            int16_t range_data[NUM_RANGE_BINS];
            for (int i = 0; i < NUM_RANGE_BINS; i++) {
                range_data[i] = (int16_t)((buffer[8 + i * 2 + 1] << 8) | buffer[8 + i * 2]);
            }

            float min_distance = 1000.0f;
            for (int i = 0; i < NUM_RANGE_BINS; i++) {
                float distance = (float)range_data[i] * RANGE_RESOLUTION;
                if (distance < min_distance) {
                    min_distance = distance;
                }
            }

            if (min_distance < RANGE_THRESHOLD) {
                printf("Intrusion detected! Distance: %.3f meters\n", min_distance);
                gpioWrite(GPIO_LED, 1);
                gpioDelay(2000000);
                gpioWrite(GPIO_LED, 0);

                if (log_intrusion(min_distance) != 0) {
                    fprintf(stderr, "Failed to log intrusion\n");
                }
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

