#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    int last_state = -1;

    while (program_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
            log_event("Error reading sensor value");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        int obstacle_detected = (sensor_value == 0);

        if (gpiod_line_set_value(buzzer_line, obstacle_detected ? 1 : 0) < 0) {
            fprintf(stderr, "Error writing to buzzer: %s\n", strerror(errno));
            log_event("Error writing to buzzer");
        }

        if (obstacle_detected && last_state != 1) {
            log_event("Obstacle detected");
            printf("Obstacle detected!\n");
        } else if (!obstacle_detected && last_state != 0) {
            log_event("Obstacle cleared");
            printf("Obstacle cleared.\n");
        }

        last_state = obstacle_detected ? 1 : 0;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    log_event("System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

