#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR             0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START       0x007
#define VL53L1X_REG_SYSRANGE_START          0x000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x014

#define EXPECTED_MODEL_ID 0xEA
#define LOG_FILE_NAME     "distance_log.csv"
#define POLL_TIMEOUT_MS   100
#define LOOP_DELAY_MS     100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID register.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%02X (expected 0x%02X).\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(2000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }

    uint8_t start_status = 0;
    int timeout = 0;
    do {
        if (i2c_read_reg16(handle, VL53L1X_REG_SYSRANGE_START, &start_status, 1) != 1) {
            fprintf(stderr, "Error: Failed to read SYSRANGE_START.\n");
            return -1;
        }
        gpioDelay(1000);
        timeout++;
    } while ((start_status & 0x01) && timeout < POLL_TIMEOUT_MS);

    if (timeout >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: Timeout waiting for sensor to start ranging.\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 0;
    do {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) {
            fprintf(stderr, "Error: Failed to read interrupt status.\n");
            return -1;
        }
        gpioDelay(1000);
        timeout++;
    } while (!(status & 0x01) && timeout < POLL_TIMEOUT_MS);

    if (timeout >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Error: Timeout waiting for data ready.\n");
        return -1;
    }

    uint8_t data[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance);
    fflush(fp);
}

static void parking_guidance(uint16_t distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            log_distance(g_log_file, distance);
            parking_guidance(distance);
        } else {
            fprintf(stderr, "Warning: Failed to read distance.\n");
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

