#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/* CH201 register addresses (verified against datasheet) */
#define REG_DISTANCE_MSB 0x00
#define REG_DISTANCE_LSB 0x01
#define REG_STATUS       0x02
#define REG_CONFIG       0x03

/* Status bit 0: data ready */
#define STATUS_DATA_READY 0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a CH201 register; returns 0 on success, -1 on failure. */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read a single byte from a CH201 register; returns 0 on success, -1 on failure. */
static int ch201_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *out = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read distance in mm; returns 0 on success, -1 on failure. */
static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t msb, lsb;

    if (ch201_read_reg(handle, REG_DISTANCE_MSB, &msb) != 0)
        return -1;
    if (ch201_read_reg(handle, REG_DISTANCE_LSB, &lsb) != 0)
        return -1;

    *distance_mm = ((uint16_t)msb << 8) | lsb;
    return 0;
}

/* Map distance (mm) to blink frequency (Hz). */
static float distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm > 500)
        return 1.0f;
    if (distance_mm < 50)
        return 10.0f;
    return 10.0f + (500.0f - (float)distance_mm) * 9.0f / 450.0f;
}

/* Blink LED at given frequency for one half-cycle. */
static void blink_led(float frequency)
{
    if (frequency <= 0.0f) {
        gpioWrite(LED_GPIO, 0);
        return;
    }

    uint32_t half_period_us = (uint32_t)(500000.0f / frequency);
    uint32_t on_us = half_period_us / 2;
    uint32_t off_us = half_period_us - on_us;

    gpioWrite(LED_GPIO, 1);
    gpioDelay(on_us);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(off_us);
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Open I2C bus to CH201 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d).\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence by reading STATUS register --- */
    uint8_t status = 0;
    if (ch201_read_reg(g_i2c_handle, REG_STATUS, &status) != 0) {
        fprintf(stderr, "Error: CH201 not responding at address 0x%02X on bus %d.\n",
                I2C_ADDR, I2C_BUS);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("CH201 distance sensor monitoring started.\n");
    printf("I2C bus %d, address 0x%02X, LED on GPIO %d.\n", I2C_BUS, I2C_ADDR, LED_GPIO);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Error: failed to read distance after %d retries.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float frequency = distance_to_frequency(distance_mm);
        blink_led(frequency);

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        printf("[%s] Distance: %u mm  Blink: %.2f Hz\n", ts, distance_mm, frequency);
        fflush(stdout);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

