#include <errno.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x50
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t terminate = 0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, MLX75030_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_distance(int *distance_cm) {
    char cmd = 0x01;
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                    retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(10000);
            continue;
        }

        *distance_cm = (buf[0] << 8) | buf[1];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1;
}

static int log_data(const char *timestamp, int distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void get_timestamp(char *timestamp, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(void) {
    char timestamp[20];
    int distance_cm;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting MLX75030 distance logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        get_timestamp(timestamp, sizeof(timestamp));

        if (read_distance(&distance_cm) == 0) {
            if (log_data(timestamp, distance_cm) != 0) {
                fprintf(stderr, "Failed to log data at %s\n", timestamp);
            } else {
                printf("%s, Distance: %d cm\n", timestamp, distance_cm);
            }
        } else {
            fprintf(stderr, "Failed to read distance at %s\n", timestamp);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

