/*
 * Smart Parking System - TDK CH-101 ToF Sensor Reader
 * Board:  Raspberry Pi 5
 * Bus:    /dev/i2c-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: TDK CH-101, 7-bit I2C address 0x49
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_reader ch101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- CH-101 register map (verified against datasheet) ---- */
#define CH101_I2C_ADDR        0x49
#define REG_MEAS_TRIGGER      0x04
#define REG_MEAS_STATUS       0x06
#define REG_DIST_HIGH         0x08
#define REG_DIST_LOW          0x09

#define I2C_BUS               "/dev/i2c-1"
#define LOG_FILE              "distance_log.csv"
#define SAMPLE_PERIOD_MS      500
#define MEAS_TIMEOUT_MS       50

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "[I2C] write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit little-endian value from two consecutive registers.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int i2c_read_reg16(int fd, uint8_t reg_high, uint16_t *out)
{
    uint8_t hi, lo;
    if (i2c_read_reg8(fd, reg_high, &hi) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg_high + 1, &lo) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */

/*
 * Trigger a single range measurement.
 * Returns 0 on success, -1 on error.
 */
static int ch101_trigger_measurement(int fd)
{
    return i2c_write_reg8(fd, REG_MEAS_TRIGGER, 0x01);
}

/*
 * Wait for the data-ready bit (bit 0) of MEAS_STATUS to be set.
 * Returns 0 on success, -1 on timeout or I2C error.
 */
static int ch101_wait_data_ready(int fd)
{
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 10) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(10 * 1000);
    }
    fprintf(stderr, "[CH101] measurement timeout (data-ready bit never set)\n");
    return -1;
}

/*
 * Read the 16-bit distance in millimetres.
 * Returns 0 on success and stores the value in *out, -1 on error.
 */
static int ch101_read_distance(int fd, uint16_t *out)
{
    if (ch101_trigger_measurement(fd) != 0)
        return -1;
    if (ch101_wait_data_ready(fd) != 0)
        return -1;
    return i2c_read_reg16(fd, REG_DIST_HIGH, out);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_open(FILE **fp)
{
    *fp = fopen(LOG_FILE, "a");
    if (!*fp) {
        fprintf(stderr, "[LOG] cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (ftell(*fp) == 0)
        fprintf(*fp, "timestamp,distance_mm\n");
    return 0;
}

static void log_sample(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        return;
    }
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[SIG] sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[SIG] sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "[I2C] open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the CH-101 slave address */
    if (ioctl(fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "[I2C] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open log file */
    if (log_open(&log_fp) != 0)
        goto cleanup;

    printf("Smart Parking System - CH-101 ToF Sensor Reader\n");
    printf("Bus: %s  Address: 0x%02X  Log: %s\n", I2C_BUS, CH101_I2C_ADDR, LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance_mm;

        if (ch101_read_distance(fd, &distance_mm) == 0) {
            log_sample(log_fp, distance_mm);
            printf("Distance: %u mm\n", distance_mm);
        } else {
            fprintf(stderr, "[MAIN] sensor read failed; skipping sample\n");
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fflush(log_fp);
        fclose(log_fp);
    }
    if (fd >= 0)
        close(fd);
    return rc;
}

