#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* VL53L4CX I2C default address (7-bit) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses (16-bit, big-endian on the bus) */
#define VL53L4CX_SOFT_RESET_REG      0x7FFF
#define VL53L4CX_SYSTEM_START_REG    0x0009
#define VL53L4CX_INT_STATUS_REG      0x0046
#define VL53L4CX_DISTANCE_HIGH_REG   0x0096
#define VL53L4CX_DISTANCE_LOW_REG    0x0097

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Write a 16-bit register address followed by a single byte value */
static int vl53l4cx_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit register address followed by a single byte */
static int vl53l4cx_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char addr_buf[2];
    char data_buf[1];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* Read a 16-bit register address followed by two bytes (big-endian) */
static int vl53l4cx_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char addr_buf[2];
    char data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Initialize the VL53L4CX sensor */
static int vl53l4cx_init(int handle) {
    /* Soft reset */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_SOFT_RESET_REG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start ranging */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_SYSTEM_START_REG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write system start register\n");
        return -1;
    }

    return 0;
}

/* Read distance from the VL53L4CX sensor */
static int vl53l4cx_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    uint16_t dist;

    /* Check interrupt status */
    if (vl53l4cx_read_reg8(handle, VL53L4CX_INT_STATUS_REG, &status) != 0) {
        fprintf(stderr, "Error: Failed to read interrupt status\n");
        return -1;
    }

    if ((status & 0x01) == 0) {
        /* No new data available */
        return 1;
    }

    /* Read distance (16-bit, big-endian) */
    if (vl53l4cx_read_reg16(handle, VL53L4CX_DISTANCE_HIGH_REG, &dist) != 0) {
        fprintf(stderr, "Error: Failed to read distance data\n");
        return -1;
    }

    *distance = dist;
    return 0;
}

/* Get current timestamp with microsecond precision */
static void get_timestamp(char *timestamp, size_t max_len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, max_len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(timestamp);
    snprintf(timestamp + len, max_len - len, ".%06ld", ts.tv_nsec / 1000);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, VL53L4CX_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Initialize sensor */
    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L4CX distance sensor reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (1) {
        uint16_t distance;
        int ret = vl53l4cx_read_distance(i2c_handle, &distance);

        if (ret == 0) {
            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));
            printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
        } else if (ret < 0) {
            /* I2C communication error — continue to next cycle */
        }
        /* ret == 1: no new data available — skip */

        gpioDelay(500000); /* 500 ms */
    }

    /* Cleanup (unreachable in normal operation, but kept for completeness) */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

