#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD_MM 100
#define I2C_BUS 1
#define POLL_DELAY_US 500000

#define REG_SOFT_RESET 0x0001
#define REG_I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define REG_SYSTEM__MODE_START 0x0007
#define REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    return 0;
}

static int init_vl53l1x(int handle) {
    if (write_reg16(handle, REG_SOFT_RESET, 0x0000) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, REG_SOFT_RESET, 0x0001) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, REG_I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR) != 0) return -1;
    if (write_reg16(handle, REG_SYSTEM__MODE_START, 0x0000) != 0) return -1;
    gpioDelay(10000);
    if (write_reg16(handle, REG_SYSTEM__MODE_START, 0x0007) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint16_t status;
    int retries = 0;
    do {
        if (read_reg16(handle, REG_SYSTEM__MODE_START, &status) != 0) return -1;
        if (status & 0x0001) break;
        gpioDelay(1000);
        retries++;
    } while (retries < 100);
    if (retries >= 100) return -1;
    if (read_reg16(handle, REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, distance) != 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int buzzer_active = 0;
    uint16_t distance;

    while (running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD_MM && !buzzer_active) {
