#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static mqd_t message_queue = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to I2C register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error setting I2C register 0x%04X for read\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error setting I2C register 0x%04X for read\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit from I2C register 0x%04X\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0xEA)\n", model_id);
