#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define BUZZER_THRESHOLD_CM 30.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize BUZZER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register alert function for ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static float calculate_distance(uint32_t pulse_width_us) {
    return (float)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
}

static void control_buzzer(float distance) {
    if (distance < BUZZER_THRESHOLD_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void cleanup(void) {
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (!echo_received && running) {
            if (gpioTick() - start_wait > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (!running) {
            break;
        }

        if (!echo_received) {
            fprintf(stderr, "Warning: No echo received (sensor absent or out of range).\n");
            control_buzzer(MAX_DISTANCE_CM + 1.0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;
        float distance = calculate_distance(pulse_width);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: Distance %.2f cm out of valid range [%.0f, %.0f].\n",
                    distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            control_buzzer(MAX_DISTANCE_CM + 1.0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        control_buzzer(distance);
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("Parking sensor stopped.\n");
    return EXIT_SUCCESS;
}

