#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "gate_controller"

#define VL53L1X_REG_SOFT_RESET 0x000B
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086

static int i2c_handle = -1;
static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", ts, event);
    fclose(fp);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t val) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000);
    uint8_t status;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) == 0) {
            break;
        }
        gpioDelay(1000);
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start ranging failed\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle) {
    uint8_t status;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0) {
        return -1;
    }
    if (!(status & 0x01)) {
        return -2;
    }
    uint8_t buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, buf, 2) != 0) {
        return -1;
    }
    i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01);
    return (buf[0] << 8) | buf[1];
}

static void gate_open(void) {
    gpioServo(SERVO_PIN, 1800);
    log_event("Gate opened");
}

static void gate_close(void) {
    gpioServo(SERVO_PIN, 500);
    log_event("Gate closed");
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    if (!result) {
        mosquitto_subscribe(m, NULL, "gate_control", 0);
    } else {
        fprintf(stderr, "MQTT connect failed: %s\n", mosquitto_strerror(result));
    }
}

static void mqtt_message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        if (strcmp(payload, "force_open") == 0) {
            gate_open();
        } else if (strcmp(payload, "force_close") == 0) {
            gate_close();
        } else if (strcmp(payload, "status_request") == 0) {
            char status[64];
            snprintf(status, sizeof(status), "Gate status: %s", gpioRead(SERVO_PIN) == 1800 ? "OPEN" : "CLOSED");
            mosquitto_publish(m, NULL, "gate_status", strlen(status), status, 0, false);
        }
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
