#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24

#define SPEED_OF_SOUND_CM_PER_US 0.0343f
#define MIN_VALID_PULSE_US       100
#define MAX_VALID_PULSE_US       30000
#define ECHO_TIMEOUT_US          60000
#define TRIGGER_PULSE_US         10
#define LOOP_DELAY_US            200000

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback for ECHO pin                                   */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    static uint32_t start_tick = 0;
    static int      got_rising  = 0;

    if (gpio != ECHO_PIN)
        return;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        start_tick = tick;
        got_rising  = 1;
    } else if (level == 0 && got_rising) {
        /* Falling edge: echo pulse ends */
        uint32_t pulse_us = tick - start_tick;   /* handles 32-bit wrap */

        if (pulse_us >= MIN_VALID_PULSE_US && pulse_us <= MAX_VALID_PULSE_US) {
            float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

            printf("%s Distance: %.2f cm\n", timestamp, distance);
            fflush(stdout);

            if (g_log_file) {
                fprintf(g_log_file, "%s Distance: %.2f cm\n", timestamp, distance);
                fflush(g_log_file);
            }
        } else {
            /* Reject noise or timeout/no-object readings */
            if (pulse_us < MIN_VALID_PULSE_US)
                fprintf(stderr, "Warning: pulse too short (%u us)\n", pulse_us);
            else
                fprintf(stderr, "Warning: pulse too long (%u us)\n", pulse_us);
        }

        got_rising = 0;
    }
    /* level == 2 indicates a watchdog timeout; ignore */
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the TRIGGER pin                            */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down on ECHO so the line is defined when idle */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Open log file --- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening distance_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to register SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Warning: failed to register SIGTERM handler");
    }

    /* --- Register alert callback for ECHO pin --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to exit.\n", TRIGGER_PIN, ECHO_PIN);
    fflush(stdout);

    /* --- Main measurement loop --- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        int      got_echo   = 0;

        while (g_running) {
            uint32_t now = gpioTick();
            if ((now - wait_start) >= ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo timeout (%u us) - no object detected.\n",
                        ECHO_TIMEOUT_US);
                break;
            }
            /* Small sleep to avoid busy-waiting */
            gpioDelay(1000);
            /* Check if callback set got_rising */
            if (got_rising) {
                got_echo = 1;
                break;
            }
        }

        if (!got_echo) {
            /* No valid echo received - log timeout and continue */
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

            fprintf(stderr, "%s Warning: no valid echo received.\n", timestamp);
            if (g_log_file) {
                fprintf(g_log_file, "%s Warning: no valid echo received.\n", timestamp);
                fflush(g_log_file);
            }
        }

        /* Wait before next measurement cycle */
        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/*
 * Notes:
 *
 * 1. The HC-SR04 ECHO output is 5 V, exceeding the Pi's 3.3 V GPIO tolerance.
 *    A voltage divider or logic-level converter is required on the ECHO line.
 *    The pigpio library handles the GPIO level transitions, but the voltage
