#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define I2C_BUS 1

#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18

#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_START 0x0000
#define REG_DATA_READY 0x0089
#define REG_DISTANCE_MSB 0x0096
#define REG_DISTANCE_LSB 0x0097

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t ready = 0;
    int retries = 3;
    while (retries > 0) {
        if (i2c_read_reg16(handle, REG_DATA_READY, &ready, 1) != 0) {
            retries--;
            gpioDelay(10000);
            continue;
        }
        if (ready & 0x01) break;
        gpioDelay(10000);
        retries--;
    }
    if (retries == 0) return -1;

    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_DISTANCE_MSB, buf, 2) != 0) return -1;
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void motor_forward(void) {
    gpioWrite(GPIO_MOTOR_FORWARD, 1);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void) {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    printf("Motor: BACKWARD\n");
}

static void motor_stop(void) {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    printf("Motor: STOP\n");
}

static void trigger_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)level; (void)tick;
    uint16_t distance;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < DISTANCE_THRESHOLD_LOW) motor_forward();
        else if (distance > DISTANCE_THRESHOLD_HIGH) motor_backward();
        else motor_stop();
    } else {
        fprintf(stderr, "Error reading distance\n");
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    motor_stop();

    gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_callback, NULL);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Program running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    motor_stop();
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

