    if (i2c_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg(MPR121_E0TTH + i * 2, 0x0B) < 0) return -1;
        if (i2c_write_reg(MPR121_E0RTH + i * 2, 0xC8) < 0) return -1;
    }

    if (i2c_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    uint8_t low, high;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_reg(MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *status = ((uint16_t)high << 8) | low;
    return 0;
}

static void set_led_pattern(uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        int val = (pattern >> i) & 1;
        if (gpiod_line_set_value(led_lines[i], val) < 0) {
            fprintf(stderr, "Failed to set LED %d: %s\n", i + 1, strerror(errno));
        }
    }
}

static void log_proximity_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (touch_status == 0) {
        fprintf(log_file, "%s - No electrode touched\n", timestamp);
    } else {
        fprintf(log_file, "%s - Electrode(s) touched: ", timestamp);
        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                fprintf(log_file, "ELE%d ", i);
            }
        }
        fprintf(log_file, "\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (chip) {
        for (int i = 0; i < 4; i++) {
            if (led_lines[i]) {
                gpiod_line_set_value(led_lines[i], 0);
                gpiod_line_release(led_lines[i]);
            }
        }
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    int led_pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    printf("Proximity-based interactive art installation started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        uint8_t pattern = 0;
        if (touch_status & 0x0001) pattern = 0x01;
        else if (touch_status & 0x0002) pattern = 0x02;
        else if (touch_status & 0x0004) pattern = 0x04;
        else if (touch_status & 0x0008) pattern = 0x08;
        else if (touch_status & 0x0010) pattern = 0x01;
        else if (touch_status & 0x0020) pattern = 0x02;
        else if (touch_status & 0x0040) pattern = 0x04;
        else if (touch_status & 0x0080) pattern = 0x08;
        else if (touch_status & 0x0100) pattern = 0x01;
        else if (touch_status & 0x0200) pattern = 0x02;
        else if (touch_status & 0x0400) pattern = 0x04;
        else if (touch_status & 0x0800) pattern = 0x08;

        set_led_pattern(pattern);
        log_proximity_event(touch_status);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

