#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define SPEED_OF_SOUND 0.0343
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_SETTLE_US 5
#define LOOP_DELAY_US 1000000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int trigger_sensor(void) {
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_SETTLE_US);

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIGGER_PULSE_US);

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static long long wait_for_edge(struct gpiod_line *line, int target_value, long long timeout_us) {
    long long start = gpiod_line_get_value(line);
    if (start < 0) {
        fprintf(stderr, "Failed to read initial line value: %s\n", strerror(errno));
        return -1;
    }

    long long elapsed = 0;
    while (elapsed < timeout_us) {
        long long val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", strerror(errno));
            return -1;
        }
        if (val == target_value) {
            return elapsed;
        }
        usleep(10);
        elapsed += 10;
    }
    return -1;
}

static long long measure_pulse(void) {
    long long rise = wait_for_edge(echo_line, 1, ECHO_TIMEOUT_US);
    if (rise < 0) {
        return -1;
    }

    long long fall = wait_for_edge(echo_line, 0, ECHO_TIMEOUT_US);
    if (fall < 0) {
        return -1;
    }

    return fall - rise;
}

