        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGTERM handler\n");
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_sensor();

        uint32_t waited = 0;
        while (!echo_received && waited < 50000 && running) {
            gpioDelay(100);
            waited += 100;
        }

        if (!echo_received) {
            fprintf(stderr, "Warning: Echo timeout (no response from sensor)\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t pulse_us = end_tick - start_tick;

        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: Invalid pulse width %u us (out of range)\n", pulse_us);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double distance = calculate_distance(pulse_us);
        log_distance(distance);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

