#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_DELAY_US 100000

#define REG_MODEL_ID 0x010F
#define REG_RANGE_MODE 0x0021
#define REG_START_RANGING 0x0015
#define REG_DISTANCE_H 0x0089
#define REG_DISTANCE_L 0x008A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", ts, msg);
    fflush(log_file);
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        log_message("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        log_message("I2C write (reg select) failed");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        log_message("I2C read failed");
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_vl53l1x(int handle) {
    uint16_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) != 0) {
        log_message("Failed to read model ID");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Unexpected model ID: 0x%04X", model_id);
        log_message(msg);
        return -1;
    }
    if (i2c_write_reg8(handle, REG_RANGE_MODE, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, REG_START_RANGING, 0x01) != 0) return -1;
    return 0;
}

static int read_distance_cm(int handle, int *distance_cm) {
    uint16_t raw = 0;
    if (i2c_read_reg16(handle, REG_DISTANCE_H, &raw) != 0) return -1;
    *distance_cm = (int)(raw / 10);
    return 0;
}

static void control_gate(int gpio, int open) {
    gpioWrite(gpio, open ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

