#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_INTERVAL_US 100000
#define MOVING_AVG_SIZE 5
#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end = 0;
static volatile int echo_received = 0;
static volatile int echo_timeout = 0;
static FILE *log_file = NULL;

static double distance_history[MOVING_AVG_SIZE] = {0.0};
static int history_index = 0;
static int history_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_start = tick;
        echo_received = 0;
        echo_timeout = 0;
    } else if (level == 0) {
        pulse_end = tick;
        echo_received = 1;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    double distance = (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;
    }
    return distance;
}

static int calculate_angle(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    double log_dist = log10(distance);
    double log_min = log10(MIN_DISTANCE);
    double log_max = log10(MAX_DISTANCE);
    double norm = (log_dist - log_min) / (log_max - log_min);
    return (int)(norm * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse_width = (int)((double)angle / (MAX_ANGLE - MIN_ANGLE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) + SERVO_MIN_PULSE);
    int rc = gpioServo(SERVO_PIN, pulse_width);
    if (rc < 0) {
        fprintf(stderr, "Error: gpioServo failed with code %d\n", rc);
        return -1;
    }
    return 0;
}

static double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;
    if (history_count < MOVING_AVG_SIZE) {
        history_count++;
    }
    double sum = 0.0;
    for (int i = 0; i < history_count; i++) {
        sum += distance_history[i];
    }
    return sum / (double)history_count;
}

static void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: Failed to set alert function for echo pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Ultrasonic distance measurement and servo tracking started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        echo_timeout = 0;
        pulse_start = 0;
        pulse_end = 0;

        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        while (!echo_received && !echo_timeout && running) {
            if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
                echo_timeout = 1;
            }
            gpioDelay(100);
        }

        if (!running) break;

        if (echo_timeout) {
            fprintf(stderr, "Warning: Echo timeout (no object detected or sensor fault)\n");
            log_data(-1.0, 90);
            set_servo_angle(90);
            gpioDelay(TRIGGER_INTERVAL_US);
            continue;
        }

        uint32_t pulse_width = pulse_end - pulse_start;
        double distance = calculate_distance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Warning: Distance out of range (%u us)\n", pulse_width);
            log_data(-1.0, 90);
            set_servo_angle(90);
            gpioDelay(TRIGGER_INTERVAL_US);
            continue;
        }

        double avg_distance = moving_average(distance);
        int angle = calculate_angle(avg_distance);

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Warning: Failed to set servo angle\n");
        }

        log_data(avg_distance, angle);
        gpioDelay(TRIGGER_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

