#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define INTERRUPT_GPIO 27

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
static int proximity_value = 0;
static int proximity_valid = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_proximity(int handle) {
    int high = i2cReadByteData(handle, PROXIMITY_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "Error reading proximity high byte: %d\n", high);
        return -1;
    }
    int low = i2cReadByteData(handle, PROXIMITY_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "Error reading proximity low byte: %d\n", low);
        return -1;
    }
    return (high << 8) | low;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    int val = read_proximity(i2c_handle);
    if (val >= 0) {
        pthread_mutex_lock(&data_mutex);
        proximity_value = val;
        proximity_valid = 1;
        pthread_mutex_unlock(&data_mutex);
    }
}

static void log_data(FILE *fp, int proximity, int threshold, int above_threshold) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Proximity: %d, Status: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            proximity, above_threshold ? "ALERT" : "SAFE");
    fflush(fp);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(INTERRUPT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", INTERRUPT_GPIO);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", INTERRUPT_GPIO);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
