#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPEAKER_PIN 18
#define TRIGGER_PIN 23
#define ECHO_PIN 24

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 200.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 200000
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set speaker pin %d as output.\n", SPEAKER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize trigger pin low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set trigger high.\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set trigger low.\n");
        return -1.0;
    }

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout.\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout.\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (pulse_width * 34300.0) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance %.2f cm out of range [%.0f, %.0f].\n",
                distance, MIN_DISTANCE, MAX_DISTANCE);
        return -1.0;
    }

    return distance;
}

static int calculate_frequency(float distance) {
    if (distance < 0.0) {
        return -1;
    }
    float freq = MIN_FREQUENCY * expf(distance / 50.0);
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return (int)freq;
}

static int set_tone(int frequency) {
    if (frequency < 0) {
        if (gpioPWM(SPEAKER_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to stop PWM on pin %d.\n", SPEAKER_PIN);
            return -1;
        }
        return 0;
    }

    if (gpioSetPWMfrequency(SPEAKER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency to %d Hz.\n", frequency);
        return -1;
    }

    if (gpioPWM(SPEAKER_PIN, 128) != 0) {
        fprintf(stderr, "Error: Failed to start PWM on pin %d.\n", SPEAKER_PIN);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    int previous_frequency = -1;

    while (running) {
        float distance = measure_distance();
        int frequency = calculate_frequency(distance);

        if (frequency != previous_frequency) {
            if (set_tone(frequency) != 0) {
                fprintf(stderr, "Error setting tone.\n");
            }
            previous_frequency = frequency;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_tone(-1);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

