#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5.0
#define MAX_DIST 50.0
#define TIMEOUT_US 100000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000);
    return 0;
}

static float read_distance(void) {
    uint32_t start_tick, end_tick;
    int timeout;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (++timeout > TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us * 34300.0f) / 2000000.0f;

    if (distance < MIN_DIST || distance > MAX_DIST) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DIST, MAX_DIST);
        return -1.0;
    }
    return distance;
}

static int set_frequency(float distance) {
    if (distance < 0.0f) return -1;

    float freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;

    if (gpioHardwarePWM(BUZZER_PIN, (int)freq, 500000) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %.0f Hz\n", freq);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    float last_valid_distance = MAX_DIST;

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read failed; using last valid distance %.2f cm\n",
                    last_valid_distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        if (set_frequency(distance) != 0) {
            fprintf(stderr, "Frequency set failed\n");
        }

        printf("Distance: %.2f cm, Frequency: %.0f Hz\n", distance,
               MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST));

        gpioDelay(LOOP_DELAY_US);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

