    float distance = (pulse_us * 34300.0f) / 2000000.0f;

    if (distance < MIN_DIST || distance > MAX_DIST) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DIST, MAX_DIST);
        return -1.0;
    }
    return distance;
}

static int set_frequency(float distance) {
    if (distance < 0.0f) return -1;

    float freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    if (freq < MIN_FREQ) freq = MIN_FREQ;
    if (freq > MAX_FREQ) freq = MAX_FREQ;

    if (gpioHardwarePWM(BUZZER_PIN, (int)freq, 500000) != 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed for frequency %.0f Hz\n", freq);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    float last_valid_distance = MAX_DIST;

    while (running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read failed; using last valid distance %.2f cm\n",
                    last_valid_distance);
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        if (set_frequency(distance) != 0) {
            fprintf(stderr, "Frequency set failed\n");
        }

        printf("Distance: %.2f cm, Frequency: %.0f Hz\n", distance,
               MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST));

        gpioDelay(LOOP_DELAY_US);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

