#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000  // 50 ms timeout for echo
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SPEED_OF_SOUND_CM_PER_US 29.1
#define LOOP_DELAY_US 500000  // 500 ms

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int trigger_sensor(int trigger_pin) {
    gpioWrite(trigger_pin, PI_HIGH);
    gpioDelay(10);  // 10 us trigger pulse
    gpioWrite(trigger_pin, PI_LOW);
    return 0;
}

int measure_echo_pulse(int echo_pin, uint32_t *pulse_width) {
    uint32_t start_tick, end_tick;
    int timeout;

    // Wait for echo to go high
    timeout = 0;
    while (gpioRead(echo_pin) == PI_LOW) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            return -1;  // Timeout waiting for echo start
        }
    }
    start_tick = gpioTick();

    // Wait for echo to go low
    timeout = 0;
    while (gpioRead(echo_pin) == PI_HIGH) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            return -1;  // Timeout waiting for echo end
        }
    }
    end_tick = gpioTick();

    *pulse_width = end_tick - start_tick;
    return 0;
}

float calculate_distance(uint32_t pulse_width) {
    return (float)pulse_width / 2.0 / SPEED_OF_SOUND_CM_PER_US;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, PI_LOW);

    signal(SIGINT, signal_handler);

    while (program_running) {
        uint32_t pulse_width;
        float distance;

        if (trigger_sensor(TRIGGER_PIN) != 0) {
            fprintf(stderr, "Error triggering sensor\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (measure_echo_pulse(ECHO_PIN, &pulse_width) != 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        distance = calculate_distance(pulse_width);

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading\n");
