#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ICU-20201 SPI configuration
#define SPI_CHANNEL 0       // CE0
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_MODE 0          // Mode 0 (CPOL=0, CPHA=0)
#define CS_PIN 8            // GPIO8 (CE0)

// ICU-20201 register addresses
#define REG_MEAS_CTRL 0x00
#define REG_RANGE_SEL 0x02
#define REG_DIST_LOW 0x0C
#define REG_DIST_HIGH 0x0D

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_write_register(uint8_t reg, uint8_t value);
int spi_read_register(uint8_t reg, uint8_t *value);
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void signal_handler(int signal);
int initialize_sensor();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize the ICU-20201 sensor
int initialize_sensor() {
    // Set chip select pin as output and deselect sensor
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %s\n", strerror(errno));
        return -1;
    }

    // Configure sensor: continuous measurement mode
    if (spi_write_register(REG_MEAS_CTRL, 0x01) != 0) {
        fprintf(stderr, "Error configuring measurement control register\n");
        return -1;
    }

    // Set range to 5 m (0x00 = 5 m)
    if (spi_write_register(REG_RANGE_SEL, 0x00) != 0) {
        fprintf(stderr, "Error configuring range selection register\n");
        return -1;
    }

    // Trigger a measurement to start continuous readings
    if (spi_write_register(REG_MEAS_CTRL, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    return 0;
}

// Write a value to a register via SPI
int spi_write_register(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F;  // Write command (bit 7 = 0)
    tx_buf[1] = value;

    gpioWrite(CS_PIN, 0);  // Select sensor
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1);  // Deselect sensor

    if (result != 2) {
        fprintf(stderr, "SPI write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read a value from a register via SPI
int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80;  // Read command (bit 7 = 1)
    tx_buf[1] = 0x00;        // Dummy byte for clocking data out

    gpioWrite(CS_PIN, 0);  // Select sensor
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1);  // Deselect sensor

    if (result != 2) {
        fprintf(stderr, "SPI read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    uint8_t low_byte, high_byte;

    // Read low byte
    if (spi_read_register(REG_DIST_LOW, &low_byte) != 0) {
        return -1;
    }

    // Read high byte
    if (spi_read_register(REG_DIST_HIGH, &high_byte) != 0) {
        return -1;
    }

    *distance = ((uint16_t)high_byte << 8) | low_byte;
    return 0;
}

// Log distance to a CSV file
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed. Check wiring and SPI configuration.\n");
        cleanup();
        return 1;
    }

    printf("ICU-20201 sensor initialized. Logging distance to distance_log.csv...\n");

    // Main loop
    while (!terminate) {
        uint16_t distance;

        if (read_distance(&distance) == 0) {
            // Validate distance range (200-5000 mm)
            if (distance >= 200 && distance <= 5000) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %u mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100000);  // 100 ms delay
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

