#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA0, &low) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA1, &high) < 0) {
        return -1;
    }
    *als_visible = (uint16_t)((high << 8) | low);
    return 0;
}

static int log_data(FILE *fp, uint16_t als_visible) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, als_visible) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        if (fprintf(log_fp, "timestamp,als_visible\n") < 0) {
            fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
            fclose(log_fp);
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        fflush(log_fp);
    }

    printf("Si1175 proximity logger started. Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        uint16_t als_visible;
        if (read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible data: %s\n", strerror(errno));
        } else {
            if (log_data(log_fp, als_visible) < 0) {
                fprintf(stderr, "Error logging data: %s\n", strerror(errno));
            } else {
                printf("ALS Visible: %u\n", als_visible);
            }
        }

