#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1120_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "si1120_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Si1120 register addresses */
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19
#define REG_COMMAND 0x30

/* Expected part ID for Si1120 */
#define SI1120_PART_ID 0x41

/* Command to reset the sensor */
#define CMD_RESET 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown (Ctrl+C) */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Write a byte to a register with retry logic */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (attempt %d/%d): %s\n",
                value, reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read a byte from a register with retry logic */
static int read_register(int handle, uint8_t reg) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        }
        fprintf(stderr, "Error reading register 0x%02X (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Initialize the Si1120 sensor */
static int initialize_sensor(int handle) {
    int part_id;

    /* Reset the sensor */
    if (write_register(handle, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120 sensor.\n");
        return -1;
    }
    gpioDelay(10000); /* Wait 10 ms for reset to complete */

    /* Verify part ID */
    part_id = read_register(handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read part ID.\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X). Sensor not present or wrong device.\n",
                part_id, SI1120_PART_ID);
        return -1;
    }

    printf("Si1120 sensor initialized successfully. Part ID: 0x%02X\n", part_id);
    return 0;
}

/* Read ambient light (ALS) data from the sensor */
static int read_ambient_light(int handle) {
    int low_byte, high_byte;

    low_byte = read_register(handle, REG_ALS_VIS_DATA0);
    if (low_byte < 0) {
        return -1;
    }

    high_byte = read_register(handle, REG_ALS_VIS_DATA1);
    if (high_byte < 0) {
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

/* Read proximity (PS1) data from the sensor */
static int read_proximity(int handle) {
    int low_byte, high_byte;

    low_byte = read_register(handle, REG_PS1_DATA0);
    if (low_byte < 0) {
        return -1;
    }

    high_byte = read_register(handle, REG_PS1_DATA1);
    if (high_byte < 0) {
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

/* Log data to a file */
static int log_data(FILE *fp, int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }

    if (fprintf(fp, "%s, Ambient Light: %d, Proximity: %d\n", timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int ambient_light, proximity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler: %s\n", strerror(errno));
    }

    printf("Starting data logging. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        /* Read ambient light data */
        ambient_light = read_ambient_light(i2c_handle);
        if (ambient_light < 0) {
            fprintf(stderr, "Error reading ambient light data.\n");
        }

        /* Read proximity data */
        proximity = read_proximity(i2c_handle);
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity data.\n");
        }

        /* Log the data if both reads were successful */
        if (ambient_light >= 0 && proximity >= 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        /* Delay for 500 milliseconds */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

