#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1182_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"

#define REG_PART_ID 0x00
#define REG_MEAS_RATE 0x08
#define REG_ALS_DATA0 0x22
#define REG_ALS_DATA1 0x23
#define REG_PS_DATA0 0x24
#define REG_PS_DATA1 0x25

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int fd, float *lux, int *proximity) {
    uint8_t als_low, als_high, ps_low, ps_high;

    if (i2c_read_reg8(fd, REG_ALS_DATA0, &als_low) < 0) return -1;
    if (i2c_read_reg8(fd, REG_ALS_DATA1, &als_high) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS_DATA0, &ps_low) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS_DATA1, &ps_high) < 0) return -1;

    uint16_t als_raw = (uint16_t)((als_high << 8) | als_low);
    uint16_t ps_raw = (uint16_t)((ps_high << 8) | ps_low);

    *lux = (float)als_raw * 0.1f;
    *proximity = (int)ps_raw;
    return 0;
}

static void log_data(FILE *fp, float lux, int proximity) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[64];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.2f,%d\n", timestamp, ts.tv_nsec / 1000000, lux, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
