        fprintf(stderr, "Sensor not responding at address 0x%02X\n", SI1182_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X). Sensor not present?\n", part_id, EXPECTED_PART_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(i2c_fd, REG_MEAS_RATE, 0x07) < 0) {
        fprintf(stderr, "Failed to configure measurement rate\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1182 sensor initialized. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
