#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"
#define MAX_RETRIES 3

/* Si1145 register addresses */
#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_IRQ_ENABLE 0x1A
#define REG_ALS_VIS_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80
#define REG_PS1_DATA0 0x16
#define REG_PS1_DATA1 0x17

/* Si1145 commands */
#define CMD_PS_FORCE 0x05

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int init_si1145(int handle) {
    /* Hardware key: required for proper operation */
    if (write_register(handle, REG_HW_KEY, 0x03) < 0) return -1;

    /* Measurement rate: 2 ms (0x02) */
    if (write_register(handle, REG_MEAS_RATE, 0x02) < 0) return -1;

    /* Disable interrupts */
    if (write_register(handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;

    /* ALS VIS ADC counter: 16-bit, 1/15 gain */
    if (write_register(handle, REG_ALS_VIS_ADC_COUNTER, 0x0B) < 0) return -1;

    /* ALS VIS ADC gain: 0x00 */
    if (write_register(handle, REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;

    /* PS ADC counter: 16-bit, 1/15 gain */
    if (write_register(handle, REG_PS_ADC_COUNTER, 0x49) < 0) return -1;

    /* PS LED21 current: 180 mA */
    if (write_register(handle, REG_PS_LED21, 0x03) < 0) return -1;

    /* PS LED3 current: 180 mA */
    if (write_register(handle, REG_PS_LED3, 0x0F) < 0) return -1;

    /* PS ADC MISC: small IR */
    if (write_register(handle, REG_PS_ADC_MISC, 0x03) < 0) return -1;

    /* PS ADC gain: 7.7x */
    if (write_register(handle, REG_PS_ADC_GAIN, 0x07) < 0) return -1;

    return 0;
}

static int read_proximity(int handle) {
    int low = read_register(handle, REG_PS1_DATA0);
    if (low < 0) return -1;

    int high = read_register(handle, REG_PS1_DATA1);
    if (high < 0) return -1;

    return (high << 8) | low;
}

static void log_data(FILE *fp, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Proximity: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, proximity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n",
                SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialisation failed. Check wiring and I2C address.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 proximity sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int proximity = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && proximity < 0) {
            /* Force a proximity measurement */
            if (write_register(i2c_handle, REG_COMMAND, CMD_PS_FORCE) < 0) {
                retries++;
                gpioDelay(10000); /* 10 ms delay before retry */
                continue;
            }

            gpioDelay(10000); /* Wait 10 ms for measurement to complete */

            proximity = read_proximity(i2c_handle);
            if (proximity < 0) {
                retries++;
                gpioDelay(10000); /* 10 ms delay before retry */
            }
        }

        if (proximity >= 0) {
            log_data(log_file, proximity);
            printf("Proximity: %d\n", proximity);
        } else {
            log_error(log_file, "Failed to read proximity data after multiple retries");
            fprintf(stderr, "Failed to read proximity data after multiple retries\n");
        }

        gpioDelay(100000); /* 100 ms delay between readings */
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

