#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_CENTER_PULSE 1500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

float measure_distance() {
    uint32_t start_tick, end_tick;
    int timeout;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        if (timeout++ > 100000) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    start_tick = gpioTick();

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        if (timeout++ > 100000) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
        gpioDelay(1);
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Warning: Distance out of range (%.2f cm)\n", distance);
        return -1.0;
    }

    return distance;
}

void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_MIN_PULSE + (int)((float)angle / 180.0 * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    signal(SIGINT, signal_handler);

    while (program_running) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);

            int angle;
            if (distance > 200.0) angle = 0;
            else if (distance < 20.0) angle = 180;
            else angle = 90 - (int)((distance - 20.0) / 180.0 * 90.0);

            set_servo_angle(angle);
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
            set_servo_angle(90);
        }

        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

