#define MAX_ANGLE 180
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define LOOP_DELAY_US 100000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
    }
}

float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    // Ensure trigger is low
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);

    // Send 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high with timeout
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_tick) > ECHO_TIMEOUT_US) {
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_duration = end_tick - start_tick;
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2.0;
    return distance;
}

int calculate_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
    }
}

void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse_width = (int)(((float)angle / MAX_ANGLE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) + SERVO_MIN_PULSE);
    gpioServo(SERVO_PIN, pulse_width);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); // 100 ms settle time

    while (program_running) {
        float distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Error: Echo timeout or sensor error\n");
            set_servo_angle(90); // Stop servo on error
        } else {
            int angle = calculate_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    // Cleanup
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly\n");
    return 0;
}

