#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x01
#define SI7005_REG_HUMID 0x02
#define SI7005_REG_CONFIG 0x03
#define SI7005_CONFIG_VAL 0x00
#define CONVERSION_DELAY_US 10000
#define RECOVERY_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, SI7005_REG_CONFIG, SI7005_CONFIG_VAL) < 0) {
        fprintf(stderr, "Failed to write CONFIG register\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    return 0;
}

static int read_raw_temperature(uint16_t *raw_temp) {
    int result = i2cReadWordData(i2c_handle, SI7005_REG_TEMP);
    if (result < 0) {
        fprintf(stderr, "Failed to read temperature register: %d\n", result);
        return -1;
    }
    *raw_temp = (uint16_t)result;
    return 0;
}

static int read_raw_humidity(uint16_t *raw_hum) {
    int result = i2cReadWordData(i2c_handle, SI7005_REG_HUMID);
    if (result < 0) {
        fprintf(stderr, "Failed to read humidity register: %d\n", result);
        return -1;
    }
    *raw_hum = (uint16_t)result;
    return 0;
}

static float convert_temperature(uint16_t raw_temp) {
    return ((175.72f * (float)raw_temp) / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw_hum) {
    return ((125.0f * (float)raw_hum) / 65536.0f) - 6.0f;
}

static void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!terminate) {
        uint16_t raw_temp, raw_hum;

        if (read_raw_temperature(&raw_temp) == 0 && read_raw_humidity(&raw_hum) == 0) {
            float temperature = convert_temperature(raw_temp);
            float humidity = convert_humidity(raw_hum);
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Sensor read failed, attempting recovery...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(RECOVERY_DELAY_US);
            if (init_i2c() != 0 || configure_sensor() != 0) {
                fprintf(stderr, "Recovery failed, exiting.\n");
                break;
            }
        }

        gpioDelay(2000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

