#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Initialize the MPU-6050 sensor */
static int init_mpu6050(int handle) {
    int who_am_i = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register (I2C error: %d)\n", who_am_i);
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor not present?\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Reset the device */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for reset to complete */

    /* Wake up the device (clear sleep bit) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake up MPU-6050\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms delay for oscillator to stabilize */

    /* Set sample rate divider to 7 for 1 kHz / (1 + 7) = 125 Hz output */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to set sample rate divider\n");
        return -1;
    }

    /* Set DLPF_CFG to 0 for bandwidth 1 kHz, delay 0 ms */
    if (i2cWriteByteData(handle, MPU6050_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set DLPF_CFG\n");
        return -1;
    }

    /* Set gyroscope range to ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyroscope range\n");
        return -1;
    }

    /* Set accelerometer range to ±2 g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accelerometer range\n");
        return -1;
    }

    return 0;
}

