    int bytes_read = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buffer, 14);
    if (bytes_read != 14) {
        fprintf(stderr, "Error: Failed to read 14 bytes of data (got %d)\n", bytes_read);
        return -1;
    }

