#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, SDP810_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing configuration to SDP810: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: expected 9 bytes, got %d: %s\n",
                result, strerror(errno));
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    if (crc8(&buffer[6], 2) != buffer[8]) {
        fprintf(stderr, "CRC error in scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    data->differential_pressure = (float)raw_pressure / (float)scale_factor;
    data->temperature = (float)raw_temperature / (float)scale_factor;

    return 0;
}

static int log_data(const sensor_data_t *data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Differential Pressure (Pa),Temperature (C)\n");
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data->differential_pressure, data->temperature);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying in 1 second...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

