#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define CMD_TEMP_NO_HOLD 0xF3
#define CMD_HUMID_NO_HOLD 0xF5
#define MEASUREMENT_DELAY_US 20000  /* 20 ms max conversion time */
#define SAMPLE_INTERVAL_US 5000000 /* 5 seconds */
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit measurement from the Si7015.
 * Returns 0 on success and stores the raw value in *raw;
 * returns -1 on failure.
 */
static int read_measurement(int handle, uint8_t cmd, uint16_t *raw) {
    int rc;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        rc = i2cWriteByte(handle, cmd);
        if (rc < 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), pigpio error %d: %s\n",
                    cmd, rc, pigpio_error(rc));
            retries++;
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        rc = i2cReadWordData(handle, 0);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X), pigpio error %d: %s\n",
                    cmd, rc, pigpio_error(rc));
            retries++;
            gpioDelay(10000);
            continue;
        }

        *raw = (uint16_t)rc;
        return 0;
    }

    fprintf(stderr, "Failed to read measurement after %d retries (cmd 0x%02X)\n",
            MAX_RETRIES, cmd);
    return -1;
}

static float convert_temperature(uint16_t raw) {
    return ((175.72f * (float)raw) / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw) {
    float rh = ((125.0f * (float)raw) / 65536.0f) - 6.0f;
    if (rh < 0.0f) rh = 0.0f;
