#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

static Reading circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI7021_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    uint8_t cmd_temp = 0xE3;
    uint8_t cmd_hum = 0xE5;
    uint8_t buf[2];
    int retries;

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        if (i2cWriteDevice(i2c_handle, (char *)&cmd_temp, 1) != 0) {
            fprintf(stderr, "Error writing temperature command (attempt %d)\n", retries + 1);
            gpioDelay(10000);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_US);
        if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) {
            fprintf(stderr, "Error reading temperature data (attempt %d)\n", retries + 1);
            gpioDelay(10000);
            continue;
        }
        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
        *temperature = 175.72f * (float)raw_temp / 65536.0f - 46.85f;

        if (i2cWriteDevice(i2c_handle, (char *)&cmd_hum, 1) != 0) {
            fprintf(stderr, "Error writing humidity command (attempt %d)\n", retries + 1);
            gpioDelay(10000);
