#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000
#define MEASUREMENT_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending command 0x%04X: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    uint8_t buf[9];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 9);
    if (rc != 9) {
        fprintf(stderr, "Error reading measurement data: expected 9 bytes, got %d\n", rc);
        return -1;
    }
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on humidity word\n");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    uint16_t raw_t = (buf[3] << 8) | buf[4];
    uint16_t raw_h = (buf[6] << 8) | buf[7];
    *temp = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *hum = 100.0f * (float)raw_h / 65535.0f;
    return 0;
}

static void log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(0x21B1) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        goto cleanup;
    }
    gpioDelay(MEASUREMENT_INTERVAL_US);

    while (!terminate) {
        if (send_command(0xE4B8) != 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        gpioDelay(10000);

        uint8_t ready_buf[3];
        int rc = i2cReadDevice(i2c_handle, (char *)ready_buf, 3);
        if (rc != 3) {
            fprintf(stderr, "Error reading data-ready flag: %d\n", rc);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (crc8(&ready_buf[0], 2) != ready_buf[2]) {
            fprintf(stderr, "CRC mismatch on data-ready flag\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        uint16_t ready = (ready_buf[0] << 8) | ready_buf[1];
        if (ready == 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (send_command(0xEC05) != 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        gpioDelay(10000);

        uint16_t co2;
        float temp, hum;
        if (read_measurement(&co2, &temp, &hum) == 0) {
            log_data(co2, temp, hum);
            printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
        } else {
            fprintf(stderr, "Failed to read measurement data\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (send_command(0x3F86) != 0) {
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    }

cleanup:
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

