static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int start_periodic_measurement(void) {
    return send_command(CMD_START_PERIODIC);
}

static int stop_periodic_measurement(void) {
    return send_command(CMD_STOP_PERIODIC);
}

static int is_data_ready(void) {
    if (send_command(CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(10000);
    uint8_t buf[3];
    if (read_data(buf, 3) != 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready status\n");
        return -1;
    }
    return (buf[0] & 0x07) != 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    if (send_command(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    uint8_t buf[9];
    if (read_data(buf, 9) != 0)
        return -1;
    if (crc8(&buf[0], 2) != buf[2] || crc8(&buf[3], 2) != buf[5] || crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on measurement data\n");
        return -1;
    }
    *co2 = (buf[0] << 8) | buf[1];
    uint16_t t_raw = (buf[3] << 8) | buf[4];
    uint16_t h_raw = (buf[6] << 8) | buf[7];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void add_to_buffer(uint16_t co2, float temp, float hum) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temp;
    circular_buffer[buffer_index].humidity = hum;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE)
        buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&circular_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n",
               ts, circular_buffer[idx].co2,
               circular_buffer[idx].temperature,
               circular_buffer[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d addr 0x%02X (err=%d)\n",
                I2C_BUS, SCD40_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = is_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Warning: Data-ready check failed, retrying...\n");
            gpioDelay(1000000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(1000000);
            continue;
        }

        uint16_t co2;
        float temp, hum;
        if (read_measurement(&co2, &temp, &hum) == 0) {
            add_to_buffer(co2, temp, hum);
            printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
            if (co2 > CO2_THRESHOLD)
                gpioWrite(LED_GPIO, 1);
