                consecutive_errors++;
                fprintf(stderr, "Timeout waiting for TL falling edge\n");
                return -1;
            }
        }
        if (!running) break;

        /* Wait for rising edge (end of TL) */
        tl_state = 0;
        while (running) {
            if (gpioRead(TMP05_GPIO) == 1) {
                tl_end = gpioTick();
                break;
            }
            if ((gpioTick() - tl_start) > EDGE_TIMEOUT_US) {
                consecutive_errors++;
                fprintf(stderr, "Timeout waiting for TL rising edge\n");
                return -1;
            }
        }
        if (!running) break;

        uint32_t th_us = th_end - th_start;
        uint32_t tl_us = tl_end - tl_start;

        if (tl_us == 0) {
            consecutive_errors++;
            fprintf(stderr, "Invalid TL measurement (zero)\n");
            return -1;
        }

        float ratio = (float)th_us / (float)tl_us;
        *temperature = 4215.0f - (2143.0f * ratio);

        if (*temperature < MIN_TEMP || *temperature > MAX_TEMP) {
            consecutive_errors++;
            fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
            return -1;
        }

        return 0;
    }

    return -1;
}

int main(void) {
    float temperature;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TMP05_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TMP05_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 temperature logger started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        if (read_tmp05(&temperature) == 0) {
            consecutive_errors = 0;
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Failed to read temperature (consecutive errors: %d)\n", consecutive_errors);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Max consecutive errors reached. Logging malfunction.\n");
                if (log_malfunction() != 0) {
                    fprintf(stderr, "Failed to log malfunction\n");
                }
                consecutive_errors = 0;
            }
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

