#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define SHT35_ADDR 0x44
#define I2C_BUS 1
#define MEASUREMENT_CMD_HIGH_REP 0x2400
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_US 5000000
#define OFFSET_PERIOD_US 3600000000
#define OFFSET_AMPLITUDE_TEMP 2.0
#define OFFSET_AMPLITUDE_HUM 5.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SHT35_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sht35(SensorData *data) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD_HIGH_REP >> 8) & 0xFF, MEASUREMENT_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write error (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read error (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + (175.0f * raw_temp) / 65535.0f;
        data->humidity = 100.0f * raw_hum / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT35 after %d retries\n", RETRY_COUNT);
    return -1;
}

static void apply_offset(SensorData *data, uint32_t elapsed_us) {
    double time_frac = (double)elapsed_us / OFFSET_PERIOD_US;
    data->temperature += OFFSET_AMPLITUDE_TEMP * sin(2.0 * M_PI * time_frac);
    data->humidity += OFFSET_AMPLITUDE_HUM * sin(2.0 * M_PI * time_frac);
}

static void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t start_time = gpioTick();

    while (!terminate) {
        SensorData sensor_data;
        if (read_sht35(&sensor_data) == 0) {
            uint32_t elapsed = gpioTick() - start_time;
            apply_offset(&sensor_data, elapsed);
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Skipping log entry due to sensor read failure\n");
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    cleanup();
    return 0;
}

