#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define POLL_TIMEOUT_MS    100
#define SAMPLE_INTERVAL_S  5

#define CMD_RESET          0xFE
#define CMD_MEASURE_RH     0xF5
#define CMD_MEASURE_TEMP   0xF3
#define CMD_READ_PREV_RH   0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n", n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int si7021_reset(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);
    return 0;
}

static int si7021_read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    uint8_t buf[3];
    int elapsed = 0;

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    while (elapsed < POLL_TIMEOUT_MS) {
        usleep(2000);
        elapsed += 2;
        if (i2c_read_bytes(fd, buf, 3) == 0)
            break;
    }

    if (elapsed >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
        return -1;
    }

    *raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_temperature(int fd, float *temp_c) {
    uint16_t raw;
    if (si7021_read_measurement(fd, CMD_MEASURE_TEMP, &raw) < 0)
        return -1;
    *temp_c = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *rh) {
    uint16_t raw;
    if (si7021_read_measurement(fd, CMD_MEASURE_RH, &raw) < 0)
        return -1;
    *rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static int log_data(const char *filename, float temp, float rh) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    } else {
        fprintf(fp, "ERROR,%.2f,%.2f\n", temp, rh);
    }
    fclose(fp);
    return 0;
}

static int log_error(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,ERROR\n", ts);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR\n");
    }
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (si7021_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Cannot create %s: %s\n", LOG_FILE, strerror(errno));
            close(g_i2c_fd);
            return 1;
        }
    } else {
        fclose(fp);
    }

    while (g_running) {
        float temp = 0.0f, rh = 0.0f;
        int ok = 1;

        if (read_temperature(g_i2c_fd, &temp) < 0) {
            fprintf(stderr, "Temperature read failed; resetting sensor.\n");
            ok = 0;
        }
        if (ok && read_humidity(g_i2c_fd, &rh) < 0) {
            fprintf(stderr, "Humidity read failed; resetting sensor.\n");
            ok = 0;
        }

        if (ok) {
            if (log_data(LOG_FILE, temp, rh) < 0)
                fprintf(stderr, "Logging failed.\n");
        } else {
            if (si7021_reset(g_i2c_fd) < 0)
                fprintf(stderr, "Sensor reset failed after error.\n");
            if (log_error(LOG_FILE) < 0)
                fprintf(stderr, "Error logging failed.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

