#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define PWM_RANGE 1000000   // 1,000,000 steps for 0-100% duty cycle
#define SAMPLE_INTERVAL_US 100000 // 100 ms
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *raw_pressure);
float convert_to_flow_rate(int16_t raw_pressure);
int set_fan_speed(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Turn off fan
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();

    // Close I2C handle
