#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* STLM75 temperature read                                             */
/* ------------------------------------------------------------------ */
/*
 * The STLM75 returns a 16-bit two's-complement word in little-endian
 * order.  Bits [15:9] are the temperature, bits [8:7] are the fractional
 * bits (always 0), and bits [6:0] are always 0.
 *
 * pigpio's i2cReadWordData returns the two bytes in little-endian order
 * on the Pi.  We swap them, right-shift by 7, and divide by 2 to get
 * degrees Celsius.
 */
static int read_temperature(int handle, float *temperature)
{
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register (pigpio code %d)\n",
                raw);
        return -1;
    }

    /* pigpio returns bytes in little-endian order: [low, high] */
    uint16_t swapped = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));

    /* Sign-extend the 9-bit temperature field */
    int16_t temp_raw = (int16_t)(swapped >> 7);

    *temperature = (float)temp_raw / 2.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void control_led(int gpio, float average_temperature)
{
    int level = (average_temperature > TEMP_THRESHOLD) ? 1 : 0;
    if (gpioWrite(gpio, level) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio, level);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X "
                        "(pigpio code %d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- Initialize circular buffer --- */
    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
