#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define CO2_THRESHOLD_LOW 800
#define CO2_THRESHOLD_HIGH 1200

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_DATA_READY 0x0202
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define CMD_SET_AMBIENT_PRESSURE 0x4610

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_arg(uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    buf[2] = (arg >> 8) & 0xFF;
    buf[3] = arg & 0xFF;
    buf[4] = crc8(&buf[2], 2);
    if (i2cWriteDevice(i2c_handle, (char *)buf, 5) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X with arg 0x%04X\n", cmd, arg);
        return -1;
    }
    return 0;
}

static int scd30_read_measurement(float *co2, float *temperature, float *humidity) {
    uint8_t buf[18];
    if (i2cReadDevice(i2c_handle, (char *)buf, 18) != 18) {
        fprintf(stderr, "Error: i2cReadDevice failed for measurement data\n");
        return -1;
    }
    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }
    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];
    *co2 = (float)co2_raw;
    *temperature = (float)temp_raw / 100.0f;
    *humidity = (float)hum_raw / 100.0f;
    return 0;
}

static int scd30_data_ready(void) {
    if (scd30_write_command(CMD_DATA_READY) != 0)
        return -1;
    gpioDelay(10000);
    uint8_t buf[3];
    if (i2cReadDevice(i2c_handle, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: i2cReadDevice failed for data-ready status\n");
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready status\n");
        return -1;
    }
    uint16_t status = (buf[0] << 8) | buf[1];
    return (status == 1) ? 1 : 0;
}

static int scd30_init(void) {
    if (scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_write_command_with_arg(CMD_SET_MEASUREMENT_INTERVAL, MEASUREMENT_INTERVAL_SEC) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_write_command_with_arg(CMD_SET_AMBIENT_PRESSURE, 0) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_write_command(CMD_START_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    return 0;
}

static void log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

static void control_ventilation(float co2) {
    if (co2 < CO2_THRESHOLD_LOW) {
        printf("Ventilation: OFF\n");
    } else if (co2 < CO2_THRESHOLD_HIGH) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (scd30_init() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SCD30 initialized. Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, MEASUREMENT_INTERVAL_SEC);

    while (!terminate) {
        int ready = scd30_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Warning: data-ready check failed, retrying...\n");
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
            continue;
        }

        float co2, temperature, humidity;
        if (scd30_read_measurement(&co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Warning: measurement read failed\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
    gpioDelay(10000);
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    if (log_file != NULL)
        fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

