#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define HDC1000_ADDR        0x40
#define TEMP_REG            0x00
#define CONFIG_REG          0x02
#define I2C_BUS             "/dev/i2c-1"
#define READ_INTERVAL_SEC   5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (ret=%zd)\n",
                reg, value, strerror(errno), ret);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    ssize_t ret = write(fd, &reg_buf, sizeof(reg_buf));
    if (ret != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "i2c_read_reg16: write pointer 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }

    uint8_t data[2];
    ret = read(fd, data, sizeof(data));
    if (ret != (ssize_t)sizeof(data)) {
        fprintf(stderr, "i2c_read_reg16: read 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    /*
     * Configuration Register (0x02):
     *   Bit 12: TRES[1:0] = 00 (14-bit temperature)
     *   Bit 11: HRES[1:0] = 00 (14-bit humidity)
     *   Bit 10: MODE[1:0] = 00 (temperature + humidity)
     *   Bit 9:  BDU       = 1  (block data update)
     *   Bits 8-0: reserved
     * Value = 0x1000
     */
    if (i2c_write_reg8(fd, CONFIG_REG, 0x10) != 0) {
        fprintf(stderr, "Failed to configure HDC1000\n");
        return -1;
    }
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw_temp, raw_hum;

    if (i2c_read_reg16(fd, TEMP_REG, &raw_temp) != 0)
        return -1;

    if (i2c_read_reg16(fd, TEMP_REG, &raw_hum) != 0)
        return -1;

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    int fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) != 0) {
        fprintf(stderr, "HDC1000 initialization failed (sensor may be absent)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s at address 0x%02X. Reading every %d seconds...\n",
           I2C_BUS, HDC1000_ADDR, READ_INTERVAL_SEC);

    while (g_running) {
        float temperature, humidity;

        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nExiting cleanly...\n");
    if (fd >= 0)
        close(fd);
    return EXIT_SUCCESS;
}

