#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_INTERVAL_US 500000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_pressure(int handle, float *pressure) {
    char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, buf, 3);
        if (bytes_read == 3) {
            uint16_t raw = ((uint16_t)(buf[0] & 0x0F) << 8) | (uint8_t)buf[1];
            *pressure = (float)raw * 0.001f;
            return 0;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                retries + 1, MAX_RETRIES, strerror(errno));
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(10000);
        }
    }
    return -1;
}

static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Pressure: %.3f kPa\n", timestamp, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %s\n",
                I2C_BUS, MLX90833_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 pressure sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_pressure(i2c_handle, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
        }
        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

