#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ICP10101_ADDR 0x63
#define I2C_BUS 1
#define MEASURE_CMD 0x40
#define READ_CALIB_CMD 0x50
#define MEASURE_DELAY_US 7000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

static int read_calibration(uint16_t cal[4]) {
    char cmd = READ_CALIB_CMD;
    char buf[8];

    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write calibration read command\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2cReadDevice(i2c_handle, buf, 8) != 8) {
        fprintf(stderr, "Error: failed to read 8-byte calibration data\n");
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(uint8_t)buf[2 * i] << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
