#define MLX90819_ADDR  0x60
#define PRESSURE_MSB   0xAA
#define PRESSURE_LSB   0xAB
#define SCALE_FACTOR   0.1f
#define READ_INTERVAL  1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read error (expected %zu bytes, got %zd): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_out) {
    uint8_t msb, lsb;

    if (i2c_write_byte(fd, PRESSURE_MSB) < 0)
        return -1;

    if (i2c_read_bytes(fd, &msb, 1) < 0)
        return -1;

    if (i2c_write_byte(fd, PRESSURE_LSB) < 0)
        return -1;

    if (i2c_read_bytes(fd, &lsb, 1) < 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *pressure_out = (float)raw * SCALE_FACTOR;
    return 0;
}

