    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    printf("[%s] Pressure: %.2f kPa\n", ts, pressure);
    fflush(stdout);
}

