#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01f
#define MIN_PRESSURE 200.0f
#define MAX_PRESSURE 250.0f
#define LOG_FILE "pressure_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, MLX90821_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure register (got %d bytes): %s\n",
                result, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s,%.2f\n", ts, pressure);
    fflush(log_file);
}

static void check_pressure_range(float pressure) {
    if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa out of range [%.0f, %.0f]\n",
                pressure, MIN_PRESSURE, MAX_PRESSURE);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

