        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    printf("Tire pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "I2C read failed; attempting to reopen...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Reopen failed; will retry next cycle.\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

