#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HIH6130_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hih6130(int handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    /* Trigger measurement: write 0x00 to command register */
    result = i2cWriteByte(handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    /* Read 4 bytes: status, humidity MSB, humidity LSB, temperature MSB */
    result = i2cReadDevice(handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: expected 4 bytes, got %d\n", result);
        return -1;
    }

    /* Validate status bits (bits 0-1 of byte 0) */
    if (buf[0] & 0x03) {
        fprintf(stderr, "Sensor status error: 0x%02X\n", buf[0]);
        return -1;
    }

    uint16_t raw_humidity = ((uint16_t)(buf[1] & 0xFF) << 8) | (uint16_t)(buf[2] & 0xFF);
    uint16_t raw_temperature = ((uint16_t)(buf[3] & 0xFF) << 8) | (uint16_t)(buf[2] & 0xFF);

    *humidity = (float)raw_humidity * 100.0f / 16383.0f;
    *temperature = (float)raw_temperature * 165.0f / 16383.0f - 40.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    /* Check file size and truncate if needed */
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size >= LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        fp = fopen(filename, "w");
        if (fp == NULL) {
            perror("Error truncating log file");
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C device */
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HIH6130 sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hih6130(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

