#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define READ_TIMEOUT_US 1000000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(int gpio, int *nibble) {
    uint32_t start_tick, end_tick, pulse_us;
    int level;

    /* Wait for falling edge (start of synchronization pulse) */
    level = gpioRead(gpio);
    if (level < 0) return -1;
    if (level == 0) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start_tick > READ_TIMEOUT_US) return -2; /* Timeout waiting for sync */
        }
    } else {
        start_tick = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - start_tick > READ_TIMEOUT_US) return -2;
        }
    }

    /* Measure high pulse width */
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > READ_TIMEOUT_US) return -2;
    }
    end_tick = gpioTick();
    pulse_us = end_tick - start_tick;

    /* Convert to ticks */
    int ticks = (int)(pulse_us / TICK_US);

    /* Validate nibble pulse width */
    if (ticks < NIBBLE_MIN_TICKS || ticks > NIBBLE_MAX_TICKS) {
        return -3; /* Bus error: invalid pulse width */
    }

    *nibble = ticks - 12;
    return 0;
}

static int read_sent_data(int gpio, int *status, int *data1, int *data2, int *data3, int *checksum) {
    int ret;

    ret = read_sent_nibble(gpio, status);
    if (ret != 0) return ret;

    ret = read_sent_nibble(gpio, data1);
    if (ret != 0) return ret;

    ret = read_sent_nibble(gpio, data2);
    if (ret != 0) return ret;

    ret = read_sent_nibble(gpio, data3);
    if (ret != 0) return ret;

    ret = read_sent_nibble(gpio, checksum);
    if (ret != 0) return ret;

    return 0;
}

static int validate_checksum(int status, int data1, int data2, int data3, int checksum) {
    int calc = (status + data1 + data2 + data3) & 0x0F;
    return (calc == checksum) ? 0 : -1;
}

static float convert_to_pressure(int raw_value) {
    /* Example linear transfer function: raw * scale + offset */
    float scale = 100.0f;
    float offset = 0.0f;
    return (float)raw_value * scale + offset;
}

static int log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int status, data1, data2, data3, checksum;
    int raw_value;
    float pressure;
    int ret;

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Set GPIO mode to input */
    if (gpioSetMode(SENT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENT_GPIO);
        gpioTerminate();
        return 1;
    }

    /* Enable pull-up resistor to ensure stable reading */
    if (gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENT_GPIO);
        gpioTerminate();
        return 1;
    }

    printf("Brake Pressure Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        ret = read_sent_data(SENT_GPIO, &status, &data1, &data2, &data3, &checksum);

        if (ret == 0) {
            /* Validate checksum */
            if (validate_checksum(status, data1, data2, data3, checksum) == 0) {
                /* Combine nibbles into 12-bit raw value */
                raw_value = (status << 8) | (data1 << 4) | data2;

                /* Convert to pressure */
                pressure = convert_to_pressure(raw_value);

                /* Log pressure */
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure reading\n");
                }

                printf("Pressure: %.2f Pa\n", pressure);
            } else {
                fprintf(stderr, "Checksum error: calculated 0x%X, received 0x%X\n",
                        (status + data1 + data2 + data3) & 0x0F, checksum);
            }
        } else if (ret == -2) {
            fprintf(stderr, "Sensor absent or bus error: timeout waiting for synchronization pulse\n");
        } else if (ret == -3) {
            fprintf(stderr, "Bus error: invalid pulse width\n");
        } else {
            fprintf(stderr, "Unknown SENT read error\n");
        }

        /* Wait for next reading */
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean up */
    gpioTerminate();
    printf("\nBrake Pressure Monitoring System stopped.\n");

    return 0;
}

