#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define EXPECTED_DEVICE_ID 0x0117
#define DATA_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *data_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int16_t raw_temp;

    if (i2cReadI2CBlockData(handle, TEMP_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature register: %s\n", strerror(errno));
        return -1;
    }

    raw_temp = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw_temp * 0.0078125f;
    return 0;
}

static int write_temperature_to_file(FILE *fp, float temperature) {
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (data_file != NULL) {
        fclose(data_file);
        data_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    data_file = fopen(DATA_FILE, "ab");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file '%s': %s\n", DATA_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify device ID */
    char id_buf[2];
    if (i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, id_buf, 2) != 2) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    uint16_t device_id = (uint16_t)((id_buf[1] << 8) | id_buf[0]);
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n", device_id, EXPECTED_DEVICE_ID);
        cleanup();
        return 1;
    }

    printf("Greenhouse temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (write_temperature_to_file(data_file, temperature) != 0) {
                fprintf(stderr, "Failed to write temperature to file.\n");
            } else {
                printf("Temperature: %.2f °C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

