    if (fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data->temperature, data->humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file.\n");
        return -1;
    }

    return 0;
}

