    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to register SIGINT handler");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        cleanup();
        return 1;
    }

    SensorData sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Warning: Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }

        gpioDelay(READ_INTERVAL_US);
    }

    cleanup();
    return 0;
}

