    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (addr 0x%02X): %s\n",
                SHTC3_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    printf("SHTC3 environmental monitor started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (!terminate) {
        float temperature, humidity;

