#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(void);
int read_sensor_data(int16_t *magnetic_field, int16_t *temperature);
void convert_data(int16_t raw_magnetic_field, int16_t raw_temperature, float *magnetic_field_gauss, float *temperature_celsius);
int log_data(float magnetic_field_gauss, float temperature_celsius);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initializes the I2C interface
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X on bus %d: %s\n", SI7202_ADDR, I2C_BUS, strerror(errno));
        return -1;
    }
    return 0;
}

// Reads raw data from the Si7202 sensor
int read_sensor_data(int16_t *magnetic_field, int16_t *temperature) {
    char buf[4];
    int result;

    // Read 4 bytes of data from the sensor
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d: %s\n", result, strerror(errno));
        return -1;
    }

    // Combine the two bytes for magnetic field and temperature
    *magnetic_field = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Converts raw data to Gauss and Celsius
void convert_data(int16_t raw_magnetic_field, int16_t raw_temperature, float *magnetic_field_gauss, float *temperature_celsius) {
    *magnetic_field_gauss = (float)raw_magnetic_field * 0.1f;
    *temperature_celsius = (float)raw_temperature * 0.01f - 25.0f;
}

// Logs the data to a CSV file
int log_data(float magnetic_field_gauss, float temperature_celsius) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, magnetic_field_gauss, temperature_celsius) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int16_t raw_magnetic_field, raw_temperature;
    float magnetic_field_gauss, temperature_celsius;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error flushing header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Set up signal handling for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_magnetic_field, &raw_temperature) == 0) {
            // Convert data
            convert_data(raw_magnetic_field, raw_temperature, &magnetic_field_gauss, &temperature_celsius);

            // Log data
            if (log_data(magnetic_field_gauss, temperature_celsius) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            // Log NaN values on read failure
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Error logging NaN values.\n");
            }
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Program terminated.\n");

    return 0;
}

