#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.txt"
#define SAMPLE_INTERVAL_US 2000000
#define MAX_RETRIES 3

#define DHT11_OK 0
#define DHT11_ERROR_TIMEOUT -1
#define DHT11_ERROR_CHECKSUM -2
#define DHT11_ERROR_SENSOR_ABSENT -3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message, int status_code) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Status: %d, Message: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, status_code, message);
    } else {
        fprintf(fp, "Timestamp error, Status: %d, Message: %s\n", status_code, message);
    }
    fclose(fp);
}

static int read_dht11(int gpio, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i, j;
    uint32_t start_tick, elapsed;

    for (i = 0; i < MAX_RETRIES; i++) {
        memset(data, 0, sizeof(data));

        /* Send start signal: pull low for at least 18 ms, then release */
        if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
            log_error("Failed to set GPIO mode to output", DHT11_ERROR_TIMEOUT);
            return DHT11_ERROR_TIMEOUT;
        }
        if (gpioWrite(gpio, 0) < 0) {
            log_error("Failed to write GPIO low", DHT11_ERROR_TIMEOUT);
            return DHT11_ERROR_TIMEOUT;
        }
        gpioDelay(20000); /* 20 ms low */

        if (gpioWrite(gpio, 1) < 0) {
            log_error("Failed to write GPIO high", DHT11_ERROR_TIMEOUT);
            return DHT11_ERROR_TIMEOUT;
        }
        gpioDelay(30); /* 30 us high */

        /* Switch to input with pull-up; sensor will pull low */
        if (gpioSetMode(gpio, PI_INPUT) < 0) {
            log_error("Failed to set GPIO mode to input", DHT11_ERROR_TIMEOUT);
            return DHT11_ERROR_TIMEOUT;
        }
        if (gpioSetPullUpDown(gpio, PI_PUD_UP) < 0) {
            log_error("Failed to set pull-up on GPIO", DHT11_ERROR_TIMEOUT);
            return DHT11_ERROR_TIMEOUT;
        }

        /* Wait for sensor response: low ~80 us, high ~80 us */
        start_tick = gpioTick();
        while (gpioRead(gpio) == 1) {
            elapsed = gpioTick() - start_tick;
            if (elapsed > 100) {
                log_error("Sensor not responding (stuck high)", DHT11_ERROR_SENSOR_ABSENT);
                return DHT11_ERROR_SENSOR_ABSENT;
            }
        }
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            elapsed = gpioTick() - start_tick;
            if (elapsed > 100) {
                log_error("Sensor response low timeout", DHT11_ERROR_TIMEOUT);
                return DHT11_ERROR_TIMEOUT;
            }
        }
        start_tick = gpioTick();
        while (gpioRead(gpio) == 1) {
            elapsed = gpioTick() - start_tick;
            if (elapsed > 100) {
                log_error("Sensor response high timeout", DHT11_ERROR_TIMEOUT);
                return DHT11_ERROR_TIMEOUT;
            }
        }

        /* Read 40 data bits */
        for (j = 0; j < 40; j++) {
            /* Wait for low-to-high transition (end of ~50 us low pulse) */
            start_tick = gpioTick();
            while (gpioRead(gpio) == 0) {
                elapsed = gpioTick() - start_tick;
                if (elapsed > 100) {
                    log_error("Data bit low timeout", DHT11_ERROR_TIMEOUT);
                    return DHT11_ERROR_TIMEOUT;
                }
            }
            /* Measure high-pulse duration: ~26-28 us = '0', ~70 us = '1' */
            start_tick = gpioTick();
            while (gpioRead(gpio) == 1) {
                elapsed = gpioTick() - start_tick;
                if (elapsed > 100) {
                    log_error("Data bit high timeout", DHT11_ERROR_TIMEOUT);
                    return DHT11_ERROR_TIMEOUT;
                }
            }
            /* High pulse > 40 us => '1' */
            if (elapsed > 40) {
                data[j / 8] |= (1 << (7 - (j % 8)));
            }
        }

        /* Verify checksum */
        uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
        if (checksum != data[4]) {
            log_error("Checksum mismatch", DHT11_ERROR_CHECKSUM);
            return DHT11_ERROR_CHECKSUM;
        }

        /* Parse: humidity = data[0], temperature = data[2] (integer, Celsius) */
        *humidity = (float)data[0];
        *temperature = (float)data[2];
        return DHT11_OK;
    }

    log_error("Max retries reached", DHT11_ERROR_TIMEOUT);
    return DHT11_ERROR_TIMEOUT;
}

static void log_reading(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Temperature: %.1f C, Humidity: %.1f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    } else {
        fprintf(fp, "Timestamp error, Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;
    int status;

    while (running) {
        status = read_dht11(DHT11_GPIO, &temperature, &humidity);
        if (status == DHT11_OK) {
            log_reading(temperature, humidity);
        }
        /* On error, log_error already called; just wait and retry */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

