#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_DEVICE_ID 0x00
#define ADPD105_REG_RED_DATA 0x64
#define ADPD105_REG_GREEN_DATA 0x66
#define ADPD105_REG_BLUE_DATA 0x68
#define ADPD105_EXPECTED_DEVICE_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adpd105_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(handle, ADPD105_REG_RED_DATA, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading ADPD105 data (handle %d): %s\n", handle, strerror(errno));
        return -1;
    }

    *red = (uint16_t)((buf[1] << 8) | buf[0]);
    *green = (uint16_t)((buf[3] << 8) | buf[2]);
    *blue = (uint16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float n = (float)(red + green + blue);
    if (n == 0.0f) return 0.0f;

    float x = (float)red / n;
    float y = (float)green / n;

    float n1 = (x - 0.3320f) / (0.1858f - y);
    float n2 = (-0.4000f * x) + (1.5743f * y) + 0.0129f;

    float cct = 449.0f * n1 * n1 * n1 + 3525.0f * n1 * n1 + 6823.3f * n1 + 5520.33f;
    if (cct < 0.0f) cct = 0.0f;
    return cct;
}

static int log_cct(float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, cct) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int result;
    uint16_t red1, green1, blue1;
    uint16_t red2, green2, blue2;
    float cct1, cct2, avg_cct;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 (addr 0x%02X): %s\n", ADPD105_ADDR_1, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 (addr 0x%02X): %s\n", ADPD105_ADDR_2, strerror(errno));
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        if (fprintf(log_file, "Timestamp,Average_CCT\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fflush(log_file);
    }

    while (running) {
        result = i2cReadByteData(i2c_handle_1, ADPD105_REG_DEVICE_ID);
        if (result != ADPD105_EXPECTED_DEVICE_ID) {
            fprintf(stderr, "Error: Sensor 1 (addr 0x%02X) not detected or device ID mismatch (got 0x%02X, expected 0x%02X)\n",
                    ADPD105_ADDR_1, result, ADPD105_EXPECTED_DEVICE_ID);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        result = i2cReadByteData(i2c_handle_2, ADPD105_REG_DEVICE_ID);
        if (result != ADPD105_EXPECTED_DEVICE_ID) {
            fprintf(stderr, "Error: Sensor 2 (addr 0x%02X) not detected or device ID mismatch (got 0x%02X, expected 0x%02X)\n",
                    ADPD105_ADDR_2, result, ADPD105_EXPECTED_DEVICE_ID);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_adpd105_data(i2c_handle_1, &red1, &green1, &blue1) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (read_adpd105_data(i2c_handle_2, &red2, &green2, &blue2) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        cct1 = calculate_cct(red1, green1, blue1);
        cct2 = calculate_cct(red2, green2, blue2);
        avg_cct = (cct1 + cct2) / 2.0f;

        if (log_cct(avg_cct) != 0) {
            fprintf(stderr, "Error logging CCT data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

