#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000

#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0.0
#define PMAX_KPA 800.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_raw_data(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static float convert_pressure(uint16_t raw_pressure) {
    return ((float)raw_pressure - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN) + PMIN_KPA;
}

static float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature * 0.01f - 40.0f;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, address 0x%02X: %s\n", I2C_BUS, MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

