        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Tire pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_pressure = 0;
        uint16_t raw_temperature = 0;

        if (read_raw_data(i2c_handle, PRESSURE_REG, &raw_pressure) != 0) {
            log_error(log_file, "Failed to read pressure data");
        } else if (read_raw_data(i2c_handle, TEMPERATURE_REG, &raw_temperature) != 0) {
            log_error(log_file, "Failed to read temperature data");
        } else {
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);
            log_data(log_file, pressure, temperature);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

