#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW 26.0f
#define POLL_INTERVAL_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, LM75B_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char reg = TEMP_REG;
    char data[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing temperature register address: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    raw >>= 5;
    *temperature = (float)raw * 0.5f;
    return 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static float calculate_average(const CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

static int control_fan(float average_temperature) {
    static int fan_state = 0;

    if (average_temperature > TEMP_THRESHOLD_HIGH && fan_state == 0) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_state = 1;
            printf("Fan ON (avg=%.2f C)\n", average_temperature);
        } else {
            fprintf(stderr, "Error turning fan ON: %s\n", strerror(errno));
            return -1;
        }
    } else if (average_temperature < TEMP_THRESHOLD_LOW && fan_state == 1) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_state = 0;
            printf("Fan OFF (avg=%.2f C)\n", average_temperature);
        } else {
            fprintf(stderr, "Error turning fan OFF: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", FAN_GPIO, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing fan to OFF: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer temperature_buffer;
    init_circular_buffer(&temperature_buffer);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&temperature_buffer, temperature);
            float average_temperature = calculate_average(&temperature_buffer);

            if (control_fan(average_temperature) != 0) {
                fprintf(stderr, "Fan control error, continuing...\n");
            }

            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Temperature read failed, retrying...\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

