#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_GPIO       17
#define TEMP_THRESHOLD_HIGH 28.0f
#define TEMP_THRESHOLD_LOW  27.0f
#define POLL_INTERVAL_SEC   1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: got %zd bytes, %s\n",
                reg, n, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float raw_to_celsius(uint16_t raw)
{
    return (float)(raw >> 4) * 0.0625f;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "stts2004-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int led_state = 0;
    int exit_code = EXIT_SUCCESS;

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16(i2c_fd, TEMP_REG, &raw) != 0) {
            fprintf(stderr, "Fatal I2C error; exiting.\n");
            exit_code = EXIT_FAILURE;
            break;
        }

        float temp = raw_to_celsius(raw);
        printf("Temperature: %.2f °C\n", temp);

        if (temp > TEMP_THRESHOLD_HIGH) {
            if (led_state == 0) {
                if (gpiod_line_set_value(led, 1) < 0) {
                    fprintf(stderr, "Failed to set LED high: %s\n",
                            strerror(errno));
                    exit_code = EXIT_FAILURE;
                    break;
                }
                led_state = 1;
            }
        } else if (temp < TEMP_THRESHOLD_LOW) {
            if (led_state == 1) {
                if (gpiod_line_set_value(led, 0) < 0) {
                    fprintf(stderr, "Failed to set LED low: %s\n",
                            strerror(errno));
                    exit_code = EXIT_FAILURE;
                    break;
                }
                led_state = 0;
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean shutdown */
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return exit_code;
}

