#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60
#define MAX_RETRIES    3
#define MEASURE_DELAY_US 25000  /* 25 ms for no-hold measurement */

/* Si7021 commands */
#define CMD_MEASURE_RH_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_PREV_RH        0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,ERROR,%s\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        } else {
            fprintf(fp, "[timestamp-error],ERROR,%s\n", msg);
        }
        fclose(fp);
    }
    fprintf(stderr, "[%ld] ERROR: %s\n", (long)time(NULL), msg);
}

/*
 * Read a 16-bit big-endian value from the Si7021.
 * Returns 0 on success, -1 on failure.
 */
static int read_si7021_word(uint8_t cmd, uint16_t *out)
{
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Send measurement command */
        rc = i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1);
        if (rc < 0) {
            log_error("I2C write failed (measurement command)");
            gpioDelay(10000);
            continue;
        }

        /* Wait for conversion to complete */
        gpioDelay(MEASURE_DELAY_US);

        /* Read 2 bytes of result */
        rc = i2cReadDevice(g_i2c_handle, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        log_error("I2C read failed (measurement data)");
        gpioDelay(10000);
    }
    return -1;
}

/*
 * Read temperature from the previous RH measurement.
 * Returns 0 on success, -1 on failure.
 */
static int read_temperature(float *temp_c)
{
    uint16_t raw;
    if (read_si7021_word(CMD_READ_PREV_RH, &raw) != 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/*
 * Read relative humidity.
 * Returns 0 on success, -1 on failure.
 */
static int read_humidity(float *rh_pct)
{
    uint16_t raw;
    if (read_si7021_word(CMD_MEASURE_RH_NO_HOLD, &raw) != 0)
        return -1;
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    *rh_pct = rh;
    return 0;
}

/*
 * Validate sensor presence by reading the electronic ID byte.
 * Returns 0 on success, -1 on failure.
 */
static int validate_sensor(void)
{
    char buf[8];
    int rc = i2cReadDevice(g_i2c_handle, buf, 8);
    if (rc != 8) {
        log_error("Sensor not responding (ID read failed)");
        return -1;
    }
    /* Si7021 ID bytes: SNA_0=0x15, SNA_1=0x0C, SNB_0=0x0D, SNB_1=0x0E */
    if (buf[0] != 0x15 || buf[1] != 0x0C || buf[2] != 0x0D || buf[3] != 0x0E) {
        log_error("Unexpected sensor ID bytes (not a Si7021)");
        return -1;
    }
    return 0;
}

static void log_data(float temp_c, float rh_pct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file for writing");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c, rh_pct);
    } else {
        fprintf(fp, "[timestamp-error],%.2f,%.2f\n", temp_c, rh_pct);
    }
    fclose(fp);
    printf("%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n",
           tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
           tm.tm_hour, tm.tm_min, tm.tm_sec, temp_c, rh_pct);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (validate_sensor() != 0) {
        fprintf(stderr, "Sensor validation failed. Check wiring and address.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 sensor detected. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c, rh_pct;

        if (read_temperature(&temp_c) != 0) {
            log_error("Failed to read temperature");
        } else if (read_humidity(&rh_pct) != 0) {
            log_error("Failed to read humidity");
        } else {
            log_data(temp_c, rh_pct);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

