#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define LOG_FILE "enviro_log.txt"
#define I2C_BUS 1
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int init_hdc1080(int handle) {
    // Configure: 14-bit temp (0x00), 14-bit humidity (0x00), heater off (0x00)
    // Config register: bits 15-12 = temp res, bits 11-8 = humidity res, bits 1-0 = heater
    // For 14-bit temp and humidity, resolution bits = 0000 (14-bit)
    // Config value = 0x0000
    char config[2] = {0x00, 0x00};
    if (i2cWriteI2CBlockData(handle, CONFIG_REG, config, 2) != 0) {
        fprintf(stderr, "Error writing HDC1080 config register\n");
        return -1;
    }
    return 0;
}

int read_hdc1080(int handle, float *temperature, float *humidity) {
    char reg = TEMP_REG;
    char buf[4];

    // Write pointer to temperature register
    if (i2cWriteI2CBlockData(handle, TEMP_REG, &reg, 1) != 0) {
        fprintf(stderr, "Error writing temperature register pointer\n");
        return -1;
    }

    // Wait for conversion (max 14-bit temp + 14-bit humidity = ~14.5 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes: 2 bytes temperature, 2 bytes humidity
    if (i2cReadI2CBlockData(handle, TEMP_REG, buf, 4) != 4) {
        fprintf(stderr, "Error reading HDC1080 data\n");
        return -1;
    }

    unsigned int raw_temp = ((unsigned int)buf[0] << 8) | (unsigned int)buf[1];
    unsigned int raw_humidity = ((unsigned int)buf[2] << 8) | (unsigned int)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, HDC1080_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hdc1080(i2c_handle) != 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (running) {
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry\n");
        }

        // Sleep in 1-second increments to allow signal handler to interrupt promptly
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

