#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_INTERVAL_SEC 5
#define LOG_FILE_INTERVAL_SEC 60
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static int logging_thread_created = 0;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

