#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define OTP_REG        0x66
#define MEASURE_CMD    0x4011
#define MEASURE_DELAY_MS 20
#define POLL_INTERVAL_MS 1000
#define HIGH_ALT_THRESHOLD_PA 95000.0f
#define LED_GPIO_LINE  17
#define GPIO_CHIP      "gpiochip4"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration(int fd, uint16_t *cal) {
    if (i2c_write_cmd(fd, OTP_REG) < 0)
        return -1;
    usleep(1000);
    uint8_t buf[8];
    if (i2c_read_bytes(fd, buf, 8) < 0)
        return -1;
    for (int i = 0; i < 4; i++) {
        if (crc8(&buf[i * 2], 2) != buf[i * 2 + 1]) {
            fprintf(stderr, "Calibration CRC mismatch at index %d\n", i);
            return -1;
        }
        cal[i] = ((uint16_t)buf[i * 2] << 8) | buf[i * 2 + 1];
    }
    return 0;
}

static int read_sensor(int fd, const uint16_t *cal, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0)
        return -1;
    usleep(MEASURE_DELAY_MS * 1000);
    uint8_t buf[6];
    if (i2c_read_bytes(fd, buf, 6) < 0)
        return -1;
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    uint32_t raw_t = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    float p_comp = (float)raw_p / 65536.0f;
    float t_comp = (float)raw_t / 65536.0f;
    *pressure = cal[0] + cal[1] * p_comp + cal[2] * t_comp + cal[3] * p_comp * t_comp;
    *temperature = -45.0f + 175.0f * t_comp;
    return 0;
}

static void sleep_ms(int ms) {
    struct timespec ts = { ms / 1000, (ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ICP10125_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t cal[4];
    if (read_calibration(fd, cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "icp10125_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    printf("ICP-10125 initialized. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure, temperature;
        if (read_sensor(fd, cal, &pressure, &temperature) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        int led_state = (pressure < HIGH_ALT_THRESHOLD_PA) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        }

        int blink_ms = (pressure < HIGH_ALT_THRESHOLD_PA) ? 100 : 500;
        sleep_ms(blink_ms);
        if (gpiod_line_set_value(led, 0) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        }
        sleep_ms(blink_ms);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

