#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    int raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw = i2cReadWordData(handle, reg);
        if (raw >= 0) {
            *temp = (float)raw * 0.02f - 273.15f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
        }
    }
    return -1;
}

static void control_fan(int gpio, float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(gpio, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (object %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(gpio, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (object %.2f C)\n", object_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    } else {
        fprintf(fp, "Timestamp error, Ambient: %.2f C, Object: %.2f C\n", ambient, object);
    }

    fclose(fp);
}

int main(void) {
    float ambient_temp, object_temp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MLX90614_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90614 temperature monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(i2c_handle, AMBIENT_TEMP_REG, &ambient_temp) == 0 &&
            read_temperature(i2c_handle, OBJECT_TEMP_REG, &object_temp) == 0) {
            printf("Ambient: %.2f C, Object: %.2f C\n", ambient_temp, object_temp);
            log_temperature(ambient_temp, object_temp);
            control_fan(FAN_GPIO, object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(2000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

