#define MEAS_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define MEAS_TRIGGER 0x01
#define MAX_RETRIES 3
#define POLL_DELAY_US 10000
#define MEAS_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, uint16_t *temperature, uint16_t *humidity) {
    uint8_t config_val;
    uint8_t meas_config_val;
    int retries = 0;

    if (write_register(handle, MEAS_CONFIG_REG, MEAS_TRIGGER) < 0) {
        return -1;
    }

    while (retries < MAX_RETRIES) {
        if (read_register(handle, MEAS_CONFIG_REG, &meas_config_val) < 0) {
            return -1;
        }
        if ((meas_config_val & 0x01) == 0) {
            break;
        }
        gpioDelay(POLL_DELAY_US);
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Measurement timeout\n");
        return -1;
    }

    uint8_t temp_low, temp_high, humid_low, humid_high;

    if (read_register(handle, TEMP_REG, &temp_low) < 0) return -1;
    if (read_register(handle, TEMP_REG + 1, &temp_high) < 0) return -1;
    if (read_register(handle, HUMID_REG, &humid_low) < 0) return -1;
    if (read_register(handle, HUMID_REG + 1, &humid_high) < 0) return -1;

    *temperature = ((uint16_t)temp_high << 8) | temp_low;
    *humidity = ((uint16_t)humid_high << 8) | humid_low;

    return 0;
}

static float convert_temperature(uint16_t raw_temperature) {
    return ((float)raw_temperature / 65536.0f) * 165.0f - 40.0f;
}

static float convert_humidity(uint16_t raw_humidity) {
    return ((float)raw_humidity / 65536.0f) * 100.0f;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t config_val;
    if (read_register(i2c_handle, CONFIG_REG, &config_val) < 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", HDC2010_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("HDC2010 detected. Config register: 0x%02X\n", config_val);

    while (running) {
        uint16_t raw_temperature, raw_humidity;

        if (read_measurement(i2c_handle, &raw_temperature, &raw_humidity) == 0) {
            float temperature = convert_temperature(raw_temperature);
            float humidity = convert_humidity(raw_humidity);

            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nExiting gracefully...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

