#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_TEMP 250.0
#define MIN_TEMP 0.0
#define MAX_DUTY_CYCLE 1.0
#define MIN_DUTY_CYCLE 0.0
#define KP 1.0
#define KI 0.01
#define KD 0.1
#define SAMPLE_INTERVAL_SEC 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    float time;
    float temperature;
} TemperatureProfile;

typedef struct {
    float kp;
    float ki;
    float kd;
    float integral;
    float previous_error;
} PIDController;

int read_temperature(int spi_fd, float *temperature) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_temp = (rx[0] << 8) | rx[1];
    if (raw_temp & 0x0004) {
        fprintf(stderr, "MAX6675 open circuit detected\n");
        return -1;
    }

    *temperature = (raw_temp >> 4) * 0.25;
    return 0;
}

float calculate_pid(PIDController *pid, float setpoint, float actual) {
    float error = setpoint - actual;
    pid->integral += error;
    float derivative = error - pid->previous_error;
    float output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->previous_error = error;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    if (output < MIN_DUTY_CYCLE) output = MIN_DUTY_CYCLE;
    return output;
}

int load_temperature_profile(const char *filename, TemperatureProfile **profile, int *num_points) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening profile file: %s\n", strerror(errno));
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        count++;
    }
    rewind(fp);

    *profile = (TemperatureProfile *)malloc(count * sizeof(TemperatureProfile));
    if (!*profile) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(fp);
        return -1;
    }

    *num_points = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (sscanf(line, "%f,%f", &(*profile)[*num_points].time, &(*profile)[*num_points].temperature) == 2) {
            (*num_points)++;
        } else {
            fprintf(stderr, "Invalid format in profile file at line %d\n", *num_points + 1);
            free(*profile);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

float get_target_temperature(float time, TemperatureProfile *profile, int num_points) {
    if (time <= profile[0].time) return profile[0].temperature;
    if (time >= profile[num_points - 1].time) return profile[num_points - 1].temperature;

    for (int i = 0; i < num_points - 1; i++) {
        if (time >= profile[i].time && time <= profile[i + 1].time) {
            float t1 = profile[i].temperature;
            float t2 = profile[i + 1].temperature;
            float t1_time = profile[i].time;
            float t2_time = profile[i + 1].time;
            return t1 + (time - t1_time) * (t2 - t1) / (t2_time - t1_time);
        }
    }
    return profile[num_points - 1].temperature;
}

int log_data(const char *filename, float time, float temperature, float duty_cycle) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", time, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 || ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
