#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define RELAY_LINE 17
#define PWM_LINE 18
#define PWM_PERIOD_NS 10000000  // 10ms period for 100Hz
#define LOG_FILE "greenhouse.log"
#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"
#define MAX_SENSORS 10
#define MAX_PATH_LEN 256

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int read_temperature(const char *sensor_id, float *temperature) {
    char path[MAX_PATH_LEN];
    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_DIR, sensor_id, W1_SLAVE_FILE);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    // Validate CRC
    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    // Extract temperature from line 2
    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

int find_sensors(char sensor_ids[][20], int max_sensors) {
    DIR *dir = opendir(W1_DEVICES_DIR);
    if (!dir) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return -1;
    }

    struct dirent *entry;
    int count = 0;
    while ((entry = readdir(dir)) != NULL && count < max_sensors) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            strncpy(sensor_ids[count], entry->d_name, sizeof(sensor_ids[count]) - 1);
            sensor_ids[count][sizeof(sensor_ids[count]) - 1] = '\0';
            count++;
        }
    }
    closedir(dir);

    if (count == 0) {
        fprintf(stderr, "No DS18B20 sensors found\n");
        return -1;
    }
    return count;
}

float calculate_pid(float setpoint, float current_temp, float *integral, float *previous_error, float Kp, float Ki, float Kd) {
    float error = setpoint - current_temp;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

int set_pwm_duty_cycle(struct gpiod_line *pwm_line, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    int on_time_ns = (PWM_PERIOD_NS * duty_cycle) / 100;
    int off_time_ns = PWM_PERIOD_NS - on_time_ns;

    struct timespec on_ts = {0, on_time_ns};
    struct timespec off_ts = {0, off_time_ns};

    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Failed to set PWM high: %s\n", strerror(errno));
        return -1;
    }
    nanosleep(&on_ts, NULL);

    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Failed to set PWM low: %s\n", strerror(errno));
        return -1;
    }
    nanosleep(&off_ts, NULL);

    return 0;
}

int log_data(FILE *log_file, float average_temp, float setpoint, float pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, average_temp, setpoint, pid_output, duty_cycle) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);
    float Kd = atof(argv[4]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_LINE);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line %d: %s\n", RELAY_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *pwm_line = gpiod_chip_get_line(chip, PWM_LINE);
    if (!pwm_line) {
        fprintf(stderr, "Failed to get PWM line %d: %s\n", PWM_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "greenhouse_relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(pwm_line, "greenhouse_pwm", 0) < 0) {
        fprintf(stderr, "Failed to request PWM line as output: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    char sensor_ids[MAX_SENSORS][20];
    int num_sensors = find_sensors(sensor_ids, MAX_SENSORS);
    if (num_sensors < 0) {
        fclose(log_file);
        gpiod_line_release(relay_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    float temperatures[MAX_SENSORS];
    float integral = 0.0f;
    float previous_error = 0.0f;

    while (program_running) {
        float sum = 0.0f;
        int valid_readings = 0;

        for (int i = 0; i < num_sensors; i++) {
            if (read_temperature(sensor_ids[i], &temperatures[i]) == 0) {
                sum += temperatures[i];
                valid_readings++;
            } else {
                fprintf(stderr, "Failed to read temperature from sensor %s\n", sensor_ids[i]);
            }
        }

        if (valid_readings == 0) {
            fprintf(stderr, "No valid temperature readings, skipping cycle\n");
            sleep(5);
            continue;
        }

        float average_temp = sum / valid_readings;
        float pid_output = calculate_pid(setpoint, average_temp, &integral, &previous_error, Kp, Ki, Kd);

        int duty_cycle = (int)pid_output;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        if (set_pwm_duty_cycle(pwm_line, duty_cycle) < 0) {
            fprintf(stderr, "PWM control failed, continuing\n");
        }

        if (log_data(log_file, average_temp, setpoint, pid_output, duty_cycle) < 0) {
            fprintf(stderr, "Logging failed, continuing\n");
        }

        sleep(5);
    }

    // Cleanup
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_set_value(pwm_line, 0);
    gpiod_line_release(relay_line);
    gpiod_line_release(pwm_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    printf("Program terminated cleanly.\n");
    return 0;
}

