#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LINE      17
#define HUMIDITY_HIGH  60.0f
#define HUMIDITY_LOW   55.0f
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL  5
#define MEASURE_DELAY  80000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd, uint8_t arg1, uint8_t arg2) {
    uint8_t buf[3] = {cmd, arg1, arg2};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 3) == 3) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len) return 0;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int aht20_init(int fd) {
    if (i2c_write_cmd(fd, 0xBE, 0x08, 0x00) < 0) {
        fprintf(stderr, "AHT20 init failed (write)\n");
        return -1;
    }
    usleep(15000);
    return 0;
}

static int aht20_read(int fd, float *humidity) {
    if (i2c_write_cmd(fd, 0xAC, 0x33, 0x00) < 0) {
        fprintf(stderr, "AHT20 trigger failed\n");
        return -1;
    }
    usleep(MEASURE_DELAY);

    uint8_t data[6];
    if (i2c_read_bytes(fd, data, 6) < 0) {
        fprintf(stderr, "AHT20 read failed\n");
        return -1;
    }

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy or not calibrated\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    *humidity = (100.0f * raw) / 0x1000000;
    return 0;
}

static void log_data(float humidity, int relay_state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    printf("[%s] Humidity: %.2f%%, Relay: %s\n", ts, humidity, relay_state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 not detected at 0x%02X\n", AHT20_ADDR);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "aht20_relay", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    int relay_state = 0;

    while (running) {
        float humidity;
        if (aht20_read(i2c_fd, &humidity) == 0) {
            if (humidity > HUMIDITY_HIGH && !relay_state) {
                if (gpiod_line_set_value(line, 1) == 0) {
                    relay_state = 1;
                    printf("Humidity %.2f%% > %.1f%%, turning relay ON\n", humidity, HUMIDITY_HIGH);
                } else {
                    perror("gpiod_line_set_value ON");
                }
            } else if (humidity < HUMIDITY_LOW && relay_state) {
                if (gpiod_line_set_value(line, 0) == 0) {
                    relay_state = 0;
                    printf("Humidity %.2f%% < %.1f%%, turning relay OFF\n", humidity, HUMIDITY_LOW);
                } else {
                    perror("gpiod_line_set_value OFF");
                }
            }
            log_data(humidity, relay_state);
        } else {
            fprintf(stderr, "Sensor read failed after retries\n");
        }
        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

