#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define API_KEY "YOUR_API_KEY"
#define READ_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sock_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

int read_humidity(int fd, float *humidity) {
    uint8_t cmd = 0xE5;
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_cmd(fd, cmd) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        usleep(10000);

        if (i2c_read_bytes(fd, buf, 3) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            syslog(LOG_ERR, "CRC mismatch on humidity data");
            retries++;
            sleep(1);
            continue;
        }

        uint16_t raw = (buf[0] << 8) | buf[1];
        raw &= 0xFFFC;
        *humidity = -6.0f + (125.0f * (float)raw / 65536.0f);
        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d retries", MAX_RETRIES);
    return -1;
}

int send_http_post(const char *json_data) {
    struct sockaddr_in server_addr;
    char request[512];
    int len = snprintf(request, sizeof(request),
        "POST %s HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Authorization: Bearer %s\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s",
        API_ENDPOINT, strlen(json_data), API_KEY, json_data);

    if (len < 0 || (size_t)len >= sizeof(request)) {
        syslog(LOG_ERR, "HTTP request buffer too small");
        return -1;
    }

    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, "api.example.com", &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: api.example.com");
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    if (connect(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    ssize_t sent = send(sock_fd, request, strlen(request), 0);
    if (sent < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    char response[1024];
    ssize_t recvd = recv(sock_fd, response, sizeof(response) - 1, 0);
    if (recvd < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }
    response[recvd] = '\0';

    if (strstr(response, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP POST failed: %s", response);
        close(sock_fd);
        sock_fd = -1;
        return -1;
    }

    close(sock_fd);
    sock_fd = -1;
    return 0;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            char json_data[128];
            int len = snprintf(json_data, sizeof(json_data),
                "{\"humidity\": %.2f}", humidity);
            if (len > 0 && (size_t)len < sizeof(json_data)) {
                if (send_http_post(json_data) == 0) {
                    syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
                } else {
                    syslog(LOG_ERR, "Failed to send HTTP POST");
                }
            } else {
                syslog(LOG_ERR, "JSON formatting failed");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (sock_fd >= 0) close(sock_fd);
    closelog();
    return 0;
}

