#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define AHT20_ADDR 0x38
#define AHT20_INIT_CMD {0xBE, 0x08, 0x00}
#define AHT20_MEASURE_CMD {0xAC, 0x33, 0x00}
#define PIR_GPIO_CHIP "gpiochip4"
#define PIR_GPIO_LINE 17
#define LOG_FILE_PREFIX "sensor_data_"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t program_running = 1;
static int i2c_fd_tmp117 = -1;
static int i2c_fd_aht20 = -1;
static struct gpiod_chip *pir_chip = NULL;
static struct gpiod_line *pir_line = NULL;
static char current_log_filename[256] = {0};

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int i2c_write_bytes(int fd, const uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int init_tmp117(void) {
    i2c_fd_tmp117 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C bus for TMP117: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd_tmp117, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
        return -1;
    }
    return 0;
}

static int init_aht20(void) {
    i2c_fd_aht20 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C bus for AHT20: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd_aht20, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
