#include <linux/gpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define GPIO_CHIP_NAME "gpiochip4"
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_DURATION_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
    printf("[%s] %s\n", buf, message);
    fflush(stdout);
}

static int gpio_request_output(struct gpiod_line *line, const char *consumer, int value) {
    if (gpiod_line_request_output(line, consumer, value) < 0) {
        fprintf(stderr, "Failed to request output on line %d: %s\n",
                gpiod_line_offset(line), strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_request_input(struct gpiod_line *line, const char *consumer) {
    if (gpiod_line_request_input(line, consumer) < 0) {
        fprintf(stderr, "Failed to request input on line %d: %s\n",
                gpiod_line_offset(line), strerror(errno));
        return -1;
    }
    return 0;
}

static int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read rain sensor on line %d: %s\n",
                gpiod_line_offset(line), strerror(errno));
        return -1;
    }
    return value;
}

static int motor_forward(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2) {
    if (gpiod_line_set_value(enable, 1) < 0) {
        fprintf(stderr, "Failed to set enable high: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in1, 1) < 0) {
        fprintf(stderr, "Failed to set IN1 high: %s\n", strerror(errno));
        gpiod_line_set_value(enable, 0);
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        fprintf(stderr, "Failed to set IN2 low: %s\n", strerror(errno));
        gpiod_line_set_value(enable, 0);
        gpiod_line_set_value(in1, 0);
        return -1;
    }
    return 0;
}

static int motor_stop(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2) {
    if (gpiod_line_set_value(enable, 0) < 0) {
        fprintf(stderr, "Failed to set enable low: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in1, 0) < 0) {
        fprintf(stderr, "Failed to set IN1 low: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        fprintf(stderr, "Failed to set IN2 low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!rain_line || !enable_line || !in1_line || !in2_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_request_input(rain_line, "rain_sensor") < 0) {
        goto cleanup;
    }
    if (gpio_request_output(enable_line, "motor_enable", 0) < 0) {
        goto cleanup;
    }
    if (gpio_request_output(in1_line, "motor_in1", 0) < 0) {
        goto cleanup;
    }
    if (gpio_request_output(in2_line, "motor_in2", 0) < 0) {
        goto cleanup;
    }

    log_event("Rain sensor monitoring started.");

    while (program_running) {
        int rain_value = read_rain_sensor(rain_line);
        if (rain_value < 0) {
            log_event("Error reading rain sensor, retrying in 1 second.");
            sleep(1);
            continue;
        }

        if (rain_value == 0) {
            log_event("Rain detected! Closing window.");
            if (motor_forward(enable_line, in1_line, in2_line) < 0) {
                log_event("Error starting motor, retrying in 1 second.");
                sleep(1);
                continue;
            }

            for (int i = 0; i < MOTOR_RUN_DURATION_SEC && program_running; i++) {
                sleep(1);
            }

            if (motor_stop(enable_line, in1_line, in2_line) < 0) {
                log_event("Error stopping motor.");
            }
            log_event("Window closed.");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_event("Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    if (enable_line) gpiod_line_release(enable_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

