#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_stats(unsigned long long *prev_idle, unsigned long long *prev_total) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        perror("fgets");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Failed to parse /proc/stat\n");
        return -1;
    }

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_idle && prev_total) {
        unsigned long long prev_idle_total = *prev_idle + *prev_total;
        unsigned long long idle_diff = idle_total - prev_idle_total;
        unsigned long long total_diff = total - *prev_total;

        if (total_diff > 0) {
            double cpu_usage = (double)(total_diff - idle_diff) / total_diff;
            return (int)(cpu_usage * 100.0);
        }
    }

    *prev_idle = idle_total;
    *prev_total = total;
    return 0;
}

static void set_led_color(int red, int green, int blue) {
    if (red < 0) red = 0;
    if (red > PWM_RANGE) red = PWM_RANGE;
    if (green < 0) green = 0;
    if (green > PWM_RANGE) green = PWM_RANGE;
    if (blue < 0) blue = 0;
    if (blue > PWM_RANGE) blue = PWM_RANGE;

    /* Common-anode LED: invert PWM values */
    gpioPWM(RED_PIN, PWM_RANGE - red);
    gpioPWM(GREEN_PIN, PWM_RANGE - green);
    gpioPWM(BLUE_PIN, PWM_RANGE - blue);
}

static void map_cpu_to_color(int cpu_load, int *red, int *green, int *blue) {
    if (cpu_load < 0) cpu_load = 0;
    if (cpu_load > 100) cpu_load = 100;

    if (cpu_load < 50) {
        *red = (cpu_load * 51) / 50;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = (255 - ((cpu_load - 50) * 51) / 50);
        *blue = 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    unsigned long long prev_idle = 0, prev_total = 0;
    int first_sample = 1;

    while (running) {
        int cpu_load = read_cpu_stats(&prev_idle, &prev_total);
        if (cpu_load < 0) {
            fprintf(stderr, "Failed to read CPU stats, retrying in 1 second...\n");
            gpioDelay(1000000);
            continue;
        }

        if (first_sample) {
            first_sample = 0;
            /* Seed previous values with current sample so first iteration is valid */
            prev_idle = (unsigned long long)cpu_load * 10;
            prev_total = 1000;
        }

        int red, green, blue;
        map_cpu_to_color(cpu_load, &red, &green, &blue);
        set_led_color(red, green, blue);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: turn LED off (full off for common-anode) */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return 0;
}

