#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define BUFFER_SIZE     20
#define SAMPLE_PERIOD_S 1.0

#define TEMP_MIN 25.0
#define TEMP_MAX 60.0
#define DUTY_MIN 0
#define DUTY_MAX 255

#define DUTY_LOW  0
#define DUTY_MED  50
#define DUTY_HIGH 200
#define DUTY_FULL 255

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;
static int    spi_handle   = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, %d Hz).\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X).\n", raw);
        if (raw & 0x00000001) fprintf(stderr, "  Fault: Open circuit.\n");
        if (raw & 0x00000002) fprintf(stderr, "  Fault: Short to GND.\n");
        if (raw & 0x00000004) fprintf(stderr, "  Fault: Short to VCC.\n");
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < TEMP_MIN) return DUTY_LOW;
    if (temperature < 40.0f)  return (int)(((temperature - TEMP_MIN) / (40.0f - TEMP_MIN)) * (DUTY_MED - DUTY_LOW) + DUTY_LOW);
    if (temperature < TEMP_MAX) return (int)(((temperature - 40.0f) / (TEMP_MAX - 40.0f)) * (DUTY_HIGH - DUTY_MED) + DUTY_MED);
    return DUTY_FULL;
}

static void set_fan_speed(int duty_cycle) {
    if (duty_cycle < DUTY_MIN) duty_cycle = DUTY_MIN;
    if (duty_cycle > DUTY_MAX) duty_cycle = DUTY_MAX;
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Warning: gpioPWM failed for duty %d.\n", duty_cycle);
    }
}

static void log_reading(float temperature, int duty_cycle) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle   = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Circular Buffer Contents (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, Duty: %d\n", ts, buffer[idx].temperature, buffer[idx].duty_cycle);
    }
    printf("--------------------------------------------\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize() != 0) {
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        if (read_max31855(&temperature) == 0) {
            int duty_cycle = calculate_duty_cycle(temperature);
            set_fan_speed(duty_cycle);
            log_reading(temperature, duty_cycle);
            printf("Temp: %.2f C, Duty: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Skipping fan update due to read/fault error.\n");
        }
        time_sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    print_buffer();
    cleanup();
    printf("Fan control stopped.\n");
    return 0;
}

