#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO_CHIP "gpiochip4" // RP1 GPIO chip on Raspberry Pi 5
#define CS_GPIO_LINE 8 // GPIO8 (SPI0 CE0)
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Register Addresses
#define RTD_MSB_REG 0x00
#define RTD_LSB_REG 0x01
#define HF_MSB_REG 0x02
#define HF_LSB_REG 0x03
#define LF_MSB_REG 0x04
#define LF_LSB_REG 0x05
#define CONFIG_REG 0x06
#define FAULT_REG 0x07

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int max31865_read_register(uint8_t reg, uint8_t *value);
int max31865_write_register(uint8_t reg, uint8_t value);
int max31865_init(void);
int max31865_read_rtd(uint16_t *rtd_raw);
int max31865_read_fault(uint8_t *fault_status);
float calculate_temperature(uint16_t rtd_raw);
int log_data(float temperature);
void signal_handler(int signal);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    // Set SPI mode (Mode 0)
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set bits per word (8 bits)
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a register from the MAX31865
int max31865_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx_buf[2] = {reg & 0x7F, 0x00}; // Read command (bit 7 = 0)
    uint8_t rx_buf[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// Function to write a register to the MAX31865
int max31865_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2] = {reg | 0x80, value}; // Write command (bit 7 = 1)
    uint8_t rx_buf[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// MAX31865 initialization function
int max31865_init(void) {
    // Configure the MAX31865 for 3-wire RTD mode with bias voltage enabled
    // Config register: VBIAS=1 (bit 7), 50Hz filter=0 (bit 6), Auto-convert=0 (bit 5), 3-wire=1 (bit 4), Fault status clear=1 (bit 3), Fault detection 1 (bit 2-0) = 111 (140°C)
    uint8_t config = 0x80 | 0x40 | 0x20 | 0x10 | 0x08 | 0x07;
    if (max31865_write_register(CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    // Wait for the first conversion to complete (typical 750ms for 50Hz filter)
    usleep(1000000); // 1 second

    return 0;
}

// Function to read the RTD value from the MAX31865
int max31865_read_rtd(uint16_t *rtd_raw) {
    uint8_t msb, lsb;

    if (max31865_read_register(RTD_MSB_REG, &msb) < 0) {
        return -1;
    }
    if (max31865_read_register(RTD_LSB_REG, &lsb) < 0) {
        return -1;
    }

    *rtd_raw = ((uint16_t)msb << 8) | lsb;
    return 0;
}

