int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read a register from the MAX31865
int max31865_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx_buf[2] = {reg & 0x7F, 0x00}; // Read command (bit 7 = 0)
    uint8_t rx_buf[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// Function to write a register to the MAX31865
int max31865_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2] = {reg | 0x80, value}; // Write command (bit 7 = 1)
    uint8_t rx_buf[2] = {0};

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// MAX31865 initialization function
int max31865_init(void) {
    // Configure the MAX31865 for 3-wire RTD mode with bias voltage enabled
    // Config register: VBIAS=1 (bit 7), 50Hz filter=0 (bit 6), Auto-convert=0 (bit 5), 3-wire=1 (bit 4), Fault status clear=1 (bit 3), Fault detection 1 (bit 2-0) = 111 (140°C)
    uint8_t config = 0x80 | 0x40 | 0x20 | 0x10 | 0x08 | 0x07;
    if (max31865_write_register(CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }

    // Wait for the first conversion to complete (typical 750ms for 50Hz filter)
    usleep(1000000); // 1 second

    return 0;
}

