#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB00 0x88
#define BME280_REG_CALIB26 0xE1

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
} bme280_calib_data;

static bme280_calib_data calib;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(i2c_fd, buf, len) != (ssize_t)len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_calibration_data(void) {
    uint8_t buf[26];
    if (i2c_read_regs(BME280_REG_CALIB00, buf, 26) < 0) return -1;
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    calib.dig_H1 = buf[25];

    uint8_t h_buf[7];
    if (i2c_read_regs(BME280_REG_CALIB26, h_buf, 7) < 0) return -1;
    calib.dig_H2 = (int16_t)(h_buf[0] | (h_buf[1] << 8));
    calib.dig_H3 = h_buf[2];
    calib.dig_H4 = (int16_t)((h_buf[3] << 4) | (h_buf[4] & 0x0F));
    calib.dig_H5 = (int16_t)((h_buf[5] << 4) | (h_buf[4] >> 4));
    calib.dig_H6 = (int8_t)h_buf[6];
    return 0;
}

static int init_bme280(void) {
    uint8_t chip_id;
    if (i2c_read_regs(BME280_REG_ID, &chip_id, 1) < 0) return -1;
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(BME280_REG_RESET, BME280_RESET_CMD) < 0) return -1;
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_regs(BME280_REG_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "Error: BME280 reset timeout\n");
        return -1;
    }

    if (read_calibration_data() < 0) return -1;

    if (i2c_write_reg(BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int read_bme280_data(float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_regs(BME280_REG_DATA, data, 8) < 0) return -1;

    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];

    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = (((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0)) * (double)calib.dig_T3;
    t_fine = (int32_t)(var1 + var2);
    *temp = (float)((var1 + var2) / 5120.0);

    double vh1 = (double)t_fine - 76800.0;
    double vh2 = (double)raw_hum - ((double)calib.dig_H4 * 64.0 + (double)calib.dig_H5 / 16384.0 * vh1);
    double vh3 = vh2 * ((double)calib.dig_H2 / 65536.0 * (1.0 + (double)calib.dig_H6 / 67108864.0 * vh1 * (1.0 + (double)calib.dig_H3 / 67108864.0 * vh1)));
    double vh4 = (double)calib.dig_H1 * vh3 / 524288.0;
    double vh5 = vh4 * (1.0 - vh4 / 524288.0);
    if (vh5 < 0.0) vh5 = 0.0;
    if (vh5 > 100.0) vh5 = 100.0;
    *hum = (float)vh5;

    double var3 = ((double)t_fine / 2.0) - 64000.0;
    double var4 = var3 * var3 * (double)calib.dig_P6 / 32768.0;
    var4 = var4 + var3 * (double)calib.dig_P5 * 2.0;
    var4 = (var4 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var3 = ((double)calib.dig_P3 * var3 * var3 / 524288.0 + (double)calib.dig_P2 * var3) / 524288.0;
    var3 = (1.0 + var3 / 32768.0) * (double)calib.dig_P1;
    if (var3 == 0.0) return -1;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var4 / 4096.0)) * 6250.0 / var3;
    var3 = (double)calib.dig_P9 * p * p / 2147483648.0;
