#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_START 0xAA

// Oversampling setting (OSS = 0 for ultra-low power)
#define OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Pressure deviation threshold (hPa)
#define PRESSURE_DEVIATION_THRESHOLD 5.0

// Circular buffer size (60 seconds * 100 ms)
#define BUFFER_SIZE 600

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Calibration coefficients
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

PressureReading pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_bmp180_calibration_data();
int read_bmp180_raw_temperature(int32_t *raw_temperature);
int read_bmp180_raw_pressure(int32_t *raw_pressure);
float calculate_pressure(int32_t raw_temperature, int32_t raw_pressure);
void add_to_buffer(float pressure);
float calculate_rolling_average();
void check_pressure_deviation(float current_pressure);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);
void cleanup();

// Function to read calibration data from the BMP180
int read_bmp180_calibration_data() {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_START, buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data from BMP180\n");
        return -1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_bmp180_raw_temperature(int32_t *raw_temperature) {
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) {
        fprintf(stderr, "Error: Failed to write temperature request to BMP180\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms for conversion
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data from BMP180\n");
        return -1;
    }
    *raw_temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_bmp180_raw_pressure(int32_t *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) != 0) {
        fprintf(stderr, "Error: Failed to write pressure request to BMP180\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5 ms for conversion (OSS=0)
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read pressure data from BMP180\n");
        return -1;
    }
    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int32_t raw_temperature, int32_t raw_pressure) {
    int32_t x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    x1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)raw_pressure - b3) * (50000 >> OSS);

    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p / 100.0; // Convert to hPa
}

// Function to add a pressure reading to the circular buffer
void add_to_buffer(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average pressure
float calculate_rolling_average() {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (pressure_buffer[i].timestamp != 0) {
            sum += pressure_buffer[i].pressure;
            count++;
        }
    }
    if (count == 0) {
        return 0.0;
    }
    return sum / count;
}

// Function to check if the current pressure deviates from the rolling average
void check_pressure_deviation(float current_pressure) {
    float rolling_average = calculate_rolling_average();
    float deviation = fabs(current_pressure - rolling_average);

    if (deviation > PRESSURE_DEVIATION_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Activate alert
        fprintf(stderr, "Alert: Pressure deviation detected! Current: %.2f hPa, Rolling Average: %.2f hPa, Deviation: %.2f hPa\n",
                current_pressure, rolling_average, deviation);
    } else {
        gpioWrite(ALERT_GPIO, 0); // Deactivate alert
    }
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    (void)timer_id;
    (void)user_data;

    int32_t raw_temperature, raw_pressure;

    if (read_bmp180_raw_temperature(&raw_temperature) == 0 &&
        read_bmp180_raw_pressure(&raw_pressure) == 0) {
        float pressure = calculate_pressure(raw_temperature, raw_pressure);
        add_to_buffer(pressure);
        check_pressure_deviation(pressure);
        printf("Pressure: %.2f hPa\n", pressure);
    } else {
        fprintf(stderr, "Error: Failed to read sensor data\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup function
void cleanup() {
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is off
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_bmp180_calibration_data() != 0) {
        fprintf(stderr, "Error: Failed to read calibration data. Sensor may be absent.\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin as output and ensure it's off
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback function (every 50 ms)
    if (gpioSetTimerFuncEx(0, 50, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer function\n");
        cleanup();
        return 1;
    }

    printf("BMP180 pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100000); // Sleep for 100 ms
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

