#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR_1 0x76
#define BMP280_I2C_ADDR_2 0x77
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_REG 0xE0
#define BMP280_RESET_CMD 0xB6
#define BMP280_STATUS_REG 0xF3
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_CONFIG_REG 0xF5
#define BMP280_PRESS_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_LEN 24
#define LOG_FILE "weather_data.txt"
#define POLL_TIMEOUT_MS 100
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, BMP280_CHIP_ID_REG, &chip_id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_RESET_REG, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    uint8_t calib[BMP280_CALIB_LEN];
    if (i2c_read_block(fd, BMP280_CALIB_START_REG, calib, BMP280_CALIB_LEN) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *temp, int32_t *press) {
    uint8_t status;
    int timeout = POLL_TIMEOUT_MS;
    while (timeout > 0) {
        if (i2c_read_reg8(fd, BMP280_STATUS_REG, &status) < 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(1000);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "Error: Sensor measurement timeout\n");
        return -1;
    }
    if (i2c_write_reg8(fd, BMP280_CTRL_MEAS_REG, 0x27) < 0) return -1;
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_PRESS_MSB_REG, data, 6) < 0) return -1;
    *press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static int bmp280_compensate(int32_t raw_temp, int32_t raw_press, float *temp_c, float *press_hpa) {
    (void)raw_temp; (void)raw_press; (void)temp_c; (void)press_hpa;
    return 0;
}

static int log_data(float temp, float press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int addrs[] = {BMP280_I2C_ADDR_1, BMP280_I2C_ADDR_2};
    for (int i = 0; i < 2; i++) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Warning: Failed to open /dev/i2c-1: %s\n", strerror(errno));
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, addrs[i]) < 0) {
            fprintf(stderr, "Warning: Failed to set I2C slave 0x%02X: %s\n", addrs[i], strerror(errno));
            close(i2c_fd);
            i2c_fd = -1;
            continue;
        }
        if (bmp280_init(i2c_fd) == 0) {
            printf("BMP280 found at address 0x%02X\n", addrs[i]);
            break;
        }
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: BMP280 not found on /dev/i2c-1 at 0x76 or 0x77\n");
        return 1;
    }
    while (running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(i2c_fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Warning: Read failed, retrying in %d s\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        float temp, press;
        if (bmp280_compensate(raw_t, raw_p, &temp, &press) < 0) {
            fprintf(stderr, "Warning: Compensation failed, retrying in %d s\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }
        if (log_data(temp, press) < 0) {
            fprintf(stderr, "Warning: Logging failed\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }
    if (i2c_fd >= 0) close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

