static volatile sig_atomic_t running = 1;

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

