#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <jansson.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define CONFIG_FILE "config.json"
#define MAX_TEMP 80.0
#define RTD_NOMINAL_RES 100.0
#define RTD_REF_RES 430.0
#define RTD_A 0.0039083
#define RTD_B -0.0000005775
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = 25.0;
static double kp = 1.0, ki = 0.1, kd = 0.01;
static double integral = 0.0, previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Warning: Could not load config file '%s': %s\n", filename, error.text);
        return -1;
    }
    json_t *t = json_object_get(root, "target_temperature");
    json_t *k = json_object_get(root, "kp");
    json_t *i = json_object_get(root, "ki");
    json_t *d = json_object_get(root, "kd");
    if (json_is_number(t)) target_temperature = json_number_value(t);
    if (json_is_number(k)) kp = json_number_value(k);
    if (json_is_number(i)) ki = json_number_value(i);
    if (json_is_number(d)) kd = json_number_value(d);
    json_decref(root);
    return 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = {(char)(reg & 0x7F), (char)value};
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = {(char)(reg | 0x80), 0x00};
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int init_max31865(void) {
    if (spi_write_reg(0x80, 0xC1) != 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_rtd_temperature(double *temperature) {
    uint8_t msb, lsb, fault;
    if (spi_read_reg(0x01, &msb) != 0) return -1;
    if (spi_read_reg(0x02, &lsb) != 0) return -1;
    if (spi_read_reg(0x07, &fault) != 0) return -1;
    if (fault & 0x01) {
        fprintf(stderr, "Error: MAX31865 fault detected (0x%02X)\n", fault);
        return -1;
    }
    int16_t rtd_code = ((int16_t)msb << 8) | lsb;
    rtd_code >>= 1;
    if (rtd_code == 0) {
        fprintf(stderr, "Error: RTD code is zero\n");
        return -1;
    }
    double rtd_resistance = (rtd_code / 32768.0) * RTD_REF_RES;
    double z1 = -RTD_A;
    double z2 = RTD_A * RTD_A - 4.0 * RTD_B * (1.0 - rtd_resistance / RTD_NOMINAL_RES);
    if (z2 < 0) {
        fprintf(stderr, "Error: RTD resistance out of valid range\n");
        return -1;
    }
    double t = (-RTD_A + sqrt(z2)) / (2.0 * RTD_B);
    *temperature = t;
    return 0;
}

static double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

static void cleanup(void) {
    set_heater_pwm(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }
    read_config(CONFIG_FILE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    if (init_max31865() != 0) {
        fprintf(stderr, "Error: MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    printf("Temperature control started. Target: %.2f°C, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
           target_temperature, kp, ki, kd);
    while (running) {
        double temperature;
        if (read_rtd_temperature(&temperature) != 0) {
            fprintf(stderr, "Error: Temperature read failed, shutting down\n");
            break;
        }
        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Error: Temperature exceeds max (%.2f°C), shutting down\n", MAX_TEMP);
            break;
        }
        double duty_cycle = calculate_pid(temperature);
        set_heater_pwm(duty_cycle);
        printf("Temperature: %.2f°C, Duty: %.2f%%\n", temperature, duty_cycle / PWM_RANGE * 100.0);
        gpioDelay(LOOP_DELAY_US);
    }
    cleanup();
    return 0;
}

