int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetAlertFuncEx(GPIO_PIN, toggle_logging, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO alert function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 pressure logger started. Press GPIO27 to toggle logging.\n");

    while (running) {
        if (log_file) {
            int32_t ut, up, b5, pressure;
            if (read_raw_temp(i2c_handle, &ut) == 0 && read_raw_pressure(i2c_handle, &up) == 0) {
                b5 = compute_b5(ut, &cal);
                pressure = compute_pressure(up, b5, &cal);
                log_pressure(log_file, pressure);
            } else {
                fprintf(stderr, "Error: I2C read failure during logging\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

