#include <unistd.h>
#include <errno.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define MAX_DUTY_CYCLE 80
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_max31855(int handle, float *temperature) {
    char buffer[4];
    int bytes_read = spiRead(handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read failed: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & 0x00000001) fprintf(stderr, "open circuit ");
        if (raw & 0x00000002) fprintf(stderr, "short to GND ");
        if (raw & 0x00000004) fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25f;
    return 0;
}

static void set_heater_duty_cycle(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(gpio, duty_cycle);
}

static void log_data(FILE *fp, float temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(fp);
}

int main(int argc, char *argv[]) {
    float target_temperature = 25.0f;
    if (argc > 1) {
        target_temperature = atof(argv[1]);
        if (target_temperature < 0.0f || target_temperature > 1000.0f) {
            fprintf(stderr, "Invalid target temperature: %.2f\n", target_temperature);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater_duty_cycle(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0f;
    float previous_error = 0.0f;
    const float Kp = 0.1f;
    const float Ki = 0.01f;
    const float Kd = 0.05f;

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) != 0) {
            set_heater_duty_cycle(HEATER_GPIO, 0);
            log_data(log_file, -999.0f, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float error = target_temperature - temperature;
        integral += error;
        float derivative = error - previous_error;
        float output = Kp * error + Ki * integral + Kd * derivative;

        int duty_cycle = (int)(output + 0.5f);
        if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
        if (duty_cycle < 0) duty_cycle = 0;

        set_heater_duty_cycle(HEATER_GPIO, duty_cycle);
        log_data(log_file, temperature, duty_cycle);

        previous_error = error;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_heater_duty_cycle(HEATER_GPIO, 0);
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

