#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE  255
#define PWM_FREQ   1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen(" TEMP_FILE ")");
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "fscanf failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "I/O error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

static void set_rgb(int red, int green, int blue)
{
    /* Common-anode: duty 255 = off, duty 0 = full on */
    gpioPWM(RED_PIN,   PWM_RANGE - red);
    gpioPWM(GREEN_PIN, PWM_RANGE - green);
    gpioPWM(BLUE_PIN,  PWM_RANGE - blue);
}

static void mood_light(int temp)
{
    int red, green, blue;

    if (temp < 40000) {
        red   = 0;
        green = 0;
        blue  = 255;
    } else if (temp < 60000) {
        red   = 0;
        green = 255;
        blue  = 0;
    } else {
        red   = 255;
        green = 0;
        blue  = 0;
    }

    set_rgb(red, green, blue);
    printf("Temp: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off (common-anode: duty 255 = off) */
    set_rgb(0, 0, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        set_rgb(0, 0, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp >= 0) {
            mood_light(temp);
        } else {
            fprintf(stderr, "Skipping update due to temperature read failure\n");
        }
        time_sleep(0.5);
    }

    /* Clean shutdown: turn off LED and release pigpio */
    set_rgb(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

