#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    int bits[40];
    uint8_t bytes[5] = {0};

    data->valid = 0;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000); // 2 ms low
    gpioWrite(gpio, 1);
    gpioDelay(30);   // 30 us high

    // Switch to input with pull-up
    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);

    // Wait for sensor response
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) return -1; // Sensor absent
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) return -2; // Timeout
        }

        gpioDelay(40); // Wait for high pulse

        bits[i] = gpioRead(gpio);
    }

    // Convert bits to bytes
    for (i = 0; i < 40; i++) {
        j = i / 8;
        bytes[j] <<= 1;
        if (bits[i] == 1) {
            bytes[j] |= 1;
        }
    }

    // Checksum
    uint8_t checksum = bytes[0] + bytes[1] + bytes[2] + bytes[3];
    if (checksum != bytes[4]) {
        return -3; // Checksum error
    }

    // Parse data
    data->humidity = (float)((bytes[0] << 8) + bytes[1]) / 10.0;
    data->temperature = (float)(((bytes[2] & 0x7F) << 8) + bytes[3]) / 10.0;
    if (bytes[2] & 0x80) {
        data->temperature = -data->temperature;
    }

    data->valid = 1;
    return 0;
}

int post_data(const char *url, float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char json_string[256];
    int retries = 0;

    snprintf(json_string, sizeof(json_string), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    while (retries < MAX_RETRIES) {
        curl = curl_easy_init();
        if (!curl) {
            fprintf(stderr, "curl_easy_init() failed\n");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        headers = curl_slist_append(headers, "Content-Type: application/json");
        if (!headers) {
            fprintf(stderr, "curl_slist_append() failed\n");
            curl_easy_cleanup(curl);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
        } else {
            long response_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                printf("Data posted successfully.\n");
                curl_slist_free_all(headers);
                curl_easy_cleanup(curl);
                return 0;
            } else {
                fprintf(stderr, "Server returned error code: %ld\n", response_code);
