            fflush(stdout);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

