#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 10
#define DHT22_TIMEOUT_US 100000

static volatile sig_atomic_t terminate = 0;
static char *server_url = "http://your-server.com/api/humidity";

typedef struct {
    float humidity;
    int valid;
} DHT22Data;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static size_t write_cb(char *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)ptr;
    (void)userdata;
    return size * nmemb;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    char json[128];
    int ret = snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
    if (ret < 0 || (size_t)ret >= sizeof(json)) {
        syslog(LOG_ERR, "snprintf() failed or truncated");
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
    } else {
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code < 200 || http_code >= 300) {
            syslog(LOG_ERR, "HTTP POST returned status %ld", http_code);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return (res == CURLE_OK && http_code >= 200 && http_code < 300) ? 0 : -1;
}

static DHT22Data read_dht22(void) {
    DHT22Data data = {0.0f, 0};
    int retries = 0;

    while (retries < MAX_RETRIES && !terminate) {
        int dht22_data[5] = {0, 0, 0, 0, 0};
        int last_state = PI_HIGH;
        int bit_idx = 0;
        int byte_idx = 0;

        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, PI_LOW);
        gpioDelay(2000);
        gpioWrite(DHT22_GPIO, PI_HIGH);
        gpioDelay(30);
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        uint32_t start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == PI_HIGH) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: timeout waiting for sensor response (high)");
                goto retry;
            }
        }
        start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == PI_LOW) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: timeout waiting for sensor response (low)");
                goto retry;
            }
        }
        start_tick = gpioTick();
        while (gpioRead(DHT22_GPIO) == PI_HIGH) {
            if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                syslog(LOG_ERR, "DHT22: timeout waiting for sensor response (high2)");
                goto retry;
            }
        }

        for (int i = 0; i < 40; i++) {
            start_tick = gpioTick();
            while (gpioRead(DHT22_GPIO) == PI_LOW) {
                if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22: timeout waiting for bit start (low)");
                    goto retry;
                }
            }
            start_tick = gpioTick();
            while (gpioRead(DHT22_GPIO) == PI_HIGH) {
                if (gpioTick() - start_tick > DHT22_TIMEOUT_US) {
                    syslog(LOG_ERR, "DHT22: timeout waiting for bit end (high)");
                    goto retry;
                }
            }
            uint32_t high_us = gpioTick() - start_tick;
            if (high_us > 50) {
                dht22_data[byte_idx] |= (1 << (7 - bit_idx));
            }
            bit_idx++;
            if (bit_idx == 8) {
                bit_idx = 0;
                byte_idx++;
            }
        }

        if (dht22_data[4] == ((dht22_data[0] + dht22_data[1] + dht22_data[2] + dht22_data[3]) & 0xFF)) {
            uint16_t raw_humidity = (dht22_data[0] << 8) | dht22_data[1];
            data.humidity = (float)raw_humidity / 10.0f;
            data.valid = 1;
            return data;
        } else {
            syslog(LOG_ERR, "DHT22: checksum mismatch");
        }

    retry:
        retries++;
        if (retries < MAX_RETRIES) {
            syslog(LOG_WARNING, "DHT22 read failed, retry %d/%d", retries, MAX_RETRIES);
            sleep(2);
        }
    }

    syslog(LOG_ERR, "DHT22 read failed after %d retries", MAX_RETRIES);
    return data;
}

