    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity_logger", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 humidity logger (server: %s)", server_url);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
        syslog(LOG_ERR, "curl_global_init() failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        DHT22Data dht22_data = read_dht22();
        if (dht22_data.valid) {
            syslog(LOG_INFO, "Humidity: %.2f%%", dht22_data.humidity);
            if (post_humidity(dht22_data.humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 data");
        }
        sleep(READ_INTERVAL_SEC);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

