#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", CPU_TEMP_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli;
}

static int read_fan_max_state(void) {
    FILE *fp = fopen(FAN_MAX_STATE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_STATE_FILE, strerror(errno));
        return -1;
    }

    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_MAX_STATE_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return max_state;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int log_fan_speed(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Fan speed set to state %d\n", timestamp, state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int calculate_fan_state(int cpu_temp) {
    if (cpu_temp < 45000) return 0;
    if (cpu_temp < 55000) return 1;
    if (cpu_temp < 65000) return 2;
    return 3;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int current_fan_state = -1;

    while (program_running) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int max_state = read_fan_max_state();
        if (max_state == -1) {
            fprintf(stderr, "Failed to read fan max state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int desired_fan_state = calculate_fan_state(cpu_temp);

        if (desired_fan_state > max_state) {
            fprintf(stderr, "Desired fan state (%d) exceeds max state (%d). Setting to max.\n", desired_fan_state, max_state);
            desired_fan_state = max_state;
        }

        if (desired_fan_state != current_fan_state) {
            if (write_fan_state(desired_fan_state) == 0) {
                current_fan_state = desired_fan_state;
                if (log_fan_speed(desired_fan_state) != 0) {
                    fprintf(stderr, "Warning: Failed to log fan speed change.\n");
                }
            } else {
                fprintf(stderr, "Failed to write fan state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    fprintf(stderr, "Shutting down...\n");

    if (current_fan_state != -1) {
        if (write_fan_state(0) != 0) {
            fprintf(stderr, "Warning: Failed to stop fan during shutdown.\n");
        }
    }

    if (log_fan_speed(0) != 0) {
        fprintf(stderr, "Warning: Failed to log shutdown event.\n");
    }

    return 0;
}

