#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HEATER_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define LOG_FILE "heater_log.txt"
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    double Kp, Ki, Kd;
    double integral, previous_error;
    double target;
} PIDController;

static PIDController pid = {KP, KI, KD, 0.0, 0.0, TARGET_TEMPERATURE};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int read_max31855(double *temperature) {
    char buffer[4];
    int bytes_read = spiRead(spi_handle, buffer, 4);
    if (bytes_read != 4) {
        log_message("SPI read failed");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)buffer[0] << 24) |
                   ((uint32_t)(uint8_t)buffer[1] << 16) |
                   ((uint32_t)(uint8_t)buffer[2] << 8)  |
                   ((uint32_t)(uint8_t)buffer[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000004) {
            log_message("Thermocouple fault: Open circuit");
        } else if (raw & 0x00000002) {
            log_message("Thermocouple fault: Short to GND");
        } else if (raw & 0x00000001) {
            log_message("Thermocouple fault: Short to VCC");
        } else {
            log_message("Thermocouple fault: Unknown");
        }
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 18);
    *temperature = temp_raw * 0.25;
    return 0;
}

static double calculate_pid(double current_temperature) {
    double error = pid.target - current_temperature;
    pid.integral += error;
    double derivative = error - pid.previous_error;
    double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    pid.previous_error = error;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0));
    gpioPWM(HEATER_PIN, pwm_value);
}

static void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Temperature: %.2f C, PWM Duty Cycle: %.2f%%, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(HEATER_PIN, 0);
    gpioTerminate();
    if (log_file) {
        log_message("Cleanup complete");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);
    gpioPWM(HEATER_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    while (running) {
        double temperature;
        if (read_max31855(&temperature) != 0) {
            log_message("Error reading temperature, disabling heater");
            set_heater_pwm(0.0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Temperature out of range: %.2f C, disabling heater", temperature);
            log_message(msg);
            set_heater_pwm(0.0);
            pid.integral = 0.0;
            pid.previous_error = 0.0;
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double pid_output = calculate_pid(temperature);
        double duty_cycle = pid_output;
        if (duty_cycle < 0.0) duty_cycle = 0.0;
        if (duty_cycle > 100.0) duty_cycle = 100.0;
        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, pid_output);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

