#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define PWM_FREQUENCY 25000
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }

    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "Error reading temperature value\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    *temp = (float)raw / 1000.0;
    return 0;
}

static int calculate_pwm_duty(float temp) {
    if (temp <= MIN_TEMP) return 0;
    if (temp >= MAX_TEMP) return 100;

    float range = MAX_TEMP - MIN_TEMP;
    float val = (temp - MIN_TEMP) / range;
    return (int)(val * 100.0);
}

static int log_data(float temp, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temp, duty);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Could not set PWM frequency to %d Hz\n", PWM_FREQUENCY);
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Temperature (C),PWM Duty Cycle (%%)\n");
            fclose(fp);
        } else {
            perror("Error creating log file");
            gpioTerminate();
            return 1;
        }
    } else {
        fclose(fp);
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL);
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty = calculate_pwm_duty(temp);

        if (gpioPWM(FAN_GPIO, duty) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty);
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Temperature: %.2f°C, PWM Duty Cycle: %d%%\n", temp, duty);

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan control stopped.\n");

    return 0;
}

