static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error writing measurement command to I2C handle %d\n", handle);
            retries--;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(10000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "Error reading 3 bytes from I2C handle %d\n", handle);
            retries--;
            gpioDelay(10000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on I2C handle %d\n", handle);
            retries--;
            gpioDelay(10000);
            continue;
        }

        int16_t raw_value = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw_value * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries on I2C handle %d\n", RETRY_COUNT, handle);
    return -1;
