    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2) < 0) {
        perror("Error writing to flow_log.txt");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing flow_log.txt");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
