#define SENSOR_B_PIN 18
#define PULSES_PER_REVOLUTION 360
#define LOG_FILE "encoder_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0;
}

int read_sensor_a() {
    return gpioRead(SENSOR_A_PIN);
}

int read_sensor_b() {
    return gpioRead(SENSOR_B_PIN);
}

int log_data(int sensor_a, int sensor_b, float angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Sensor A: %d, Sensor B: %d, Angular Position: %.2f\n",
                timestamp, sensor_a, sensor_b, angular_position) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    int previous_state = 0;
    int current_state;
    int sensor_a, sensor_b;
    float angular_position = 0.0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sensor_a = read_sensor_a();
        sensor_b = read_sensor_b();

        if (sensor_a < 0 || sensor_b < 0) {
            fprintf(stderr, "Error reading sensor pins\n");
            break;
        }

        current_state = (sensor_a << 1) | sensor_b;

        if (current_state != previous_state) {
            switch (current_state) {
                case 0:
                    if (previous_state == 1) {
                        angular_position += 90.0;
                    } else if (previous_state == 3) {
                        angular_position -= 90.0;
                    }
                    break;
                case 1:
                    if (previous_state == 0) {
                        angular_position += 90.0;
                    } else if (previous_state == 2) {
                        angular_position -= 90.0;
                    }
                    break;
                case 2:
                    if (previous_state == 3) {
                        angular_position += 90.0;
                    } else if (previous_state == 1) {
                        angular_position -= 90.0;
                    }
                    break;
                case 3:
                    if (previous_state == 2) {
                        angular_position += 90.0;
                    } else if (previous_state == 0) {
                        angular_position -= 90.0;
                    }
                    break;
            }

            if (angular_position >= 360.0) {
                angular_position -= 360.0;
            } else if (angular_position < 0.0) {
                angular_position += 360.0;
            }

            if (log_data(sensor_a, sensor_b, angular_position) != 0) {
                fprintf(stderr, "Logging failed, exiting.\n");
                break;
            }

            previous_state = current_state;
        }

        gpioDelay(1000);
    }

    cleanup();
    printf("Encoder monitoring stopped.\n");

    return EXIT_SUCCESS;
}

