#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define GPIO_CHIP      "gpiochip0"
#define GPIO_LED       17
#define IR_THRESHOLD   2000
#define LOG_FILE       "adpd144ri_log.txt"
#define SAMPLE_MS      100

/* ADPD144RI register addresses */
#define REG_FIFO_DATA  0x60
#define REG_FIFO_STATUS 0x61
#define REG_FIFO_CONFIG 0x62
#define REG_MODE_CONFIG 0x63
#define REG_RESET      0x64

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int adpd144ri_init(int fd)
{
    uint8_t part_id;

    /* Verify sensor presence by reading PART_ID (0x00) */
    if (i2c_read_reg8(fd, 0x00, &part_id) < 0) {
        fprintf(stderr, "ADPD144RI not responding on 0x%02X\n", ADPD144RI_ADDR);
        return -1;
    }
    if (part_id != 0x44) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x44)\n", part_id);
        return -1;
    }

    /* Software reset */
    if (i2c_write_reg8(fd, REG_RESET, 0x01) < 0)
        return -1;
    usleep(10000);

    /* Configure FIFO: 16-bit data, 1 sample per FIFO entry */
    if (i2c_write_reg8(fd, REG_FIFO_CONFIG, 0x00) < 0)
        return -1;

    /* Set mode: continuous measurement */
    if (i2c_write_reg8(fd, REG_MODE_CONFIG, 0x01) < 0)
        return -1;

    return 0;
}

static int adpd144ri_read_fifo(int fd, uint16_t *red, uint16_t *ir)
{
    uint8_t status;
    uint16_t data;

    if (i2c_read_reg8(fd, REG_FIFO_STATUS, &status) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* FIFO empty — no new data yet */
        return 1;
    }

    /* Read 16-bit red channel data */
    if (i2c_read_reg16(fd, REG_FIFO_DATA, &data) < 0)
        return -1;
    *red = data;

    /* Read 16-bit IR channel data */
    if (i2c_read_reg16(fd, REG_FIFO_DATA, &data) < 0)
        return -1;
    *ir = data;

    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

int main(void)
{
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
