#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1.0

static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)tick;
    (void)user;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_rpm(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses / interval_sec * 60.0;
}

static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d: %s\n", GPIO_PIN, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL);
    if (ret != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d: %s\n", GPIO_PIN, pigpio_error(ret));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (!terminate) {
        time_sleep(SAMPLE_INTERVAL_SEC);

        int pulses;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(pulses, SAMPLE_INTERVAL_SEC);
        log_rpm(rpm);
    }

    printf("\nShutting down...\n");

    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();

    pthread_mutex_destroy(&pulse_mutex);

    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

