#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define START_MEASUREMENT_CMD 0x3608
#define READ_INTERVAL_US 1000000
#define LOG_FILE "flow_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_sensor(void) {
    uint8_t cmd[2] = {
        (uint8_t)((START_MEASUREMENT_CMD >> 8) & 0xFF),
        (uint8_t)(START_MEASUREMENT_CMD & 0xFF)
    };
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command to sensor.\n");
        return -1;
    }
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed (expected 3 bytes, got %d).\n", bytes_read);
        return -1;
    }

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on flow data.\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw_flow / 1000.0f;
    return 0;
}

