#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define SENSOR_STATE_REG 0x00
#define SENSOR_STATE_LEN 7

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *buf, int len) {
    int bytes_read = i2cReadI2CBlockData(handle, SENSOR_STATE_REG, (char *)buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading sensor data: expected %d bytes, got %d (pigpio error %d)\n",
                len, bytes_read, bytes_read);
        return -1;
    }
    return 0;
}

static int calculate_iaq_index(uint16_t tvoc, uint16_t eco2) {
    float iaq = 100.0f - ((float)tvoc / 10.0f) - ((float)(eco2 - 400) / 50.0f);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return (int)(iaq + 0.5f);
}

static int log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%u,%u\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t sensor_data[SENSOR_STATE_LEN];
    int consecutive_errors = 0;

    while (running) {
        if (read_sensor_data(i2c_handle, sensor_data, SENSOR_STATE_LEN) == 0) {
            consecutive_errors = 0;
            uint16_t tvoc = ((uint16_t)sensor_data[1] << 8) | sensor_data[0];
            uint16_t eco2 = ((uint16_t)sensor_data[5] << 8) | sensor_data[4];
            int iaq = calculate_iaq_index(tvoc, eco2);
            if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors; aborting\n");
                break;
            }
        }
        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
    }

    cleanup();
    return EXIT_SUCCESS;
}

