#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define SAMPLE_RATE 48000
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE 4096

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(int *fd) {
    *fd = open(I2S_DEVICE, O_RDONLY);
    if (*fd < 0) {
        fprintf(stderr, "Error opening I2S device %s: %s\n", I2S_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S32_LE;
    if (ioctl(*fd, SNDCTL_DSP_SETFMT, &format) == -1) {
        fprintf(stderr, "Error setting I2S format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(*fd, SNDCTL_DSP_CHANNELS, &channels) == -1) {
        fprintf(stderr, "Error setting I2S channels: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(*fd, SNDCTL_DSP_SPEED, &rate) == -1) {
        fprintf(stderr, "Error setting I2S sample rate: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "inmp441_select", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

static int select_left_channel(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int select_right_channel(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_audio_data(int fd, int16_t *buffer, size_t num_samples) {
    size_t bytes_to_read = num_samples * sizeof(int32_t);
    size_t bytes_read = 0;
    int32_t *raw_buffer = (int32_t *)buffer;

    while (bytes_read < bytes_to_read) {
        ssize_t bytes = read(fd, (uint8_t *)raw_buffer + bytes_read, bytes_to_read - bytes_read);
        if (bytes < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
            return -1;
        } else if (bytes == 0) {
            fprintf(stderr, "End of stream reached.\n");
            return -1;
        }
        bytes_read += bytes;
    }

    // Extract 24-bit data from 32-bit frame and right-shift to get 16-bit PCM
    for (size_t i = 0; i < num_samples; i++) {
        int32_t sample = raw_buffer[i];
        // Right-shift by 8 to get 24-bit value, then right-shift by 8 to get 16-bit PCM
        buffer[i] = (int16_t)(sample >> 8);
    }

    return 0;
}

static int write_audio_data(const char *filename, const int16_t *buffer, size_t num_samples) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t bytes_written = fwrite(buffer, sizeof(int16_t), num_samples, fp);
    if (bytes_written != num_samples) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int i2s_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *gpio_line = NULL;
    int16_t *audio_buffer = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    if (init_i2s(&i2s_fd) != 0) {
        goto cleanup;
    }

    if (init_gpio(&gpio_chip, &gpio_line) != 0) {
        goto cleanup;
    }

    if (select_left_channel(gpio_line) != 0) {
        goto cleanup;
    }

    audio_buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Error allocating memory for audio buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Audio capture started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_audio_data(i2s_fd, audio_buffer, BUFFER_SIZE) != 0) {
            break;
        }

        if (write_audio_data("audio_capture.pcm", audio_buffer, BUFFER_SIZE) != 0) {
            break;
        }
    }

    printf("\nAudio capture stopped.\n");
    ret = 0;

cleanup:
    if (audio_buffer) free(audio_buffer);
    if (gpio_line) gpiod_line_release(gpio_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (i2s_fd >= 0) close(i2s_fd);

    return ret;
}

