#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 50
#define MAX_FLAME_DURATION_MS 60000
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);
    fprintf(log_file, "%s: %s\n", buf, event);
    fflush(log_file);
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

static void control_fan(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty_cycle);
    }
}

static int calculate_fan_speed(int flame_duration_ms) {
    if (flame_duration_ms <= 0) return 0;
    if (flame_duration_ms > MAX_FLAME_DURATION_MS) flame_duration_ms = MAX_FLAME_DURATION_MS;
    double normalized = (double)flame_duration_ms / MAX_FLAME_DURATION_MS;
    double speed = 80.0 * pow(normalized, 2.0);
    return (int)speed;
}

static void cleanup(void) {
    control_fan(0);
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting flame sensor GPIO %d as input\n", FLAME_SENSOR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting fan GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: Could not set PWM frequency to %d Hz\n", PWM_FREQUENCY);
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: Could not set PWM range to %d\n", PWM_RANGE);
    }

    control_fan(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    int flame_active = 0;
    int flame_start_tick = 0;
    int no_flame_count = 0;

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (sensor_value == 0) {
            no_flame_count++;
            if (no_flame_count >= 10) {
                if (flame_active) {
                    int flame_duration = gpioTick() - flame_start_tick;
                    int fan_speed = calculate_fan_speed(flame_duration);
                    control_fan(fan_speed);
                    char log_message[256];
                    snprintf(log_message, sizeof(log_message), "Flame ended, duration: %d ms, fan speed: %d%%", flame_duration, fan_speed);
                    log_event(log_message);
                    flame_active = 0;
                }
                no_flame_count = 0;
            }
        } else {
            no_flame_count = 0;
            if (!flame_active) {
                flame_start_tick = gpioTick();
                flame_active = 1;
                log_event("Flame detected");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

