#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.bin"

#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint32_t magic_number;
    uint8_t timestamp[8];
    struct {
        float start_frequency;
        float end_frequency;
        uint16_t num_chirps;
        uint16_t num_samples;
        uint32_t frame_period_us;
    } config;
} __attribute__((packed)) log_header_t;

typedef struct {
    uint32_t magic_number;
    uint8_t timestamp[8];
    uint32_t frame_number;
    uint32_t data_size;
} __attribute__((packed)) frame_header_t;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

