#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_timestamp(void) {
    time_t rawtime;
    struct tm timeinfo;
    char buffer[80];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown time] ");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure the line settings: input, bias pull-up */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        fprintf(stderr, "Error: Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set line direction: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set line bias: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure the line config with the settings */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, &(unsigned int){GPIO_LINE_OFFSET}, 1, line_settings);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to add line settings to config: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure the request config: consumer name */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    /* Request the line */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        fprintf(stderr, "Error: Failed to request GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        log_timestamp();
        printf("Flame Detected: %s\n", (value == 0) ? "YES" : "NO");
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

cleanup:
    /* Release resources in reverse order */
    if (line_req != NULL) {
        gpiod_line_request_release(line_req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (line_settings != NULL) {
        gpiod_line_settings_free(line_settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

