#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN  27
#define POLL_DELAY_US     50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (safe_set_mode(LEFT_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(CENTER_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-down resistors to settle sensor outputs */
    gpioDelay(10000);  /* 10 ms */

    printf("KY-033 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO %d, Center: GPIO %d, Right: GPIO %d\n",
           LEFT_SENSOR_PIN, CENTER_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Error: gpioRead failed (left=%d, center=%d, right=%d)\n",
                    left, center, right);
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

