#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Request each GPIO line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", channel_pins[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-touch");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input\n", channel_pins[i]);
            goto cleanup;
        }
    }

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        goto cleanup;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO line %u\n", channel_pins[i]);
                goto cleanup;
            }
            printf("Channel %d: %d\n", i + 1, value);
        }
        printf("---\n");
        fflush(stdout);
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    /* Release all lines and close the chip */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

