#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n",
                    channel_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n",
                    channel_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void log_data(const int states[NUM_CHANNELS])
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long ms = ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;

    printf("[+%ld ms] ", ms);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("CH%d=%d ", i + 1, states[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

