#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int channel_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_data(const int values[NUM_CHANNELS]) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf(",%d", values[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    int values[NUM_CHANNELS];
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, channel_pins, NUM_CHANNELS, settings);
    if (ret != 0) {
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    request = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Timestamp");
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf(",CH%d", i + 1);
    }
    printf("\n");
    fflush(stdout);

    while (program_running) {
        ret = gpiod_line_request_get_values(request, values);
        if (ret != 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        log_data(values);
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

