#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_tilt_state(int tilt_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    if (tilt_state == 0) {
        printf("[%s] Tilted\n", timestamp);
    } else if (tilt_state == 1) {
        printf("[%s] Not Tilted\n", timestamp);
    } else {
        printf("[%s] ERROR: Invalid tilt state: %d\n", timestamp, tilt_state);
    }
    fflush(stdout);
}

int main(void)
{
    int last_tilt_state = -1;

    /* Install SIGINT handler for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 4 as input with internal pull-up */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           TILT_SENSOR_GPIO);
    fflush(stdout);

    /* Main polling loop */
    while (g_running) {
        int tilt_state = gpioRead(TILT_SENSOR_GPIO);

        if (tilt_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", TILT_SENSOR_GPIO);
            break;
        }

        if (tilt_state != last_tilt_state) {
            log_tilt_state(tilt_state);
            last_tilt_state = tilt_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

