#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UVINDEX0 0x2C
#define SI1145_REG_UVINDEX1 0x2D
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE 0x20
#define SI1145_REG_CHLIST 0x01

// Si1145 commands
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06

// Expected PART ID for Si1145
#define SI1145_PART_ID 0x45

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init(int handle);
int si1145_read_uv_index(int handle, float *uv_index);
int si1145_read_als_visible(int handle, uint16_t *als_visible);
int log_data(FILE *fp, float uv_index, uint16_t als_visible);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize the Si1145 sensor
int si1145_init(int handle) {
    int part_id;

    // Reset the sensor
    if (i2cWriteByteData(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1145: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset to complete

    // Verify PART ID
    part_id = i2cReadByteData(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
