#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_CHIP "gpiochip4"
#define ALARM_PIN 17
#define FLOW_THRESHOLD 0.5f
#define FLOW_SCALE_FACTOR 0.036f
#define MEASUREMENT_DELAY_MS 100
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd1 = -1, i2c_fd2 = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alarm_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, 0x3608) < 0)
        return -1;
    usleep(MEASUREMENT_DELAY_MS * 1000);
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on flow measurement\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw_flow * FLOW_SCALE_FACTOR;
    return 0;
}

static void log_flow_rate(float avg_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Average Flow Rate: %.2f ml/min\n", timestamp, avg_flow);
    fflush(log_file);
}

static void control_alarm(float avg_flow) {
    int val = (avg_flow < FLOW_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(alarm_line, val) < 0)
        fprintf(stderr, "Failed to set alarm GPIO: %s\n", strerror(errno));
}

static void cleanup(void) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd1 >= 0) close(i2c_fd1);
    if (i2c_fd2 >= 0) close(i2c_fd2);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_sensor(i2c_fd1) < 0 || init_sensor(i2c_fd2) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(i2c_fd1, &flow1);
        int ok2 = read_flow_rate(i2c_fd2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            float avg_flow = (flow1 + flow2) / 2.0f;
            log_flow_rate(avg_flow);
            control_alarm(avg_flow);
        } else {
            fprintf(stderr, "Error reading flow rates, skipping cycle\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

