#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_to_buffer(time_t timestamp, int reading) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].reading = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Obstacle Detection Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Reading: %d\n", timestamp_str, circular_buffer[index].reading);
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (program_running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: Failed to read GPIO %d\n", SENSOR_PIN);
            break;
        }

        if (reading == 0) {
            time_t current_time = time(NULL);
            if (current_time == (time_t)-1) {
                fprintf(stderr, "Error: Failed to get current time\n");
                break;
            }
            add_to_buffer(current_time, reading);
            printf("Obstacle detected at %ld\n", (long)current_time);
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

