#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define CSV_FILE       "fan_health.csv"
#define SAMPLE_PERIOD  500000   /* microseconds */
#define ACTIVE_TIMEOUT 1000000  /* microseconds */

/* D7S register addresses */
#define REG_MODE_CONTROL 0x1D
#define REG_OP_STATUS    0x1B
#define REG_ACCEL_X_LSB  0x2A
#define REG_ACCEL_X_MSB  0x2B
#define REG_ACCEL_Y_LSB  0x2C
#define REG_ACCEL_Y_MSB  0x2D
#define REG_ACCEL_Z_LSB  0x2E
#define REG_ACCEL_Z_MSB  0x2F

/* Scaling factor: 0.0009765625 g/LSB (from datasheet) */
#define ACCEL_SCALE 0.0009765625f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to an 8-bit register */
static int d7s_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read one byte from an 8-bit register */
static int d7s_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "write (reg select 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "read reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian signed acceleration value */
static int d7s_read_accel(int fd, uint8_t lsb_reg, int16_t *out)
{
    uint8_t lsb, msb;
    if (d7s_read_reg8(fd, lsb_reg, &lsb) < 0)
        return -1;
    if (d7s_read_reg8(fd, lsb_reg + 1, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* Initialize the D7S: switch to active mode */
static int d7s_init(int fd)
{
    if (d7s_write_reg8(fd, REG_MODE_CONTROL, 0x10) < 0) {
        fprintf(stderr, "Failed to set D7S to active mode\n");
        return -1;
    }

    /* Wait for the sensor to become active (bit 0 of OP_STATUS) */
    uint8_t status = 0;
    for (int i = 0; i < ACTIVE_TIMEOUT / 10000; i++) {
        if (d7s_read_reg8(fd, REG_OP_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(10000);
    }

    fprintf(stderr, "D7S did not become active within %d ms (status=0x%02X)\n",
            ACTIVE_TIMEOUT / 1000, status);
    return -1;
}

/* Append a CSV row with an ISO-8601 timestamp */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the D7S slave address */
    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (d7s_init(fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open the CSV file in append mode; write a header if it is new/empty */
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "timestamp,x_g,y_g,z_g\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
        fflush(fp);
    }

    printf("D7S vibration monitor started. Logging to %s. Press Ctrl+C to stop.\n",
           CSV_FILE);

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (d7s_read_accel(fd, REG_ACCEL_X_LSB, &raw_x) < 0 ||
            d7s_read_accel(fd, REG_ACCEL_Y_LSB, &raw_y) < 0 ||
            d7s_read_accel(fd, REG_ACCEL_Z_LSB, &raw_z) < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        float x = (float)raw_x * ACCEL_SCALE;
        float y = (float)raw_y * ACCEL_SCALE;
        float z = (float)raw_z * ACCEL_SCALE;

        if (log_data(fp, x, y, z) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        usleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

