        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "timestamp,x_g,y_g,z_g\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
        fflush(fp);
    }

    printf("D7S vibration monitor started. Logging to %s. Press Ctrl+C to stop.\n",
           CSV_FILE);

    /* Main sampling loop */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (d7s_read_accel(fd, REG_ACCEL_X_LSB, &raw_x) < 0 ||
            d7s_read_accel(fd, REG_ACCEL_Y_LSB, &raw_y) < 0 ||
            d7s_read_accel(fd, REG_ACCEL_Z_LSB, &raw_z) < 0) {
            fprintf(stderr, "Sensor read error; retrying next cycle\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        float x = (float)raw_x * ACCEL_SCALE;
        float y = (float)raw_y * ACCEL_SCALE;
        float z = (float)raw_z * ACCEL_SCALE;

        if (log_data(fp, x, y, z) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        usleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    fclose(fp);
    close(fd);
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

