    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        safe_set_mode(LED_PIN, PI_OUTPUT)    != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (safe_write(LED_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int s1 = safe_read(SENSOR_1_PIN);
        int s2 = safe_read(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error: turn LED off and exit */
            safe_write(LED_PIN, 0);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        /* Active-LOW: 0 = obstacle detected */
        int obstacle = (s1 == 0 || s2 == 0) ? 1 : 0;

        if (safe_write(LED_PIN, obstacle ? 1 : 0) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    safe_write(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

