#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170 register addresses */
#define TMAG5170_REG_DEVICE_ID  0x00
#define TMAG5170_REG_X_MSB      0x01
#define TMAG5170_REG_X_LSB      0x02
#define TMAG5170_REG_Y_MSB      0x03
#define TMAG5170_REG_Y_LSB      0x04
#define TMAG5170_REG_Z_MSB      0x05
#define TMAG5170_REG_Z_LSB      0x06
#define TMAG5170_REG_CONFIG     0x07

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID      0x8D

/* Configuration register bits */
#define TMAG5170_CONFIG_MODE_CONTINUOUS 0x00
#define TMAG5170_CONFIG_CH_X_EN         0x01
#define TMAG5170_CONFIG_CH_Y_EN         0x02
#define TMAG5170_CONFIG_CH_Z_EN         0x04
#define TMAG5170_CONFIG_RANGE_50MT      0x00

/* LSB scale factor for 50 mT range: 1 LSB = 0.000122 mT */
#define TMAG5170_LSB_SCALE_50MT 0.000122f

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a TMAG5170 register */
static int tmag5170_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n",
                value, reg, rc);
    }
    return rc;
}

/* Read a single byte from a TMAG5170 register */
static int tmag5170_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Initialize the TMAG5170 sensor */
static int tmag5170_init(int handle) {
    uint8_t device_id = 0;

    /* Verify device ID */
    if (tmag5170_read_reg(handle, TMAG5170_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Failed to read device ID.\n");
        return -1;
    }
    if (device_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X).\n",
                device_id, TMAG5170_DEVICE_ID);
        return -1;
    }
    printf("TMAG5170 detected (Device ID: 0x%02X).\n", device_id);

    /* Configure: continuous mode, all three axes enabled, 50 mT range */
    uint8_t config = TMAG5170_CONFIG_MODE_CONTINUOUS |
                     TMAG5170_CONFIG_CH_X_EN |
                     TMAG5170_CONFIG_CH_Y_EN |
                     TMAG5170_CONFIG_CH_Z_EN |
                     TMAG5170_CONFIG_RANGE_50MT;

    if (tmag5170_write_reg(handle, TMAG5170_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to configure TMAG5170.\n");
        return -1;
    }

    /* Allow time for the first conversion to complete */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* Read magnetic field data from the TMAG5170 */
static int tmag5170_read_magnetic_field(int handle, float *x, float *y, float *z) {
    uint8_t x_msb = 0, x_lsb = 0;
    uint8_t y_msb = 0, y_lsb = 0;
    uint8_t z_msb = 0, z_lsb = 0;

    /* Read X axis */
    if (tmag5170_read_reg(handle, TMAG5170_REG_X_MSB, &x_msb) != 0) return -1;
    if (tmag5170_read_reg(handle, TMAG5170_REG_X_LSB, &x_lsb) != 0) return -1;

    /* Read Y axis */
    if (tmag5170_read_reg(handle, TMAG5170_REG_Y_MSB, &y_msb) != 0) return -1;
    if (tmag5170_read_reg(handle, TMAG5170_REG_Y_LSB, &y_lsb) != 0) return -1;

    /* Read Z axis */
    if (tmag5170_read_reg(handle, TMAG5170_REG_Z_MSB, &z_msb) != 0) return -1;
    if (tmag5170_read_reg(handle, TMAG5170_REG_Z_LSB, &z_lsb) != 0) return -1;

    /* Combine MSB and LSB into 16-bit two's-complement values */
    int16_t raw_x = (int16_t)((x_msb << 8) | x_lsb);
    int16_t raw_y = (int16_t)((y_msb << 8) | y_lsb);
    int16_t raw_z = (int16_t)((z_msb << 8) | z_lsb);

    /* Convert to mT using the 50 mT range scale factor */
    *x = (float)raw_x * TMAG5170_LSB_SCALE_50MT;
    *y = (float)raw_y * TMAG5170_LSB_SCALE_50MT;
    *z = (float)raw_z * TMAG5170_LSB_SCALE_50MT;

    return 0;
}

/* Log data to a CSV file */
static int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file.\n");
        return -1;
    }

    return 0;
}

int main(void) {
