#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdatomic.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define SAMPLE_INTERVAL_S 1.0
#define LOG_FILE "rpm_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Atomic pulse counter — updated by the pigpio alert callback */
static atomic_int pulse_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of the sensor pin      */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    atomic_fetch_add(&pulse_count, 1);
}

/* ------------------------------------------------------------------ */
/* Log RPM to file and stdout                                          */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r()");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s %.2f\n", timestamp, rpm) < 0) {
            perror("fprintf(log_file)");
        }
        if (fflush(log_file) != 0) {
            perror("fflush(log_file)");
        }
    }

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input with pull-up ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback for rising-edge detection ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(%d) failed\n", SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (running) {
        /* Reset pulse counter for this window */
        atomic_store(&pulse_count, 0);

        /* Sleep for the sample interval (interruptible by signals) */
        time_sleep(SAMPLE_INTERVAL_S);

        /* Snapshot the count */
        int pulses = atomic_load(&pulse_count);

        /* RPM = pulses per second * 60 (one pulse per revolution) */
        double rpm = (double)pulses / SAMPLE_INTERVAL_S * 60.0;

        log_rpm(rpm);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    /* Disable alert callback and timer */
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);

    /* Close log file */
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose(log_file)");
        }
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();

    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

