#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"

static volatile int sensor_a_state = 0;
static volatile int sensor_b_state = 0;
static volatile int last_a_state = 0;
static volatile int last_b_state = 0;
static volatile int rotation_direction = 0;
static volatile int rotation_detected = 0;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t rotation_cond = PTHREAD_COND_INITIALIZER;
static volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
    pthread_cond_signal(&rotation_cond);
}

void sensor_a_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        sensor_a_state = 1;
    } else if (level == 0) {
        sensor_a_state = 0;
    }
}

void sensor_b_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        sensor_b_state = 1;
    } else if (level == 0) {
        sensor_b_state = 0;
    }
}

void log_rotation(int direction) {
    pthread_mutex_lock(&log_mutex);
    if (log_file == NULL) {
        pthread_mutex_unlock(&log_mutex);
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: Rotation %s\n", timestamp, ts.tv_nsec / 1000000, direction == 1 ? "CW" : "CCW");
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

void *rotation_detection_thread(void *arg) {
    (void)arg;
    while (program_running) {
        pthread_mutex_lock(&log_mutex);
        int current_a = sensor_a_state;
        int current_b = sensor_b_state;
        pthread_mutex_unlock(&log_mutex);

        if (current_a != last_a_state || current_b != last_b_state) {
            if (current_a != last_a_state) {
                if (current_a == current_b) {
                    rotation_direction = 1;
                } else {
                    rotation_direction = -1;
                }
                log_rotation(rotation_direction);
                last_a_state = current_a;
            }
            if (current_b != last_b_state) {
                if (current_b == current_a) {
                    rotation_direction = 1;
                } else {
                    rotation_direction = -1;
                }
                log_rotation(rotation_direction);
                last_b_state = current_b;
            }
        }
        gpioDelay(1000);
    }
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_A_PIN, sensor_a_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR_B_PIN, sensor_b_callback) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    pthread_t rotation_thread;
    if (pthread_create(&rotation_thread, NULL, rotation_detection_thread, NULL) != 0) {
        perror("Failed to create rotation detection thread");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        pthread_cond_wait(&rotation_cond, &log_mutex);
    }

    pthread_join(rotation_thread, NULL);
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

