#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22

#define BUFFER_SIZE 100
#define DEBOUNCE_US  50000  /* 50 ms */

typedef struct {
    int  sensor_pin;
    time_t timestamp;
    int  state;
} sensor_event_t;

static sensor_event_t event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_overflow = 0;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_2_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-downs so the inputs read LOW when the sensor is open */
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d\n", SENSOR_1_PIN);
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d\n", SENSOR_2_PIN);
    }

    /* Ensure LEDs are off at startup */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d to LOW\n", LED_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO %d to LOW\n", LED_2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_event(int sensor_pin, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp  = time(NULL);
    event_buffer[buffer_index].state      = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_overflow++;
    }
}

static void print_buffer_contents(void) {
    printf("\n--- Event Log ---\n");
    printf("Buffer size: %d entries, Overflow: %d\n", BUFFER_SIZE, buffer_overflow);

    int start = buffer_index;  /* oldest entry */
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        if (event_buffer[idx].timestamp == 0) {
            break;  /* entry was never written */
        }
        printf("[%d] Sensor: %d, Timestamp: %ld, State: %d\n",
               i,
               event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp,
               event_buffer[idx].state);
    }
    printf("--- End Log ---\n");
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_state1 = gpioRead(SENSOR_1_PIN);
    int last_state2 = gpioRead(SENSOR_2_PIN);

    if (last_state1 < 0) {
        fprintf(stderr, "Error: initial read failed on GPIO %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (last_state2 < 0) {
        fprintf(stderr, "Error: initial read failed on GPIO %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LEDs reflect initial sensor states */
    if (gpioWrite(LED_1_PIN, last_state1) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, last_state2) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event(SENSOR_1_PIN, last_state1);
    log_event(SENSOR_2_PIN, last_state2);

    while (program_running) {
        int current_state1 = gpioRead(SENSOR_1_PIN);
        int current_state2 = gpioRead(SENSOR_2_PIN);

        if (current_state1 < 0) {
            fprintf(stderr, "Error: read failed on GPIO %d\n", SENSOR_1_PIN);
            break;
        }
        if (current_state2 < 0) {
            fprintf(stderr, "Error: read failed on GPIO %d\n", SENSOR_2_PIN);
            break;
        }

        if (current_state1 != last_state1) {
            if (gpioWrite(LED_1_PIN, current_state1) != 0) {
                fprintf(stderr, "Error: write failed on GPIO %d\n", LED_1_PIN);
                break;
            }
            log_event(SENSOR_1_PIN, current_state1);
            last_state1 = current_state1;
        }

        if (current_state2 != last_state2) {
            if (gpioWrite(LED_2_PIN, current_state2) != 0) {
                fprintf(stderr, "Error: write failed on GPIO %d\n", LED_2_PIN);
                break;
            }
            log_event(SENSOR_2_PIN, current_state2);
            last_state2 = current_state2;
        }

        gpioDelay(DEBOUNCE_US);
    }

    /* Graceful shutdown */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();

    print_buffer_contents();
    printf("Program terminated gracefully.\n");

    return EXIT_SUCCESS;
}

