#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_US 5000  // 5 ms debounce
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
    }
}

int read_sensor(int gpio) {
    return gpioRead(gpio);
}

void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

void calculate_rpm(int sensor1_state, int sensor2_state, int *last_sensor1_state, int *last_sensor2_state, double *rpm) {
    static double last_time = 0.0;
    static int pulse_count = 0;

    double current_time = time_time();

    if (sensor1_state != *last_sensor1_state || sensor2_state != *last_sensor2_state) {
        if (current_time - last_time > 0.000001) {
            *rpm = (double)pulse_count / (current_time - last_time) * 60.0;
            pulse_count = 0;
            last_time = current_time;
        }
    }

    if (sensor1_state == 1 && *last_sensor1_state == 0) {
        pulse_count++;
    }
    if (sensor2_state == 1 && *last_sensor2_state == 0) {
        pulse_count++;
    }

    *last_sensor1_state = sensor1_state;
    *last_sensor2_state = sensor2_state;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    signal(SIGINT, signal_handler);

    int last_sensor1_state = 0;
    int last_sensor2_state = 0;
    double rpm = 0.0;

    while (program_running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        gpioDelay(DEBOUNCE_US);

        calculate_rpm(sensor1_state, sensor2_state, &last_sensor1_state, &last_sensor2_state, &rpm);

        printf("RPM: %.2f\n", rpm);
        log_data(sensor1_state, sensor2_state);
    }

    gpioTerminate();
    return 0;
}

