#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define LOG_FILE "biometric_log.txt"
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define CONFIG_REG 0x30
#define PART_ID_REG 0x00
#define EXPECTED_PART_ID 0x82

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *heart_rate, int *spo2);
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor presence by reading PART_ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    // Configure sensor for continuous measurement
    // Write 0x01 to CONFIG register to start continuous measurement
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read heart rate and SpO2 data from the sensor
int read_sensor_data(int *heart_rate, int *spo2) {
    int hr_val = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (hr_val < 0) {
        fprintf(stderr, "Error reading heart rate: %d\n", hr_val);
        return -1;
    }
    *heart_rate = hr_val;

    int spo2_val = i2cReadByteData(i2c_handle, SPO2_REG);
    if (spo2_val < 0) {
        fprintf(stderr, "Error reading SpO2: %d\n", spo2_val);
        return -1;
    }
    *spo2 = spo2_val;

    return 0;
}

// Log data to a file with timestamp
int log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
    fclose(log_file);
    log_file = NULL;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int heart_rate, spo2;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&heart_rate, &spo2) == 0) {
            if (log_data(heart_rate, spo2) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

