#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1_REG 0x1F
#define CTRL2_REG 0x20
#define OUT_X_L_REG 0x28
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500.0f
#define POLL_DELAY_US 100000
#define LED_ON_DURATION_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ctrl1 = i2cReadByteData(i2c_handle, CTRL1_REG);
        if (ctrl1 < 0) {
            fprintf(stderr, "Error reading CTRL1 (attempt %d): %d\n", retries + 1, ctrl1);
            retries++;
            gpioDelay(10000);
            continue;
        }
        if ((ctrl1 & 0x01) == 0) {
            fprintf(stderr, "Sensor not present or power-down bit not set (CTRL1=0x%02X)\n", ctrl1);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, CTRL1_REG, ctrl1 & ~0x01) < 0) {
            fprintf(stderr, "Error clearing power-down bit (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10000);
            continue;
        }
        return 0;
    }
    fprintf(stderr, "Failed to initialize sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buf[6];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int bytes = i2cReadI2CBlockData(i2c_handle, OUT_X_L_REG, buf, 6);
        if (bytes == 6) {
            int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
            int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
            int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
            *x = (float)raw_x;
            *y = (float)raw_y;
            *z = (float)raw_z;
            return 0;
        }
        fprintf(stderr, "I2C block read failed (attempt %d): %d\n", retries + 1, bytes);
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static float calculate_vibration(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void trigger_led(void) {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_DURATION_US);
    gpioWrite(LED_GPIO, 0);
}

static void log_event(float vibration) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s - Vibration: %.2f\n", timestamp, vibration);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            float vibration = calculate_vibration(x, y, z);
            if (vibration > VIBRATION_THRESHOLD) {
                printf("Vibration threshold exceeded: %.2f\n", vibration);
                trigger_led();
                log_event(vibration);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

