#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define POLL_INTERVAL_MS 50

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};
static const unsigned int led_pin = 18;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret;
    int i;

    for (i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = NULL;
    }

    /* Open the default gpiochip (gpiochip4 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    /* Get sensor lines */
    for (i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %m\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, led_pin);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %u: %m\n", led_pin);
        goto cleanup;
    }

    /* Request sensor lines as inputs */
    for (i = 0; i < NUM_SENSORS; i++) {
        ret = gpiod_line_request_input(sensor_lines[i], "ky032-sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %m\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    /* Request LED line as output, initial value LOW (off) */
    ret = gpiod_line_request_output(led_line, "ky032-led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %u as output: %m\n", led_pin);
        goto cleanup;
    }

    /* Set up signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
