/*
 * flame_monitor.c — Raspberry Pi 3 Model B+ flame sensor monitor
 *
 * Monitors 5 Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * Digital output (LOW = flame detected, HIGH = no flame).
 * Logs rising-edge transitions to /var/log/flame_events.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define TIMESTAMP_LEN    32

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line *g_lines[NUM_SENSORS];
static int                 g_lines_requested = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_message(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
    fprintf(stderr, "[%s] %s\n",
            priority == LOG_ERR ? "ERROR" : "INFO", msg);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */

static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_utc;

    if (time(&rawtime) == (time_t)-1)
        return -1;

    if (gmtime_r(&rawtime, &tm_utc) == NULL)
        return -1;

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Event logging                                                       */
/* ------------------------------------------------------------------ */

static int log_event(int sensor_id, unsigned int pin)
{
    char ts[TIMESTAMP_LEN];
    FILE *fp;
    int fd;

    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        log_message(LOG_ERR, "Failed to generate timestamp");
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_message(LOG_ERR, "Failed to open log file");
        return -1;
    }

    fd = fileno(fp);
    if (fd < 0) {
        log_message(LOG_ERR, "fileno() failed");
        fclose(fp);
        return -1;
    }

    if (flock(fd, LOCK_EX) != 0) {
        log_message(LOG_ERR, "flock(LOCK_EX) failed");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        log_message(LOG_ERR, "fprintf to log file failed");
        flock(fd, LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        log_message(LOG_ERR, "fflush failed");
        flock(fd, LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fd, LOCK_UN) != 0) {
        log_message(LOG_ERR, "flock(LOCK_UN) failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        log_message(LOG_ERR, "fclose failed");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read with debounce                                           */
/* ------------------------------------------------------------------ */

/*
 * Returns:
 *   1  — flame detected (confirmed by debounce)
 *   0  — no flame
 *  -1  — read error
 */
static int read_sensor_debounced(struct gpiod_line *line, int sensor_id)
{
    int v1, v2;

    v1 = gpiod_line_get_value(line);
    if (v1 < 0) {
        syslog(LOG_ERR, "Sensor %d: read failed (first attempt): %s",
               sensor_id, strerror(errno));
        return -1;
    }

    if (v1 == 0) {
        /* No flame — no need to debounce */
        return 0;
    }

    /* Debounce: wait DEBOUNCE_MS, then re-read */
    usleep(DEBOUNCE_MS * 1000);

    v2 = gpiod_line_get_value(line);
    if (v2 < 0) {
        syslog(LOG_ERR, "Sensor %d: read failed (second attempt): %s",
               sensor_id, strerror(errno));
        return -1;
    }

    return (v2 == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_lines_requested) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (g_lines[i]) {
                gpiod_line_release(g_lines[i]);
                g_lines[i] = NULL;
            }
        }
        g_lines_requested = 0;
    }

    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }

    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    /* ---- Open syslog ---- */
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_message(LOG_ERR, "sigaction(SIGINT) failed");
        goto out;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "sigaction(SIGTERM) failed");
        goto out;
    }

    /* ---- Open GPIO chip ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        log_message(LOG_ERR, "Failed to open gpiochip0");
        goto out;
    }

    /* ---- Acquire and request each line ---- */
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_lines[i] = gpiod_chip_get_line(g_chip, sensor_pins[i]);
        if (!g_lines[i]) {
            syslog(LOG_ERR, "Failed to get line %u: %s",
                   sensor_pins[i], strerror(errno));
            log_message(LOG_ERR, "Failed to get GPIO line");
            goto out;
        }

        if (gpiod_line_request_input(g_lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request line %u as input: %s",
                   sensor_pins[i], strerror(errno));
            log_message(LOG_ERR, "Failed to request GPIO line as input");
            goto out;
        }

        g_lines_requested = 1;
        prev_state[i] = 1;   /* assume no flame at startup */
    }

    log_message(LOG_INFO, "Flame sensor monitoring started");

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = read_sensor_debounced(g_lines[i], i + 1);

            if (val < 0) {
                /* Read error — log and continue */
                continue;
            }

            if (val == 1 && prev_state[i] == 1) {
                /* Rising edge: no flame -> flame */
                if (log_event(i + 1, sensor_pins[i]) != 0) {
                    log_message(LOG_ERR, "Failed to log event");
                }
            }

            prev_state[i] = val;
        }

        sleep(POLL_INTERVAL_S);
    }

    log_message(LOG_INFO, "Flame sensor monitoring stopped");
    ret = EXIT_SUCCESS;

out:
    cleanup();
    return ret;
}

