#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define VEML7700_ADDR 0x10
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int veml7700_init(int handle) {
    /* ALS gain 1/8 (0x00), ALS integration time 100 ms (0x00) */
    uint16_t config = (0x00 << 12) | (0x00 << 10) | (0x00 << 8) | (0x00 << 6) | (0x00 << 4) | (0x00 << 2) | 0x00;
    char buf[3];
    buf[0] = VEML7700_ALS_CONF;
    buf[1] = (char)(config & 0xFF);
    buf[2] = (char)((config >> 8) & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    char reg = VEML7700_ALS;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error selecting ALS register: %s\n", strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (uint16_t)((uint8_t)data[1] << 8) | (uint8_t)data[0];
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int gpio, int brightness) {
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int calculate_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (veml7700_init(i2c_handle) != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", LED_GPIO, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: could not set PWM frequency to %d Hz\n", PWM_FREQ);
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set PWM range to %d\n", PWM_RANGE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int error_code = veml7700_read_lux(i2c_handle, &lux);
        int brightness = calculate_brightness(lux);

        if (error_code == 0) {
            if (set_led_brightness(LED_GPIO, brightness) != 0) {
                error_code = -2;
            }
        } else {
            set_led_brightness(LED_GPIO, 0);
        }

        log_data(log_file, lux, brightness, error_code);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_led_brightness(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

