    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure channel pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security keypad simulation started. Press Ctrl+C to exit.\n");

    int last_state[NUM_CHANNELS] = {0};
    uint32_t last_change_tick[NUM_CHANNELS] = {0};

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int current_state = gpioRead(channel_pins[i]);
            if (current_state < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", channel_pins[i]);
                continue;
            }

            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_change_tick[i];

            if (current_state != last_state[i] && elapsed >= DEBOUNCE_US) {
                if (current_state == 1) {
                    if (log_touch_event(i + 1) != 0) {
                        fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                    }
                }
                last_state[i] = current_state;
                last_change_tick[i] = now;
            }

            if (current_state == 1) {
                any_touched = 1;
            }
        }

        if (gpioWrite(LED_PIN, any_touched ? 1 : 0) != 0) {
            fprintf(stderr, "Error writing to LED pin\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Security keypad simulation stopped.\n");

    return EXIT_SUCCESS;
}

