#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define OPT3001_ADDR        0x44
#define OPT3001_RESULT_REG  0x00
#define OPT3001_CONFIG_REG  0x01
#define OPT3001_CONFIG_VAL  0xC810  /* RN=100, CT=100ms, M=1, FC=0, L=0, POL=0, ME=0, CR=10 */
#define LOG_FILE            "light_data.txt"
#define I2C_BUS             1
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_WAIT_US        100000   /* 100 ms for first conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* OPT3001 expects big-endian (MSB first) for configuration and result words */
static uint16_t opt3001_swap_word(uint16_t word)
{
    return ((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8);
}

static int opt3001_write_config(int handle, uint16_t config)
{
    uint16_t swapped = opt3001_swap_word(config);
    int rc = i2cWriteWordData(handle, OPT3001_CONFIG_REG, swapped);
    if (rc < 0) {
        fprintf(stderr, "Error writing OPT3001 config register (pigpio rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, float *lux_out)
{
    int raw = i2cReadWordData(handle, OPT3001_RESULT_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading OPT3001 result register (pigpio rc=%d): %s\n",
                raw, strerror(errno));
        return -1;
    }

    uint16_t swapped = opt3001_swap_word((uint16_t)raw);
    uint16_t exponent = (swapped >> 12) & 0x0F;
    uint16_t mantissa = swapped & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1 << exponent);
    return 0;
}

static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (pigpio rc=%d): %s\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_write_config(g_i2c_handle, OPT3001_CONFIG_VAL) != 0) {
        fprintf(stderr, "Failed to configure OPT3001 sensor\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    gpioDelay(CONV_WAIT_US);

    printf("OPT3001 greenhouse light monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;

        if (opt3001_read_result(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

