#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500
#define ALERT_DURATION_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error formatting time\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor GPIO %d: %s\n", FLAME_SENSOR_GPIO, pigpio_error(value));
        return -1;
    }
    return value;
}

static int trigger_alert(void) {
    if (gpioWrite(ALERT_GPIO, 1) != 0) {
        fprintf(stderr, "Error setting alert GPIO %d HIGH\n", ALERT_GPIO);
        return -1;
    }

    gpioDelay(ALERT_DURATION_MS * 1000);

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error setting alert GPIO %d LOW\n", ALERT_GPIO);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting flame sensor GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting alert GPIO %d as output\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing alert GPIO %d to LOW\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading flame sensor");
        } else if (sensor_value == 0) {
            printf("Flame detected!\n");
            log_event("Flame detected");
            if (trigger_alert() != 0) {
                log_event("Error triggering alert");
            }
        } else {
            log_event("No flame detected");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

