#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define FLOW_SCALE_FACTOR 90.0f
#define SAMPLE_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 2000
#define MAX_FLOW_RATE 100.0f
#define MIN_FLOW_RATE 0.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, SLF3S_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = {0x36, 0x08};
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", rc);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[3];
    int rc = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "Error reading flow data (got %d bytes)\n", rc);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE_FACTOR;
    return 0;
}

static void log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    signal(SIGINT, signal_handler);
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (start_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }
    printf("Cooling system monitoring started. Press Ctrl+C to exit.\n");
    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            if (flow_rate >= MIN_FLOW_RATE && flow_rate <= MAX_FLOW_RATE) {
                log_data(flow_rate, "OK");
            } else {
                log_data(flow_rate, "INVALID");
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow_rate);
            }
        } else {
            log_data(0.0f, "ERROR");
            fprintf(stderr, "Read error, attempting recovery...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "Recovery failed, exiting.\n");
                break;
            }
            if (start_measurement() != 0) {
                fprintf(stderr, "Measurement restart failed, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Cooling system monitoring stopped.\n");
    return EXIT_SUCCESS;
}

