/*
 * Flame detection safety system for Raspberry Pi 3 Model B+
 * Uses libgpiod (character-device API, not wiringPi or sysfs).
 *
 * Wiring:
 *   KY-026 digital out -> GPIO17 (physical pin 11)
 *   Active buzzer      -> GPIO18 (physical pin 12)
 *
 * KY-026 is active-low: LOW = flame detected, HIGH = no flame.
 * Buzzer is active-high: HIGH = sound on.
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define FLAME_SENSOR_PIN  17
#define BUZZER_PIN        18
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_MS 2000
#define SLICE_MS          100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, const char *event)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void activate_buzzer(struct gpiod_line *buzzer, int duration_ms)
{
    if (gpiod_line_set_value(buzzer, 1) < 0) {
        fprintf(stderr, "Failed to activate buzzer: %s\n", strerror(errno));
        return;
    }

    for (int elapsed = 0; elapsed < duration_ms && program_running;
         elapsed += SLICE_MS) {
        usleep(SLICE_MS * 1000);
    }

    if (gpiod_line_set_value(buzzer, 0) < 0) {
        fprintf(stderr, "Failed to deactivate buzzer: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup_log;
    }

    /* --- Get lines --- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (flame_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup_chip;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup_chip;
    }

    /* --- Request lines --- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup_lines;
    }

    /* --- Log startup --- */
    log_event(log_file, "System started");

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int last_flame_state = gpiod_line_get_value(flame_line);
    if (last_flame_state < 0) {
        fprintf(stderr, "Initial flame sensor read failed: %s\n",
                strerror(errno));
        goto cleanup_lines;
    }

    /* --- Main polling loop --- */
    while (program_running) {
        int current_flame_state = gpiod_line_get_value(flame_line);
        if (current_flame_state < 0) {
            fprintf(stderr, "Failed to read flame sensor: %s\n",
                    strerror(errno));
            break;
        }

        /* Detect HIGH -> LOW transition (flame detected) */
        if (last_flame_state == 1 && current_flame_state == 0) {
            log_event(log_file, "Flame detected!");
            activate_buzzer(buzzer_line, BUZZER_DURATION_MS);
        }

        last_flame_state = current_flame_state;

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_MS / SLICE_MS && program_running; i++) {
            usleep(SLICE_MS * 1000);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    log_event(log_file, "System stopped");
    ret = EXIT_SUCCESS;

    /* Ensure buzzer is off */
    if (buzzer_line != NULL) {
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            fprintf(stderr, "Failed to turn off buzzer during shutdown: %s\n",
                    strerror(errno));
        }
    }

cleanup_lines:
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line != NULL) {
        gpiod_line_release(buzzer_line);
    }

cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

cleanup_log:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
