#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_DELAY_US 200000  /* 200 ms */
#define POLL_INTERVAL_US 10000    /* 10 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
