/*
 * TMAG5110A1 Hall-effect latch magnetic sensor monitor for Raspberry Pi 4.
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4  (input, internal pull-up)
 *   Sensor 2 OUT -> GPIO17 (input, internal pull-up)
 *   Sensor 3 OUT -> GPIO27 (input, internal pull-up)
 *
 * The TMAG5110A1 OUT pin is open-drain: it pulls low when a south pole
 * is present and releases high otherwise.  A logic low therefore means
 * "magnet present" and a logic high means "magnet removed".
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals for signal-handler cleanup                                  */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamp into buf (size >= 25)                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00+0000");
    }
}

/* ------------------------------------------------------------------ */
/* Append a state change line to the log file                           */
/* ------------------------------------------------------------------ */
static void log_state_change(int sensor_id, int state)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(g_log_fp, "%s - Sensor %d: %s\n",
                ts, sensor_id, state ? "MAGNET_REMOVED" : "MAGNET_PRESENT") < 0) {
        perror("fprintf to log file failed");
    } else {
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin; returns 0 or 1 on success, -1 on error            */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d (pigpio error %d)\n", pin, v);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Configure a GPIO pin as input with internal pull-up                 */
/* ------------------------------------------------------------------ */
static int configure_sensor_pin(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pins[3] = {SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN};
    int prev_state[3] = {-1, -1, -1};
    int first_read[3] = {1, 1, 1};
    int rc = EXIT_FAILURE;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins ---- */
    for (int i = 0; i < 3; i++) {
        if (configure_sensor_pin(pins[i]) != 0) {
            goto cleanup_gpio;
        }
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        goto cleanup_gpio;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO%d, GPIO%d, GPIO%d.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int v = read_sensor(pins[i]);
            if (v < 0) {
                /* Sensor read error — skip this cycle */
                continue;
            }

            if (first_read[i]) {
                /* Record initial state without logging a transition */
                prev_state[i] = v;
                first_read[i] = 0;
            } else if (v != prev_state[i]) {
                log_state_change(i + 1, v);
                prev_state[i] = v;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup_gpio:
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return rc;
}

