#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SI1182_ADDR 0x4A
#define I2C_BUS 1

#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HW_REV 0x01
#define SI1182_REG_LED_CURRENT 0x3F
#define SI1182_REG_AVG_SAMPLES 0x04
#define SI1182_REG_ENABLE 0x01
#define SI1182_REG_HR_DATA 0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01

#define BPM_MIN 30.0f
#define BPM_MAX 220.0f
#define MOVING_AVG_SIZE 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

static MovingAverageFilter bpm_filter = {0};

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int verify_sensor(void) {
    int part_id = i2cReadByteData(i2c_handle, SI1182_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    int hw_rev = i2cReadByteData(i2c_handle, SI1182_REG_HW_REV);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    printf("Si1182 verified: PART_ID=0x%02X, HW_REV=0x%02X\n", part_id, hw_rev);
    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, SI1182_REG_LED_CURRENT, 0x3F) < 0) {
        fprintf(stderr, "Error writing LED_CURRENT register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1182_REG_AVG_SAMPLES, 0x04) < 0) {
        fprintf(stderr, "Error writing AVG_SAMPLES register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1182_REG_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error writing ENABLE register\n");
        return -1;
    }
    return 0;
}

static int read_heart_rate(float *bpm) {
    int raw = i2cReadWordData(i2c_handle, SI1182_REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading HR_DATA register: %d\n", raw);
        return -1;
    }
    *bpm = (float)raw * 0.5f;
    return 0;
}

static float apply_moving_average(float new_value) {
    bpm_filter.buffer[bpm_filter.index] = new_value;
    bpm_filter.index = (bpm_filter.index + 1) % MOVING_AVG_SIZE;
    if (bpm_filter.count < MOVING_AVG_SIZE) {
        bpm_filter.count++;
    }

    float sum = 0.0f;
    for (int i = 0; i < bpm_filter.count; i++) {
        sum += bpm_filter.buffer[i];
    }
    return sum / (float)bpm_filter.count;
}

static int log_data(float bpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Starting heart rate monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float bpm;
        if (read_heart_rate(&bpm) != 0) {
            fprintf(stderr, "Read error, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        float filtered = apply_moving_average(bpm);

        if (filtered >= BPM_MIN && filtered <= BPM_MAX) {
            if (log_data(filtered) != 0) {
                fprintf(stderr, "Logging error, continuing...\n");
            }
        } else {
            fprintf(stderr, "Invalid BPM: %.2f (filtered), skipping log\n", filtered);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

