#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE_PATH   "flame_log.txt"
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void log_flame_detection(FILE *log_file)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - FLAME DETECTED\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int ret;
    int prev_value = 1;  /* assume no flame at startup (HIGH) */

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_PATH, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    /* Request the line as input with internal pull-up */
    ret = gpiod_line_request_input_flags(line, "flame-sensor",
                                         GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_get_value(line);
