/*
 * touch_counter.c — 8-channel TTP226 capacitive touch sensor reader
 * and 8-bit binary counter display on Raspberry Pi Zero W using
 * libgpiod v2+ bulk/config API (no sysfs, no wiringPi, no libgpiod v1).
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    sudo ./touch_counter
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT1 -> GPIO5
 *   TTP226 OUT2 -> GPIO6
 *   TTP226 OUT3 -> GPIO7
 *   TTP226 OUT4 -> GPIO8
 *   TTP226 OUT5 -> GPIO9
 *   TTP226 OUT6 -> GPIO10
 *   TTP226 OUT7 -> GPIO11
 *   TTP226 OUT8 -> GPIO12
 *   Display bit0 -> GPIO17
 *   Display bit1 -> GPIO18
 *   Display bit2 -> GPIO19
 *   Display bit3 -> GPIO20
 *   Display bit4 -> GPIO21
 *   Display bit5 -> GPIO22
 *   Display bit6 -> GPIO23
 *   Display bit7 -> GPIO24
 *
 * TTP226 outputs are active-high (3.3 V touched, 0 V idle).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 10
#define STABILIZE_MS 200
#define LOG_FILE "touch_log.txt"

/* BCM GPIO numbers for the 8 sensor inputs */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
/* BCM GPIO numbers for the 8 display output bits */
static const unsigned int display_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* Write an 8-bit value to the 8 display output pins; bit b -> GPIO 17+b */
static int write_display(struct gpiod_line_request *req, unsigned char value)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int ret = gpiod_line_request_set_value(req, display_pins[i],
                                              (value >> i) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error writing display bit %d (GPIO %u): %s\n",
                    i, display_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

/* Log a touch event to the log file and stdout */
static void log_touch(int channel, unsigned char counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm);
        fprintf(fp, "%s, Channel: %d, Counter: %u\n", ts, channel, counter);
    } else {
        fprintf(fp, "(timestamp error), Channel: %d, Counter: %u\n",
                channel, counter);
    }
    fclose(fp);

    printf("Touch on channel %d | Counter: %u\n", channel, counter);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *sensor_cfg = NULL;
    struct gpiod_line_config *display_cfg = NULL;
    struct gpiod_line_settings *sensor_settings = NULL;
    struct gpiod_line_settings *display_settings = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *display_req = NULL;
    unsigned char counter = 0;
    int prev_state[NUM_CHANNELS] = {0};
    int ret = EXIT_FAILURE;

    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default gpiochip (gpiochip0 on Pi Zero W) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Sensor line configuration: input, rising-edge events --- */
    sensor_settings = gpiod_line_settings_new();
    if (!sensor_settings) {
        fprintf(stderr, "gpiod_line_settings_new (sensor): %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(sensor_settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_edge_detection(sensor_settings,
                                            GPIOD_LINE_EDGE_RISING_EDGE);

    sensor_cfg = gpiod_line_config_new();
    if (!sensor_cfg) {
        fprintf(stderr, "gpiod_line_config_new (sensor): %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_config_add_line_settings(sensor_cfg, sensor_pins,
                                            NUM_CHANNELS, sensor_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (sensor): %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Display line configuration: output, initial low --- */
    display_settings = gpiod_line_settings_new();
    if (!display_settings) {
        fprintf(stderr, "gpiod_line_settings_new (display): %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(display_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(display_settings, GPIOD_LINE_VALUE_INACTIVE);

    display_cfg = gpiod_line_config_new();
    if (!display_cfg) {
        fprintf(stderr, "gpiod_line_config_new (display): %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_config_add_line_settings(display_cfg, display_pins,
                                            NUM_CHANNELS, display_settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings (display): %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Request the sensor lines for rising-edge events --- */
    sensor_req = gpiod_chip_request_lines(chip, NULL, sensor_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines (sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request the display lines as outputs, initial low --- */
    display_req = gpiod_chip_request_lines(chip, NULL, display_cfg);
    if (!display_req) {
        fprintf(stderr, "gpiod_chip_request_lines (display): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Allow sensor lines to settle after request --- */
    usleep(STABILIZE_MS * 1000);

    printf("Touch sensor counter started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor channel %d (GPIO %u): %s\n",
                        i + 1, sensor_pins[i], strerror(errno));
                continue;
            }

            /* Detect rising edge: inactive -> active */
            if (val == 1 && prev_state[i] == 0) {
                counter = (counter + 1) & 0xFF;
                if (write_display(display_req, counter) < 0) {
                    /* Non-fatal: continue polling */
                }
                log_touch(i + 1, counter);
            }
            prev_state[i] = val;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Graceful shutdown: reset display to 0, release resources --- */
    if (display_req) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_line_request_set_value(display_req, display_pins[i], 0);
        }
        gpiod_line_request_release(display_req);
    }
    if (sensor_req) {
        gpiod_line_request_release(sensor_req);
    }
    if (display_cfg) {
        gpiod_line_config_free(display_cfg);
    }
    if (sensor_cfg) {
        gpiod_line_config_free(sensor_cfg);
    }
    if (display_settings) {
        gpiod_line_settings_free(display_settings);
    }
    if (sensor_settings) {
        gpiod_line_settings_free(sensor_settings);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting cleanly.\n");
    return ret;
}

