    }
    if (line18) {
        gpiod_line_release(line18);
        line18 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_LINE_17);
    if (!line17) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_17, strerror(errno));
        return -1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_LINE_18);
    if (!line18) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_18, strerror(errno));
        return -1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "tilt_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
    };

    if (gpiod_line_request(line17, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_17, strerror(errno));
        return -1;
    }

    if (gpiod_line_request(line18, &config, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_18, strerror(errno));
        return -1;
    }

    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_event(int sensor_id) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_id) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev_state17 = 1;
    int prev_state18 = 1;
    struct timespec last_change17 = {0, 0};
    struct timespec last_change18 = {0, 0};

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0 || val18 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (val17 == 0 && prev_state17 == 1) {
            long elapsed_ms = (now.tv_sec - last_change17.tv_sec) * 1000L +
                              (now.tv_nsec - last_change17.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                log_event(1);
                last_change17 = now;
            }
        }
        prev_state17 = val17;

        if (val18 == 0 && prev_state18 == 1) {
            long elapsed_ms = (now.tv_sec - last_change18.tv_sec) * 1000L +
                              (now.tv_nsec - last_change18.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                log_event(2);
                last_change18 = now;
            }
        }
        prev_state18 = val18;

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Tilt sensor monitoring stopped.\n");
    return 0;
}

