        int s1_val = gpiod_line_get_value(s1_line);
        int s2_val = gpiod_line_get_value(s2_line);

        if (s1_val < 0 || s2_val < 0) {
            fprintf(stderr, "Failed to read sensor values: %s\n", strerror(errno));
            break;
        }

        int led_state = (s1_val == 0 && s2_val == 0) ? 1 : 0;

        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
            break;
        }

        if (log_data(log_fp, s1_val, s2_val, led_state) < 0) {
            break;
