#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125  /* ~8 kHz */
#define LED_ON_DURATION_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_timestamp(void)
{
    struct timespec ts;
    struct tm tm_info;
    char buf[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld\n", buf, ts.tv_nsec / 1000000);
    fflush(stdout);
}

int main(void)
{
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure microphone GPIO as input */
    ret = gpioSetMode(MIC_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input (code %d)\n", MIC_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO as output and ensure it starts OFF */
    ret = gpioSetMode(LED_GPIO, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output (code %d)\n", LED_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioWrite(LED_GPIO, 0);
    if (ret != 0) {
        fprintf(stderr, "Failed to initialise LED GPIO%d OFF (code %d)\n", LED_GPIO, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound peak detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (program_running) {
        int mic_value = gpioRead(MIC_GPIO);
        if (mic_value < 0) {
            fprintf(stderr, "Error reading GPIO%d (code %d)\n", MIC_GPIO, mic_value);
            break;
        }

        if (mic_value == 1) {
            log_timestamp();

            /* Turn LED on */
            ret = gpioWrite(LED_GPIO, 1);
            if (ret != 0) {
                fprintf(stderr, "Failed to turn LED ON (code %d)\n", ret);
                break;
            }

            /* Keep LED on for 100 ms (pigpio gpioDelay is microseconds) */
            gpioDelay(LED_ON_DURATION_US);

            /* Turn LED off */
            ret = gpioWrite(LED_GPIO, 0);
            if (ret != 0) {
                fprintf(stderr, "Failed to turn LED OFF (code %d)\n", ret);
                break;
            }
        }

        /* Sample at ~8 kHz */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

