#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define CONSUMER_NAME    "tracing_sensor"
#define POLL_INTERVAL_US 100000  // 100 ms

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL, *center_line = NULL, *right_line = NULL;
    int ret;

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open the default gpiochip (gpiochip0 on Raspberry Pi 4)
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!left_line || !center_line || !right_line) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    // Request lines as inputs with pull-up enabled
    ret = gpiod_line_request_input_flags(left_line, CONSUMER_NAME, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request left line as input");
        goto cleanup;
    }
    ret = gpiod_line_request_input_flags(center_line, CONSUMER_NAME, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request center line as input");
        goto cleanup;
    }
    ret = gpiod_line_request_input_flags(right_line, CONSUMER_NAME, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request right line as input");
        goto cleanup;
    }

    printf("Tracing sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int left_val, center_val, right_val;

        // Read sensor values (active-low: 0 = object detected, 1 = no object)
        left_val = gpiod_line_get_value(left_line);
        center_val = gpiod_line_get_value(center_line);
        right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            perror("Failed to read sensor values");
            break;
        }

        // Print sensor states (0 = object detected, 1 = no object)
        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    // Release lines and close chip
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

