#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define SI1175_ADDR 0x49
#define I2C_BUS "/dev/i2c-1"
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

int main() {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 Heart Rate Sensor Reader\n");
    printf("I2C Bus: %s, Address: 0x%02X\n", I2C_BUS, SI1175_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        uint8_t lsb = 0, msb = 0;

        if (i2c_read_reg8(fd, ALS_VIS_LSB_REG, &lsb) < 0) {
            fprintf(stderr, "Error reading ALS_VIS_LSB register: %s\n", strerror(errno));
            goto cleanup;
        }

        if (i2c_read_reg8(fd, ALS_VIS_MSB_REG, &msb) < 0) {
            fprintf(stderr, "Error reading ALS_VIS_MSB register: %s\n", strerror(errno));
            goto cleanup;
        }

        uint16_t als_vis = (msb << 8) | lsb;
        printf("ALS Visible: %u\n", als_vis);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting gracefully.\n");
    return ret;
}

