        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request each line as input */
    ret = gpiod_line_request_input(left_line, "3-way-tracking-sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", LEFT_PIN, strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_request_input(middle_line, "3-way-tracking-sensor");
    if (ret < 0) {
