    ret = gpiod_line_request_input(right_line, "3-way-tracking-sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", RIGHT_PIN, strerror(errno));
        goto cleanup;
    }

    printf("3-Way Tracking Sensor Program (libgpiod)\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    /* Release lines and close chip */
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nProgram terminated.\n");
    return EXIT_SUCCESS;
}

