/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod (v1.x API).
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   TTP226 TP1 -> BCM GPIO 5
 *   TTP226 TP2 -> BCM GPIO 6
 *   TTP226 TP3 -> BCM GPIO 13
 *   TTP226 TP4 -> BCM GPIO 19
 *   TTP226 TP5 -> BCM GPIO 26
 *   TTP226 TP6 -> BCM GPIO 12
 *   TTP226 TP7 -> BCM GPIO 16
 *   TTP226 TP8 -> BCM GPIO 20
 *   TTP226 VCC -> 3.3 V
 *   TTP226 GND -> GND
 *
 * Compile:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 *
 * Run:
 *   ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int channel_pins[NUM_CHANNELS] = {
    5,  6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return;
    }
    printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000L);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
    }

    if (install_signal_handlers() == -1) {
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        print_timestamp();

        for (int i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("CH%d=%d ", i + 1, values[i]);
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

