#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DELAY_US (5000000 / FADE_STEPS)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_color(int red, int green, int blue) {
    /* Common-anode: invert each channel */
    int r = PWM_RANGE - red;
    int g = PWM_RANGE - green;
    int b = PWM_RANGE - blue;

    if (gpioPWM(RED_PIN, r) != 0) {
        syslog(LOG_ERR, "Failed to set PWM on RED_PIN");
    }
    if (gpioPWM(GREEN_PIN, g) != 0) {
        syslog(LOG_ERR, "Failed to set PWM on GREEN_PIN");
    }
    if (gpioPWM(BLUE_PIN, b) != 0) {
        syslog(LOG_ERR, "Failed to set PWM on BLUE_PIN");
    }
}

static void fade_to_color(int red, int green, int blue) {
    int current_red, current_green, current_blue;
    int delta_red, delta_green, delta_blue;

    if (gpioGetPWMdutycycle(RED_PIN) < 0 ||
        gpioGetPWMdutycycle(GREEN_PIN) < 0 ||
        gpioGetPWMdutycycle(BLUE_PIN) < 0) {
        syslog(LOG_ERR, "Failed to read current PWM duty cycles");
        return;
    }

    current_red   = PWM_RANGE - gpioGetPWMdutycycle(RED_PIN);
    current_green = PWM_RANGE - gpioGetPWMdutycycle(GREEN_PIN);
    current_blue  = PWM_RANGE - gpioGetPWMdutycycle(BLUE_PIN);

    delta_red   = (red   - current_red)   / FADE_STEPS;
    delta_green = (green - current_green) / FADE_STEPS;
    delta_blue  = (blue  - current_blue)  / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS && running; i++) {
        current_red   += delta_red;
        current_green += delta_green;
        current_blue  += delta_blue;

        set_led_color(current_red, current_green, current_blue);
        usleep(FADE_DELAY_US);
    }

    set_led_color(red, green, blue);
}

static void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b) {
    if (s <= 0.0f) {
        *r = *g = *b = (int)(v * PWM_RANGE);
        return;
    }

    float hh = h;
    if (hh >= 360.0f) hh = 0.0f;
    hh /= 60.0f;
    int i = (int)hh;
    float ff = hh - i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - (s * ff));
    float t = v * (1.0f - (s * (1.0f - ff)));

    switch (i) {
        case 0: *r = (int)(v * PWM_RANGE); *g = (int)(t * PWM_RANGE); *b = (int)(p * PWM_RANGE); break;
        case 1: *r = (int)(q * PWM_RANGE); *g = (int)(v * PWM_RANGE); *b = (int)(p * PWM_RANGE); break;
        case 2: *r = (int)(p * PWM_RANGE); *g = (int)(v * PWM_RANGE); *b = (int)(t * PWM_RANGE); break;
        case 3: *r = (int)(p * PWM_RANGE); *g = (int)(q * PWM_RANGE); *b = (int)(v * PWM_RANGE); break;
        case 4: *r = (int)(t * PWM_RANGE); *g = (int)(p * PWM_RANGE); *b = (int)(v * PWM_RANGE); break;
        default: *r = (int)(v * PWM_RANGE); *g = (int)(p * PWM_RANGE); *b = (int)(q * PWM_RANGE); break;
    }
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set RED_PIN as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GREEN_PIN as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set BLUE_PIN as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency on RED_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency on GREEN_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        syslog(LOG_ERR, "Failed to set PWM frequency on BLUE_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range on RED_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range on GREEN_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != PWM_RANGE) {
        syslog(LOG_ERR, "Failed to set PWM range on BLUE_PIN");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int hue = rand() % 360;
        int red, green, blue;

        hsv_to_rgb((float)hue, 1.0f, 1.0f, &red, &green, &blue);
        fade_to_color(red, green, blue);

        /* Wait 5 seconds, checking running flag every 100 ms */
        for (int i = 0; i < 50 && running; i++) {
            usleep(100000);
        }
    }

    /* Graceful shutdown: turn off LED */
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

