#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define LED_GPIO_LINE  17
#define RED_THRESHOLD  200
#define POLL_DELAY_MS  200

/* TCS34725 registers */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID      0x92
#define TCS34725_CDATA   0x94
#define TCS34725_RDATA   0x96
#define TCS34725_GDATA   0x98
#define TCS34725_BDATA   0x9A

/* Enable register bits */
#define TCS34725_PON     0x01
#define TCS34725_AEN     0x02

/* Control register bits */
#define TCS34725_AGAIN_1X 0x00

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_PON) < 0) return -1;
    usleep(3000);

    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, TCS34725_AGAIN_1X) < 0) return -1;

    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) return -1;
    usleep(3000);

    return 0;
}

static int tcs34725_read_all(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_reg16(fd, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_RDATA, red)   < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_reg16(fd, TCS34725_BDATA, blue)  < 0) return -1;
    return 0;
}

static void calibrate(uint16_t raw_c, uint16_t raw_r, uint16_t raw_g, uint16_t raw_b,
                      float *cal_r, float *cal_g, float *cal_b, float *cal_c) {
    *cal_r = (float)raw_r * 1.0f;
    *cal_g = (float)raw_g * 1.0f;
    *cal_b = (float)raw_b * 1.0f;
    *cal_c = (float)raw_c * 1.0f;
}

int main(void) {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        goto cleanup;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("TCS34725 initialized. Reading every %d ms. Press Ctrl+C to exit.\n", POLL_DELAY_MS);

    while (g_running) {
        uint16_t raw_c, raw_r, raw_g, raw_b;

        if (tcs34725_read_all(i2c_fd, &raw_c, &raw_r, &raw_g, &raw_b) < 0) {
            fprintf(stderr, "Read error; attempting re-initialization...\n");
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed.\n");
            }
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        float cal_r, cal_g, cal_b, cal_c;
        calibrate(raw_c, raw_r, raw_g, raw_b, &cal_r, &cal_g, &cal_b, &cal_c);

        printf("R: %6.1f  G: %6.1f  B: %6.1f  C: %6.1f\n", cal_r, cal_g, cal_b, cal_c);

        int led_val = (cal_r > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_val) < 0) {
            fprintf(stderr, "Failed to set LED GPIO value: %s\n", strerror(errno));
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        uint8_t enable = 0;
        i2c_write_reg8(i2c_fd, TCS34725_ENABLE, enable);
        close(i2c_fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

