#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_GPIO 18
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_MEASUREMENT_DELAY_MS 180
#define NUM_LEDS 10
#define MAX_LUX 1000.0f
#define MIN_LUX 0.0f
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0
#define I2C_BUS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int wave_id = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", BH1750_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_light_level(float *lux_out) {
    char cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result == 0) {
            break;
        }
        fprintf(stderr, "I2C write failed (attempt %d/%d): %d\n", attempt + 1, RETRY_COUNT, result);
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (result != 0) {
        fprintf(stderr, "I2C write failed after %d attempts\n", RETRY_COUNT);
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_MS * 1000);

    char buf[2];
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            break;
        }
        fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", attempt + 1, RETRY_COUNT, result);
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (result != 2) {
        fprintf(stderr, "I2C read failed after %d attempts\n", RETRY_COUNT);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int map_light_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float normalized = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float brightness = powf(normalized, 0.5f) * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) + MIN_BRIGHTNESS;
    return (int)brightness;
}

static int set_led_brightness(int brightness) {
    if (brightness < MIN_BRIGHTNESS) brightness = MIN_BRIGHTNESS;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

    unsigned char data[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS; i++) {
        data[i * 3] = (unsigned char)brightness;
        data[i * 3 + 1] = (unsigned char)brightness;
        data[i * 3 + 2] = (unsigned char)brightness;
    }

    gpioWaveClear();
    wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "Failed to create wave: %d\n", wave_id);
        return -1;
    }

    gpioPulse_t pulse;
    pulse.gpioOn = (1 << LED_GPIO);
    pulse.gpioOff = 0;
    pulse.usDelay = 0;

    for (int i = 0; i < NUM_LEDS * 3; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            if (data[i] & (1 << bit)) {
                pulse.usDelay = 0.35f * 1000;
            } else {
                pulse.usDelay = 0.8f * 1000;
            }
            gpioWaveAddGeneric(1, &pulse);
        }
    }

    pulse.gpioOn = 0;
    pulse.gpioOff = (1 << LED_GPIO);
    pulse.usDelay = 50 * 1000;
    gpioWaveAddGeneric(1, &pulse);

    if (gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT) < 0) {
        fprintf(stderr, "Failed to send wave\n");
        gpioWaveDelete(wave_id);
        wave_id = -1;
        return -1;
    }

    while (gpioWaveTxBusy()) {
        gpioDelay(1000);
    }

    gpioWaveDelete(wave_id);
    wave_id = -1;
    return 0;
}

static void cleanup(void) {
    if (wave_id >= 0) {
        gpioWaveDelete(wave_id);
        wave_id = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Light-controlled WS2812B LED strip running. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_light_level(&lux) == 0) {
            int brightness = map_light_to_brightness(lux);
            if (set_led_brightness(brightness) != 0) {
                fprintf(stderr, "Failed to set LED brightness\n");
            }
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read light level\n");
        }
        gpioDelay(100000);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

