#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 120
#define NUM_LEDS 10
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define I2C_DEVICE "/dev/i2c-1"
#define MIN_LUX 10.0f
#define MAX_LUX 300.0f
#define MAX_BRIGHTNESS 31

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_init(const char *device, uint8_t addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int bh1750_read_lux(int fd, float *lux) {
    uint8_t cmd = BH1750_ONE_TIME_HIGH_RES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to write BH1750 command: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read BH1750 data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int spi_init(const char *device, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

void apa102_send_frame(int fd, uint8_t brightness, uint8_t r, uint8_t g, uint8_t b) {
    uint8_t start[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led[4] = {0xE0 | brightness, b, g, r};
    uint8_t *frame = malloc(4 + NUM_LEDS * 4 + 4);
    if (!frame) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    memcpy(frame, start, 4);
    for (int i = 0; i < NUM_LEDS; i++) {
        memcpy(frame + 4 + i * 4, led, 4);
    }
    memcpy(frame + 4 + NUM_LEDS * 4, end, 4);
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)frame,
        .rx_buf = 0,
        .len = 4 + NUM_LEDS * 4 + 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
    }
    free(frame);
}

void apa102_off(int fd) {
    apa102_send_frame(fd, 0, 0, 0, 0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = i2c_init(I2C_DEVICE, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    printf("Starting light-controlled LED strip...\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            usleep(100000);
            continue;
        }
        if (lux < MIN_LUX) lux = MIN_LUX;
        if (lux > MAX_LUX) lux = MAX_LUX;
        int brightness = (int)(((lux - MIN_LUX) / (MAX_LUX - MIN_LUX)) * MAX_BRIGHTNESS);
        if (brightness < 0) brightness = 0;
        if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
        apa102_send_frame(spi_fd, (uint8_t)brightness, 0, 0, 0);
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(50000);
    }

    printf("\nShutting down...\n");
    apa102_off(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

