    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: Failed to read BH1750 data from handle %d (read %d bytes)\n", handle, bytes_read);
        return -1;
    }
    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *lux = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 100000.0f) lux = 100000.0f;
    int brightness = (int)((1.0f - (lux / 100000.0f)) * (float)MAX_BRIGHTNESS);
    if (brightness < MIN_BRIGHTNESS) brightness = MIN_BRIGHTNESS;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return brightness;
}

static int fade_to_brightness(int target) {
    int step = (target > current_brightness) ? 1 : -1;
    int steps_needed = abs(target - current_brightness);
    int delay_per_step = (FADE_DURATION_MS * 1000) / steps_needed;
    for (int i = 0; i < steps_needed; i++) {
        current_brightness += step;
        if (current_brightness < MIN_BRIGHTNESS) current_brightness = MIN_BRIGHTNESS;
        if (current_brightness > MAX_BRIGHTNESS) current_brightness = MAX_BRIGHTNESS;
        if (spiWrite(spi_handle, (char *)&current_brightness, 1) != 0) {
