    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Warning: Could not open BH1750 at 0x%02X (handle %d), skipping\n", BH1750_ADDR_LOW, i2c_handles[0]);
    } else {
        if (init_bh1750(i2c_handles[0]) != 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X init failed, skipping\n", BH1750_ADDR_LOW);
            i2cClose(i2c_handles[0]);
            i2c_handles[0] = -1;
        }
