    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Warning: Could not open BH1750 at 0x%02X (handle %d), skipping\n", BH1750_ADDR_HIGH, i2c_handles[1]);
    } else {
        if (init_bh1750(i2c_handles[1]) != 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X init failed, skipping\n", BH1750_ADDR_HIGH);
            i2cClose(i2c_handles[1]);
            i2c_handles[1] = -1;
        }
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialization failed\n");
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) i2cClose(i2c_handles[i]);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Ambient light-controlled APA102 LED strip running. Press Ctrl+C to exit.\n");

    while (running) {
        float lux_sum = 0.0f;
        int valid_sensors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] < 0) continue;
            float lux;
            if (read_bh1750(i2c_handles[i], &lux) == 0) {
                lux_sum += lux;
                valid_sensors++;
            }
        }

        if (valid_sensors > 0) {
            float avg_lux = lux_sum / (float)valid_sensors;
            int target_brightness = map_lux_to_brightness(avg_lux);
            if (fade_to_brightness(target_brightness) != 0) {
                fprintf(stderr, "Error: Fade operation failed, exiting\n");
                break;
            }
        } else {
            fprintf(stderr, "Warning: No valid BH1750 sensors found, keeping current brightness\n");
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    turn_off_leds();

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

