#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define WS2812B_GPIO_LINE 18
#define NUM_LEDS 10
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile int keep_running = 1;

// Function prototypes
int init_veml7700(int fd);
int read_veml7700_lux(int fd, float *lux);
int init_ws2812b(void);
void set_led_brightness(int brightness);
void cleanup(void);
void signal_handler(int sig);

// Initialize VEML7700 sensor
int init_veml7700(int fd) {
    uint8_t config[2];
    config[0] = VEML7700_CONFIG_REG;
    config[1] = 0x0000; // Integration time 100ms, gain 1/8
    if (write(fd, config, 2) != 2) {
        fprintf(stderr, "Error writing to VEML7700 config register: %s\n", strerror(errno));
        return -1;
    }
    usleep(10000); // Wait 10ms for configuration to take effect
    return 0;
}

// Read lux value from VEML7700 sensor
int read_veml7700_lux(int fd, float *lux) {
    uint8_t reg = VEML7700_ALS_DATA_REG;
    uint8_t data[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to VEML7700 ALS data register: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS data register: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (data[1] << 8) | data[0];
    // Convert raw value to lux: lux = raw * 0.0036 * (1/gain) * (100ms/integration_time)
    // For gain 1/8 and integration time 100ms, lux = raw * 0.0288
    *lux = (float)raw * 0.0288f;
    return 0;
}

// Initialize WS2812B strip using libgpiod
int init_ws2812b(void) {
    chip = gpiod_chip_open_by_number(0); // GPIO chip 0 on Raspberry Pi
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }
    line = gpiod_chip_get_line(chip, WS2812B_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", WS2812B_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }
    return 0;
}

// Set LED brightness using bit-banging (simple on/off control for demonstration)
void set_led_brightness(int brightness) {
    if (brightness > 255) brightness = 255;
    if (brightness < 0) brightness = 0;
    // For simplicity, we assume a single LED connected to GPIO18
    // We would normally use a timing-accurate bit-banging approach
    // Here we simply set the line high or low based on brightness
    if (brightness > 0) {
        gpiod_line_set_value(line, 1);
    } else {
        gpiod_line_set_value(line, 0);
    }
}

// Cleanup resources
void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0); // Turn off LED strip
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize VEML7700 sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize WS2812B
    if (init_ws2812b() != 0) {
        fprintf(stderr, "Failed to initialize WS2812B strip\n");
        close(i2c_fd);
        return 1;
    }

    printf("Starting ambient light control loop...\n");

    while (keep_running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;

        // Retry loop for I2C communication
        while (retries < MAX_RETRIES && !success) {
            if (read_veml7700_lux(i2c_fd, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read lux value after %d retries\n", MAX_RETRIES);
            // Continue with previous lux value or turn off LED
        }

        // Map lux to brightness (0-255) with gamma correction
        float brightness = 255.0f * powf(lux / 120000.0f, 1.0f / 2.2f);
        if (brightness > 255.0f) brightness = 255.0f;
        if (brightness < 0.0f) brightness = 0.0f;

        // Set LED brightness
        set_led_brightness((int)brightness);

        // Print values
        printf("Lux: %.2f, Brightness: %.0f\n", lux, brightness);

        // Delay
        usleep(LOOP_DELAY_MS * 1000);
    }

    // Cleanup
    cleanup();
    printf("Program terminated cleanly.\n");
    return 0;
}

