#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_DEVICE "/dev/i2c-1"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_exported = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_init(const char *device, uint8_t addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int bh1750_init(int fd) {
    uint8_t cmd = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to send BH1750 init command: %s\n", strerror(errno));
        return -1;
    }
    usleep(180000); // Wait for first measurement (max 180ms)
    return 0;
}

int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read BH1750 data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int gpio_export(int pin) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY) return 0; // Already exported
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    char buf[4];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        fprintf(stderr, "Failed to write GPIO export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    gpio_exported = 1;
    return 0;
}

int gpio_unexport(int pin) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    char buf[4];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        fprintf(stderr, "Failed to write GPIO unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    gpio_exported = 0;
    return 0;
}

int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO direction: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO value: %s\n", strerror(errno));
        return -1;
    }
    char buf[2];
    snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, strlen(buf)) != (ssize_t)strlen(buf)) {
        fprintf(stderr, "Failed to write GPIO value: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

float calculate_average(float buffer[], int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

int main() {
    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    signal(SIGINT, signal_handler);

    i2c_fd = i2c_init(I2C_DEVICE, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    printf("Starting light sensor monitoring...\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) == 0) {
            lux_buffer[buffer_index] = lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) {
                buffer_count++;
            }

            float avg_lux = calculate_average(lux_buffer, buffer_count);

            float blink_rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
            if (blink_rate < 0.5f) blink_rate = 0.5f;
            if (blink_rate > 5.0f) blink_rate = 5.0f;

            float half_period_us = 1000000.0f / (blink_rate * 2.0f);

            gpio_write(GPIO_PIN, 1);
            usleep((useconds_t)half_period_us);
            gpio_write(GPIO_PIN, 0);
            usleep((useconds_t)half_period_us);

            printf("Lux: %.2f, Avg: %.2f, Blink: %.2f Hz\n", lux, avg_lux, blink_rate);
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpio_write(GPIO_PIN, 0);
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);
    printf("Cleanup complete.\n");
    return 0;
}

