#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>
#include <signal.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define CHIP_NAME "gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (latch_line) gpiod_line_release(latch_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (data_line) gpiod_line_release(data_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_line, (data >> i) & 1);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1);
    gpiod_line_set_value(latch_line, 0);
    usleep(1);
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        cleanup_and_exit(0);
    }

    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup_and_exit(0);
    }

    while (1) {
        // Display digit '5' on common cathode: segments a,b,c,d,e,f ON (1)
        shift_out(0b00100101); // Q0=a, Q1=b, Q2=c, Q3=d, Q4=e, Q5=f, Q6=g, Q7=dp
        usleep(500000);
        shift_out(0x00); // Clear display
        usleep(500000);
    }

    cleanup_and_exit(0);
    return 0;
}

