#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_INTERVAL_MS 1000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handler for graceful exit
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line as output, initially low
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line as input with pull-up and falling-edge event detection
    ret = gpiod_line_request_falling_edge_events_flags(button_line, "blink_button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("Failed to request button line as input with pull-up");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Blinking LED on BCM GPIO%d every %d ms. Press button (BCM GPIO%d) to stop.\n", LED_PIN, BLINK_INTERVAL_MS, BUTTON_PIN);

    int led_state = 0;
    struct timespec sleep_time = {0, BLINK_INTERVAL_MS * 1000000L};

    while (keep_running) {
        // Wait for button event with timeout
        ret = gpiod_line_event_wait(button_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (ret < 0) {
            perror("Error waiting for button event");
            break;
        } else if (ret == 0) {
            // Timeout, continue blinking
            nanosleep(&sleep_time, NULL);
            led_state = !led_state;
            ret = gpiod_line_set_value(led_line, led_state);
            if (ret < 0) {
                perror("Failed to set LED value");
                break;
            }
            continue;
        }

        // Event detected, read it
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("Failed to read button event");
            break;
        }

        // Stop blinking on falling edge
        printf("Button pressed! Stopping blinking.\n");
        led_state = 0;
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Failed to turn off LED");
            break;
        }
        break;
    }

    // Cleanup
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

