#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5
#define BLINK_DELAY_MS 750

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    while (program_running) {
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(BLINK_DELAY_MS * 1000);

        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(BLINK_DELAY_MS * 1000);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return 0;
}

