#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define CHIP_NAME "gpiochip0"
#define BLINK_INTERVAL_MS 500

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret;

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line (GPIO24)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Failed to get button line (GPIO22)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure LED as output, initially low
    ret = gpiod_line_request_output(led_line, "led-blink", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure button as input with internal pull-down
    ret = gpiod_line_request_input_flags(button_line, "button-input", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("Failed to request button line as input with pull-down");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("LED blinking program started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int button_val = gpiod_line_get_value(button_line);
        if (button_val < 0) {
            perror("Failed to read button value");
            break;
        }

        if (button_val == 1) {
            // Button pressed: blink LED
            gpiod_line_set_value(led_line, 1);
            usleep(BLINK_INTERVAL_MS * 1000);
            gpiod_line_set_value(led_line, 0);
            usleep(BLINK_INTERVAL_MS * 1000);
        } else {
            // Button released: ensure LED is off
            gpiod_line_set_value(led_line, 0);
            usleep(10000); // 10 ms to avoid busy-waiting
        }
    }

    // Cleanup
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

