                    // Retry if interrupted by signal
                }
            }

            // Turn off green
            if (gpiod_line_set_value(green_line, 0) < 0) {
                perror("Failed to set green line low");
                release_resources();
                return EXIT_FAILURE;
            }

            // Turn on blue if duty cycle is non-zero
            if (blue_val > 0) {
                if (gpiod_line_set_value(blue_line, 1) < 0) {
                    perror("Failed to set blue line high");
                    release_resources();
                    return EXIT_FAILURE;
                }
                struct timespec req = {0, (blue_val * PWM_PERIOD_NS) / 100};
                while (nanosleep(&req, &req) == -1 && errno == EINTR && keep_running) {
                    // Retry if interrupted by signal
                }
