#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADPD188BI I2C address (7-bit)
#define ADPD188BI_ADDR 0x39

// ADPD188BI register addresses
#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_RED_MSB 0x68
#define REG_BLUE_LSB 0x6A

// GPIO pin for LED control (hardware PWM)
#define LED_PIN 18

// PWM range (0-255)
#define PWM_RANGE 255

// I2C bus
#define I2C_BUS 1

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_adpd188bi(int handle);
int read_als(int handle, uint16_t *als);
int read_color(int handle, uint16_t *red, uint16_t *green, uint16_t *blue);
void control_led(uint16_t als);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    // Turn off LED
    gpioPWM(LED_PIN, 0);
    gpioTerminate();
}

// Initialize ADPD188BI sensor
