#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_OUT_X_MSB  0x01

/* Expected WHO_AM_I value for FXOS8700CQ */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* Impact threshold: 2g in m/s^2 (9.81 m/s^2 per g) */
#define IMPACT_THRESHOLD 19.62f

/* Sensitivity for ±2g range: 4096 counts/g */
#define ACCEL_SENSITIVITY 4096.0f

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Initialize FXOS8700CQ: verify WHO_AM_I, configure ±2g, activate */
static int init_fxos8700(int handle) {
    int who_am_i = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                FXOS8700_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit in CTRL_REG1 */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error putting FXOS8700CQ into standby\n");
        return -1;
    }

    /* Configure ±2g range (0x00) */
    if (i2cWriteByteData(handle, FXOS8700_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error configuring XYZ_DATA_CFG\n");
        return -1;
    }

    /* Active mode, 200 Hz ODR: set ACTIVE bit (bit 0) */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error activating FXOS8700CQ\n");
        return -1;
    }

    return 0;
}

/* Read 6 bytes of acceleration data and convert to m/s^2 */
static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    /* Data is 14-bit left-justified; shift right by 2 */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Convert to m/s^2: raw * sensitivity / 1000 * 9.81 */
    *x = (float)raw_x * ACCEL_SENSITIVITY / 1000.0f * 9.81f;
    *y = (float)raw_y * ACCEL_SENSITIVITY / 1000.0f * 9.81f;
    *z = (float)raw_z * ACCEL_SENSITIVITY / 1000.0f * 9.81f;

    return 0;
}

/* Compute magnitude of acceleration vector */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Log impact event to file */
static void log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize sensor */
    if (init_fxos8700(i2c_handle) < 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    /* Main loop */
    while (1) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
            }
        }
        gpioDelay(50000); /* 50 ms delay */
    }

    /* Cleanup (unreachable in normal operation, but kept for completeness) */
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

