#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GYRO_ADDR        0x69
#define WHO_AM_I         0x0F
#define WHO_AM_I_VAL     0xD3
#define CTRL_REG1        0x20
#define CTRL_REG4        0x23
#define OUT_X_L          0x28
#define OUT_X_H          0x29
#define OUT_Y_L          0x2A
#define OUT_Y_H          0x2B
#define OUT_Z_L          0x2C
#define OUT_Z_H          0x2D

#define SENSITIVITY      0.00875f   /* dps/LSB at 250 dps full-scale */
#define THRESHOLD_DPS    50.0f
#define CALIB_SAMPLES    100
#define SAMPLE_PERIOD_US 50000      /* 20 Hz */
#define LOG_FILE         "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read %zu bytes from 0x%02X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x0F = normal mode, XYZ axes enabled, 100 Hz ODR */
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0)
        return -1;

    /* CTRL_REG4: 0x00 = 250 dps full-scale, continuous update */
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0)
        return -1;

    return 0;
}

static int gyro_read_raw(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L | 0x80, buf, 6) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void calibrate(int fd, float *x_off, float *y_off, float *z_off)
{
    float sx = 0.0f, sy = 0.0f, sz = 0.0f;
    int16_t rx, ry, rz;

    printf("Calibrating gyroscope (%d samples)...\n", CALIB_SAMPLES);
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (gyro_read_raw(fd, &rx, &ry, &rz) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            *x_off = *y_off = *z_off = 0.0f;
            return;
        }
        sx += rx; sy += ry; sz += rz;
        usleep(10000);
    }
    *x_off = sx / CALIB_SAMPLES;
    *y_off = sy / CALIB_SAMPLES;
    *z_off = sz / CALIB_SAMPLES;
    printf("Calibration complete: X=%.2f Y=%.2f Z=%.2f\n", *x_off, *y_off, *z_off);
}

static void log_data(FILE *fp, float x, float y, float z, int alert)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, X: %.2f, Y: %.2f, Z: %.2f", ts, x, y, z);
    if (alert)
        fprintf(fp, ", ALERT: Exceeded threshold");
    fprintf(fp, "\n");
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open("/dev/i2c-1", O_RDWR);
    if (g_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (gyro_init(g_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(g_fd);
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen log");
        close(g_fd);
        return EXIT_FAILURE;
    }

    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;
    calibrate(g_fd, &x_off, &y_off, &z_off);

    printf("Logging gyro data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        int16_t rx, ry, rz;
        if (gyro_read_raw(g_fd, &rx, &ry, &rz) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float x = (rx - x_off) * SENSITIVITY;
        float y = (ry - y_off) * SENSITIVITY;
        float z = (rz - z_off) * SENSITIVITY;

        int alert = (fabsf(x) > THRESHOLD_DPS ||
                     fabsf(y) > THRESHOLD_DPS ||
                     fabsf(z) > THRESHOLD_DPS);

        log_data(g_log, x, y, z, alert);

        if (alert)
            fprintf(stderr, "ALERT: X=%.2f Y=%.2f Z=%.2f dps\n", x, y, z);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log) fclose(g_log);
    if (g_fd >= 0) close(g_fd);
    return EXIT_SUCCESS;
}

