#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDR        0x53
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_DEVID_VAL   0xE5
#define LED_GPIO            17
#define ACCEL_THRESHOLD_G   2.0f
#define SAMPLE_PERIOD_US    100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_adxl345(void) {
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register (pigpio error %d)\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VAL);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write POWER_CTL (standby)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to write DATA_FORMAT (full-res, +/-2g)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write POWER_CTL (measure)\n");
        return -1;
    }
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read failed (rc=%d)\n", rc);
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at 0x%02X (pigpio error %d)\n", ADXL345_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_adxl345() != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("accel_log.txt", "a");
    if (!log_file) {
        perror("Error opening accel_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_accel(&x, &y, &z) == 0) {
            log_data(x, y, z);
            if (fabsf(x) > ACCEL_THRESHOLD_G || fabsf(y) > ACCEL_THRESHOLD_G || fabsf(z) > ACCEL_THRESHOLD_G) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Warning: read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

