#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ACCEL_ADDR 0x19
#define MAG_ADDR   0x1E

#define CTRL_REG1_A 0x20
#define MR_REG_M    0x02
#define OUT_X_L_A   0x28
#define OUT_X_H_M   0x03

#define ACCEL_SCALE 0.000244f
#define MAG_SCALE   0.00014f

static volatile sig_atomic_t running = 1;
static int accel_handle = -1;
static int mag_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C: %d\n", accel_handle);
        return -1;
    }
    if (i2cWriteByteData(accel_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        i2cClose(accel_handle);
        accel_handle = -1;
        return -1;
    }
    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C: %d\n", mag_handle);
        i2cClose(accel_handle);
        accel_handle = -1;
        return -1;
    }
    if (i2cWriteByteData(mag_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        i2cClose(accel_handle);
        accel_handle = -1;
        i2cClose(mag_handle);
        mag_handle = -1;
        return -1;
    }
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(accel_handle, OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = raw_x * ACCEL_SCALE;
    *y = raw_y * ACCEL_SCALE;
    *z = raw_z * ACCEL_SCALE;
    return 0;
}

static int read_mag(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(mag_handle, OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);
    *x = raw_x * MAG_SCALE;
    *y = raw_y * MAG_SCALE;
    *z = raw_z * MAG_SCALE;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float cos_roll = cosf(roll);
    float sin_roll = sinf(roll);
    float cos_pitch = cosf(pitch);
    float sin_pitch = sinf(pitch);
    float mx_comp = mx * cos_pitch + mz * sin_pitch;
    float my_comp = mx * sin_roll * sin_pitch + my * cos_roll - mz * sin_roll * cos_pitch;
    float heading = atan2f(my_comp, mx_comp) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    printf("Compass logging started. Press Ctrl+C to stop.\n");
    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accel(&ax, &ay, &az) == 0 && read_mag(&mx, &my, &mz) == 0) {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
            printf("Heading: %.2f, Accel: %.6f %.6f %.6f, Mag: %.6f %.6f %.6f\n",
                   heading, ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Sensor read error, skipping log entry\n");
        }
        gpioDelay(100000);
    }
    if (accel_handle >= 0) i2cClose(accel_handle);
    if (mag_handle >= 0) i2cClose(mag_handle);
    gpioTerminate();
    printf("Compass logging stopped.\n");
    return 0;
}

