#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VL6180X_ADDR 0x29
#define I2C_BUS 1
#define DISTANCE_THRESHOLD 100
#define LOG_FILE "distance_log.txt"

#define REG_IDENTIFICATION_MODEL_ID 0x000
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSRANGE_START 0x018
#define REG_RESULT_RANGE_STATUS 0x04d
#define REG_RESULT_RANGE_VAL 0x062

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int init_vl6180x(int handle) {
    uint8_t model_id = 0;
    if (read_reg8(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xB4) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xB4).\n", model_id);
        return -1;
    }

    uint8_t fresh = 0;
    if (read_reg8(handle, REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh) != 0) {
        fprintf(stderr, "Error: Failed to read fresh-out-of-reset register.\n");
        return -1;
    }
    if (fresh != 0x01) {
        fprintf(stderr, "Warning: Sensor not fresh out of reset (0x%02X).\n", fresh);
    }

    if (write_reg16(handle, 0x0207, 0x01) != 0) return -1;
    if (write_reg16(handle, 0x0208, 0x01) != 0) return -1;
    if (write_reg16(handle, 0x0096, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x0097, 0xfd) != 0) return -1;
    if (write_reg16(handle, 0x00e3, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00e4, 0x04) != 0) return -1;
    if (write_reg16(handle, 0x00e5, 0x02) != 0) return -1;
    if (write_reg16(handle, 0x00e6, 0x01) != 0) return -1;
    if (write_reg16(handle, 0x00e7, 0x03) != 0) return -1;
    if (write_reg16(handle, 0x00f5, 0x02) != 0) return -1;
    if (write_reg16(handle, 0x00d9, 0x05) != 0) return -1;
    if (write_reg16(handle, 0x00db, 0xce) != 0) return -1;
    if (write_reg16(handle, 0x00dc, 0x03) != 0) return -1;
    if (write_reg16(handle, 0x00dd, 0xf8) != 0) return -1;
    if (write_reg16(handle, 0x009f, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00ea, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00eb, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00ec, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00ed, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00ee, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00ef, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f0, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f1, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f2, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f3, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f4, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f5, 0x02) != 0) return -1;
    if (write_reg16(handle, 0x00f6, 0x01) != 0) return -1;
    if (write_reg16(handle, 0x00f7, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f8, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00f9, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00fa, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00fb, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00fc, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00fd, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00fe, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x00ff, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x0100, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x0198, 0x01) != 0) return -1;
    if (write_reg16(handle, 0x01b0, 0x17) != 0) return -1;
    if (write_reg16(handle, 0x01ad, 0x00) != 0) return -1;
    if (write_reg16(handle, 0x0030, 0x00) != 0) return -1;

    return 0;
}

static int read_distance(int handle) {
    if (write_reg16(handle, REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start range measurement.\n");
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        uint8_t status = 0;
        if (read_reg8(handle, REG_RESULT_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read range status.\n");
            return -1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        gpioDelay(1000);
        if (i == 99) {
            fprintf(stderr, "Error: Range measurement timeout.\n");
            return -1;
        }
    }

    uint8_t distance = 0;
    if (read_reg8(handle, REG_RESULT_RANGE_VAL, &distance) != 0) {
        fprintf(stderr, "Error: Failed to read range value.\n");
        return -1;
    }

    return (int)distance;
}

static void log_data(const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %s\n", timestamp, status);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", VL6180X_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (init_vl6180x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL6180X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Proximity-based door opener started. Press Ctrl+C to exit.\n");

    while (!terminate) {
