#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_VAL 0x80
#define SAMPLE_INTERVAL_US 10000 // 10 ms
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int i2c_bus, int sensor_address);
int read_audio_sample(int i2c_handle, int16_t *sample);
int read_sensor_data(int i2c_handle1, int i2c_handle2, sensor_data_t *data);
int calculate_tdoa(sensor_data_t data);
int log_data(sensor_data_t data, int tdoa);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c(int i2c_bus, int sensor_address) {
    int handle = i2cOpen(i2c_bus, sensor_address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", sensor_address, handle);
        return -1;
    }

    // Write control register to enable continuous measurement
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_VAL) < 0) {
        fprintf(stderr, "Error writing to control register at address 0x%02X\n", sensor_address);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Read audio sample from sensor
int read_audio_sample(int i2c_handle, int16_t *sample) {
    int raw_data = i2cReadWordData(i2c_handle, DATA_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading data from I2C handle %d\n", i2c_handle);
        return -1;
    }

    // pigpio returns data in little-endian format, swap bytes to get big-endian
    *sample = (int16_t)((raw_data >> 8) | (raw_data << 8));
    return 0;
}

// Read sensor data from both sensors
int read_sensor_data(int i2c_handle1, int i2c_handle2, sensor_data_t *data) {
    if (read_audio_sample(i2c_handle1, &data->sensor1) != 0) {
        fprintf(stderr, "Error reading sensor 1 data\n");
        return -1;
    }
    if (read_audio_sample(i2c_handle2, &data->sensor2) != 0) {
        fprintf(stderr, "Error reading sensor 2 data\n");
        return -1;
    }

    if (clock_gettime(CLOCK_REALTIME, &data->timestamp) != 0) {
        perror("clock_gettime");
        return -1;
    }

    return 0;
}

// Calculate Time Difference of Arrival (TDOA)
int calculate_tdoa(sensor_data_t data) {
    return data.sensor1 - data.sensor2;
}

// Log data to file
int log_data(sensor_data_t data, int tdoa) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%ld,%ld,%d,%d,%d\n", data.timestamp.tv_sec, data.timestamp.tv_nsec, data.sensor1, data.sensor2, tdoa) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    int tdoa;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle1, i2c_handle2, &sensor_data) == 0) {
            tdoa = calculate_tdoa(sensor_data);
            if (log_data(sensor_data, tdoa) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

