#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (7-bit, left-justified in 16-bit SPI word) */
#define REG_X_GYRO   0x04
#define REG_Y_GYRO   0x06
#define REG_Z_GYRO   0x08
#define REG_X_ACCEL  0x0A
#define REG_Y_ACCEL  0x0C
#define REG_Z_ACCEL  0x0E

/* Sensitivities (from ADIS16488A datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000     /* 1 MHz */
#define SPI_FLAGS   0b11000000000 /* CPHA=1, CPOL=1, aux SPI off */

/* Sampling interval */
#define SAMPLE_INTERVAL_US 100000 /* 100 ms */

/* Global state for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close resources in reverse order of acquisition          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16488A                           */
/* Returns 0 on success, -1 on SPI transfer error                      */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *value)
{
    char tx_buf[2];
    char rx_buf[2];

    /*
