#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Scale factors
#define GYRO_SCALE 0.02f
#define ACCEL_SCALE 0.00025f

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define CS_PIN 8

// Global variables for cleanup
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int adis16448_read_register(uint8_t reg, int16_t *value);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1); // Deselect chip
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

// Initialize SPI interface
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Perform SPI transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read a 16-bit register from ADIS16448
int adis16448_read_register(uint8_t reg, int16_t *value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Phase 1: Send read command (address with bit 7 set)
    tx_buf[0] = reg | 0x80;
    tx_buf[1] = 0x00;

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        return -1;
    }

    // Small delay to allow register to be read
    usleep(10);

    // Phase 2: Read data
    tx_buf[0] = 0x00; // Dummy byte to clock out data
    tx_buf[1] = 0x00;

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        return -1;
    }

    // Combine bytes (MSB first)
    *value = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

int main(void) {
    // Initialize libgpiod for chip-select
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "adis16448_cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADIS16448 IMU Reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (adis16448_read_register(XGYRO_OUT, &gyro_x) < 0 ||
            adis16448_read_register(YGYRO_OUT, &gyro_y) < 0 ||
            adis16448_read_register(ZGYRO_OUT, &gyro_z) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        // Read accelerometer data
        if (adis16448_read_register(XACCL_OUT, &accel_x) < 0 ||
            adis16448_read_register(YACCL_OUT, &accel_y) < 0 ||
            adis16448_read_register(ZACCL_OUT, &accel_z) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        // Convert to physical units
        float gyro_x_dps = gyro_x * GYRO_SCALE;
        float gyro_y_dps = gyro_y * GYRO_SCALE;
        float gyro_z_dps = gyro_z * GYRO_SCALE;

        float accel_x_g = accel_x * ACCEL_SCALE;
        float accel_y_g = accel_y * ACCEL_SCALE;
        float accel_z_g = accel_z * ACCEL_SCALE;

        // Print data
        printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);
        printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n", accel_x_g, accel_y_g, accel_z_g);

        // Wait 100 milliseconds
        usleep(100000);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");

    return 0;
}

