#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6886_ADDR 0x68
#define I2C_BUS "/dev/i2c-1"

#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x86
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int mpu6886_init(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);

    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    if (i2c_write_reg8(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_raw_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    int retries = 3;

    while (retries > 0) {
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 14) == 0) {
            *ax = (int16_t)((buf[0] << 8) | buf[1]);
            *ay = (int16_t)((buf[2] << 8) | buf[3]);
            *az = (int16_t)((buf[4] << 8) | buf[5]);
            *gx = (int16_t)((buf[8] << 8) | buf[9]);
            *gy = (int16_t)((buf[10] << 8) | buf[11]);
            *gz = (int16_t)((buf[12] << 8) | buf[13]);
            return 0;
        }
        retries--;
        if (retries > 0) usleep(10000);
    }

    fprintf(stderr, "Error reading raw data after retries: %s\n", strerror(errno));
    return -1;
}

int main(void) {
    int fd = -1;
    int16_t ax, ay, az, gx, gy, gz;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6886_init(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("MPU-6886 initialized. Reading raw data every 50 ms...\n");

    while (running) {
        if (read_raw_data(fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d | Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(50000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

