#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I    0x75
#define PWR_MGMT_1  0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define WHO_AM_I_EXPECTED 0x12

/* Sampling interval in microseconds (100 ms = 10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize the ICM-20602 sensor */
static int init_icm20602(int handle) {
    int result;

    /* Verify sensor identity */
    result = i2cReadByteData(handle, WHO_AM_I);
    if (result < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (result != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                WHO_AM_I_EXPECTED, result);
        return -1;
    }

    /* Wake up the sensor (clear sleep bit) */
    result = i2cWriteByteData(handle, PWR_MGMT_1, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle time after wake-up */

    /* Set accelerometer range to +/- 2g (AFS_SEL = 0) */
    result = i2cWriteByteData(handle, ACCEL_CONFIG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps (FS_SEL = 0) */
    result = i2cWriteByteData(handle, GYRO_CONFIG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read accelerometer and gyroscope data using burst reads */
static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];
    int result;

    /* Burst read 14 bytes starting at ACCEL_XOUT_H (0x3B) */
    result = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 14);
    if (result != 14) {
        fprintf(stderr, "Error reading sensor data block: %s\n", strerror(errno));
        return -1;
    }

    /* Accelerometer data: buf[0] = high byte, buf[1] = low byte */
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);

    /* Gyroscope data: buf[8] = high byte, buf[9] = low byte */
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/* Log data to CSV file */
static int log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                    int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec, ax, ay, az, gx, gy, gz) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int16_t ax, ay, az, gx, gy, gz;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_icm20602(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");
        fflush(log_file);
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler: %s\n", strerror(errno));
    }

    printf("Logging IMU data to imu_log.csv at 10 Hz. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            if (log_data(log_file, ax, ay, az, gx, gy, gz) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

