#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0x1A
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define ACCEL_SCALE 1024.0f
#define ACCEL_THRESHOLD 2.0f
#define LED_GPIO_LINE 17
#define POLL_INTERVAL_US 100000
#define LED_ON_DURATION_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%02X, val 0x%02X) failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
    if (i2c_read_reg8(fd, OUT_X_MSB, &x_msb) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_MSB + 1, &x_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_MSB + 2, &y_msb) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_MSB + 3, &y_lsb) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_MSB + 4, &z_msb) < 0) return -1;
    if (i2c_read_reg8(fd, OUT_X_MSB + 5, &z_lsb) < 0) return -1;

    int16_t raw_x = (int16_t)((x_msb << 8) | x_lsb);
    int16_t raw_y = (int16_t)((y_msb << 8) | y_lsb);
    int16_t raw_z = (int16_t)((z_msb << 8) | z_lsb);

    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static int detect_impact(float x, float y, float z) {
    return (fabsf(x) > ACCEL_THRESHOLD || fabsf(y) > ACCEL_THRESHOLD || fabsf(z) > ACCEL_THRESHOLD);
}

static void log_impact(FILE *log_file) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Impact detected!\n", timestamp);
    fflush(log_file);
}

int main(void) {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MMA8451Q_ADDR, strerror(errno));
        goto cleanup;
    }

    uint8_t who_am_i = 0;
    if (i2c_read_reg8(i2c_fd, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        goto cleanup;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, who_am_i);
        goto cleanup;
    }

    if (i2c_write_reg8(i2c_fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to enable MMA8451Q\n");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "mma8451q_impact", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (detect_impact(x, y, z)) {
            printf("Impact detected! X=%.2f g, Y=%.2f g, Z=%.2f g\n", x, y, z);
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED: %s\n", strerror(errno));
            }
            log_impact(log_file);
            usleep(LED_ON_DURATION_US);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED: %s\n", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

