#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATAX0 0x32
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20

#define ADXL345_DEVID_VALUE 0xE5
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_INT_ENABLE_FREEFALL 0x04
#define ADXL345_INT_MAP_FREEFALL 0x00

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "freefall_log.csv"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr = ADXL345_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgs[1].addr = ADXL345_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = (uint16_t)len;
    msgs[1].buf = buf;

    data.msgs = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) < 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, ADXL345_THRESH_FF, 0x14) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_TIME_FF, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, ADXL345_INT_MAP_FREEFALL) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, ADXL345_INT_ENABLE_FREEFALL) < 0) return -1;
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, ADXL345_POWER_CTL_MEASURE) < 0) return -1;

    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    uint8_t int_source = 0;
    uint8_t data[6];
    int16_t x, y, z;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_falling_edge_events(line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling edge events on GPIO %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (i2c_read_reg8(i2c_fd, ADXL345_INT_SOURCE, &int_source) < 0) {
            continue;
        }

        if ((int_source & ADXL345_INT_ENABLE_FREEFALL) == 0) {
            continue;
        }

        if (i2c_read_block(i2c_fd, ADXL345_DATAX0, data, 6) < 0) {
            continue;
        }

        x = (int16_t)((data[1] << 8) | data[0]);
        y = (int16_t)((data[3] << 8) | data[2]);
        z = (int16_t)((data[5] << 8) | data[4]);

        if (log_data(log_file, x, y, z) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }
    }

    printf("\nCleaning up...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_INT_ENABLE, 0x00);
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

