#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x69
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define STATUS_REG 0x1E

#define ACCEL_SCALE 0.000061f
#define GYRO_SCALE 0.00875f

#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define TIMEOUT_SEC 1.0

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm6dsr(void) {
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing CTRL1_XL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing CTRL2_G\n");
        return -1;
    }
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buf[12];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buf + 6, 6) != 6) {
        fprintf(stderr, "Error reading accel data\n");
        return -1;
    }
    int16_t raw_gyro_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_gyro_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_gyro_z = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_accel_x = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_accel_y = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_accel_z = (int16_t)((buf[11] << 8) | buf[10]);
    data->gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    data->gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    data->gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    data->accel_x = (float)raw_accel_x * ACCEL_SCALE;
    data->accel_y = (float)raw_accel_y * ACCEL_SCALE;
    data->accel_z = (float)raw_accel_z * ACCEL_SCALE;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

static void detect_fall(const sensor_data_t *data) {
    static int state = 0;
    static time_t start_time = 0;
    float accel_mag = sqrtf(data->accel_x * data->accel_x +
                           data->accel_y * data->accel_y +
                           data->accel_z * data->accel_z);
    time_t now = time(NULL);
    switch (state) {
        case 0:
            if (accel_mag < FREEFALL_THRESHOLD) {
                state = 1;
                start_time = now;
            }
            break;
        case 1:
            if (accel_mag > IMPACT_THRESHOLD) {
                state = 2;
                start_time = now;
            } else if (difftime(now, start_time) > TIMEOUT_SEC) {
                state = 0;
            }
            break;
        case 2:
            if (accel_mag < FREEFALL_THRESHOLD) {
                printf("Fall detected!\n");
                state = 0;
            } else if (difftime(now, start_time) > TIMEOUT_SEC) {
                state = 0;
            }
            break;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "Sensor not found (WHO_AM_I=0x%02X, expected 0x%02X)\n",
                who_am_i, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sensor_data_t sensor_data;
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            detect_fall(&sensor_data);
        } else {
            fprintf(stderr, "Read error, retrying...\n");
        }
        gpioDelay(10000);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

