#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_XGYRO_OUT  0x14
#define ADIS16266_REG_WHO_AM_I   0x00
#define ADIS16266_REG_SMPL_PRD   0x36
#define ADIS16266_REG_GLOB_CMD   0x68

/* ADIS16266 Expected Device ID */
#define ADIS16266_WHO_AM_I_VAL   0x3F5A

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x03     /* Mode 3: CPOL=1, CPHA=1 */

/* Sampling Period (10 ms) */
#define SAMPLE_PERIOD_US 10000

/* Global Variables */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function Prototypes */
static int adis16266_read_register(uint8_t reg, uint16_t *value);
static int adis16266_write_register(uint8_t reg, uint16_t value);
static int adis16266_init(void);
static int adis16266_read_gyro_rate(float *rate);
static void log_data(float gyro_rate);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Read a 16-bit register from the ADIS16266 */
static int adis16266_read_register(uint8_t reg, uint16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Send read command: bit 7 = 1 */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Small delay to allow register to be read */
    gpioDelay(10);

    /* Send dummy command to read data */
    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Data is returned in the second byte */
    *value = (uint16_t)((rx_buf[1] << 8) | (rx_buf[0] & 0xFF));
    return 0;
}

/* Write a 16-bit value to a register on the ADIS16266 */
static int adis16266_write_register(uint8_t reg, uint16_t value) {
    char tx_buf[2];
    char rx_buf[2];

    /* Send write command: bit 7 = 0 */
    tx_buf[0] = (char)(reg & 0x7F);
    tx_buf[1] = (char)(value & 0xFF);

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "Error: SPI write transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Small delay to allow register to be written */
    gpioDelay(10);

    return 0;
}

/* Initialize the ADIS16266 */
static int adis16266_init(void) {
    uint16_t who_am_i = 0;

    /* Verify device identity */
    if (adis16266_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch. Expected 0x%04X, got 0x%04X\n",
                ADIS16266_WHO_AM_I_VAL, who_am_i);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* Set sample period to 10 ms (0x000A) */
    if (adis16266_write_register(ADIS16266_REG_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Error: Failed to set sample period\n");
        return -1;
    }

    /* Reset the device */
    if (adis16266_write_register(ADIS16266_REG_GLOB_CMD, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to reset device\n");
        return -1;
    }

    gpioDelay(10000); /* Wait 10 ms for reset to complete */

    return 0;
}

/* Read the gyroscope rate from the ADIS16266 */
static int adis16266_read_gyro_rate(float *rate) {
    uint16_t raw_rate = 0;

    if (adis16266_read_register(ADIS16266_REG_XGYRO_OUT, &raw_rate) != 0) {
        return -1;
    }

    /* Convert raw data to degrees per second (0.0305 deg/sec/LSB) */
    *rate = (float)raw_rate * 0.0305f;

    return 0;
}

/* Log the gyroscope data to a CSV file */
static void log_data(float gyro_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, gyro_rate);
    fflush(log_file);
}

int main(void) {
    float gyro_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, speed %d, flags 0x%02X)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADIS16266 */
    if (adis16266_init() != 0) {
        fprintf(stderr, "Error: ADIS16266 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Gyro Rate (deg/sec)\n");
        fflush(log_file);
    }

    /* Register signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Logging gyroscope data to gyro_log.csv. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        if (adis16266_read_gyro_rate(&gyro_rate) == 0) {
            log_data(gyro_rate);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope rate\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();

    return EXIT_SUCCESS;
}

