#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// L3G4200D I2C address
#define L3G4200D_ADDR 0x69

// L3G4200D registers
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Expected WHO_AM_I value
#define L3G4200D_WHO_AM_I 0xD3

// Sensitivity for +/- 250 dps range (mdps/LSB)
#define SENSITIVITY 8.75f

// I2C bus
#define I2C_BUS 1

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful termination
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to initialize the L3G4200D
int init_gyro() {
    int retries = 3;
    int result;

    while (retries > 0) {
        // Verify sensor identity
        result = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (result < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register (I2C error %d): %s\n", result, strerror(errno));
            retries--;
            gpioDelay(10000); // 10 ms delay before retry
            continue;
        }
        if (result != L3G4200D_WHO_AM_I) {
            fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", L3G4200D_WHO_AM_I, result);
            retries--;
            gpioDelay(10000);
            continue;
        }

        // Configure CTRL_REG1: Normal mode, all axes enabled
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (result < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1 (I2C error %d): %s\n", result, strerror(errno));
            retries--;
            gpioDelay(10000);
            continue;
        }

        // Configure CTRL_REG4: +/- 250 dps full-scale range
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4 (I2C error %d): %s\n", result, strerror(errno));
            retries--;
            gpioDelay(10000);
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize L3G4200D after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data = {0.0f, 0.0f, 0.0f};
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;
    int result;

    // Read 6 bytes of data starting from OUT_X_L
    result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data (I2C error %d): %s\n", result, strerror(errno));
        return data; // Return zeros on error
    }

    // Combine high and low bytes (little-endian)
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data.x = (float)raw_x / SENSITIVITY;
    data.y = (float)raw_y / SENSITIVITY;
    data.z = (float)raw_z / SENSITIVITY;

    return data;
}

// Function to log data to a file
void log_data(gyro_data_t data) {
    struct timespec ts;
    char timestamp[40];

    // Get current timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    // Write data to file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header to the log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Set up signal handling for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        gyro_data_t data = read_gyro_data();

        // Log data
        log_data(data);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10 ms
    }

    // Clean up resources
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

