#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for Ctrl+C (SIGINT) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Get current timestamp as a static string; caller must copy */
static const char *get_timestamp(void) {
    static char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        return timestamp;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

/* Log a message to the log file and flush immediately */
static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }
    fprintf(log_file, "%s - %s\n", get_timestamp(), message);
    fflush(log_file);
}

/* Read the flame sensor; returns 0 (flame detected), 1 (no flame), or -1 on error */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: Invalid GPIO pin %d.\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO17 as input with internal pull-up */
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);
    log_event("Monitoring started.");

    /* Main polling loop */
    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) {
            /* Flame detected (active-LOW) */
            printf("FLAME DETECTED!\n");
            log_event("Flame detected: YES");
        } else if (sensor_value == 1) {
            /* No flame */
            log_event("Flame detected: NO");
        } else {
            /* Error reading sensor */
            log_event("Error reading flame sensor.");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    log_event("Monitoring stopped.");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

