#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define ACCEL_REG_X_LSB 0x28
#define ACCEL_REG_X_MSB 0x29
#define ACCEL_REG_Y_LSB 0x2A
#define ACCEL_REG_Y_MSB 0x2B
#define ACCEL_REG_Z_LSB 0x2C
#define ACCEL_REG_Z_MSB 0x2D
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf;
    if (read(fd, &buf, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = buf;
    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, ACCEL_REG_X_LSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_X_MSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_Y_LSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_Y_MSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_Z_LSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, ACCEL_REG_Z_MSB, &zh) < 0) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);

    /* Sensor-absent heuristic: all registers 0xFF or 0x00 indicates no device */
    if (*x == 0x0000 && *y == 0x0000 && *z == 0x0000) {
        fprintf(stderr, "Warning: acceleration registers all zero — sensor may be absent\n");
        return -1;
    }
    if (*x == 0xFFFF && *y == 0xFFFF && *z == 0xFFFF) {
        fprintf(stderr, "Warning: acceleration registers all 0xFF — sensor may be absent\n");
        return -1;
    }

    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_info);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    fp = fopen("vibration_log.csv", "w");
    if (!fp) {
        fprintf(stderr, "Cannot open vibration_log.csv: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
        fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
        goto cleanup;
    }
    fflush(fp);

    printf("Vibration monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_acceleration(fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            usleep(10000); /* 10 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "Skipping sample due to persistent I2C errors\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
            fprintf(stderr, "Cannot write CSV row: %s\n", strerror(errno));
            goto cleanup;
        }
        fflush(fp);

        printf("%s  X=%6d  Y=%6d  Z=%6d\n", ts, x, y, z);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

