#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define METAL_THRESHOLD_MG 800.0f
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t whoami = 0;
    if (i2c_read_reg8(fd, WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I\n");
        return -1;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", whoami, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, CTRL_REG1, 0x70) != 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG2, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG3, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x0C) != 0) return -1;

    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) != 0) {
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * 0.146f;
    *y = (float)raw_y * 0.146f;
    *z = (float)raw_z * 0.146f;

    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void check_metal_detection(float x, float y, float z) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD_MG) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            break;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            fprintf(stderr, "Retrying LIS3MDL init (%d/%d)...\n", retries, MAX_RETRIES);
            usleep(100000);
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize LIS3MDL after %d retries.\n", MAX_RETRIES);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open magnetic_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LIS3MDL initialized. Logging to magnetic_log.txt at 10 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_metal_detection(x, y, z);
        } else {
            fprintf(stderr, "Failed to read magnetometer data.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

