#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_DEVID_AD   0x00
#define ADXL354B_REG_PARTID     0x01
#define ADXL354B_REG_XDATA_L    0x08
#define ADXL354B_REG_XDATA_H    0x09
#define ADXL354B_REG_YDATA_L    0x0B
#define ADXL354B_REG_YDATA_H    0x0C
#define ADXL354B_REG_ZDATA_L    0x0E
#define ADXL354B_REG_ZDATA_H    0x0F
#define ADXL354B_REG_STATUS     0x04
#define ADXL354B_REG_POWER_CTL  0x2D
#define ADXL354B_REG_RESET      0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// ADXL354B Constants
#define ADXL354B_PARTID_EXPECTED 0x1D
#define ADXL354B_SENSITIVITY 0.0000039f // 3.9 microg/LSB for +-2g range
#define ADXL354B_STATUS_STABLE 0x01

// Global Variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t reg, uint8_t *value);
int spi_write_register(uint8_t reg, uint8_t value);
int spi_read_burst(uint8_t reg, uint8_t *data, int len);
int read_acceleration(float *x, float *y, float *z);
int log_data(float x, float y, float z);
void signal_handler(int signal);
int initialize_adxl354b();
void cleanup();

// SPI Read Register Function
int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg | 0x80) & 0xBF; // Set read bit (bit 7) and clear multi-byte bit (bit 6)
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    *value = (uint8_t)rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg & 0x3F); // Clear read/multi-byte bits for write
    tx_buf[1] = value;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// SPI Burst Read Function
int spi_read_burst(uint8_t reg, uint8_t *data, int len) {
    char tx_buf[256];
    char rx_buf[256];

    if (len > 255) {
        fprintf(stderr, "Burst read length exceeds maximum\n");
        return -1;
    }

    tx_buf[0] = (reg | 0x80) | 0x40; // Set read bit (bit 7) and multi-byte bit (bit 6)
    memset(tx_buf + 1, 0x00, len);

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "SPI burst read error for register 0x%02X\n", reg);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Read Acceleration Data Function
int read_acceleration(float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (spi_read_burst(ADXL354B_REG_XDATA_L, data, 6) != 0) {
        return -1;
    }

    raw_x = (int16_t)((data[1] << 8) | data[0]);
    raw_y = (int16_t)((data[3] << 8) | data[2]);
    raw_z = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)raw_x * ADXL354B_SENSITIVITY;
    *y = (float)raw_y * ADXL354B_SENSITIVITY;
    *z = (float)raw_z * ADXL354B_SENSITIVITY;

    return 0;
}

// Log Data Function
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize ADXL354B Function
int initialize_adxl354b() {
    uint8_t partid;

    // Check sensor presence by reading PARTID
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != ADXL354B_PARTID_EXPECTED) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID_EXPECTED);
        return -1;
    }

    printf("ADXL354B detected (PARTID: 0x%02X)\n", partid);

    // Reset the device
    if (spi_write_register(ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms for reset to complete

    // Clear RUN bit in POWER_CTL to enter standby mode
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        return -1;
    }

    // Wait for the device to stabilize
    uint8_t status;
    int timeout = 100; // 100 * 10ms = 1 second timeout
    do {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) {
            fprintf(stderr, "Failed to read STATUS\n");
            return -1;
        }
        gpioDelay(10000); // 10 ms
        timeout--;
    } while ((status & ADXL354B_STATUS_STABLE) == 0 && timeout > 0);

    if (timeout == 0) {
        fprintf(stderr, "ADXL354B not stable after reset\n");
        return -1;
    }

    // Set RUN bit in POWER_CTL to start measurement
    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }

    return 0;
}

// Cleanup Function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    float x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (initialize_adxl354b() != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

