#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADIS16362 Register Addresses (from datasheet)
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

// Scaling factors (from datasheet)
#define GYRO_SCALE  0.05f   // deg/sec/LSB
#define ACCL_SCALE  0.0025f // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 // 1 MHz
#define SPI_FLAGS   0x03    // Mode 3: CPOL=1, CPHA=1

// Global variables for cleanup
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Function to read a 16-bit register from the ADIS16362
// Returns 0 on success, -1 on error
int read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Send the register address with MSB set (read command)
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00; // Dummy byte to clock out data

    // Transfer the data
    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error for register 0x%02X: %d\n", reg_addr, result);
        return -1;
    }

    // Combine the bytes to form the 16-bit data (MSB first)
    *data = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);

    return 0;
}

// Function to read IMU data from the ADIS16362
// Returns 0 on success, -1 on error
int read_imu_data(int handle, imu_data_t *data) {
