/*
 * KY-032 IR Obstacle Avoidance Sensor Reader (libgpiod v2)
 * Board:  Raspberry Pi 3 Model B+
 * Sensors: Keyes KY-032 x2 (active-low: 0 = obstacle, 1 = clear)
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (BCM 17, physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (BCM 27, physical pin 13)
 *   VCC -> 3.3 V, GND -> GND
 *
 * Build:  gcc -Wall -Wextra -O2 -o ky032_collision ky032_collision.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define SENSOR_1_OFFSET 17
#define SENSOR_2_OFFSET 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    unsigned int offsets[2] = { SENSOR_1_OFFSET, SENSOR_2_OFFSET };
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        perror("gpiod_line_settings_set_direction");
        goto cleanup;
    }

    /*
     * Request both lines in a single bulk request so that the kernel
     * can return both values in a single read.
     */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) < 0) {
        perror("gpiod_line_config_add_line_settings");
        goto cleanup;
    }

    /* --- Request config: consumer label --- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-collision");

    /* --- Request the lines --- */
    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("KY-032 collision avoidance system started.\n");
    printf("  Sensor 1: GPIO%u (BCM)\n", SENSOR_1_OFFSET);
    printf("  Sensor 2: GPIO%u (BCM)\n", SENSOR_2_OFFSET);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value values[2];
        int rc = gpiod_line_request_get_values(req, values);

        if (rc < 0) {
            perror("gpiod_line_request_get_values");
            break;
        }

        /*
         * KY-032 is active-low: 0 = obstacle detected, 1 = clear.
         * Log the inverse so that "1" means an obstacle is present.
         */
        log_timestamp();
        printf("Sensor 1: %d  Sensor 2: %d\n",
               values[0] == GPIOD_LINE_VALUE_INACTIVE ? 1 : 0,
               values[1] == GPIOD_LINE_VALUE_INACTIVE ? 1 : 0);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (req != NULL)
        gpiod_line_request_release(req);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

