            perror("gpiod_line_request_get_values");
            break;
        }

        /*
         * KY-032 is active-low: 0 = obstacle detected, 1 = clear.
         * Log the inverse so that "1" means an obstacle is present.
         */
        log_timestamp();
        printf("Sensor 1: %d  Sensor 2: %d\n",
               values[0] == GPIOD_LINE_VALUE_INACTIVE ? 1 : 0,
               values[1] == GPIOD_LINE_VALUE_INACTIVE ? 1 : 0);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (req != NULL)
        gpiod_line_request_release(req);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

