#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define CS_PIN 8 // GPIO8 (SPI0 CE0)

// Scale factor for ADIS16266 (deg/sec/LSB)
#define GYRO_SCALE 0.02f

// Global variables for cleanup
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int adis16266_init(void);
int adis16266_read_register(uint8_t reg, int16_t *value);
float convert_to_angular_rate(int16_t raw_data);
void cleanup(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

// Initialize SPI interface
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize GPIO for chip select
int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    // Request CS line as output, initially high (inactive)
    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        cs_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    return 0;
}

// Initialize ADIS16266 sensor
int adis16266_init(void) {
    // Enable data ready mode in MSC_CTRL register
    uint8_t reg = ADIS16266_MSC_CTRL;
    uint8_t value = 0x00; // Enable data ready mode (bit 0 = 1)
    uint8_t tx_buf[2] = {reg | 0x80, value}; // Write command: MSB set for write
    uint8_t rx_buf[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    // Assert CS
    gpiod_line_set_value(cs_line, 0);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Failed to write to MSC_CTRL register: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }

    // Deassert CS
    gpiod_line_set_value(cs_line, 1);

    usleep(10000); // Wait 10ms for initialization

    return 0;
}

// Read a 16-bit register from ADIS16266 using two-transfer read protocol
int adis16266_read_register(uint8_t reg, int16_t *value) {
    uint8_t tx_buf[2] = {reg | 0x80, 0x00}; // Write command: MSB set for read
    uint8_t rx_buf[2] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    // Assert CS
    gpiod_line_set_value(cs_line, 0);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %s\n", reg, strerror(errno));
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }

    // Deassert CS
    gpiod_line_set_value(cs_line, 1);

    // Small delay to allow data to be read
    usleep(10);

    // Read data from second transfer
    tx_buf[0] = 0x00; // Dummy byte to read data
    tx_buf[1] = 0x00;

    // Assert CS
    gpiod_line_set_value(cs_line, 0);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Failed to read data from register 0x%02X: %s\n", reg, strerror(errno));
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }

    // Deassert CS
    gpiod_line_set_value(cs_line, 1);

    // Combine bytes (MSB first)
    *value = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Convert raw data to angular rate (deg/sec)
float convert_to_angular_rate(int16_t raw_data) {
    return (float)raw_data * GYRO_SCALE;
}

int main(void) {
    // Register signal handler for graceful shutdown
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Initialize ADIS16266
    if (adis16266_init() < 0) {
        fprintf(stderr, "ADIS16266 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("ADIS16266 initialized successfully. Reading gyroscope data...\n");

    // Main loop
    while (keep_running) {
        int16_t raw_x, raw_y, raw_z;

        // Read X-axis gyroscope data
        if (adis16266_read_register(ADIS16266_XGYRO_OUT, &raw_x) < 0) {
            fprintf(stderr, "Error reading X-axis gyroscope data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Read Y-axis gyroscope data
        if (adis16266_read_register(ADIS16266_YGYRO_OUT, &raw_y) < 0) {
            fprintf(stderr, "Error reading Y-axis gyroscope data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Read Z-axis gyroscope data
        if (adis16266_read_register(ADIS16266_ZGYRO_OUT, &raw_z) < 0) {
            fprintf(stderr, "Error reading Z-axis gyroscope data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw data to angular rates
        float x_rate = convert_to_angular_rate(raw_x);
        float y_rate = convert_to_angular_rate(raw_y);
        float z_rate = convert_to_angular_rate(raw_z);

        // Print the angular rates to the console
        printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n", x_rate, y_rate, z_rate);

        // Delay for 100 milliseconds
        usleep(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Cleanup complete. Exiting.\n");

    return 0;
}

