#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* WHO_AM_I register and expected value */
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VAL 0x6B

/* CTRL1_XL: accelerometer ODR=104 Hz, FS=+-2g, anti-aliasing BW=408 Hz */
#define CTRL1_XL_VAL 0x42

/* CTRL2_G: gyroscope ODR=104 Hz, FS=+-250 dps */
#define CTRL2_G_VAL 0x42

/* Gyroscope sensitivity: 8.75 mdps/LSB at FS=250 dps */
#define GYRO_SENSITIVITY 0.00875f

/* Accelerometer sensitivity: 0.061 mg/LSB at FS=2g */
#define ACCEL_SENSITIVITY 0.000061f

/* First gyroscope data register (OUTX_L_G) */
#define OUTX_L_G_REG 0x22

/* Burst read length: 6 gyro bytes + 6 accel bytes = 12 bytes */
#define BURST_LEN 12

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: pigpio error %d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading I2C block from 0x%02X: pigpio error %d\n", reg, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "Short burst read: got %d of %u bytes\n", rc, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    int who = i2cReadByteData(handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: pigpio error %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(handle, CTRL1_XL, CTRL1_XL_VAL) < 0) return -1;
    if (i2c_write_reg(handle, CTRL2_G, CTRL2_G_VAL) < 0) return -1;

    return 0;
}

static void convert_data(const uint8_t *raw, float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az)
{
    int16_t rgx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t rgy = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rgz = (int16_t)((raw[5] << 8) | raw[4]);
    int16_t rax = (int16_t)((raw[7] << 8) | raw[6]);
    int16_t ray = (int16_t)((raw[9] << 8) | raw[8]);
    int16_t raz = (int16_t)((raw[11] << 8) | raw[10]);

    *gx = (float)rgx * GYRO_SENSITIVITY;
    *gy = (float)rgy * GYRO_SENSITIVITY;
    *gz = (float)rgz * GYRO_SENSITIVITY;
    *ax = (float)rax * ACCEL_SENSITIVITY;
    *ay = (float)ray * ACCEL_SENSITIVITY;
    *az = (float)raz * ACCEL_SENSITIVITY;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: pigpio error %d\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t raw[BURST_LEN];
    float gx, gy, gz, ax, ay, az;

    while (g_running) {
        if (i2c_read_burst(g_i2c_handle, OUTX_L_G_REG, raw, BURST_LEN) < 0) {
            fprintf(stderr, "Read error; continuing after delay\n");
            gpioDelay(100000);
            continue;
        }

        convert_data(raw, &gx, &gy, &gz, &ax, &ay, &az);
        printf("Gyro: X=%.3f Y=%.3f Z=%.3f dps | Accel: X=%.3f Y=%.3f Z=%.3f g\n",
               gx, gy, gz, ax, ay, az);
        fflush(stdout);

        gpioDelay(100000); /* 100 ms */
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

