#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_SCALE_FACTOR 0.0039
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int init_adxl345(int fd) {
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to power on ADXL345\n");
        return -1;
    }
    return 0;
}

int read_accelerometer_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, ADXL345_DATAX0, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ADXL345_SCALE_FACTOR;
    *y = (float)raw_y * ADXL345_SCALE_FACTOR;
    *z = (float)raw_z * ADXL345_SCALE_FACTOR;
    return 0;
}

float calculate_tilt_angle(float x, float y, float z) {
    float roll = atan2(y, z) * 180.0 / M_PI;
    float pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;
    return sqrt(roll * roll + pitch * pitch);
}

void log_tilt_event(float tilt_angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt angle exceeded threshold: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_adxl345(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed. Check wiring and address.\n");
        close(i2c_fd);
        return 1;
    }

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            float tilt_angle = calculate_tilt_angle(x, y, z);
            if (tilt_angle > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }
        usleep(100000);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Exiting.\n");
    return 0;
}

