#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define WINDOW_DURATION_S 5
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown time] ");
    }
}

int main(int argc, char *argv[])
{
    int threshold;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  <threshold> must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (sscanf(argv[1], "%d", &threshold) != 1) {
        fprintf(stderr, "Error: '%s' is not a valid integer.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as input */
    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring noise levels on GPIO%d (threshold: %d high readings per %d s)...\n",
           SOUND_SENSOR_GPIO, threshold, WINDOW_DURATION_S);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int high_count = 0;
        int elapsed = 0;

        /* Sample for the entire 5-second window */
        while (program_running && elapsed < WINDOW_DURATION_S) {
            int level = gpioRead(SOUND_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n",
                        SOUND_SENSOR_GPIO);
                gpioTerminate();
                return EXIT_FAILURE;
            }

            if (level == 1) {
                high_count++;
            }

            gpioDelay(SAMPLE_INTERVAL_US);
            elapsed++;
        }

        if (!program_running) {
            break;
        }

        print_timestamp();

        if (high_count > threshold) {
            printf("ALERT: Noise level exceeded threshold (%d/%d high readings).\n",
                   high_count, WINDOW_DURATION_S);
        } else {
            printf("Status: Noise level normal (%d/%d high readings).\n",
                   high_count, WINDOW_DURATION_S);
        }
        fflush(stdout);

        /* Wait 1 second before the next monitoring window */
        if (program_running) {
            gpioDelay(POLL_INTERVAL_S * 1000000);
        }
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

