#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define UNLOCK_DURATION_SEC 5
#define CODE_LENGTH 6
#define MAX_CODE_VALUE 999999
#define MIN_CODE_VALUE 100000
#define LOG_FILE "access_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int generate_random_code(void) {
    return (rand() % (MAX_CODE_VALUE - MIN_CODE_VALUE + 1)) + MIN_CODE_VALUE;
}

static int log_access(int code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int unlock_door(struct gpiod_line *line, int duration_sec) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error unlocking door (GPIO%d): %s\n", gpiod_line_offset(line), strerror(errno));
        return -1;
    }

    sleep(duration_sec);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error locking door (GPIO%d): %s\n", gpiod_line_offset(line), strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *door_a_line = NULL;
    struct gpiod_line *door_b_line = NULL;
    int code = 0;
    char input_buffer[256];
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    code = generate_random_code();
    printf("Door access code: %d\n", code);

    while (program_running) {
        printf("Enter code: ");
        fflush(stdout);

        if (!fgets(input_buffer, sizeof(input_buffer), stdin)) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            fprintf(stderr, "Error reading input: %s\n", strerror(errno));
            continue;
        }

        input_buffer[strcspn(input_buffer, "\n")] = '\0';

        char *endptr = NULL;
        long entered_code = strtol(input_buffer, &endptr, 10);

        if (*endptr != '\0' || entered_code < MIN_CODE_VALUE || entered_code > MAX_CODE_VALUE) {
            fprintf(stderr, "Invalid code. Please enter a %d-digit number between %d and %d.\n",
                    CODE_LENGTH, MIN_CODE_VALUE, MAX_CODE_VALUE);
            continue;
        }

        if (entered_code == code) {
            printf("Access granted. Unlocking Door A for %d seconds...\n", UNLOCK_DURATION_SEC);
            if (unlock_door(door_a_line, UNLOCK_DURATION_SEC) < 0) {
                fprintf(stderr, "Error unlocking Door A.\n");
            } else {
                if (log_access(code) < 0) {
                    fprintf(stderr, "Error logging access.\n");
                } else {
                    printf("Access logged.\n");
                }
                code = generate_random_code();
                printf("Door access code: %d\n", code);
            }
        } else {
            printf("Access denied.\n");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (door_a_line) {
        gpiod_line_set_value(door_a_line, 0);
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_set_value(door_b_line, 0);
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

