#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE2 0x21
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_DELAY_MS 180
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int read_bh1750(int fd, float *lux) {
    uint8_t cmd = BH1750_ONE_TIME_HIGH_RES_MODE2;
    uint8_t buf[2];

    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main() {
    int fd = -1;
    float lux;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting up signal handler");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return 1;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_bh1750(fd, &lux) == 0) {
            if (log_data(LOG_FILE, lux) == 0) {
                printf("Lux: %.2f\n", lux);
            } else {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

