#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define LSM303DLHC_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_PERIOD_NS 10000000
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "magnetometer_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg address error (0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error (reg 0x%02X, len %zu): %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        return -1;
    }
    return 0;
}

int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrtf((float)(x * x + y * y + z * z));
}

int set_led_brightness(struct gpiod_line *line, float magnitude) {
    int duty_cycle = (int)(magnitude * PWM_PERIOD_NS / 100.0f);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_PERIOD_NS) duty_cycle = PWM_PERIOD_NS;
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
        return -1;
    }
    usleep(duty_cycle / 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
        return -1;
    }
    usleep((PWM_PERIOD_NS - duty_cycle) / 1000);
    return 0;
}

void log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float magnitude) {
    if (fp) {
        fprintf(fp, "%d,%d,%d,%.2f\n", x, y, z, magnitude);
        fflush(fp);
    }
}

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303DLHC_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_magnetometer(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_GPIO, strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Magnetometer LED control started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (set_led_brightness(led_line, magnitude) < 0) {
                fprintf(stderr, "PWM error\n");
            }
            log_data(log_file, x, y, z, magnitude);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

