#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define CONFIG_A_REG 0x00
#define CONFIG_B_REG 0x01
#define MODE_REG 0x02
#define DATA_X_MSB_REG 0x03
#define DATA_X_LSB_REG 0x04
#define DATA_Z_MSB_REG 0x05
#define DATA_Z_LSB_REG 0x06
#define DATA_Y_MSB_REG 0x07
#define DATA_Y_LSB_REG 0x08

#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_hmc5883l(int handle) {
    if (i2cWriteByteData(handle, CONFIG_A_REG, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A_REG\n");
        return -1;
    }
    if (i2cWriteByteData(handle, CONFIG_B_REG, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B_REG\n");
        return -1;
    }
    if (i2cWriteByteData(handle, MODE_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE_REG\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, DATA_X_MSB_REG, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

static void calculate_offsets(int16_t x, int16_t y, int16_t z,
                              double *x_offset, double *y_offset, double *z_offset) {
    static double x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;
    static int sample_count = 0;

    x_sum -= x_sum / NUM_SAMPLES;
    y_sum -= y_sum / NUM_SAMPLES;
    z_sum -= z_sum / NUM_SAMPLES;

    x_sum += (double)x;
    y_sum += (double)y;
    z_sum += (double)z;

    sample_count++;
    if (sample_count >= NUM_SAMPLES) {
        *x_offset = x_sum / NUM_SAMPLES;
        *y_offset = y_sum / NUM_SAMPLES;
        *z_offset = z_sum / NUM_SAMPLES;
        sample_count = 0;
    }
}

static void apply_offsets(int16_t x, int16_t y, int16_t z,
                          double x_offset, double y_offset, double z_offset,
                          double *x_corrected, double *y_corrected, double *z_corrected) {
    *x_corrected = (double)x - x_offset;
    *y_corrected = (double)y - y_offset;
    *z_corrected = (double)z - z_offset;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double x_offset = 0.0, y_offset = 0.0, z_offset = 0.0;
    int16_t x, y, z;
    double x_corrected, y_corrected, z_corrected;

    while (running) {
        if (read_magnetometer(i2c_handle, &x, &y, &z) == 0) {
            calculate_offsets(x, y, z, &x_offset, &y_offset, &z_offset);
            apply_offsets(x, y, z, x_offset, y_offset, z_offset,
                          &x_corrected, &y_corrected, &z_corrected);
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", x_corrected, y_corrected, z_corrected);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

