/*
 * LSM303D accelerometer monitor with GPIO interrupt dump.
 *
 * Board:  Raspberry Pi Zero W
 * I2C:    /dev/i2c-1, LSM303D SA0 tied high -> address 0x1D
 * INT1:   GPIO23 (BCM 23, physical pin 16)
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49

#define CTRL_REG1_A         0x20
#define CTRL_REG4_A         0x23
#define INT1_CFG            0x30
#define INT1_THS            0x32
#define INT1_DURATION       0x33
#define OUT_X_L_A           0x28

/* CTRL_REG1_A: 50 Hz ODR, all axes enabled */
#define CTRL_REG1_A_VAL     0x57
/* CTRL_REG4_A: full-scale +-2g, no high-resolution, no self-test */
#define CTRL_REG4_A_VAL     0x00
/* INT1_CFG: any-axis high event, push-pull, active-high */
#define INT1_CFG_VAL        0x2A
/* INT1_THS: 2000 mg / 16 mg/LSB = 125 */
#define INT1_THS_VAL        0x7D
/* INT1_DURATION: 0 -> immediate */
#define INT1_DURATION_VAL   0x00

/* ---- GPIO / timing ---- */
#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    23          /* BCM 23 */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000       /* 10 ms */
#define DUMP_COUNT          10

/* ---- Data structure ---- */
typedef struct {
    int16_t x, y, z;
} accel_data_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ---- Circular buffer ---- */
static accel_data_t g_buffer[BUFFER_SIZE];
static int          g_buf_head = 0;
static int          g_buf_count = 0;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len)
{
    /* LSM303D auto-increments when MSB of register address is set */
    if (i2c_smbus_read_i2c_block_data(fd, reg | 0x80, len, buf) < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D init ---- */
static int lsm303d_init(int fd)
{
    uint8_t who;
    if (i2c_read_byte(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(fd, CTRL_REG1_A, CTRL_REG1_A_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, CTRL_REG4_A, CTRL_REG4_A_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, INT1_CFG, INT1_CFG_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, INT1_THS, INT1_THS_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, INT1_DURATION, INT1_DURATION_VAL) < 0)
        return -1;

    return 0;
}

/* ---- GPIO setup ---- */
static int gpio_setup(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Failed to request rising-edge events on GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_line) {
        /* Disable accelerometer before releasing line */
        if (g_i2c_fd >= 0)
            (void)i2c_write_byte(g_i2c_fd, CTRL_REG1_A, 0x00);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Circular buffer ---- */
static void buffer_add(accel_data_t d)
{
    g_buffer[g_buf_head] = d;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static void buffer_dump(void)
{
    int start = (g_buf_count < BUFFER_SIZE) ? 0 : g_buf_head;
    int count = g_buf_count;

    printf("\n--- Last %d acceleration samples ---\n", count);
    for (int i = 0; i < count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] X=%6d  Y=%6d  Z=%6d\n",
               i, g_buffer[idx].x, g_buffer[idx].y, g_buffer[idx].z);
    }
    printf("-----------------------------------\n");
    fflush(stdout);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpio_setup() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303D monitor started.  INT1=GPIO23 (rising edge).  Ctrl-C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        uint8_t raw[6];
        if (i2c_read_block(g_i2c_fd, OUT_X_L_A, raw, sizeof(raw)) < 0) {
            /* Skip this sample; do not corrupt the buffer */
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        accel_data_t d;
        d.x = (int16_t)((raw[1] << 8) | raw[0]);
        d.y = (int16_t)((raw[3] << 8) | raw[2]);
        d.z = (int16_t)((raw[5] << 8) | raw[4]);

        buffer_add(d);

        /* Check for GPIO event */
        struct timespec ts = { 0, 1000000 }; /* 1 ms poll */
        int ev = gpiod_line_event_wait(g_line, &ts);
        if (ev < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            continue;
        }
        if (ev == 1) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(g_line, &event) < 0) {
                fprintf(stderr, "GPIO event read error: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                time_t now = time(NULL);
                struct tm tm_info;
                char ts_str[32];
                localtime_r(&now, &tm_info);
                strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("\n--- INT1 rising edge at %s ---\n", ts_str);
                buffer_dump();
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

