#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define SOLENOID1_PIN 17
#define SOLENOID2_PIN 27
#define CHIP_NAME    "gpiochip0"
#define CONSUMER     "solenoid-actuator"
#define DELAY_MS     500

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts;
    ts.tv_sec  = ms / 1000;
    ts.tv_nsec = (long)(ms % 1000) * 1000000L;
    while (nanosleep(&ts, &ts) == -1) {
        if (errno != EINTR) {
            perror("nanosleep");
            break;
        }
        if (!g_running)
            break;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, SOLENOID1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(SOLENOID1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SOLENOID2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(SOLENOID2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(SOLENOID1_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(SOLENOID2_PIN)");
        goto cleanup;
    }

    printf("Solenoid actuator started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(SOLENOID1_PIN, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(SOLENOID2_PIN, 0)");
            goto cleanup;
        }
        sleep_ms(DELAY_MS);
        if (!g_running)
            break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(SOLENOID1_PIN, 0)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(SOLENOID2_PIN, 1)");
            goto cleanup;
        }
        sleep_ms(DELAY_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1)
        gpiod_line_set_value(line1, 0);
    if (line2)
        gpiod_line_set_value(line2, 0);
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nSolenoid actuator stopped.\n");

    return ret;
}

