#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define UART_PORT_1 "/dev/serial0"
#define UART_PORT_2 "/dev/serial1"
#define BAUD_RATE 9600
#define POLL_TIMEOUT_MS 5000
#define UNLOCK_DURATION_MS 2000

static volatile sig_atomic_t program_running = 1;
static int uart_handle_1 = -1;
static int uart_handle_2 = -1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LOCK_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LOCK_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LOCK_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LOCK_2_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LOCK_1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW.\n", LOCK_1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LOCK_2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO %d to LOW.\n", LOCK_2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int initialize_uart(const char *port, int baud_rate) {
    int handle = serOpen(port, baud_rate, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open UART port %s: %s\n", port, strerror(errno));
        return -1;
    }
    return handle;
}

static int read_code_from_uart(int uart_handle, char *code, int code_length) {
    int bytes_read = 0;
    int timeout_ms = 0;
    int byte;

    while (bytes_read < code_length && program_running) {
        byte = serReadByte(uart_handle);

        if (byte >= 0) {
            if (byte >= '0' && byte <= '9') {
                code[bytes_read++] = (char)byte;
                timeout_ms = 0;
            } else {
                fprintf(stderr, "Warning: Invalid character received (0x%02X), resetting input.\n", byte);
                bytes_read = 0;
            }
        } else {
            if (byte == PI_SER_READ_NO_DATA) {
                gpioDelay(1000);
                timeout_ms += 1;
                if (timeout_ms >= POLL_TIMEOUT_MS) {
                    fprintf(stderr, "Error: Timeout reading code from UART.\n");
                    return -1;
                }
            } else {
                fprintf(stderr, "Error: serReadByte failed: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    if (bytes_read < code_length) {
        fprintf(stderr, "Error: Code incomplete (received %d of %d digits).\n", bytes_read, code_length);
        return -1;
    }

    code[code_length] = '\0';
    return 0;
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK_1_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to unlock lock 1 (GPIO %d).\n", LOCK_1_GPIO);
        return -1;
    }

    if (gpioWrite(LOCK_2_GPIO, 1) != 0) {
        fprintf(stderr, "Error: Failed to unlock lock 2 (GPIO %d).\n", LOCK_2_GPIO);
        gpioWrite(LOCK_1_GPIO, 0);
        return -1;
    }

    printf("Doors unlocked.\n");
    return 0;
}

static int lock_doors(void) {
    if (gpioWrite(LOCK_1_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to lock lock 1 (GPIO %d).\n", LOCK_1_GPIO);
        return -1;
    }

    if (gpioWrite(LOCK_2_GPIO, 0) != 0) {
        fprintf(stderr, "Error: Failed to lock lock 2 (GPIO %d).\n", LOCK_2_GPIO);
        return -1;
    }

    printf("Doors locked.\n");
    return 0;
}

static int constant_time_string_compare(const char *str1, const char *str2, int length) {
    int result = 0;
    for (int i = 0; i < length; i++) {
        result |= (str1[i] ^ str2[i]);
    }
    return result;
}

static void cleanup(void) {
    if (uart_handle_1 >= 0) {
        serClose(uart_handle_1);
        uart_handle_1 = -1;
    }
    if (uart_handle_2 >= 0) {
        serClose(uart_handle_2);
        uart_handle_2 = -1;
    }
    gpioWrite(LOCK_1_GPIO, 0);
    gpioWrite(LOCK_2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    uart_handle_1 = initialize_uart(UART_PORT_1, BAUD_RATE);
    if (uart_handle_1 < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uart_handle_2 = initialize_uart(UART_PORT_2, BAUD_RATE);
    if (uart_handle_2 < 0) {
        serClose(uart_handle_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Dual-factor authentication system started. Waiting for codes...\n");

    while (program_running) {
        if (read_code_from_uart(uart_handle_1, code1, CODE_LENGTH) == 0) {
            printf("Code received from UART 1: %s\n", code1);
        } else {
            fprintf(stderr, "Error reading code from UART 1.\n");
        }

        if (read_code_from_uart(uart_handle_2, code2, CODE_LENGTH) == 0) {
            printf("Code received from UART 2: %s\n", code2);
        } else {
            fprintf(stderr, "Error reading code from UART 2.\n");
        }

        if (constant_time_string_compare(code1, code2, CODE_LENGTH) == 0 &&
            constant_time_string_compare(code1, EXPECTED_CODE, CODE_LENGTH) == 0) {
            printf("Codes match. Unlocking doors.\n");
            if (unlock_doors() == 0) {
                gpioDelay(UNLOCK_DURATION_MS * 1000);
                if (lock_doors() != 0) {
                    fprintf(stderr, "Error locking doors after unlock.\n");
                }
            } else {
                fprintf(stderr, "Error unlocking doors.\n");
            }
        } else {
            printf("Codes do not match or do not match expected code. Doors remain locked.\n");
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

