#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define MOTION_TIMEOUT_SEC 10
#define CONSUMER "door_strike"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog(CONSUMER, LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, CONSUMER) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d as input: %s", PIR_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, CONSUMER, 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d as output: %s", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike system started.");

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            sleep_ms(POLL_INTERVAL_MS);
            continue;
        }

        if (pir_value == 1) {
            log_event(LOG_INFO, "Motion detected!");

            if (gpiod_line_set_value(relay_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to energize relay: %s", strerror(errno));
            } else {
                log_event(LOG_INFO, "Relay energized (door strike activated).");
            }

            sleep_ms(STRIKE_DURATION_MS);

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s", strerror(errno));
            } else {
                log_event(LOG_INFO, "Relay de-energized.");
            }

            time_t start_time = time(NULL);
            while (program_running) {
                int pir_value = gpiod_line_get_value(pir_line);
                if (pir_value < 0) {
                    syslog(LOG_ERR, "Failed to read PIR sensor during failsafe check: %s", strerror(errno));
                    break;
                }
                if (pir_value == 0) {
                    break;
                }
                if (difftime(time(NULL), start_time) > MOTION_TIMEOUT_SEC) {
                    syslog(LOG_WARNING, "Potential malfunction: PIR sensor active for more than %d seconds.", MOTION_TIMEOUT_SEC);
                    if (gpiod_line_set_value(relay_line, 0) < 0) {
                        syslog(LOG_ERR, "Failed to de-energize relay during failsafe: %s", strerror(errno));
                    }
                    break;
                }
                sleep_ms(POLL_INTERVAL_MS);
            }
        }

        sleep_ms(POLL_INTERVAL_MS);
    }

    log_event(LOG_INFO, "Shutting down door strike system.");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
    return ret;
}

