#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_TIME_SEC 300
#define RELAY_PAUSE_TIME_SEC 60
#define TIMER_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static const int relay_gpios[] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};
static const int num_relays = sizeof(relay_gpios) / sizeof(relay_gpios[0]);

static int current_relay_index = 0;
static int current_relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int gpio, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    syslog(LOG_INFO, "%s - Relay on GPIO %d %s", timestamp, gpio, state ? "activated" : "deactivated");
}

static int activate_relay(int gpio) {
    if (gpioWrite(gpio, 0) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", gpio);
        return -1;
    }
    log_relay_state(gpio, 1);
    return 0;
}

static int deactivate_relay(int gpio) {
    if (gpioWrite(gpio, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", gpio);
        return -1;
    }
    log_relay_state(gpio, 0);
    return 0;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    static int timer_state = 0;
    static int timer_count = 0;

    if (!running) return;

    switch (timer_state) {
        case 0:
            if (activate_relay(relay_gpios[current_relay_index]) == 0) {
                current_relay_state = 1;
                timer_state = 1;
                timer_count = 0;
            }
            break;
        case 1:
            timer_count++;
            if (timer_count >= RELAY_ON_TIME_SEC / TIMER_INTERVAL_SEC) {
                if (deactivate_relay(relay_gpios[current_relay_index]) == 0) {
                    current_relay_state = 0;
                    timer_state = 2;
                    timer_count = 0;
                }
            }
            break;
        case 2:
            timer_count++;
            if (timer_count >= RELAY_PAUSE_TIME_SEC / TIMER_INTERVAL_SEC) {
                current_relay_index = (current_relay_index + 1) % num_relays;
                timer_state = 0;
                timer_count = 0;
            }
            break;
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        return -1;
    }

    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            syslog(LOG_ERR, "Failed to set GPIO %d as output", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_gpios[i], 1) != 0) {
            syslog(LOG_ERR, "Failed to initialize GPIO %d to HIGH", relay_gpios[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relay_gpios[i], 1);
    }
    gpioTerminate();
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC * 1000, timer_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set timer function");
        cleanup_gpio();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Irrigation system started");

    while (running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down irrigation system");
    cleanup_gpio();
    closelog();
    return 0;
}

