#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

#define ACCEL_SCALE 16384.0f
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 10000000L

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sysfs_fd = -1;
static struct sigevent sev;
static timer_t timer_id;

typedef struct {
    float x, y, z;
} accel_data_t;

static accel_data_t accel_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)x / ACCEL_SCALE;
    data->y = (float)y / ACCEL_SCALE;
    data->z = (float)z / ACCEL_SCALE;
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    accel_data_t data;
    if (read_accel_data(i2c_fd, &data) == 0) {
        accel_buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    }
}

static int create_sysfs_interface(void) {
    sysfs_fd = open("/sys/kernel/mpu6050_accel", O_RDWR | O_CREAT, 0666);
    if (sysfs_fd < 0) {
        fprintf(stderr, "Failed to create sysfs directory: %s\n", strerror(errno));
        return -1;
    }
    if (write(sysfs_fd, "latest", 6) != 6) {
        fprintf(stderr, "Failed to write sysfs file: %s\n", strerror(errno));
        close(sysfs_fd);
        sysfs_fd = -1;
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (timer_id != 0) {
        timer_delete(timer_id);
        timer_id = 0;
    }
    if (sysfs_fd >= 0) {
        close(sysfs_fd);
        sysfs_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        cleanup();
        return 1;
    }

    if (create_sysfs_interface() < 0) {
        cleanup();
        return 1;
    }

    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_id) < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        pause();
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

