#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"

// BCM GPIO pins for the relays
const int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};

// Prime numbers for the toggle intervals (seconds)
const int toggle_intervals[NUM_RELAYS] = {2, 3, 5, 7};

// Global variables for cleanup
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void toggle_relay(int relay_index);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    keep_running = 0;
}

// Initialize GPIO using libgpiod
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Request each GPIO line as output, initially low
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            cleanup_gpio();
            return -1;
        }

        ret = gpiod_line_request_output(lines[i], "smart-lighting", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", relay_pins[i]);
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    // Turn off all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

// Toggle the relay state for a given relay index
void toggle_relay(int relay_index) {
    int current_value;
    int new_value;

    if (relay_index < 0 || relay_index >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay index: %d\n", relay_index);
        return;
    }

    current_value = gpiod_line_get_value(lines[relay_index]);
    if (current_value < 0) {
        perror("Failed to read GPIO value");
        return;
    }

    new_value = !current_value;

    if (gpiod_line_set_value(lines[relay_index], new_value) < 0) {
        perror("Failed to set GPIO value");
        return;
    }

    printf("Relay %d toggled to %s\n", relay_index + 1, new_value ? "ON" : "OFF");
}

int main(void) {
    struct timespec start_time, current_time;
    int relay_states[NUM_RELAYS] = {0}; // 0 = OFF, 1 = ON
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Get initial time
    ret = clock_gettime(CLOCK_MONOTONIC, &start_time);
    if (ret < 0) {
        perror("Failed to get initial time");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Get current time
        ret = clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (ret < 0) {
            perror("Failed to get current time");
            break;
        }

        // Calculate elapsed time in seconds
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) +
                              (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        // Check if each relay's interval has passed
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (elapsed_time >= toggle_intervals[i]) {
                toggle_relay(i);
                relay_states[i] = !relay_states[i];
                start_time = current_time; // Reset the timer
            }
        }

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();
    printf("Smart lighting system stopped.\n");

    return EXIT_SUCCESS;
}

