#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Expected WHO_AM_I value for MPU-6050
#define MPU6050_WHO_AM_I 0x68

// Gyroscope sensitivity for default +-250 dps range
#define GYRO_SENSITIVITY 131.0

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
float calculate_angular_velocity(gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup(void);

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050(void) {
    uint8_t who_am_i;
    uint8_t write_data;

    // Verify device identity
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I, who_am_i);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit in PWR_MGMT_1)
    write_data = 0x00;
    if (write(i2c_fd, &write_data, 1) != 1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register: %s\n", strerror(errno));
        return -1;
    }

    // Allow time for the sensor to stabilize
    usleep(100000); // 100 ms

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(gyro_data_t *data) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buffer[6];

    // Write register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (big-endian)
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw data to degrees/second
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;

    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Get data from the circular buffer
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    if (index < 0 || index >= buffer->count) {
        gyro_data_t error_data = {0.0, 0.0, 0.0};
        return error_data;
    }

    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    return buffer->data[actual_index];
}

// Calculate the angular velocity magnitude
float calculate_angular_velocity(gyro_data_t data) {
