#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE    "/dev/serial0"
#define BAUD_RATE      9600
#define READ_INTERVAL  5
#define READ_TIMEOUT   1
#define LOG_FILE       "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_log_file    = NULL;
static FILE *g_err_file    = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg)
{
    if (!g_err_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_err_file, "%s: %s\n", ts, msg);
    fflush(g_err_file);
}

static int init_uart(void)
{
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        log_error("Failed to open UART device");
        return -1;
    }
    return 0;
}

static int read_co2(int *co2_ppm)
{
    unsigned char cmd[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char resp[9];
    int total = 0;
    int elapsed = 0;

    if (serWrite(g_uart_handle, (char *)cmd, sizeof(cmd)) != (int)sizeof(cmd)) {
        log_error("Failed to write MH-Z19B read command");
        return -1;
    }

    gpioDelay(100000); /* 100 ms */

    while (total < 9 && elapsed < READ_TIMEOUT * 1000000) {
        int avail = serDataAvailable(g_uart_handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail > 0) {
            int n = serRead(g_uart_handle, (char *)(resp + total), avail);
            if (n < 0) {
                log_error("serRead failed");
                return -1;
            }
            total += n;
        }
        gpioDelay(10000); /* 10 ms */
        elapsed += 10000;
    }

    if (total != 9) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Incomplete read: got %d of 9 bytes", total);
        log_error(buf);
        return -1;
    }

    /* Validate checksum: sum bytes 1-7, invert, increment by 1 */
    unsigned char calc = 0xFF - (unsigned char)(resp[1] + resp[2] + resp[3] + resp[4] + resp[5] + resp[6]) + 1;
    if (calc != resp[8]) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Checksum mismatch: calc=0x%02X recv=0x%02X", calc, resp[8]);
        log_error(buf);
        return -1;
    }

    *co2_ppm = (resp[2] << 8) | resp[3];
    return 0;
}

static void log_data(int co2_ppm, int error)
{
    if (!g_log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long us = (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
    fprintf(g_log_file, "{\"timestamp\": %lld, \"co2_ppm\": %d, \"error\": %d}\n",
            (long long)us, co2_ppm, error);
    fflush(g_log_file);
}

static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_err_file) {
        fclose(g_err_file);
        g_err_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_err_file = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_file) {
        perror("fopen error log");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_uart() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int co2_ppm = 0;
        int rc = read_co2(&co2_ppm);
        log_data(co2_ppm, rc != 0);

        if (rc == 0) {
            printf("{\"timestamp\": %lld, \"co2_ppm\": %d, \"error\": 0}\n",
                   (long long)(time(NULL) * 1000000LL), co2_ppm);
        } else {
            printf("{\"timestamp\": %lld, \"co2_ppm\": -1, \"error\": 1}\n",
                   (long long)(time(NULL) * 1000000LL));
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

