#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_X_MSB 0x03
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100
#define SAMPLE_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) {
        heading += 360.0f;
    }
    return heading;
}

static float compensate_heading(float heading, float x_offset, float y_offset) {
    return heading + x_offset + y_offset;
}

static void control_gpio(float compensated_heading, float target_heading, int gpio_pin) {
    float deviation = fabsf(compensated_heading - target_heading);
    if (deviation > 180.0f) {
        deviation = 360.0f - deviation;
    }
    if (deviation > HEADING_THRESHOLD) {
        gpioWrite(gpio_pin, 1);
    } else {
        gpioWrite(gpio_pin, 0);
    }
}

static void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() != 0) {
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    heading_buffer.head = 0;
    heading_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t x, y, z;
    float heading, compensated_heading;

    while (!terminate) {
        if (read_magnetometer(&x, &y, &z) == 0) {
            heading = calculate_heading(x, y);
            compensated_heading = compensate_heading(heading, 100.0f, -50.0f);
            control_gpio(compensated_heading, TARGET_HEADING, GPIO_PIN);
            add_to_buffer(&heading_buffer, compensated_heading);
            printf("Heading: %.2f, Compensated: %.2f\n", heading, compensated_heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data, retrying...\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

