#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22
#define I2C_BUS    "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LOG_FILE   "lighting_log.txt"
#define CONSUMER   "smart_lighting"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (red_line) {
        gpiod_line_set_value(red_line, 0);
        gpiod_line_release(red_line);
        red_line = NULL;
    }
    if (green_line) {
        gpiod_line_set_value(green_line, 0);
        gpiod_line_release(green_line);
        green_line = NULL;
    }
    if (blue_line) {
        gpiod_line_set_value(blue_line, 0);
        gpiod_line_release(blue_line);
        blue_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(red_line, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(green_line, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(blue_line, CONSUMER, 0) < 0) {
        perror("Failed to request GPIO lines as output");
        cleanup();
        return -1;
    }

    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t cmd = 0x10;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Failed to configure BH1750");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    usleep(180000);
    return 0;
}

static int read_bh1750(float *lux) {
    uint8_t buf[2];
    ssize_t bytes = read(i2c_fd, buf, 2);
    if (bytes != 2) {
        if (bytes < 0) {
            perror("I2C read error");
        } else {
            fprintf(stderr, "I2C read incomplete: %zd bytes\n", bytes);
        }
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void set_relays(float lux) {
    int r = 0, g = 0, b = 0;
    if (lux < 50.0f) {
        r = 1;
    } else if (lux < 150.0f) {
        g = 1;
    } else if (lux < 300.0f) {
        b = 1;
    } else {
        r = g = b = 1;
    }

    gpiod_line_set_value(red_line, r);
    gpiod_line_set_value(green_line, g);
    gpiod_line_set_value(blue_line, b);
}

static void log_data(float lux, int r, int g, int b) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_fp, "%s, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n",
            ts, lux, r, g, b);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Sensor read failed, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        set_relays(lux);
        int r = gpiod_line_get_value(red_line);
        int g = gpiod_line_get_value(green_line);
        int b = gpiod_line_get_value(blue_line);

        log_data(lux, r, g, b);
        printf("Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n", lux, r, g, b);

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

