#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_gpio_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_gpio_pwm(unsigned gpio, unsigned duty) {
    if (gpioPWM(gpio, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", gpio, duty);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pwm_frequency(unsigned gpio, unsigned freq) {
    if (gpioSetPWMfrequency(gpio, freq) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", gpio, freq);
        return -1;
    }
    return 0;
}

static int safe_gpio_set_pwm_range(unsigned gpio, unsigned range) {
    if (gpioSetPWMrange(gpio, range) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", gpio, range);
        return -1;
    }
    return 0;
}

static int motor_a_forward(int distance) {
    int duty = 255 - (int)(((float)(distance - 10) / 90.0f) * 255.0f);
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;

    if (safe_gpio_write(MOTOR_A_IN1, 1) != 0) return -1;
    if (safe_gpio_write(MOTOR_A_IN2, 0) != 0) return -1;
    if (safe_gpio_pwm(MOTOR_A_IN2, duty) != 0) return -1;
    return 0;
}

static int motor_a_backward(int distance) {
    int duty = (int)(((float)(distance - 10) / 90.0f) * 255.0f);
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;

    if (safe_gpio_write(MOTOR_A_IN1, 0) != 0) return -1;
    if (safe_gpio_write(MOTOR_A_IN2, 1) != 0) return -1;
    if (safe_gpio_pwm(MOTOR_A_IN2, duty) != 0) return -1;
    return 0;
}

static int motor_b_forward(int distance) {
    int duty = 255 - (int)(((float)(distance - 10) / 90.0f) * 255.0f);
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;

    if (safe_gpio_write(MOTOR_B_IN3, 1) != 0) return -1;
    if (safe_gpio_write(MOTOR_B_IN4, 0) != 0) return -1;
    if (safe_gpio_pwm(MOTOR_B_IN4, duty) != 0) return -1;
    return 0;
}

static int motor_b_backward(int distance) {
    int duty = (int)(((float)(distance - 10) / 90.0f) * 255.0f);
    if (duty < 0) duty = 0;
    if (duty > 255) duty = 255;

    if (safe_gpio_write(MOTOR_B_IN3, 0) != 0) return -1;
    if (safe_gpio_write(MOTOR_B_IN4, 1) != 0) return -1;
    if (safe_gpio_pwm(MOTOR_B_IN4, duty) != 0) return -1;
    return 0;
}

static int motor_a_stop(void) {
    if (safe_gpio_write(MOTOR_A_IN1, 0) != 0) return -1;
    if (safe_gpio_write(MOTOR_A_IN2, 0) != 0) return -1;
    if (safe_gpio_pwm(MOTOR_A_IN2, 0) != 0) return -1;
    return 0;
}

static int motor_b_stop(void) {
    if (safe_gpio_write(MOTOR_B_IN3, 0) != 0) return -1;
    if (safe_gpio_write(MOTOR_B_IN4, 0) != 0) return -1;
    if (safe_gpio_pwm(MOTOR_B_IN4, 0) != 0) return -1;
    return 0;
}

static int motor_a_control(int distance) {
    if (distance < 50) {
        return motor_a_forward(distance);
    } else {
        return motor_a_backward(distance);
    }
}

static int motor_b_control(int distance) {
    if (distance < 50) {
        return motor_b_forward(distance);
    } else {
        return motor_b_backward(distance);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
