#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    if (i2c_write_byte(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accel config: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_byte(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyro config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_mpu6050_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 14) < 0) {
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

int init_pwm(int chip, int channel) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", chip);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to export PWM: %s\n", strerror(errno));
            return -1;
        }
    } else {
        char ch[2];
        snprintf(ch, sizeof(ch), "%d", channel);
        if (write(fd, ch, strlen(ch)) < 0) {
            fprintf(stderr, "Failed to set PWM channel: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
        close(fd);
        usleep(100000);
    }
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", chip, channel);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open period: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1000000", 7) < 0) {
        fprintf(stderr, "Failed to set period: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", chip, channel);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open duty cycle: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "Failed to set duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", chip, channel);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        fprintf(stderr, "Failed to enable PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

void set_servo_position(int fd, int position) {
    if (position < 0) position = 0;
    if (position > 100) position = 100;
    int duty = (position * 1000000) / 100;
    char buf[16];
    snprintf(buf, sizeof(buf), "%d", duty);
    write(fd, buf, strlen(buf));
}

void log_data(FILE *fp, float pitch, float roll, int servo_position) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(fp);
}

void cleanup() {
    if (pwm_fd >= 0) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        fd = open(path, O_WRONLY);
        if (fd >= 0) {
            char ch[2];
            snprintf(ch, sizeof(ch), "%d", PWM_CHANNEL);
            write(fd, ch, strlen(ch));
            close(fd);
        }
        pwm_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
