#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define FADE_DURATION_SEC 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int state;
} ScheduleEntry;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, ScheduleEntry *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    int count = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;

        char *saveptr = NULL;
        char *token = strtok_r(line, ":", &saveptr);
        if (!token) continue;
        schedule[count].hour = atoi(token);

        token = strtok_r(NULL, ":", &saveptr);
        if (!token) continue;
        schedule[count].minute = atoi(token);

        token = strtok_r(NULL, ",", &saveptr);
        if (!token) continue;
        schedule[count].second = atoi(token);

        token = strtok_r(NULL, ",", &saveptr);
        if (!token) continue;
        schedule[count].relay_number = atoi(token);

        token = strtok_r(NULL, "\n", &saveptr);
        if (!token) continue;
        schedule[count].state = (strcmp(token, "on") == 0) ? 1 : 0;

        count++;
    }

    fclose(fp);
    return count;
}

static void set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
    }
}

static void fade_relay(int pin, int target_state, int duration_sec) {
    int current_state = gpioRead(pin);
    if (current_state == target_state) return;

    int steps = duration_sec * PWM_FREQUENCY;
    int step_size = (target_state - current_state) * PWM_RANGE / steps;

    for (int i = 0; i < steps && running; i++) {
        int duty = current_state + step_size;
        if (duty < 0) duty = 0;
        if (duty > PWM_RANGE) duty = PWM_RANGE;

        if (gpioPWM(pin, duty) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return;
        }
        current_state = duty;
        gpioDelay(1000000 / PWM_FREQUENCY);
    }

    if (gpioPWM(pin, target_state * PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting final PWM on GPIO %d\n", pin);
    }
}

static void apply_schedule(ScheduleEntry *schedule, int num_entries, time_t current_time) {
    struct tm *timeinfo = localtime(&current_time);
    if (!timeinfo) return;

    for (int i = 0; i < num_entries; i++) {
        if (schedule[i].hour == timeinfo->tm_hour &&
            schedule[i].minute == timeinfo->tm_min &&
            schedule[i].second == timeinfo->tm_sec) {

            int pin = relay_pins[schedule[i].relay_number - 1];
            if (pin >= 0 && pin < NUM_RELAYS) {
                fade_relay(pin, schedule[i].state, FADE_DURATION_SEC);
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        set_relay(relay_pins[i], 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ScheduleEntry schedule[100];
    int num_entries = read_schedule(SCHEDULE_FILE, schedule, sizeof(schedule) / sizeof(schedule[0]));
    if (num_entries < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Home Lighting System started. %d schedule entries loaded.\n", num_entries);

    while (running) {
        time_t current_time = time(NULL);
        if (current_time == (time_t)-1) {
            perror("Error getting current time");
            break;
        }

        apply_schedule(schedule, num_entries, current_time);
        sleep(1);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay(relay_pins[i], 0);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

