        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GREEN_PIN\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on BLUE_PIN\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on RED_PIN\n");
        gpioTerminate();
        return -1;
    }
