#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdbool.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define PWM_FREQUENCY 440
#define PWM_DUTY_CYCLE 128  /* 50% of 255 */
#define DEBOUNCE_US 50000   /* 50 ms */

/* Musical note lookup table: frequency in Hz, duration in ms */
typedef struct {
    int frequency;
    int duration;
} Note;

static const Note melody[] = {
    {262, 250}, {294, 250}, {330, 250}, {349, 250},
    {392, 250}, {440, 250}, {494, 250}, {523, 250},
    {0, 500}   /* rest */
};
static const int melody_length = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile sig_atomic_t playback_active = 0;
static volatile uint32_t last_press_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0) {
        return;  /* only act on falling edge (button press) */
    }

    uint32_t elapsed = tick - last_press_tick;
    if (elapsed < DEBOUNCE_US) {
        return;
    }
    last_press_tick = tick;

    button_pressed = 1;
}

static void play_melody(void) {
    for (int i = 0; i < melody_length && running; i++) {
        if (melody[i].frequency == 0) {
            gpioDelay(melody[i].duration * 1000);
            continue;
        }

        if (gpioHardwarePWM(BUZZER_PIN, PWM_FREQUENCY, PWM_DUTY_CYCLE) != 0) {
            fprintf(stderr, "Error: gpioHardwarePWM failed for note %d\n", i);
            return;
        }

        gpioDelay(melody[i].duration * 1000);

        if (gpioHardwarePWM(BUZZER_PIN, PWM_FREQUENCY, 0) != 0) {
            fprintf(stderr, "Error: gpioHardwarePWM stop failed for note %d\n", i);
            return;
        }
    }

    /* Ensure buzzer is off after playback */
    gpioHardwarePWM(BUZZER_PIN, PWM_FREQUENCY, 0);
    playback_active = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure button pin as input with pull-up */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer pin as output */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for buzzer pin %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register interrupt handler for button press */
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for button pin %d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell started. Press the button (GPIO%d) to play a melody.\n", BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        if (button_pressed) {
            button_pressed = 0;

            if (playback_active) {
                printf("Stopping playback...\n");
                playback_active = 0;
            } else {
                printf("Playing melody...\n");
                playback_active = 1;
                play_melody();
            }
        }
        gpioDelay(10000);  /* 10 ms sleep to reduce CPU usage */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioHardwarePWM(BUZZER_PIN, PWM_FREQUENCY, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

