#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <poll.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17
#define DEFAULT_POLL_MS     1000
#define EARTHQUAKE_THRESHOLD 3
#define WINDOW_SIZE         5
#define LOG_FILE_PATH       "vibration_events.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int log_event(FILE *log_fp, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s, GPIO%d, %d\n", timestamp, GPIO_LINE_OFFSET, value) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_fp) == EOF) {
        perror("fflush");
        return -1;
    }

    return 0;
}

static void check_earthquake(int window[], int size)
{
    int high_count = 0;
    for (int i = 0; i < size; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= EARTHQUAKE_THRESHOLD) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) == NULL) {
            perror("localtime_r");
            return;
        }

        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
            fprintf(stderr, "strftime failed\n");
            return;
        }

        printf("EARTHQUAKE ALERT: %s, HIGH count: %d/%d\n",
               timestamp, high_count, size);
        fflush(stdout);
    }
}

int main(int argc, char *argv[])
{
    int poll_ms = DEFAULT_POLL_MS;
    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_count = 0;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec ts;
    int ret;

    if (argc > 1) {
        poll_ms = atoi(argv[1]);
        if (poll_ms <= 0) {
            fprintf(stderr, "Invalid poll interval '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_POLL_MS);
            poll_ms = DEFAULT_POLL_MS;
        }
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE_PATH, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE_PATH ")");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_both_edges_events(line, "sw420-vibration");
    if (ret != 0) {
        perror("gpiod_line_request_both_edges_events");
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (chip %s). "
           "Poll interval: %d ms. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME, poll_ms);
    fflush(stdout);

    ts.tv_sec = poll_ms / 1000;
    ts.tv_nsec = (poll_ms % 1000) * 1000000L;

    while (g_running) {
        ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret != 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        int value = gpiod_line_event_get_value(&event);
        if (value < 0) {
            perror("gpiod_line_event_get_value");
            continue;
        }

        if (log_event(log_fp, value) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_count < WINDOW_SIZE) {
            window_count++;
        }

        check_earthquake(window, window_count);
    }

    printf("\nShutting down...\n");

    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        if (fclose(log_fp) == EOF) {
            perror("fclose");
        }
    }

    return EXIT_SUCCESS;
}

