            window_count++;
        }

        check_earthquake(window, window_count);
    }

    printf("\nShutting down...\n");

    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        if (fclose(log_fp) == EOF) {
            perror("fclose");
        }
    }

