#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_ADDR_MAG 0x1E
#define LSM303_REG_MR_REG_M 0x02
#define LSM303_REG_CRA_REG_M 0x00
#define LSM303_REG_OUT_X_H_M 0x03

#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    if (i2c_write_reg8(fd, LSM303_REG_MR_REG_M, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, LSM303_REG_CRA_REG_M, 0x14) < 0) return -1;
    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM303_REG_OUT_X_H_M, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calibrate_magnetometer(int16_t x, int16_t y, int16_t z,
                                  float *cx, float *cy, float *cz) {
    *cx = (float)x - X_OFFSET;
    *cy = (float)y - Y_OFFSET;
    *cz = (float)z - Z_OFFSET;
}

static float calculate_heading(float cx, float cy) {
    float heading = atan2f(cy, cx) * 180.0f / (float)M_PI;
    if (heading < 0.0f) heading += 360.0f;
    return heading;
}

static const char *map_heading_to_direction(float heading) {
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading < 67.5f) return "NE";
    if (heading < 112.5f) return "E";
    if (heading < 157.5f) return "SE";
    if (heading < 202.5f) return "S";
    if (heading < 247.5f) return "SW";
    if (heading < 292.5f) return "W";
    return "NW";
}

static int log_data(FILE *fp, float cx, float cy, float cz, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    int16_t x, y, z;
    float cx, cy, cz, heading;
    const char *direction;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, LSM303_ADDR_MAG) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303_ADDR_MAG, strerror(errno));
        goto cleanup;
    }

    if (init_magnetometer(fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        goto cleanup;
    }

    fp = fopen("mag_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open mag_log.csv: %s\n", strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        if (fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Magnetometer logging started. Press Ctrl+C to stop.\n");

    while (running) {
        if (read_magnetometer(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, skipping sample.\n");
            sleep(1);
            continue;
        }

        calibrate_magnetometer(x, y, z, &cx, &cy, &cz);
        heading = calculate_heading(cx, cy);
        direction = map_heading_to_direction(heading);

        printf("Heading: %.2f degrees (%s)\n", heading, direction);

        if (log_data(fp, cx, cy, cz, heading) < 0) {
            fprintf(stderr, "Logging failed.\n");
        }

        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) fclose(fp);
    if (fd >= 0) close(fd);
    return ret;
}

