#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME_SEC 5
#define RELAY_GAP_SEC 1
#define LOOP_INTERVAL_SEC 10
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS];
static FILE *log_fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 1);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return -1;
        }

        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output: %s\n", relay_pins[i], strerror(errno));
            cleanup();
            return -1;
        }
    }
    return 0;
}

static int init_log(void) {
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_soil_moisture(void) {
    return rand() % 101;
}

static void activate_relay(int relay_num, int moisture_level) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return;
    }

    if (gpiod_line_set_value(relay_lines[relay_num], 0) < 0) {
        fprintf(stderr, "Failed to activate relay %d: %s\n", relay_num, strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) && strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info)) {
        fprintf(log_fp, "%s - Relay %d activated (Moisture: %d)\n", timestamp, relay_num, moisture_level);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Failed to format timestamp\n");
    }

    sleep(RELAY_ON_TIME_SEC);

    if (gpiod_line_set_value(relay_lines[relay_num], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n", relay_num, strerror(errno));
    }

    sleep(RELAY_GAP_SEC);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    srand((unsigned int)time(NULL));

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_soil_moisture();

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Soil moisture low (%d). Activating relays.\n", moisture_level);
            for (int i = 0; i < NUM_RELAYS; i++) {
                if (!running) break;
                activate_relay(i, moisture_level);
            }
        } else {
            printf("Soil moisture sufficient (%d). Skipping activation.\n", moisture_level);
        }

        for (int i = 0; i < LOOP_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

