#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN    17
#define NOZZLE_SERVO_PIN   18

#define VALVE_OPEN_US      1500   /* 90 degrees  */
#define VALVE_CLOSED_US    500    /* 0 degrees   */
#define NOZZLE_MIN_US      500    /* 0 degrees   */
#define NOZZLE_MAX_US      2500   /* 180 degrees */

#define MOISTURE_THRESHOLD 50
#define WATERING_DURATION  5      /* seconds per nozzle angle */
#define CYCLE_DELAY        5      /* seconds between cycles   */
#define SERVO_RETRY_COUNT  3
#define SERVO_RETRY_DELAY  0.1    /* seconds between retries */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Safely set a servo pulse width with retries.
 * Returns 0 on success, -1 on failure.
 */
static int set_servo_with_retry(int pin, int pulse_width)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        if (gpioServo(pin, pulse_width) == 0)
            return 0;
        fprintf(stderr, "Warning: gpioServo(pin=%d, pw=%d) failed (attempt %d/%d)\n",
                pin, pulse_width, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1)
            time_sleep(SERVO_RETRY_DELAY);
    }
    return -1;
}

/*
 * Open the valve to the specified angle (0-90).
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(int angle)
{
    if (angle < 0 || angle > 90) {
        fprintf(stderr, "Error: valve angle %d out of range\n", angle);
        return -1;
    }
    int pw = VALVE_CLOSED_US + (int)((long)angle * (VALVE_OPEN_US - VALVE_CLOSED_US) / 90);
    return set_servo_with_retry(VALVE_SERVO_PIN, pw);
}

/*
 * Close the valve.
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    return set_servo_with_retry(VALVE_SERVO_PIN, VALVE_CLOSED_US);
}

/*
 * Set the nozzle direction to the specified angle (0-180).
 * Returns 0 on success, -1 on failure.
 */
static int set_nozzle_angle(int angle)
{
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: nozzle angle %d out of range\n", angle);
        return -1;
    }
    int pw = NOZZLE_MIN_US + (int)((long)angle * (NOZZLE_MAX_US - NOZZLE_MIN_US) / 180);
    return set_servo_with_retry(NOZZLE_SERVO_PIN, pw);
}

/*
 * Simulate a soil-moisture reading.
 * Returns a value between 0 and 100.
 */
static int read_soil_moisture(void)
{
    static const int values[] = {20, 40, 60, 80, 100};
    static int idx = 0;
    int v = values[idx];
    idx = (idx + 1) % (int)(sizeof(values) / sizeof(values[0]));
    return v;
}

int main(void)
{
    /* --- Install signal handlers early --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Ensure servos are stopped on exit --- */
    atexit(gpioTerminate);

    /* --- Main control loop --- */
    while (g_running) {
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d). Watering...\n", MOISTURE_THRESHOLD);

            /* Open valve to 90 degrees */
            if (open_valve(90) != 0) {
                fprintf(stderr, "Critical: failed to open valve; aborting cycle\n");
                time_sleep(CYCLE_DELAY);
                continue;
            }

            /* Sweep nozzle through five angles */
            for (int angle = 0; angle <= 180 && g_running; angle += 45) {
                if (set_nozzle_angle(angle) != 0) {
                    fprintf(stderr, "Error: failed to set nozzle angle %d; continuing\n", angle);
                    continue;
                }
                time_sleep(WATERING_DURATION);
            }

            /* Hold for 5 seconds */
            time_sleep(WATERING_DURATION);

            /* Close valve to 0 degrees */
            if (close_valve() != 0) {
                fprintf(stderr, "Warning: failed to close valve; continuing\n");
            }
        } else {
            printf("Moisture above threshold (%d). Skipping watering.\n", MOISTURE_THRESHOLD);
        }

        /* Wait 5 seconds before next cycle */
        time_sleep(CYCLE_DELAY);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioServo(VALVE_SERVO_PIN, 0);
    gpioServo(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

