#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_SENSITIVITY 131.0f
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X for read: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

static int log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    printf("MPU-6050 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }
        if (log_data(fp, x, y, z) < 0) {
            fprintf(stderr, "Error logging data, continuing...\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing I2C bus: %s\n", strerror(errno));
    }
    printf("Cleanup complete.\n");
    return 0;
}

