#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms timeout for echo edges */
#define MEASURE_US  10000   /* 10 us trigger pulse */
#define GUARD_US    60000   /* 60 ms between measurements */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * Measure the duration (in microseconds) of a HIGH pulse on the echo line.
 * Returns the pulse width in microseconds, or -1 on timeout/error.
 */
static long measure_echo_pulse(struct gpiod_line *echo_line)
{
    struct timespec start, now;
    long elapsed_us;

    /* Wait for echo to go HIGH (rising edge) */
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    for (;;) {
        if (gpiod_line_get_value(echo_line) == 1)
            break;
        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                     (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }

    /* Wait for echo to go LOW (falling edge) */
    for (;;) {
        if (gpiod_line_get_value(echo_line) == 0)
            break;
        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            return -1;
        }
        elapsed_us = (now.tv_sec - start.tv_sec) * 1000000L +
                     (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }

    return elapsed_us;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret;

    /* Open the default gpiochip (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line (BCM %d): %s\n",
                TRIGGER_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line (BCM %d): %s\n",
                ECHO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request trigger as output, initial value LOW */
    ret = gpiod_line_request_output(trigger_line, "hcsr04-trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request echo as input */
    ret = gpiod_line_request_input(echo_line, "hcsr04-echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n",
                strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Open log file once in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(log_fp);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(log_fp);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Ensure trigger is LOW for at least 2 us before pulse */
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger LOW: %s\n", strerror(errno));
            fprintf(log_fp, "-1\n");
            fflush(log_fp);
            usleep(100000);
            continue;
        }
        usleep(2);

        /* Generate 10 us trigger pulse */
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            fprintf(stderr, "Failed to set trigger HIGH: %s\n", strerror(errno));
            fprintf(log_fp, "-1\n");
            fflush(log_fp);
            usleep(100000);
            continue;
        }
        usleep(MEASURE_US);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            fprintf(stderr, "Failed to set trigger LOW: %s\n", strerror(errno));
            fprintf(log_fp, "-1\n");
            fflush(log_fp);
            usleep(100000);
            continue;
        }

        long pulse_us = measure_echo_pulse(echo_line);
        if (pulse_us < 0) {
            fprintf(log_fp, "-1\n");
            fflush(log_fp);
        } else {
            double distance_cm = (double)pulse_us * 0.01715;
            fprintf(log_fp, "%.2f\n", distance_cm);
            fflush(log_fp);
            printf("Distance: %.2f cm\n", distance_cm);
        }

        /* Guard interval to avoid false echoes */
        usleep(GUARD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (trigger_line)
        gpiod_line_release(trigger_line);
    if (echo_line)
        gpiod_line_release(echo_line);
    if (chip)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

