#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR             0x29
#define I2C_BUS                  1
#define RELAY_GPIO               18
#define DISTANCE_THRESHOLD_CM    50
#define POLL_DELAY_US            100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET           0x0000
#define REG_SYSTEM_MODE_START    0x0080
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_RANGE_STATUS   0x0089
#define REG_RESULT_DISTANCE_MSB  0x0096
#define REG_RESULT_DISTANCE_LSB  0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address (big-endian) followed by a 16-bit value */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Write a 16-bit register address (big-endian) then read N bytes */
static int vl53l1x_read_reg(int handle, uint16_t reg, char *buf, int len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, buf, len);
}

static int vl53l1x_init(int handle)
{
    /* Software reset: write 0x00 to register 0x0000 */
    if (vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x0000) < 0) {
        fprintf(stderr, "Error: failed to write soft reset register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Start continuous ranging: write 0x01 to register 0x0080 */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE_START, 0x0001) < 0) {
        fprintf(stderr, "Error: failed to start continuous ranging\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    char status_buf[1];
    char dist_buf[2];

    /* Check interrupt status: bit 0 of register 0x0044 indicates data ready */
    if (vl53l1x_read_reg(handle, REG_RESULT_INTERRUPT_STATUS, status_buf, 1) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status_buf[0] & 0x01) == 0) {
        return 1; /* not ready yet */
    }

    /* Read 16-bit distance from registers 0x0096 (MSB) and 0x0097 (LSB) */
    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE_MSB, dist_buf, 2) < 0) {
        fprintf(stderr, "Error: failed to read distance registers\n");
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)dist_buf[0] << 8) | (uint8_t)dist_buf[1];
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d)\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            uint16_t distance_cm = distance_mm / 10;
            printf("Distance: %u cm\n", distance_cm);

            if (distance_cm <= DISTANCE_THRESHOLD_CM) {
                gpioWrite(RELAY_GPIO, 1);
                printf("Door opening (distance <= %d cm)!\n", DISTANCE_THRESHOLD_CM);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        }
        /* rc == 1: data not ready yet, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

