#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the relays (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define sunrise duration (seconds)
#define SUNRISE_DURATION 1800

// Define log file path
#define LOG_FILE "smart_lighting.log"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_state(int pin, int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency for all relay pins
    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", RELAY1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", RELAY2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", RELAY3_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", RELAY4_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to set the state of a relay (ON or OFF)
void set_relay_state(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

// Cleanup function to release resources
void cleanup() {
    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    log_event("Cleanup complete.");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    log_event("Smart lighting system started.");

    // Calculate the duty cycle increment per second
    float duty_cycle_increment = 255.0 / SUNRISE_DURATION;

    // Main loop
    for (int i = 0; i <= SUNRISE_DURATION && program_running; i++) {
        // Calculate the duty cycle for this step
        float duty_cycle = i * duty_cycle_increment;

        // Set the duty cycle for all relays
        gpioPWM(RELAY1_PIN, (int)duty_cycle);
        gpioPWM(RELAY2_PIN, (int)duty_cycle);
        gpioPWM(RELAY3_PIN, (int)duty_cycle);
        gpioPWM(RELAY4_PIN, (int)duty_cycle);

        // Log the current duty cycle
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Duty cycle: %.2f", duty_cycle);
        log_event(log_message);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

