#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define LOG_FILE        "gyro_log.txt"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define GYRO_XOUT_H     0x43
#define GYRO_YOUT_H     0x45
#define GYRO_ZOUT_H     0x47
#define GYRO_SCALE      131.0f
#define MAX_RETRIES     3
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_gyro_burst(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = {0};
    uint8_t rx[7] = {0};
    tx[0] = GYRO_XOUT_H | 0x80;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        return -1;
    }
    if (spi_transfer(tx, rx, 7) < 0) {
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        return -1;
    }

    *x = (int16_t)((rx[1] << 8) | rx[2]);
    *y = (int16_t)((rx[3] << 8) | rx[4]);
    *z = (int16_t)((rx[5] << 8) | rx[6]);
    return 0;
}

static int log_data(float x, float y, float z) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[40];

    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        return -1;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    if (fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        return -1;
    }
    if (fflush(log_fp) != 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        cleanup();
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPU-9250 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (running) {
        int16_t raw_x = 0, raw_y = 0, raw_z = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_gyro_burst(&raw_x, &raw_y, &raw_z) == 0) {
                success = 1;
                break;
            }
            usleep(1000);
        }

        if (!success) {
            fprintf(stderr, "Failed to read gyro data after %d retries.\n", MAX_RETRIES);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float x_rate = (float)raw_x / GYRO_SCALE;
        float y_rate = (float)raw_y / GYRO_SCALE;
        float z_rate = (float)raw_z / GYRO_SCALE;

        if (log_data(x_rate, y_rate, z_rate) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

