#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// MPU-6050 Registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

// SPI Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000 // 3.9 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

// GPIO Configuration
#define GPIO_CHIP "gpiochip0"
#define LED_PIN 17 // GPIO17 (physical pin 11)

// Circular Buffer Size
#define BUFFER_SIZE 64

// Gyroscope Sensitivity (LSB per deg/s)
#define GYRO_SENSITIVITY 131.0f

// Threshold for angular velocity (deg/s)
#define THRESHOLD 200.0f

// Data Structure for Gyroscope Data
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular Buffer Structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global Variables
static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static circular_buffer_t gyro_buffer;

// Function Prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void check_threshold(float x, float y, float z);
void print_buffer(circular_buffer_t *buffer);
void cleanup(void);
void signal_handler(int sig);

// SPI Initialization Function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// SPI Transfer Function
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    // Assert chip select (active low)
    if (gpiod_line_set_value(led_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(led_line, 1); // Deassert CS on error
        return -1;
    }

    // Deassert chip select
    if (gpiod_line_set_value(led_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to Read Gyroscope Data
int read_gyro_data(float *x, float *y, float *z) {
    uint8_t tx_buf[7];
    uint8_t rx_buf[7];

    // Read X, Y, Z axis data (high byte) with auto-increment disabled
    tx_buf[0] = MPU6050_GYRO_XOUT_H | 0x80; // Read bit
    tx_buf[1] = 0x00; // Dummy byte for X
    tx_buf[2] = MPU6050_GYRO_YOUT_H | 0x80; // Read bit
    tx_buf[3] = 0x00; // Dummy byte for Y
    tx_buf[4] = MPU6050_GYRO_ZOUT_H | 0x80; // Read bit
    tx_buf[5] = 0x00; // Dummy byte for Z
    tx_buf[6] = 0x00; // Dummy byte for padding

    if (spi_transfer(tx_buf, rx_buf, 7) < 0) {
        return -1;
    }

    // Combine high and low bytes (big-endian)
    int16_t raw_x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    int16_t raw_y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
    int16_t raw_z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Function to Add Data to the Circular Buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Function to Check Threshold and Blink LED
void check_threshold(float x, float y, float z) {
    if (x > THRESHOLD || x < -THRESHOLD ||
        y > THRESHOLD || y < -THRESHOLD ||
        z > THRESHOLD || z < -THRESHOLD) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
        usleep(500000); // 500 ms
        gpiod_line_set_value(led_line, 0); // Turn LED off
        usleep(500000); // 500 ms
    }
}

// Function to Print the Circular Buffer Contents
void print_buffer(circular_buffer_t *buffer) {
    printf("Timestamp,X,Y,Z\n");
    int i = buffer->tail;
    for (int j = 0; j < buffer->count; j++) {
        struct tm *timeinfo = localtime(&buffer->data[i].timestamp.tv_sec);
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s.%09ld,%.2f,%.2f,%.2f\n", timestamp_str, buffer->data[i].timestamp.tv_nsec, buffer->data[i].x, buffer->data[i].y, buffer->data[i].z);
        i = (i + 1) % BUFFER_SIZE;
    }
}

// Cleanup Function
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

// Signal Handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO using libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    gyro_data_t gyro_data;

    printf("Starting MPU-6050 gyroscope data acquisition...\n");

    while (running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get current timestamp
            clock_gettime(CLOCK_REALTIME, &gyro_data.timestamp);

            // Store data in circular buffer
            gyro_data.x = x;
            gyro_data.y = y;
            gyro_data.z = z;
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold and blink LED
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Print the circular buffer contents
    print_buffer(&gyro_buffer);

    // Cleanup
    cleanup();

    printf("Exiting.\n");
    return 0;
}

