static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) != 2) {
            fprintf(stderr, "I2C write reg 0x%02X val 0x%02X failed (attempt %d): %s\n",
                    reg, val, attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        return 0;
    }
    return -1;
}

