#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define X_RATE_REG 0x02
#define Y_RATE_REG 0x04
#define SENSITIVITY 200.0f
#define SAMPLE_DELAY_US 10000
#define MAX_SPI_RETRIES 3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, int16_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0 };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, tx, rx, 2);
        if (ret == 2) {
            *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d, ret=%d)\n",
                attempt + 1, MAX_SPI_RETRIES, ret);
        gpioDelay(1000);
    }
    return -1;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int log_data(int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    if (fprintf(log_file, "%ld.%06ld,%d,%d\n",
                (long)ts.tv_sec, ts.tv_nsec / 1000,
                x_rate, y_rate) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,x_rate,y_rate\n") < 0) {
        perror("fprintf header");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyroscope logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int16_t x_rate = 0, y_rate = 0;

        if (spi_read_register(X_RATE_REG, &x_rate) != 0) {
            fprintf(stderr, "Failed to read X rate after %d retries. Exiting.\n", MAX_SPI_RETRIES);
            break;
        }
        if (spi_read_register(Y_RATE_REG, &y_rate) != 0) {
            fprintf(stderr, "Failed to read Y rate after %d retries. Exiting.\n", MAX_SPI_RETRIES);
            break;
        }

        if (log_data(x_rate, y_rate) != 0) {
            fprintf(stderr, "Logging failed. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

