#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

// ADXRS290 Register Addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// GPIO Configuration
#define LED_GPIO 17

// Threshold
#define ANGULAR_VELOCITY_THRESHOLD 20.0 // deg/s

// Circular Buffer Configuration
#define BUFFER_SIZE 100

// Data Structure for Circular Buffer
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

// Circular Buffer Structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global Variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int spi_read_register(int handle, uint8_t address, uint8_t *data);
float read_gyro_data(int handle);
void add_to_circular_buffer(circular_buffer_t *buffer, struct timespec timestamp, float angular_velocity);
void check_threshold(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// SPI Read Function
int spi_read_register(int handle, uint8_t address, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // ADXRS290 requires MSB of address to be 1 for read
    tx_buf[0] = address | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for clocking data out

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    *data = (uint8_t)rx_buf[1];
    return 0;
}

// Function to Read Gyro Data
float read_gyro_data(int handle) {
    uint8_t rate_xl, rate_xh;
    int16_t raw_rate;
    float angular_velocity;

    if (spi_read_register(handle, RATE_XL, &rate_xl) != 0) {
        fprintf(stderr, "Failed to read RATE_XL\n");
        return 0.0;
    }

    if (spi_read_register(handle, RATE_XH, &rate_xh) != 0) {
        fprintf(stderr, "Failed to read RATE_XH\n");
        return 0.0;
    }

    // Combine bytes (little-endian)
    raw_rate = (int16_t)((rate_xh << 8) | rate_xl);

    // Convert to degrees per second (200 LSB/deg/s)
    angular_velocity = (float)raw_rate / 200.0;

    return angular_velocity;
}

// Function to Add Data to the Circular Buffer
void add_to_circular_buffer(circular_buffer_t *buffer, struct timespec timestamp, float angular_velocity) {
    pthread_mutex_lock(&buffer->mutex);

    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].angular_velocity = angular_velocity;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;

    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }

    pthread_mutex_unlock(&buffer->mutex);
}

// Function to Check the Threshold and Control the LED
void check_threshold(float angular_velocity) {
    if (angular_velocity > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal Handler for Graceful Shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup Function
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;
    pthread_mutex_init(&gyro_buffer.mutex, NULL);

    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (program_running) {
        struct timespec timestamp;
        clock_gettime(CLOCK_MONOTONIC, &timestamp);

        float angular_velocity = read_gyro_data(spi_handle);

        add_to_circular_buffer(&gyro_buffer, timestamp, angular_velocity);
        check_threshold(angular_velocity);

        gpioDelay(10000); // 10ms delay (100Hz sampling rate)
    }

    // Cleanup
    cleanup();

    return 0;
}

