#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

#define PWM_RANGE 255
#define PWM_FREQUENCY 100

#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int set_lamp_brightness(int gpio, int brightness) {
    if (brightness < 0 || brightness > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid brightness value %d for GPIO %d\n", brightness, gpio);
        return -1;
    }
    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "Error: Failed to set PWM on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static int fade_lamp(int gpio, int duration_seconds) {
    if (duration_seconds <= 0) {
        fprintf(stderr, "Error: Invalid duration %d seconds for GPIO %d\n", duration_seconds, gpio);
        return -1;
    }

    int steps = duration_seconds * PWM_FREQUENCY;
    int step_delay_us = 1000000 / PWM_FREQUENCY;

    for (int i = 0; i <= steps && program_running; i++) {
        int brightness = (PWM_RANGE * (steps - i)) / steps;
        if (set_lamp_brightness(gpio, brightness) != 0) {
            return -1;
        }
        gpioDelay(step_delay_us);
    }

    if (!program_running) {
        fprintf(stderr, "Warning: Fade interrupted by signal for GPIO %d\n", gpio);
    }

    return 0;
}

static void cleanup_all_lamps(void) {
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  Fade duration must be an integer between %d and %d seconds.\n", MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    char *endptr;
    long duration = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || duration < MIN_DURATION || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid fade duration '%s'. Must be an integer between %d and %d seconds.\n", argv[1], MIN_DURATION, MAX_DURATION);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed. Ensure pigpiod is not running and you have permissions.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP2_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(LAMP3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) != 0 ||
        gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fading all lamps for %ld seconds...\n", duration);
    printf("  Lamp 1: GPIO%d\n", LAMP1_GPIO);
    printf("  Lamp 2: GPIO%d\n", LAMP2_GPIO);
    printf("  Lamp 3: GPIO%d\n", LAMP3_GPIO);
    printf("Press Ctrl+C to stop early.\n\n");

    if (fade_lamp(LAMP1_GPIO, duration) != 0) {
        fprintf(stderr, "Error: Fade failed for Lamp 1.\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!program_running) {
        printf("Fade interrupted by signal. Cleaning up...\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (fade_lamp(LAMP2_GPIO, duration) != 0) {
        fprintf(stderr, "Error: Fade failed for Lamp 2.\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (!program_running) {
        printf("Fade interrupted by signal. Cleaning up...\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (fade_lamp(LAMP3_GPIO, duration) != 0) {
        fprintf(stderr, "Error: Fade failed for Lamp 3.\n");
        cleanup_all_lamps();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Fade complete. All lamps turned off.\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

