#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_DURATION    10
#define YELLOW_DURATION  2
#define GREEN_DURATION  10
#define YELLOW2_DURATION 3

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void set_all_off(struct gpiod_line *lines[]) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
        }
    }
}

static void set_all_on(struct gpiod_line *lines[]) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
        }
    }
}

static void traffic_light_cycle(struct gpiod_line *lines[]) {
    printf("Red\n");
    fflush(stdout);
    set_all_off(lines);
    gpiod_line_set_value(lines[0], 0);
    sleep(RED_DURATION);

    if (!running) return;

    printf("Red + Yellow\n");
    fflush(stdout);
    set_all_off(lines);
    gpiod_line_set_value(lines[0], 0);
    gpiod_line_set_value(lines[1], 0);
    sleep(YELLOW_DURATION);

    if (!running) return;

    printf("Green\n");
    fflush(stdout);
    set_all_off(lines);
    gpiod_line_set_value(lines[2], 0);
    sleep(GREEN_DURATION);

    if (!running) return;

    printf("Yellow\n");
    fflush(stdout);
    set_all_off(lines);
    gpiod_line_set_value(lines[1], 0);
    sleep(YELLOW2_DURATION);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    const int pins[4] = {RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %d\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "traffic_light", 1) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %d\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Traffic light simulator started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        traffic_light_cycle(lines);
    }

    printf("\nShutting down...\n");
    set_all_off(lines);
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

