#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LOG_FILE "touch_relay.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGE_TIME 0x5C
#define MPR121_RUN_MODE 0x5E
#define MPR121_RESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write error: reg=0x%02X, val=0x%02X, err=%d", reg, value, result);
        log_message(msg);
    }
    return result;
}

static int mpr121_init(void) {
    if (mpr121_write_reg(MPR121_RESET, 0x63) < 0) return -1;
    gpioDelay(10000);
    if (mpr121_write_reg(MPR121_RUN_MODE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_TOUCH_THRESHOLD, 0x0A) < 0) return -1;
    if (mpr121_write_reg(MPR121_RELEASE_THRESHOLD, 0x08) < 0) return -1;
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write_reg(MPR121_CHARGE_TIME, 0x0D) < 0) return -1;
    if (mpr121_write_reg(MPR121_RUN_MODE, 0x0D) < 0) return -1;
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lsb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (lsb < 0) {
        log_message("Failed to read touch status LSB");
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (msb < 0) {
        log_message("Failed to read touch status MSB");
        return -1;
    }
    *status = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to open I2C device at 0x%02X: %d", MPR121_ADDR, i2c_handle);
        log_message(msg);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Touch relay control started");

    int relay_state = 0;
    uint16_t last_touch_status = 0;
    uint32_t last_touch_time = 0;

    while (running) {
        uint16_t touch_status;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        uint32_t now = gpioTick();
        if (touch_status & 0x0001) {
            if ((now - last_touch_time) > 100000) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char msg[128];
                snprintf(msg, sizeof(msg), "Relay toggled to %d", relay_state);
                log_message(msg);
                last_touch_time = now;
            }
        }
        last_touch_status = touch_status;
        gpioDelay(10000);
    }

    log_message("Shutting down");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

