#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N enable pins (HIGH to enable PWM)
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// Simulation parameters
#define MAX_TILT_ERROR 10.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define OBSTACLE_THRESHOLD 20.0
#define MAX_SPEED 255
#define CONTROL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void set_motor_speed(char motor, int speed);
void stop_motors(void);
float simulate_tilt_error(void);
float simulate_distance(void);
void avoid_obstacle(void);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Set motor speed using PWM (speed is clamped to +/-255)
void set_motor_speed(char motor, int speed) {
    int forward_pin, backward_pin;
    int enable_pin;

    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < -MAX_SPEED) speed = -MAX_SPEED;

    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = MOTOR_A_ENABLE;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor character '%c'\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
}

// Stop both motors
void stop_motors(void) {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

// Simulate tilt error (random float between -MAX_TILT_ERROR and MAX_TILT_ERROR)
float simulate_tilt_error(void) {
    return (float)(rand() % 2001 - 1000) / 100.0;
}

// Simulate distance (random float between MIN_DISTANCE and MAX_DISTANCE)
float simulate_distance(void) {
    return (float)(rand() % 39901 + 200) / 100.0;
}

// Avoid obstacle: reverse both motors at 50% speed
void avoid_obstacle(void) {
    set_motor_speed('A', -128);
    set_motor_speed('B', -128);
    gpioDelay(200000); // 200 ms
    stop_motors();
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    float tilt_error, distance;
    float integral = 0.0;
    float previous_error = 0.0;
    int motor_a_speed, motor_b_speed;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Enable PWM on enable pins
    gpioWrite(MOTOR_A_ENABLE, 1);
    gpioWrite(MOTOR_B_ENABLE, 1);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Seed random number generator
    srand(time(NULL));

    // Main control loop
    while (running) {
        // Simulate sensor readings
        tilt_error = simulate_tilt_error();
        distance = simulate_distance();

        // PID control
        integral += tilt_error;
        float derivative = tilt_error - previous_error;
        float output = KP * tilt_error + KI * integral + KD * derivative;

        // Clamp output to +/-MAX_SPEED
        if (output > MAX_SPEED) output = MAX_SPEED;
        if (output < -MAX_SPEED) output = -MAX_SPEED;

        // Set motor speeds
        motor_a_speed = (int)output;
        motor_b_speed = (int)output;

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            avoid_obstacle();
        }

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update previous error
        previous_error = tilt_error;

        // Wait for next control cycle
        gpioDelay(CONTROL_INTERVAL_MS * 1000);
    }

    // Cleanup
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

