#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000  // 50 ms

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for clean exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Enable internal pull-down on touch sensor pin (TTP223 has open-collector output)
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Ensure relay is initially OFF
    gpioWrite(RELAY_PIN, 0);

    printf("Smart Light Switch started. Touch the sensor to toggle the relay.\n");
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;  // 0 = OFF, 1 = ON

    while (program_running) {
        // Read touch sensor value
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_detected == 1) {
            // Toggle relay state
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);

            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000);  // 10 ms
    }

    // Cleanup: turn off relay and terminate pigpio
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

