/*
 * mood_light.c — Raspberry Pi 3 Model B+ mood light driven by ambient noise.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lrt -lm
 * Run:    sudo ./mood_light [sensitivity]
