        *red   = (int)(t * 255.0);
        *green = (int)(t * 255.0);
        *blue  = (int)(255.0 - t * 255.0);
    } else {
        t -= 1.0;
        *red   = (int)(255.0 - t * 255.0);
        *green = (int)(255.0 - t * 255.0);
        *blue  = (int)(255.0);
