    unsigned int channels = NUM_CHANNELS;
    err = snd_pcm_hw_params_set_channels(ctx->handle, ctx->params, channels);
    if (err < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_channels failed: %s\n",
                snd_strerror(err));
        goto fail;
    }

    /* Set the period size (frames) */
    ctx->period_size = PERIOD_FRAMES;
    err = snd_pcm_hw_params_set_period_size_near(ctx->handle, ctx->params,
                                                 &ctx->period_size, NULL);
    if (err < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_period_size_near failed: %s\n",
                snd_strerror(err));
        goto fail;
    }

    /* Set the buffer size (period_size * 2) */
    ctx->buffer_size = ctx->period_size * 2;
    err = snd_pcm_hw_params_set_buffer_size_near(ctx->handle, ctx->params,
                                                 &ctx->buffer_size);
    if (err < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params_set_buffer_size_near failed: %s\n",
                snd_strerror(err));
        goto fail;
    }

    /* Apply the hardware parameters */
    err = snd_pcm_hw_params(ctx->handle, ctx->params);
    if (err < 0) {
        fprintf(stderr, "Error: snd_pcm_hw_params failed: %s\n",
                snd_strerror(err));
        goto fail;
    }

