static void alsa_close(alsa_context_t *ctx)
{
    if (ctx->handle) {
        snd_pcm_drain(ctx->handle);
        snd_pcm_close(ctx->handle);
        ctx->handle = NULL;
    }
}

static int alsa_read_audio(alsa_context_t *ctx, int16_t *buffer, size_t frames)
{
    int err;
    snd_pcm_sframes_t frames_read;

    frames_read = snd_pcm_readi(ctx->handle, buffer, frames);
    if (frames_read < 0) {
        if (frames_read == -EPIPE) {
            fprintf(stderr, "Warning: ALSA buffer overrun (EPIPE), recovering...\n");
            err = snd_pcm_prepare(ctx->handle);
            if (err < 0) {
                fprintf(stderr, "Error: snd_pcm_prepare failed: %s\n",
                        snd_strerror(err));
                return -1;
            }
            return 0;
        } else if (frames_read == -ESTRPIPE) {
            fprintf(stderr, "Warning: ALSA stream suspended (ESTRPIPE), resuming...\n");
            err = snd_pcm_resume(ctx->handle);
            if (err < 0) {
                fprintf(stderr, "Error: snd_pcm_resume failed: %s\n",
                        snd_strerror(err));
                return -1;
            }
            return 0;
        } else {
            fprintf(stderr, "Error: snd_pcm_readi failed: %s\n",
                    snd_strerror(frames_read));
            return -1;
        }
    }

    return (int)frames_read;
}

#endif /* ALSA_AVAILABLE */

/* ------------------------------------------------------------------ */
/* Simulation (when ALSA unavailable)                                  */
/* ------------------------------------------------------------------ */
#ifndef ALSA_AVAILABLE

typedef struct {
    double phase;
} simulation_context_t;

static int simulation_init(simulation_context_t *ctx)
{
    ctx->phase = 0.0;
    return 0;
}

static int simulation_read_audio(simulation_context_t *ctx, int16_t *buffer, size_t frames)
{
    for (size_t i = 0; i < frames; i++) {
        double t = ctx->phase + (double)i / (double)SAMPLE_RATE;
        buffer[i] = (int16_t)(sin(t * 2.0 * M_PI * SIMULATION_FREQUENCY) * SIMULATION_AMPLITUDE);
    }
    ctx->phase += (double)frames / (double)SAMPLE_RATE;
    return (int)frames;
}

#endif /* ALSA_AVAILABLE */

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    double sensitivity = 1.0;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Error: sensitivity must be a positive number.\n");
            return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 8000 Hz (pigpio hardware PWM) */
    if (set_pwm_frequency(RED_PIN, SAMPLE_RATE) < 0 ||
        set_pwm_frequency(GREEN_PIN, SAMPLE_RATE) < 0 ||
        set_pwm_frequency(BLUE_PIN, SAMPLE_RATE) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range */
    if (set_pwm_range(RED_PIN, PWM_RANGE) < 0 ||
        set_pwm_range(GREEN_PIN, PWM_RANGE) < 0 ||
        set_pwm_range(BLUE_PIN, PWM_RANGE) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ALSA context */
#ifdef ALSA_AVAILABLE
    alsa_context_t alsa_ctx;
    if (alsa_init(&alsa_ctx) != 0) {
        fprintf(stderr, "Error: ALSA initialisation failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
#endif /* ALSA_AVAILABLE */

    /* Initialize simulation context */
#ifndef ALSA_AVAILABLE
    simulation_context_t sim_ctx;
    if (simulation_init(&sim_ctx) != 0) {
        fprintf(stderr, "Error: simulation initialisation failed.\n");
#ifdef ALSA_AVAILABLE
        alsa_close(&alsa_ctx);
#endif /* ALSA_AVAILABLE */
        gpioTerminate();
        return EXIT_FAILURE;
    }
#endif /* ALSA_AVAILABLE */

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Mood light started.  Sensitivity: %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int16_t *buffer = NULL;
        size_t frames_to_read;
        int frames_read;
        double amplitude = 0.0;
        int red = 0, green = 0, blue = 0;

        /* Allocate a buffer for reading audio data */
        buffer = (int16_t *)malloc(PERIOD_FRAMES * sizeof(int16_t));
        if (buffer == NULL) {
            fprintf(stderr, "Error: memory allocation failed.\n");
            break;
        }

        /* Calculate the number of frames to read */
#ifdef ALSA_AVAILABLE
        frames_to_read = alsa_ctx.frames_per_read;
#endif /* ALSA_AVAILABLE */
#ifndef ALSA_AVAILABLE
        frames_to_read = PERIOD_FRAMES;
#endif /* ALSA_AVAILABLE */

        /* Read audio data */
#ifdef ALSA_AVAILABLE
        frames_read = alsa_read_audio(&alsa_ctx, buffer, frames_to_read);
#endif /* ALSA_AVAILABLE */
#ifndef ALSA_AVAILABLE
        frames_read = simulation_read_audio(&sim_ctx, buffer, frames_to_read);
#endif /* ALSA_AVAILABLE */

        if (frames_read < 0) {
            fprintf(stderr, "Error: failed to read audio data.\n");
            break;
        }

        /* Calculate the RMS amplitude */
        amplitude = 0.0;
        for (int i = 0; i < frames_read; i++) {
            amplitude += (double)buffer[i] * (double)buffer[i];
        }
        amplitude = sqrt(amplitude / (double)frames_read);

        /* Map the amplitude to RGB values */
        map_amplitude_to_rgb(amplitude, sensitivity, &red, &green, &blue);

        /* Set the PWM duty cycle values for the RGB LED */
        if (set_pwm_duty_cycle(RED_PIN, red) < 0 ||
            set_pwm_duty_cycle(GREEN_PIN, green) < 0 ||
            set_pwm_duty_cycle(BLUE_PIN, blue) < 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
            break;
        }

        /* Free the buffer */
        free(buffer);
        buffer = NULL;

        /* Delay for 100 milliseconds */
        gpioDelay(100000);
    }

    /* Cleanup */
#ifdef ALSA_AVAILABLE
    alsa_close(&alsa_ctx);
#endif /* ALSA_AVAILABLE */

    /* Turn off the LED */
    set_pwm_duty_cycle(RED_PIN, 0);
    set_pwm_duty_cycle(GREEN_PIN, 0);
    set_pwm_duty_cycle(BLUE_PIN, 0);

    /* Terminate pigpio */
    gpioTerminate();

    printf("Mood light stopped.\n");

    return EXIT_SUCCESS;
}

