#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (read_reg(reg_low, &low) < 0) return -1;
    if (read_reg(reg_low + 1, &high) < 0) return -1;
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

static int init_sensor(void) {
    if (write_reg(TCS34725_ENABLE, 0x03) < 0) return -1;
    if (write_reg(TCS34725_ATIME, 0xD5) < 0) return -1;
    return 0;
}

static int read_sensor_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_word(TCS34725_CDATAL, clear) < 0) return -1;
    if (read_word(TCS34725_RDATAL, red) < 0) return -1;
    if (read_word(TCS34725_GDATAL, green) < 0) return -1;
    if (read_word(TCS34725_BDATAL, blue) < 0) return -1;
    return 0;
}

static void log_data(time_t timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(log_file, "%ld,%u,%u,%u,%u\n", (long)timestamp, clear, red, green, blue);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("color_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        uint16_t clear = 0, red = 0, green = 0, blue = 0;
        time_t current_time = time(NULL);

        if (read_sensor_data(&clear, &red, &green, &blue) == 0) {
            log_data(current_time, clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data, logging zeros\n");
            log_data(current_time, 0, 0, 0, 0);
        }

        gpioDelay(500000);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

