void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void set_all_lamps(int value) {
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], value);
        }
    }
}

void sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000L;
    nanosleep(&ts, NULL);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", lamp_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "sunrise-simulator", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", lamp_pins[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    printf("Sunrise/Sunset Lighting Simulator started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Sunrise: gradual increase in brightness over 1 hour
        for (int step = 0; step <= PWM_STEPS && keep_running; step++) {
            float duty = (float)step / PWM_STEPS;
            for (int i = 0; i < NUM_LAMPS; i++) {
                gpiod_line_set_value(lines[i], (duty > 0.0f) ? 0 : 1);
            }
            sleep_ms(PWM_DELAY_US);
        }

        // Daytime: full brightness for 6 hours
        for (int i = 0; i < 6 * 60 * 60 * 1000 / PWM_DELAY_US && keep_running; i++) {
            for (int i = 0; i < NUM_LAMPS; i++) {
                gpiod_line_set_value(lines[i], 0);
            }
            sleep_ms(PWM_DELAY_US);
        }

        // Sunset: gradual decrease in brightness over 1 hour
        for (int step = PWM_STEPS; step >= 0 && keep_running; step--) {
            float duty = (float)step / PWM_STEPS;
            for (int i = 0; i < NUM_LAMPS; i++) {
                gpiod_line_set_value(lines[i], (duty > 0.0f) ? 0 : 1);
            }
            sleep_ms(PWM_DELAY_US);
        }

        // Nighttime: off for 14.4 hours
        for (int i = 0; i < 14 * 60 * 60 * 1000 / PWM_DELAY_US && keep_running; i++) {
            for (int i = 0; i < NUM_LAMPS; i++) {
                gpiod_line_set_value(lines[i], 1);
            }
            sleep_ms(PWM_DELAY_US);
        }
    }

    // Cleanup
    set_all_lamps(1);
    for (int i = 0; i < NUM_LAMPS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

