#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION 5
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int get_timestamp(char *timestamp, size_t max_len) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return -1;
    }

    if (strftime(timestamp, max_len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        return -1;
    }
    return 0;
}

int record_video(const char *timestamp) {
    char command[512];
    int ret;

    snprintf(command, sizeof(command), "raspivid -o %s%s.h264 -t %d000", VIDEO_DIR, timestamp, VIDEO_DURATION);
    ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Error executing raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (WIFEXITED(ret) && WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    }
    if (WIFSIGNALED(ret)) {
        fprintf(stderr, "raspivid killed by signal %d\n", WTERMSIG(ret));
        return -1;
    }
    return 0;
}

int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }
    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    int last_state = 1; // Assume no motion initially (active low)
    char timestamp[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up for active-low sensor

    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(MOTION_SENSOR_GPIO);

        if (current_state == 0 && last_state == 1) { // Motion detected (active low)
            if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                printf("Motion detected at %s\n", timestamp);

                if (record_video(timestamp) != 0) {
                    fprintf(stderr, "Failed to record video\n");
                }

                if (log_motion_event(timestamp) != 0) {
                    fprintf(stderr, "Failed to log motion event\n");
                }
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }

            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }

        last_state = current_state;
        gpioDelay(10000); // Check every 10 ms
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

