#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

// GPIO pin for alarm
#define ALARM_GPIO 27

// Freefall threshold in g
#define FREEFALL_THRESHOLD 0.2f

// Freefall duration in seconds
#define FREEFALL_DURATION 0.5f

// Scale factor for ±2g range (256 LSB/g)
#define SCALE_FACTOR 256.0f

// I2C handle
int i2c_handle;

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_adxl345(int handle);
int read_accelerometer(int handle, float *x, float *y, float *z);
int detect_freefall(float x, float y, float z, float threshold, float duration);
void trigger_alarm(int gpio_pin);
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize ADXL345
int init_adxl345(int handle) {
    // Set data format: ±2g range, full resolution, right-justified
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int handle, float *x, float *y, float *z) {
    char buffer[6];

    // Read 6 bytes starting from DATAX0
    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes (little-endian)
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g-force
    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;

    return 0;
}

// Detect freefall event
int detect_freefall(float x, float y, float z, float threshold, float duration) {
    // Check if all axes are below threshold
    if (fabs(x) < threshold && fabs(y) < threshold && fabs(z) < threshold) {
        // Wait for duration
        time_sleep(duration);

        // Read again to confirm
        float x2, y2, z2;
        if (read_accelerometer(i2c_handle, &x2, &y2, &z2) < 0) {
            return 0; // Error reading, treat as not freefall
        }

        // Check if all axes are still below threshold
        if (fabs(x2) < threshold && fabs(y2) < threshold && fabs(z2) < threshold) {
            return 1; // Freefall confirmed
        }
    }

    return 0; // No freefall
}

// Trigger alarm
void trigger_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    time_sleep(5.0);       // Wait 5 seconds
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Log freefall event to file
void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            // Detect freefall
            if (detect_freefall(x, y, z, FREEFALL_THRESHOLD, FREEFALL_DURATION)) {
                printf("Freefall detected!\n");
                trigger_alarm(ALARM_GPIO);
                log_freefall(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        time_sleep(0.1); // Delay 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

