#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_PULSE_US 10
#define MEASUREMENT_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 100000
#define MAX_DISTANCE_CM 400.0f
#define MAX_PULSE_WIDTH_US 23200

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int measurement_ready = 0;
static FILE *log_file = NULL;
static pthread_mutex_t data_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t running = 1;

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_rising_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    }
}

static void echo_falling_callback(int gpio, int level, uint32_t tick) {
    if (level == 0 && echo_received) {
        end_tick = tick;
        measurement_ready = 1;
        echo_received = 0;
    }
}

static float calculate_distance(uint32_t pulse_width_us) {
    float distance = (float)pulse_width_us * 0.01715f;
    if (distance > MAX_DISTANCE_CM) {
        distance = MAX_DISTANCE_CM;
    }
    return distance;
}

static void log_distance(float distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    pthread_mutex_lock(&data_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance);
        fflush(log_file);
    }
    pthread_mutex_unlock(&data_mutex);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set rising edge ISR\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_falling_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set falling edge ISR\n");
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        measurement_ready = 0;
        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (!measurement_ready && running) {
            if (gpioTick() - start_wait > ECHO_TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (!running) {
            break;
        }

        if (!measurement_ready) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;
        if (pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
            continue;
        }

        float distance = calculate_distance(pulse_width);
        log_distance(distance);
        printf("Distance: %.2f cm\n", distance);

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, NULL, NULL);
    pthread_mutex_lock(&data_mutex);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&data_mutex);
    gpioTerminate();
    pthread_mutex_destroy(&data_mutex);

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

