#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L   0x28

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default thresholds (g)
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f

// Sensitivity for +/- 2g range (16384 LSB/g)
#define SENSITIVITY 16384.0f

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;
float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

// Function prototypes
int init_i2c(void);
int init_lis3dh(void);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void detect_freefall(float magnitude);
void detect_impact(float magnitude);
void activate_buzzer(void);
void cleanup(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH accelerometer
int init_lis3dh(void) {
    // Enable accelerometer: 100 Hz data rate, normal mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full scale to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (result == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0;
        } else {
            fprintf(stderr, "Error reading acceleration data (attempt %d): %d\n", 4 - retries, result);
            retries--;
            gpioDelay(10000); // 10ms delay before retry
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1;
}

// Calculate acceleration magnitude in g
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SENSITIVITY;
    float y_g = (float)y / SENSITIVITY;
    float z_g = (float)z / SENSITIVITY;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detect freefall
void detect_freefall(float magnitude) {
    if (magnitude < freefall_threshold) {
        printf("Freefall detected!\n");
    }
}

// Detect impact
void detect_impact(float magnitude) {
    if (magnitude > impact_threshold) {
        printf("Impact detected!\n");
        activate_buzzer();
    }
}

// Activate buzzer
void activate_buzzer(void) {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait for 1 second (1,000,000 microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (argc > 2) {
            impact_threshold = atof(argv[2]);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin mode for buzzer
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Fall detection system started. Press Ctrl+C to exit.\n");
    printf("Freefall threshold: %.2f g, Impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    // Main loop
    while (program_running) {
        int16_t x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            detect_freefall(magnitude);
            detect_impact(magnitude);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Skipping detection.\n");
        }

        gpioDelay(10000); // Delay for 10ms (10,000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

