    gpioWrite(MOTOR1_IN3, 0); gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0); gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0); gpioWrite(MOTOR2_IN4, 0);

    gpioTerminate();
    return 0;
}

