#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000

#define LIS3DH_REG_CTRL_REG1 0x20
#define LIS3DH_REG_CTRL_REG4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(int address) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", address, i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* CTRL_REG1: 100 Hz ODR, all axes enabled, normal mode */
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* CTRL_REG4: ±2g full scale, high-resolution mode (12-bit left-justified) */
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0f;
        *y = 0.0f;
        *z = 0.0f;
        return -1;
    }

    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* 12-bit left-justified: shift right 4 bits */
    raw_x >>= 4;
    raw_y >>= 4;
    raw_z >>= 4;

    /* ±2g full scale: 1 mg/LSB = 0.001 g/LSB */
    *x = (float)raw_x * 0.001f;
    *y = (float)raw_y * 0.001f;
    *z = (float)raw_z * 0.001f;

    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - High acceleration detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n", timestamp, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;

    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X (must be 0x08-0x77)\n", i2c_address);
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold: %.2f (must be greater than 0)\n", threshold);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_i2c(i2c_address) != 0) {
        return 1;
    }

    printf("Monitoring acceleration on LIS3DH at 0x%02X... (threshold: %.2f g)\n", i2c_address, threshold);
    fflush(stdout);

    float x, y, z;
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

