#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define POLL_INTERVAL_MS 10
#define ALERT_DURATION_MS 2000

#define CONSUMER "line_follower"

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
        alert_line = NULL;
    }
    if (right_line) {
        gpiod_line_release(right_line);
        right_line = NULL;
    }
    if (center_line) {
        gpiod_line_release(center_line);
        center_line = NULL;
    }
    if (left_line) {
        gpiod_line_release(left_line);
        left_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    if (gpiod_line_request_input(left_line, CONSUMER) < 0 ||
        gpiod_line_request_input(center_line, CONSUMER) < 0 ||
        gpiod_line_request_input(right_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request input lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(alert_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request output line: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void add_to_buffer(CircularBuffer *buffer, SensorData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

static void check_line_loss(CircularBuffer *buffer) {
    if (buffer->count < BUFFER_SIZE) {
        return;
    }
    int all_no_line = 1;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer->data[i].center == 0) {
            all_no_line = 0;
            break;
        }
    }
    if (all_no_line) {
        printf("Line lost! Activating alert.\n");
        if (gpiod_line_set_value(alert_line, 1) < 0) {
            fprintf(stderr, "Failed to set alert HIGH: %s\n", strerror(errno));
        }
        usleep(ALERT_DURATION_MS * 1000);
        if (gpiod_line_set_value(alert_line, 0) < 0) {
            fprintf(stderr, "Failed to set alert LOW: %s\n", strerror(errno));
        }
    }
}

static void move_forward(void) {
    printf("Moving forward\n");
}

static void turn_left(void) {
    printf("Turning left\n");
}

static void turn_right(void) {
    printf("Turning right\n");
}

static void stop_robot(void) {
    printf("Stopping\n");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    CircularBuffer buffer = {0};

    while (running) {
        SensorData data;
        data.left = read_sensor(left_line);
        data.center = read_sensor(center_line);
        data.right = read_sensor(right_line);

        if (data.left < 0 || data.center < 0 || data.right < 0) {
            fprintf(stderr, "Sensor read error, continuing...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        add_to_buffer(&buffer, data);
        check_line_loss(&buffer);

        if (data.center == 0) {
            move_forward();
        } else if (data.left == 0) {
            turn_left();
        } else if (data.right == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    printf("Program terminated cleanly.\n");
    return 0;
}

