#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD_MT 5.0f
#define SAMPLE_INTERVAL_US 100000
#define POLL_TIMEOUT_MS 50
#define POLL_DELAY_US 1000

#define SI7210_REG_MEAS_CTRL 0xC1
#define SI7210_REG_FIELD_LSB 0xC0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("fopen magnetic_events.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

static int read_field_raw(int16_t *raw_out) {
    if (i2cWriteByteData(i2c_handle, SI7210_REG_MEAS_CTRL, 0x01) < 0) {
        log_event("Error: failed to start measurement");
        return -1;
    }

    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        int status = i2cReadByteData(i2c_handle, SI7210_REG_MEAS_CTRL);
        if (status < 0) {
            log_event("Error: failed to read measurement status");
            return -1;
        }
        if (status == 0x00) {
            break;
        }
        gpioDelay(POLL_DELAY_US);
        if (i == POLL_TIMEOUT_MS - 1) {
            log_event("Error: measurement timeout");
            return -1;
        }
    }

    int lsb = i2cReadByteData(i2c_handle, SI7210_REG_FIELD_LSB);
    if (lsb < 0) {
        log_event("Error: failed to read field LSB");
        return -1;
    }

    int msb = i2cReadByteData(i2c_handle, SI7210_REG_FIELD_LSB + 1);
    if (msb < 0) {
        log_event("Error: failed to read field MSB");
        return -1;
    }

    *raw_out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("Error: failed to write relay GPIO");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", SI7210_ADDR, i2c_handle);
        log_event("Error: I2C open failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_event("Error: failed to set relay GPIO mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_relay(0) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        int16_t raw;
        if (read_field_raw(&raw) < 0) {
            control_relay(0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int16_t field_mt_x100 = (raw * 25) / 1000;
        float field_mt = field_mt_x100 / 100.0f;

        char msg[128];
        snprintf(msg, sizeof(msg), "Field: %.2f mT (raw=%d)", field_mt, raw);
        log_event(msg);

        if (field_mt_x100 > (int16_t)(FIELD_THRESHOLD_MT * 100)) {
            if (control_relay(1) == 0) {
                log_event("Relay activated");
            }
        } else {
            if (control_relay(0) == 0) {
                log_event("Relay deactivated");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program shutting down");
    control_relay(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

