#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x08
#define SENSOR2_ADDR   0x09
#define RELAY_GPIO     18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US  100000
#define LOG_FILE       "flow_log.txt"
#define FLOW_SCALE     1500.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_sensor(int handle) {
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to send start-measurement command to handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed on handle %d (got %d bytes)\n", handle, bytes_read);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / FLOW_SCALE;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", state);
    }
}

static void log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for appending\n", LOG_FILE);
        return;
    }
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
                tbuf, ts.tv_nsec / 1000000, flow1, flow2);
    } else {
        fprintf(fp, "(timestamp error), Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
                flow1, flow2);
    }
    fflush(fp);
    fclose(fp);
}

static void cleanup(void) {
    control_relay(0);
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
