/*
 * Rain-actuated window controller for Raspberry Pi 5
 * Library : pigpio (modern, actively maintained)
 *
 * Wiring
 *   Rain sensor DO  -> GPIO 17 (BCM), internal pull-up enabled
 *   L298N ENA       -> GPIO 22 (BCM)
 *   L298N IN1       -> GPIO 23 (BCM)
 *   L298N IN2       -> GPIO 24 (BCM)
 *
 * Behavior
 *   Polls GPIO 17 every 200 ms.  When it reads LOW (rain detected),
 *   drives the window motor for 5 s and then stops.  Only triggers
 *   on a dry-to-wet transition; rain persists for at least 3 polls
 *   (600 ms) before re-triggering.  Graceful shutdown on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_THRESHOLD     3        /* 3 polls = 600 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers with error checking                                     */
/* ------------------------------------------------------------------ */
static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        syslog(LOG_ERR, "gpioSetMode(pin=%u, mode=%u) failed", pin, mode);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Motor control                                                       */
/* ------------------------------------------------------------------ */
static int motor_stop(void)
{
    if (safe_write(MOTOR_ENA_PIN, 0) != 0)
        return -1;
    if (safe_write(MOTOR_IN1_PIN, 0) != 0)
        return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) != 0)
        return -1;
    syslog(LOG_INFO, "Motor stopped");
    return 0;
}

static int motor_close(void)
{
    if (safe_write(MOTOR_ENA_PIN, 1) != 0)
        return -1;
    if (safe_write(MOTOR_IN1_PIN, 1) != 0)
        return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) != 0)
        return -1;
    syslog(LOG_INFO, "Motor closing window");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop();
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialised");

    /* ---- GPIO configuration ---- */
    if (safe_set_mode(RAIN_SENSOR_PIN, PI_INPUT) != 0)
        goto fail;
    if (safe_set_mode(MOTOR_ENA_PIN, PI_OUTPUT) != 0)
        goto fail;
    if (safe_set_mode(MOTOR_IN1_PIN, PI_OUTPUT) != 0)
        goto fail;
    if (safe_set_mode(MOTOR_IN2_PIN, PI_OUTPUT) != 0)
        goto fail;

    /* Internal pull-up so the sensor line is defined when dry */
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(pin=%d) failed", RAIN_SENSOR_PIN);
        goto fail;
    }

    /* Ensure motor is off at start */
    if (motor_stop() != 0)
        goto fail;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        goto fail;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        goto fail;
    }

    syslog(LOG_INFO, "Rain-actuated window controller started");

    int dry_count = 0;
    int last_rain = gpioRead(RAIN_SENSOR_PIN);
    if (last_rain < 0) {
        syslog(LOG_ERR, "Initial gpioRead(pin=%d) failed", RAIN_SENSOR_PIN);
        goto fail;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(pin=%d) failed", RAIN_SENSOR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Rising edge: dry -> wet */
        if (rain == 0 && last_rain == 1) {
            dry_count = 0;
            syslog(LOG_INFO, "Rain detected (DO LOW)");

            if (motor_close() != 0) {
                syslog(LOG_ERR, "Failed to start motor close sequence");
            } else {
                /* Hold motor for 5 s, checking for shutdown */
                uint32_t elapsed = 0;
                while (g_running && elapsed < MOTOR_RUN_US) {
                    gpioDelay(POLL_INTERVAL_US);
                    elapsed += POLL_INTERVAL_US;
                }

                if (motor_stop() != 0) {
                    syslog(LOG_ERR, "Failed to stop motor after run");
                }
            }
        }

        /* Count consecutive dry polls */
        if (rain == 1) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                syslog(LOG_INFO, "Dry for %d polls (%d ms), re-arming",
                       DRY_THRESHOLD, DRY_THRESHOLD * POLL_INTERVAL_US / 1000);
                dry_count = 0;
            }
        }

        last_rain = rain;
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;

fail:
    syslog(LOG_ERR, "Initialization failed, exiting");
    cleanup();
    return EXIT_FAILURE;
}

