#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define FLOODLIGHT_DURATION_SEC 60
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *event_type, double duration) {
    FILE *fp = fopen("security_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening security_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (strcmp(event_type, "activation") == 0) {
        if (fprintf(fp, "%s - Floodlight activated\n", timestamp) < 0) {
            fprintf(stderr, "Error writing to security_log.txt: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    } else if (strcmp(event_type, "deactivation") == 0) {
        if (fprintf(fp, "%s - Floodlight deactivated (Duration: %.2f seconds)\n", timestamp, duration) < 0) {
            fprintf(stderr, "Error writing to security_log.txt: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    } else {
        fprintf(stderr, "Invalid event type: %s\n", event_type);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing security_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int control_floodlight(int state) {
    if (gpioWrite(FLOODLIGHT_PIN, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", FLOODLIGHT_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_floodlight(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    int pir_state = 0;
    int floodlight_active = 0;
    time_t floodlight_start_time = 0;

    while (running) {
        int current_pir_state = gpioRead(PIR_PIN);
        if (current_pir_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", PIR_PIN);
            break;
        }

        if (current_pir_state == 1 && pir_state == 0) {
            printf("Motion detected!\n");

            if (control_floodlight(1) != 0) {
                break;
            }
            floodlight_active = 1;
            floodlight_start_time = time(NULL);

            if (log_event("activation", 0.0) != 0) {
                control_floodlight(0);
                break;
            }
        } else if (current_pir_state == 0 && pir_state == 1) {
            if (floodlight_active) {
                time_t floodlight_end_time = time(NULL);
                double duration = difftime(floodlight_end_time, floodlight_start_time);

                if (control_floodlight(0) != 0) {
                    break;
                }
                floodlight_active = 0;

                if (log_event("deactivation", duration) != 0) {
                    break;
                }

                printf("Floodlight deactivated. Duration: %.2f seconds\n", duration);
            }
        }

        pir_state = current_pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_floodlight(0);
    gpioTerminate();
    printf("Smart Security Light System stopped.\n");

    return EXIT_SUCCESS;
}

