        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Baseline filtering: rising */
    if (mpr121_write_reg(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_R, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (mpr121_write_reg(MPR121_E0TTH, 0x0C) < 0) return -1;
    if (mpr121_write_reg(MPR121_E0TTH + 1, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6 samples, CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    /* SFI=4 samples, ESI=4 ms */
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Auto-config: enable, 16 µA charge current, 0.5 µs charge time */
    if (mpr121_write_reg(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 0xB4) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write_reg(MPR121_ECR, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int rc = i2cReadWordData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (rc < 0) {
        fprintf(stderr, "Error reading touch status: %d\n", rc);
        return -1;
    }
    *status = (uint16_t)rc;
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 initialized. Relay on GPIO%d. Touch electrode 0 to toggle.\n", RELAY_GPIO);

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        int current_touch = (touch_status & 0x0001) ? 1 : 0;

        if (current_touch && !last_touch) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        last_touch = current_touch;
        gpioDelay(20000); /* 20 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

