#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <stdarg.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define SERVO_PERIOD_US 20000
#define SERVO_PULSE_STEP_US 10
#define SERVO_STEP_DELAY_US 1000
#define SERVO_STOP_DELAY_US 1000000
#define PIR_DEBOUNCE_US 100000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t servo_thread;
static pthread_mutex_t servo_mutex = PTHREAD_MUTEX_INITIALIZER;
static int servo_angle = 0;
static int servo_pulse_width = 0;
static int pir_state = 0;
static int pir_last_state = 0;
static struct timespec pir_last_change = {0, 0};

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    syslog(priority, format, args);
    va_end(args);
    if (log_fp) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_fp, "%s: ", timestamp);
        va_start(args, format);
        vfprintf(log_fp, format, args);
        va_end(args);
        fprintf(log_fp, "\n");
        fflush(log_fp);
    }
}

static void cleanup(void) {
    running = 0;
    if (servo_line) {
        pthread_mutex_lock(&servo_mutex);
        servo_pulse_width = 0;
        pthread_mutex_unlock(&servo_mutex);
        pthread_join(servo_thread, NULL);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    closelog();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo_pwm", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void *servo_pwm_thread(void *arg) {
    (void)arg;
    while (running) {
        pthread_mutex_lock(&servo_mutex);
        int pw = servo_pulse_width;
        pthread_mutex_unlock(&servo_mutex);
        if (pw > 0) {
            gpiod_line_set_value(servo_line, 1);
            usleep(pw);
            gpiod_line_set_value(servo_line, 0);
            usleep(SERVO_PERIOD_US - pw);
        } else {
            usleep(10000);
        }
    }
    return NULL;
}

static void set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    servo_angle = angle;
    servo_pulse_width = SERVO_MIN_PULSE_WIDTH +
        (angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)) / SERVO_MAX_ANGLE;
    pthread_mutex_lock(&servo_mutex);
    servo_pulse_width = servo_pulse_width;
    pthread_mutex_unlock(&servo_mutex);
}

static void *handle_client(void *arg) {
    int client_fd = *(int *)arg;
    free(arg);
    char buffer[1024];
    ssize_t n;
    while ((n = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[n] = '\0';
        char *cmd = strtok(buffer, "\r\n");
        while (cmd) {
            if (strncmp(cmd, "SERVO", 5) == 0) {
                int angle;
                if (sscanf(cmd, "SERVO %d", &angle) == 1) {
                    set_servo_angle(angle);
                    log_message(LOG_INFO, "Servo set to angle: %d", angle);
                    send(client_fd, "OK\n", 3, 0);
                } else {
                    send(client_fd, "Invalid servo command\n", 22, 0);
                }
            } else if (strcmp(cmd, "PIR") == 0) {
                char response[16];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_state);
                send(client_fd, response, strlen(response), 0);
            } else {
                send(client_fd, "Invalid command\n", 16, 0);
            }
            cmd = strtok(NULL, "\r\n");
        }
    }
    if (n < 0) {
        log_message(LOG_WARNING, "Client socket error: %s", strerror(errno));
    }
    close(client_fd);
    return NULL;
}

static void *pir_sensor_thread(void *arg) {
    (void)arg;
    while (running) {
        int val = gpiod_line_get_value(pir_line);
        if (val < 0) {
            log_message(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            usleep(100000);
            continue;
        }
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_us = (now.tv_sec - pir_last_change.tv_sec) * 1000000L +
                          (now.tv_nsec - pir_last_change.tv_nsec) / 1000L;
        if (val != pir_last_state && elapsed_us > PIR_DEBOUNCE_US) {
            pir_state = val;
            pir_last_state = val;
            pir_last_change = now;
            log_message(LOG_INFO, "PIR sensor triggered: %d", pir_state);
        }
        usleep(10000);
    }
    return NULL;
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }
    if (init_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }
    if (pthread_create(&servo_thread, NULL, servo_pwm_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create servo thread: %s", strerror(errno));
        cleanup();
        return 1;
    }
    if (pthread_create(&servo_thread, NULL, pir_sensor_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create PIR thread: %s", strerror(errno));
        cleanup();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_ERR, "setsockopt failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed: %s", strerror(errno));
        cleanup();
        return 1;
    }
    log_message(LOG_INFO, "Server listening on port %d", PORT);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (new_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_WARNING, "Accept failed: %s", strerror(errno));
            continue;
        }
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        log_message(LOG_INFO, "Connection from %s", client_ip);
        int *fd_ptr = malloc(sizeof(int));
        if (!fd_ptr) {
            log_message(LOG_ERR, "Memory allocation failed");
            close(new_socket);
            continue;
        }
        *fd_ptr = new_socket;
        pthread_t client_thread;
        if (pthread_create(&client_thread, NULL, handle_client, fd_ptr) != 0) {
            log_message(LOG_ERR, "Failed to create client thread: %s", strerror(errno));
            free(fd_ptr);
            close(new_socket);
        } else {
            pthread_detach(client_thread);
        }
    }
    log_message(LOG_INFO, "Shutting down...");
    cleanup();
    return 0;
}

