#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_CONV_TIME_MS 120
#define SAMPLE_INTERVAL_MS 2000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %s\n",
                BH1750_ADDR, I2C_BUS, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    char buf[2];
    int result;

    result = i2cWriteByte(i2c_handle, BH1750_ONE_TIME_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Failed to write measurement command to BH1750: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read 2 bytes from BH1750 (got %d): %s\n",
                result, result < 0 ? strerror(errno) : "short read");
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    control_relay(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;

        if (read_bh1750(&lux) == 0) {
            log_data(lux);

            if (lux < LUX_THRESHOLD) {
                control_relay(1);
                printf("Lux: %.2f < %.2f. Grow light ON.\n", lux, LUX_THRESHOLD);
            } else {
                control_relay(0);
                printf("Lux: %.2f >= %.2f. Grow light OFF.\n", lux, LUX_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Failed to read lux value. Retrying in %d ms...\n", SAMPLE_INTERVAL_MS);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

