#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define DEFAULT_THRESHOLD 1000.0f
#define DEFAULT_SCALE     1000.0f
#define DEFAULT_DURATION  200
#define NUM_READINGS      5
#define TARE_READINGS     10
#define MAX_RETRIES       3
#define DOUT_TIMEOUT_US   1000000
#define POLL_INTERVAL_US  500000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *out) {
    uint32_t value = 0;
    int timeout = DOUT_TIMEOUT_US;

    while (gpiod_line_get_value(dout) == 1) {
        if (timeout <= 0) {
            syslog(LOG_ERR, "HX711 DOUT timeout: sensor not ready");
            return -1;
        }
        usleep(10);
        timeout -= 10;
    }

    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK high");
            return -1;
        }
        usleep(1);
        value <<= 1;
        if (gpiod_line_get_value(dout) == 1) {
            value |= 1;
        }
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK low");
            return -1;
        }
        usleep(1);
    }

    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK high (25th pulse)");
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low (25th pulse)");
        return -1;
    }
    usleep(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out = (int32_t)value;
    return 0;
}

static int32_t read_hx711_average(struct gpiod_line *dout, struct gpiod_line *sck, int num_readings) {
    int32_t sum = 0;
    int valid = 0;
    for (int i = 0; i < num_readings; i++) {
        int32_t val;
        if (read_hx711(dout, sck, &val) == 0) {
            sum += val;
            valid++;
        } else {
            syslog(LOG_WARNING, "HX711 read failed, retrying...");
        }
        usleep(1000);
    }
    if (valid == 0) {
        syslog(LOG_ERR, "All HX711 reads failed");
        return 0;
    }
    return sum / valid;
}

static float calculate_weight(int32_t raw, float tare_offset, float scale) {
    return (float)(raw - tare_offset) / scale;
}

static void control_solenoid(struct gpiod_line *solenoid, bool activate) {
    if (gpiod_line_set_value(solenoid, activate ? 1 : 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid %s", activate ? "HIGH" : "LOW");
    } else {
        syslog(LOG_INFO, "Solenoid %s", activate ? "activated" : "deactivated");
    }
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    float scale = DEFAULT_SCALE;
    int duration_ms = DEFAULT_DURATION;

    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting load cell monitor (threshold=%.2f, scale=%.2f, duration=%d ms)",
           threshold, scale, duration_ms);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);

    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output");
        goto cleanup;
    }

    syslog(LOG_INFO, "Taring...");
    int32_t tare_offset = 0;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        tare_offset = read_hx711_average(dout, sck, TARE_READINGS);
        if (tare_offset != 0) {
            syslog(LOG_INFO, "Tare offset: %d", tare_offset);
            break;
        }
        syslog(LOG_WARNING, "Tare failed, retrying...");
        retries++;
        usleep(100000);
    }
    if (tare_offset == 0) {
        syslog(LOG_ERR, "Tare failed after %d retries", MAX_RETRIES);
        goto cleanup;
    }

    syslog(LOG_INFO, "Monitoring weight (threshold=%.2f grams, scale=%.2f, duration=%d ms)...",
           threshold, scale, duration_ms);

    while (program_running) {
        int32_t raw = read_hx711_average(dout, sck, NUM_READINGS);
        float weight = calculate_weight(raw, tare_offset, scale);

        syslog(LOG_INFO, "Raw: %d, Weight: %.2f grams", raw, weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(solenoid, true);
            usleep(duration_ms * 1000);
            control_solenoid(solenoid, false);
        }

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down...");
    control_solenoid(solenoid, false);
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(solenoid);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

