/*
 * MQTT Relay Controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control and drives a relay on GPIO17 (BCM 17,
 * physical pin 11) HIGH for "ON" and LOW for "OFF".
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *       -lmosquitto -lpigpio -lrt
 *
 * Run:
 *   sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_TOPIC          "home/lights/control"
#define MQTT_QOS            0
#define MQTT_KEEPALIVE      60
#define MQTT_CLEAN_SESSION  true

#define GPIO_PIN            17          /* BCM 17, physical pin 11 */
#define RELAY_ON            1
#define RELAY_OFF           0

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */
static void log_info(const char *msg)
{
    syslog(LOG_INFO, "%s", msg);
}

static void log_error(const char *msg)
{
    syslog(LOG_ERR, "%s", msg);
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;

    if (result == MOSQ_ERR_SUCCESS) {
        log_info("Connected to MQTT broker.");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            char buf[128];
            snprintf(buf, sizeof(buf),
                     "Failed to subscribe to %s (rc=%d: %s)",
                     MQTT_TOPIC, rc, mosquitto_strerror(rc));
            log_error(buf);
        } else {
            log_info("Subscribed to home/lights/control (QoS 0).");
        }
    } else {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "MQTT connect failed (rc=%d: %s)",
                 result, mosquitto_connack_string(result));
        log_error(buf);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;

    if (rc != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Unexpected MQTT disconnect (rc=%d: %s)",
                 rc, mosquitto_strerror(rc));
        log_error(buf);
    } else {
        log_info("Disconnected from MQTT broker.");
    }
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message == NULL || message->payload == NULL || message->payloadlen <= 0) {
        log_error("Empty MQTT message received.");
        return;
    }

    /* Ensure payload is NUL-terminated for safe string operations */
    char payload[32];
    size_t len = (size_t)message->payloadlen;
    if (len >= sizeof(payload)) {
        len = sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    log_info(payload);

    if (strcmp(payload, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, RELAY_ON) != 0) {
            log_error("Failed to set GPIO17 HIGH (relay ON).");
        } else {
            log_info("Relay ON (GPIO17 HIGH).");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, RELAY_OFF) != 0) {
            log_error("Failed to set GPIO17 LOW (relay OFF).");
        } else {
            log_info("Relay OFF (GPIO17 LOW).");
        }
    } else {
        log_error("Invalid payload received. Expected ON or OFF.");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mosq != NULL) {
        mosquitto_loop_stop(g_mosq, false);
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();

    /* Ensure relay is OFF before terminating pigpio */
    gpioWrite(GPIO_PIN, RELAY_OFF);
    gpioTerminate();

    closelog();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed.");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO17 as output.");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_PIN, RELAY_OFF) != 0) {
        log_error("Failed to initialise GPIO17 LOW (relay OFF).");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_info("Relay controller started. GPIO17 (BCM) initialised LOW.");

    /* --- mosquitto init --- */
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, MQTT_CLEAN_SESSION, NULL);
    if (g_mosq == NULL) {
        log_error("Failed to create mosquitto client.");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                              MQTT_BROKER_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to connect to MQTT broker (rc=%d: %s).",
                 rc, mosquitto_strerror(rc));
        log_error(buf);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to register SIGINT handler.");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to register SIGTERM handler.");
    }

    /* --- main loop --- */
    rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Failed to start mosquitto loop (rc=%d: %s).",
                 rc, mosquitto_strerror(rc));
        log_error(buf);
        cleanup();
        return EXIT_FAILURE;
    }

    log_info("Entering main loop. Press Ctrl+C to exit.");

    while (g_running) {
        sleep(1);
    }

    log_info("Shutting down gracefully.");
    cleanup();
    return EXIT_SUCCESS;
}

