#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO_PIN_1 7
#define SERVO_PIN_2 8
#define SERVO_PIN_3 9
#define SERVO_PIN_4 10
#define SERVO_PIN_5 11

#define SERVO_FREQUENCY 50
#define SERVO_RANGE 20000

#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500

#define SERVO_MOVE_DELAY_MS 3000

int main(void) {
    int pins[] = {SERVO_PIN_1, SERVO_PIN_2, SERVO_PIN_3, SERVO_PIN_4, SERVO_PIN_5};
    int positions[] = {1000, 1500, 2000, 500, 2500};
    int num_servos = sizeof(pins) / sizeof(pins[0]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPWMfrequency(pins[i], SERVO_FREQUENCY) != SERVO_FREQUENCY) {
            fprintf(stderr, "Warning: Failed to set PWM frequency on GPIO %d.\n", pins[i]);
        }

        if (gpioSetPWMrange(pins[i], SERVO_RANGE) != SERVO_RANGE) {
            fprintf(stderr, "Warning: Failed to set PWM range on GPIO %d.\n", pins[i]);
        }

        if (gpioServo(pins[i], positions[i]) != 0) {
            fprintf(stderr, "Error: Failed to start servo on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moving to positions. Holding for %d ms...\n", SERVO_MOVE_DELAY_MS);
    gpioDelay(SERVO_MOVE_DELAY_MS * 1000);

    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

