#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>

/* Motor A GPIO pins */
#define MOTOR_A_PWM_PIN  17
#define MOTOR_A_DIR_PIN  18

/* Motor B GPIO pins */
#define MOTOR_B_PWM_PIN  22
#define MOTOR_B_DIR_PIN  23

/* Encoder A GPIO pins */
#define ENCODER_A_A_PIN  4
#define ENCODER_A_B_PIN  5

/* Encoder B GPIO pins */
#define ENCODER_B_A_PIN  6
#define ENCODER_B_B_PIN  12

/* Encoder parameters */
#define ENCODER_TICKS_PER_REV 64.0
#define ENCODER_STALL_TIMEOUT_MS 2000

/* Control parameters */
#define TARGET_RPM 50.0
#define KP 0.5
#define KI 0.05
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define CONTROL_PERIOD_US 100000  /* 100 ms */

/* Global state */
static volatile sig_atomic_t running = 1;
static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;
static atomic_int encoder_a_last = 0;
static atomic_int encoder_b_last = 0;
static atomic_int encoder_a_stall_start = 0;
static atomic_int encoder_b_stall_start = 0;

/* Function prototypes */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static double calculate_rpm(int encoder_count, int last_count, uint32_t last_tick, uint32_t current_tick);
static double calculate_pid(double setpoint, double actual, double *integral, double *previous_error, double kp, double ki);
static void set_motor_speed(int motor_number, double speed);
static void stop_motors(void);
static void signal_handler(int signal);
static int initialize_gpio(void);
static void cleanup_gpio(void);

/* Encoder ISR for motor A */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)level;
    (void)user;
    atomic_fetch_add(&encoder_a_count, 1);
}

/* Encoder ISR for motor B */
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)level;
    (void)user;
    atomic_fetch_add(&encoder_b_count, 1);
}

/* Calculate RPM from encoder ticks */
static double calculate_rpm(int encoder_count, int last_count, uint32_t last_tick, uint32_t current_tick) {
    double delta_ticks = (double)(encoder_count - last_count);
    double delta_time = (double)(current_tick - last_tick) / 1000000.0;
    if (delta_time <= 0.0) {
        return 0.0;
    }
    double revolutions = delta_ticks / ENCODER_TICKS_PER_REV;
    return (revolutions / delta_time) * 60.0;
}

/* PID controller */
static double calculate_pid(double setpoint, double actual, double *integral, double *previous_error, double kp, double ki) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *previous_error;
    double output = kp * error + ki * (*integral);
    *previous_error = error;
    return output;
}

/* Set motor speed using PWM */
static void set_motor_speed(int motor_number, double speed) {
    int pwm_pin, dir_pin;
    if (motor_number == 1) {
        pwm_pin = MOTOR_A_PWM_PIN;
        dir_pin = MOTOR_A_DIR_PIN;
    } else if (motor_number == 2) {
        pwm_pin = MOTOR_B_PWM_PIN;
        dir_pin = MOTOR_B_DIR_PIN;
    } else {
