        cleanup();
        return 1;
    }

    printf("Smart Chicken Coop Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Control relay based on lux with hysteresis
            if (lux < DUSK_LUX && relay_state == 0) {
                relay_state = 1;
