#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define LOOP_DELAY_MS 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_state(int relay_state) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
        printf("[%s] Relay state: %s\n", timestamp, relay_state ? "ON" : "OFF");
        fflush(stdout);
    } else {
        fprintf(stderr, "Error: localtime_r failed\n");
    }
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_state(relay_state);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    while (running) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);

            int confirmed_touch = gpioRead(TOUCH_SENSOR_PIN);
            if (confirmed_touch < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d during debounce\n", TOUCH_SENSOR_PIN);
                break;
            }

            if (confirmed_touch == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d\n", RELAY_PIN);
                    break;
                }
                log_state(relay_state);
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off relay during shutdown\n");
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

