#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define DEBOUNCE_US 1000000
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_lpm(int pulses) {
    return ((double)pulses / PULSES_PER_LITER) * 60.0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        log_event("Shutting down...");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SOLENOID_GPIO, 1);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid GPIO %d as output\n", SOLENOID_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid GPIO %d to HIGH\n", SOLENOID_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    int solenoid_state = 1;
    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses);
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Flow rate: %.2f L/min", lpm);
        log_event(log_message);

        if (lpm > LPM_THRESHOLD && solenoid_state == 1) {
            if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
                solenoid_state = 0;
                log_event("Solenoid closed (flow exceeded threshold)");
            } else {
                log_event("Failed to close solenoid");
            }
        } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS) && solenoid_state == 0) {
            if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
                solenoid_state = 1;
                log_event("Solenoid opened (flow below threshold)");
            } else {
                log_event("Failed to open solenoid");
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

