#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define PWM_FREQUENCY  50          /* Hz  -> 20 ms period */
#define MIN_PULSE_US   500         /* 0 degrees   */
#define MAX_PULSE_US   2500        /* 180 degrees */
#define DEFAULT_ANGLE  90          /* degrees     */
#define STEP_SIZE      10          /* degrees     */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int angle_to_pulse_us(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;
    return MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US)) / 180;
}

static void restore_terminal(void)
{
    struct termios saved;
    if (tcgetattr(STDIN_FILENO, &saved) == 0) {
        tcsetattr(STDIN_FILENO, TCSANOW, &saved);
    }
}

int main(void)
{
    struct termios raw;
    int angle = DEFAULT_ANGLE;
    int pulse;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO18 for hardware PWM via pigpio --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set PWM frequency to 50 Hz --- */
    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, %d) failed.\n",
                SERVO_PIN, PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start with servo at 90 degrees --- */
    pulse = angle_to_pulse_us(angle);
    if (gpioServo(SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed.\n", SERVO_PIN, pulse);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo initialized at angle %d degrees (pulse %d us).\n",
           angle, pulse);
    fflush(stdout);

    /* --- Switch to raw terminal mode --- */
    if (tcgetattr(STDIN_FILENO, &raw) != 0) {
        perror("tcgetattr");
        gpioServo(SERVO_PIN, 0);   /* stop PWM */
        gpioTerminate();
        return EXIT_FAILURE;
    }
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN]  = 0;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        gpioServo(SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    /* --- Main loop --- */
    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            /* EOF on stdin only happens when the terminal is closed */
            break;
        }

        switch (c) {
        case '+':
            angle += STEP_SIZE;
            if (angle > 180) angle = 180;
            break;
        case '-':
            angle -= STEP_SIZE;
            if (angle < 0)   angle = 0;
            break;
        case 'q':
            g_running = 0;
            break;
        default:
            /* ignore all other characters */
            continue;
        }

        if (!g_running)
            break;

        pulse = angle_to_pulse_us(angle);
        if (gpioServo(SERVO_PIN, pulse) != 0) {
            fprintf(stderr, "Warning: gpioServo(%d, %d) failed.\n",
                    SERVO_PIN, pulse);
        }
        printf("Angle: %d degrees, Pulse: %d us\n", angle, pulse);
        fflush(stdout);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* stop PWM pulses */
    gpioTerminate();
    restore_terminal();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

