    if (fprintf(fp, "%s.%03ld,%.2f\n", timestamp, ts.tv_nsec / 1000000, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line, "conveyor-belt-rpm",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE_NAME, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring conveyor belt RPM on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec last_event_ts = {0, 0};
        int pulse_count = 0;
        int debounce_active = 0;
        struct timespec debounce_start_ts = {0, 0};

        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && program_running; i++) {
            struct timespec timeout = {0, 100000000}; /* 100 ms */
            int ev = gpiod_line_event_wait(line, &timeout);

            if (ev < 0) {
                if (errno == EINTR) {
                    continue;
                }
                fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
                goto cleanup;
            }

            if (ev == 0) {
                continue; /* timeout, no event */
            }

            struct gpiod_line_event event;
            if (gpiod_line_event_read(line, &event) != 0) {
                fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
                goto cleanup;
            }

            if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
                continue;
            }

            if (!debounce_active) {
                last_event_ts = event.ts;
                pulse_count++;
                debounce_active = 1;
                clock_gettime(CLOCK_MONOTONIC, &debounce_start_ts);
            } else {
                struct timespec elapsed;
                if (clock_gettime(CLOCK_MONOTONIC, &elapsed) != 0) {
                    fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                    goto cleanup;
                }

                long elapsed_ms = (elapsed.tv_sec - debounce_start_ts.tv_sec) * 1000L +
                                  (elapsed.tv_nsec - debounce_start_ts.tv_nsec) / 1000000L;

                if (elapsed_ms >= DEBOUNCE_MS) {
                    last_event_ts = event.ts;
                    pulse_count++;
                    debounce_active = 1;
                    clock_gettime(CLOCK_MONOTONIC, &debounce_start_ts);
                }
            }
        }

        if (!program_running) {
            break;
        }

        double rpm = (double)pulse_count / (double)SAMPLE_INTERVAL_SEC * 60.0;

        if (log_rpm(log_fp, rpm) != 0) {
            fprintf(stderr, "Failed to log RPM data.\n");
            goto cleanup;
        }

        printf("RPM: %.2f\n", rpm);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return ret;
}

