#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    /* --- Install signal handlers early so cleanup works even if init fails --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled relay ready.\n");
    printf("  Touch sensor : GPIO%d (TTP223, 3.3V HIGH when touched)\n", TOUCH_SENSOR_PIN);
    printf("  Relay        : GPIO%d (active-HIGH)\n", RELAY_PIN);
    printf("  Poll interval: %d ms\n", POLL_DELAY_US / 1000);
    printf("  Failsafe     : %d s continuous HIGH -> relay OFF\n", FAILSAFE_TIMEOUT);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int failsafe_active = 0;
    uint32_t failsafe_start = 0;

    while (g_running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            /* Sensor read error — abort */
            break;
        }

        if (touch == 1) {
            if (!failsafe_active) {
                failsafe_active = 1;
                failsafe_start = gpioTick();
            } else {
                uint32_t elapsed = gpioTick() - failsafe_start;
                if (elapsed >= (uint32_t)(FAILSAFE_TIMEOUT * 1000000)) {
                    printf("Failsafe triggered: sensor HIGH for %d s — relay OFF\n",
                           FAILSAFE_TIMEOUT);
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        break;
                    }
                    relay_state = 0;
                    failsafe_active = 0;
                    /* Wait for sensor release before re-arming */
                    while (g_running && safe_read(TOUCH_SENSOR_PIN) == 1) {
                        gpioDelay(POLL_DELAY_US);
                    }
                    continue;
                }
            }
        } else {
            failsafe_active = 0;
        }

        /* Toggle on rising edge */
        if (touch == 1 && relay_state == 0) {
            relay_state = 1;
            if (safe_write(RELAY_PIN, 1) != 0) {
                break;
            }
            printf("Touch detected — relay ON\n");
        } else if (touch == 0 && relay_state == 1) {
            relay_state = 0;
            if (safe_write(RELAY_PIN, 0) != 0) {
                break;
            }
            printf("Touch released — relay OFF\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    safe_write(RELAY_PIN, 0);   /* best-effort relay OFF */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

