#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PULSES_PER_LITER   450.0
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define PWM_RANGE          255
#define KP                 1.0

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static FILE                 *g_log_file = NULL;
static double                g_target_flow = 0.0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: rising edge on flow sensor pin                                 */
/* ------------------------------------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* Compute flow rate (L/min) from accumulated pulses over interval     */
/* ------------------------------------------------------------------ */
static double calculate_flow_rate(uint32_t pulses, uint32_t interval_us)
{
    double liters = (double)pulses / PULSES_PER_LITER;
    double seconds = (double)interval_us / 1000000.0;
    return (liters / seconds) * 60.0;
}

/* ------------------------------------------------------------------ */
/* Proportional control: duty = Kp * error, clamped [0, 255]           */
/* ------------------------------------------------------------------ */
static int calculate_pwm_duty(double flow_rate)
{
    double error = g_target_flow - flow_rate;
    int duty = (int)(KP * error);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

/* ------------------------------------------------------------------ */
/* Log one data row to flow_log.csv                                    */
/* ------------------------------------------------------------------ */
static void log_data(double flow_rate, int valve_position)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);
    fprintf(g_log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure valve is off before terminating pigpio */
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;

    /* Parse target flow rate from command-line */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_target_flow = atof(optarg);
                if (g_target_flow <= 0.0) {
                    fprintf(stderr, "Error: target flow rate must be positive (got %.2f)\n",
                            g_target_flow);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (g_target_flow == 0.0) {
        fprintf(stderr, "Error: target flow rate not specified\n");
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable valve (active-high) */
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d high\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM range and initial duty cycle to 0 */
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR for flow sensor */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening flow_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_lpm,valve_position\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target: %.2f L/min. Press Ctrl+C to exit.\n",
           g_target_flow);

    /* Main control loop */
    while (g_running) {
        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        double flow_rate = calculate_flow_rate(pulses, SAMPLE_INTERVAL_US);
        int duty = calculate_pwm_duty(flow_rate);

        if (gpioPWM(VALVE_PWM_PIN, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed\n");
        }

        log_data(flow_rate, duty);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

