#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define DEBOUNCE_US 50000
#define LOCK_HOLD_US 5000000
#define POLL_DELAY_US 100000

#define LOG_FILE "/var/log/door_access.log"

static const unsigned char VALID_TAG[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static int read_rfid_tag(unsigned char *tag) {
    unsigned char tx[10] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    unsigned char rx[10] = {0};
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 10);
    if (ret != 10) {
        log_event("RFID read failed");
        return -1;
    }
    if (memcmp(rx, tx, 10) == 0) {
        log_event("No RFID tag present");
        return -1;
    }
    memcpy(tag, rx, 10);
    return 0;
}

static int authenticate(void) {
    unsigned char tag[10];
    if (read_rfid_tag(tag) != 0) return 0;
    if (memcmp(tag, VALID_TAG, 10) != 0) {
        log_event("Invalid RFID tag");
        return 0;
    }
    log_event("RFID tag authenticated");
    gpioDelay(DEBOUNCE_US);
    if (gpioRead(BUTTON_PIN) == 0) {
        log_event("Button pressed");
        return 1;
    }
    log_event("Button not pressed");
    return 0;
}

static void lock_engage(int pin) {
    gpioWrite(pin, 1);
    log_event("Lock engaged");
}

static void lock_disengage(int pin) {
    gpioWrite(pin, 0);
    log_event("Lock disengaged");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    lock_engage(LOCK_1_PIN);
    lock_engage(LOCK_2_PIN);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    lock_engage(LOCK_1_PIN);
    lock_engage(LOCK_2_PIN);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_event("System started");
    while (!terminate) {
        if (authenticate()) {
            log_event("Two-factor authentication successful");
            lock_disengage(LOCK_1_PIN);
            lock_disengage(LOCK_2_PIN);
            gpioDelay(LOCK_HOLD_US);
            lock_engage(LOCK_1_PIN);
            lock_engage(LOCK_2_PIN);
        }
        gpioDelay(POLL_DELAY_US);
    }
    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

