#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>
#include <gpiod.h>

// Motor 1 GPIO pins
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIO pins
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIO pins
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIO pins
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100

// PWM parameters
#define PWM_FREQUENCY 100
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)

// Encoder parameters
#define PULSES_PER_REVOLUTION 600

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Encoder state structures
typedef struct {
    int a_pin;
    int b_pin;
    struct gpiod_line *a_line;
    struct gpiod_line *b_line;
    int last_a_state;
    int last_b_state;
    int count;
    pthread_mutex_t mutex;
} encoder_state_t;

encoder_state_t encoder1_state;
encoder_state_t encoder2_state;

// Function prototypes
void signal_handler(int signal);
void *encoder_thread(void *arg);
int read_encoder(encoder_state_t *encoder);
void set_motor_speed(int motor_number, int speed);
double calculate_pid(double setpoint, double actual_speed, double *integral, double *previous_error);
void log_data(double motor1_speed, double motor2_speed, double pid1_output, double pid2_output);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Encoder thread function
void *encoder_thread(void *arg) {
    encoder_state_t *encoder = (encoder_state_t *)arg;
    struct gpiod_line_event event;
    struct timespec ts = {1, 0}; // 1 second timeout for event wait

    while (program_running) {
        int ret = gpiod_line_event_wait(encoder->a_line, &ts);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for encoder event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) continue; // Timeout, no event

        // Read the event
        if (gpiod_line_event_read(encoder->a_line, &event) < 0) {
            fprintf(stderr, "Error reading encoder event: %s\n", strerror(errno));
            continue;
        }

        int a_state = gpiod_line_get_value(encoder->a_line);
        int b_state = gpiod_line_get_value(encoder->b_line);

        if (a_state < 0 || b_state < 0) {
            fprintf(stderr, "Error reading encoder pins: %s\n", strerror(errno));
            continue;
        }

        // Determine direction based on A and B states
        int direction = (a_state == b_state) ? 1 : -1;

        pthread_mutex_lock(&encoder->mutex);
        encoder->count += direction;
        pthread_mutex_unlock(&encoder->mutex);
    }

    return NULL;
}

// Function to read the encoder value
int read_encoder(encoder_state_t *encoder) {
    int count;
    pthread_mutex_lock(&encoder->mutex);
    count = encoder->count;
    encoder->count = 0;
    pthread_mutex_unlock(&encoder->mutex);
    return count;
}

// Function to set the motor speed using software PWM
void set_motor_speed(int motor_number, int speed) {
    int enable_pin, in1_pin, in2_pin;
    if (motor_number == 1) {
        enable_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor_number);
        return;
    }

    struct gpiod_line *enable_line = gpiod_chip_get_line(chip, enable_pin);
    struct gpiod_line *in1_line = gpiod_chip_get_line(chip, in1_pin);
    struct gpiod_line *in2_line = gpiod_chip_get_line(chip, in2_pin);

    if (!enable_line || !in1_line || !in2_line) {
        fprintf(stderr, "Error getting motor GPIO lines: %s\n", strerror(errno));
        return;
    }

    // Set enable pin to high (motor on)
    if (gpiod_line_set_value(enable_line, 1) < 0) {
        fprintf(stderr, "Error setting enable pin high: %s\n", strerror(errno));
        return;
    }

    // Set direction pins based on speed sign
    if (speed > 0) {
        if (gpiod_line_set_value(in1_line, 1) < 0 || gpiod_line_set_value(in2_line, 0) < 0) {
            fprintf(stderr, "Error setting direction pins: %s\n", strerror(errno));
            return;
        }
    } else if (speed < 0) {
        if (gpiod_line_set_value(in1_line, 0) < 0 || gpiod_line_set_value(in2_line, 1) < 0) {
            fprintf(stderr, "Error setting direction pins: %s\n", strerror(errno));
            return;
        }
    } else {
        // Stop motor
        if (gpiod_line_set_value(in1_line, 0) < 0 || gpiod_line_set_value(in2_line, 0) < 0) {
            fprintf(stderr, "Error setting direction pins: %s\n", strerror(errno));
            return;
        }
    }

    // Calculate duty cycle (0-100%)
    int duty_cycle = abs(speed);
    if (duty_cycle > 100) duty_cycle = 100;

    // Software PWM loop
    struct timespec on_time = {0, (PWM_PERIOD_NS * duty_cycle) / 100};
    struct timespec off_time = {0, (PWM_PERIOD_NS * (100 - duty_cycle)) / 100};

    while (program_running) {
        if (clock_nanosleep(CLOCK_MONOTONIC, 0, &on_time, NULL) == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in clock_nanosleep: %s\n", strerror(errno));
            break;
        }
        if (clock_nanosleep(CLOCK_MONOTONIC, 0, &off_time, NULL) == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in clock_nanosleep: %s\n", strerror(errno));
            break;
        }
    }

    // Turn off motor and release lines
    gpiod_line_set_value(enable_line, 0);
    gpiod_line_release(enable_line);
    gpiod_line_release(in1_line);
    gpiod_line_release(in2_line);
}

// Function to calculate the PID output
double calculate_pid(double setpoint, double actual_speed, double *integral, double *previous_error) {
    double error = setpoint - actual_speed;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Function to log data to a CSV file
void log_data(double motor1_speed, double motor2_speed, double pid1_output, double pid2_output) {
    if (log_file == NULL) return;
    fprintf(log_file, "%.2f,%.2f,%.2f,%.2f\n", motor1_speed, motor2_speed, pid1_output, pid2_output);
    fflush(log_file);
}

// Cleanup function to release GPIO resources
void cleanup() {
    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    // Initialize encoder states
    encoder1_state.a_pin = ENCODER1_A;
    encoder1_state.b_pin = ENCODER1_B;
    encoder1_state.last_a_state = 0;
    encoder1_state.last_b_state = 0;
    encoder1_state.count = 0;
    pthread_mutex_init(&encoder1_state.mutex, NULL);

    encoder2_state.a_pin = ENCODER2_A;
    encoder2_state.b_pin = ENCODER2_B;
    encoder2_state.last_a_state = 0;
    encoder2_state.last_b_state = 0;
    encoder2_state.count = 0;
    pthread_mutex_init(&encoder2_state.mutex, NULL);

    // Request encoder GPIO lines
    encoder1_state.a_line = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_state.b_line = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_state.a_line = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_state.b_line = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!encoder1_state.a_line || !encoder1_state.b_line || !encoder2_state.a_line || !encoder2_state.b_line) {
        fprintf(stderr, "Error getting encoder GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request encoder lines for edge events
    if (gpiod_line_request_both_edges_events(encoder1_state.a_line, "encoder1") < 0) {
        fprintf(stderr, "Error requesting encoder1 events: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_both_edges_events(encoder2_state.a_line, "encoder2") < 0) {
        fprintf(stderr, "Error requesting encoder2 events: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize motor GPIO lines (set as outputs)
    int motor_pins[] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, motor_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Error getting motor GPIO line %d: %s\n", motor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(line, "motor", 0) < 0) {
            fprintf(stderr, "Error requesting motor GPIO line %d as output: %s\n", motor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening motor_log.csv: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_file, "Motor1_Speed_RPM,Motor2_Speed_RPM,PID1_Output,PID2_Output\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder threads
    pthread_t encoder1_thread, encoder2_thread;
    if (pthread_create(&encoder1_thread, NULL, encoder_thread, &encoder1_state) != 0) {
        fprintf(stderr, "Error creating encoder1 thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (pthread_create(&encoder2_thread, NULL, encoder_thread, &encoder2_state) != 0) {
