        int encoder1_count = read_encoder(&encoder1_state);
        int encoder2_count = read_encoder(&encoder2_state);

        // Calculate speed in RPM (600 pulses per revolution)
        double motor1_speed = (encoder1_count * 60000.0) / (PULSES_PER_REVOLUTION * SAMPLE_TIME_MS);
        double motor2_speed = (encoder2_count * 60000.0) / (PULSES_PER_REVOLUTION * SAMPLE_TIME_MS);

        // Calculate PID outputs
        double pid1_output = calculate_pid(target_rpm1, motor1_speed, &integral1, &previous_error1);
        double pid2_output = calculate_pid(target_rpm2, motor2_speed, &integral2, &previous_error2);

        // Set motor speeds (using software PWM)
        set_motor_speed(1, (int)pid1_output);
        set_motor_speed(2, (int)pid2_output);

        // Log data
        log_data(motor1_speed, motor2_speed, pid1_output, pid2_output);

        // Sleep for the sample time
