#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000 // 50 ms

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int handle);
int read_touch_status(int handle);
void control_relay(int gpio_pin, int state);
void log_relay_state(int gpio_pin, int state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

// Initialize MPR121 sensor
int mpr121_init(int handle) {
    // Soft reset
    if (i2cWriteByteData(handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to soft reset MPR121\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay after reset

    // Configure filtering (defaults from datasheet)
    if (i2cWriteByteData(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_FDLT, 0x00) < 0) return -1;

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(handle, MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1; // Touch threshold
        if (i2cWriteByteData(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; // Release threshold
    }

    // Configure debounce: 3 samples for touch, 3 for release
    if (i2cWriteByteData(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    // Configure config registers (FFI=6 samples, CDC=16uA, CDT=0.5us)
    if (i2cWriteByteData(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2cWriteByteData(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    // Enable all 12 electrodes and enter run mode
    if (i2cWriteByteData(handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) return -1;

    return 0;
}

// Read touch status from MPR121
int read_touch_status(int handle) {
    int status_low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (status_low < 0) {
        fprintf(stderr, "Error: Failed to read touch status low byte\n");
        return -1;
    }
    int status_high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status high byte\n");
        return -1;
    }
    return (status_high << 8) | status_low;
}

// Control relay state
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log relay state change to file
void log_relay_state(int gpio_pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - GPIO %d: %s\n", timestamp, gpio_pin, state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d\n", MPR121_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    // Set relay GPIO as output and ensure it's off initially
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status >= 0) {
            int any_touched = (touch_status & 0x0FFF) > 0;
            control_relay(RELAY_GPIO, any_touched);
            log_relay_state(RELAY_GPIO, any_touched);
        } else {
            fprintf(stderr, "Warning: Failed to read touch status, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

