#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define VALVE1_PAUSE_MS 5000
#define VALVE2_PAUSE_MS 10000
#define LOG_FILE "valve_log.txt"
#define GPIO_CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);
    fprintf(log_file, "%s: %s\n", buf, message);
    fflush(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE1_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE2_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(valve1_line, "valve_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", VALVE1_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        valve1_line = NULL;
        return -1;
    }

    if (gpiod_line_request_output(valve2_line, "valve_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", VALVE2_GPIO, strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        chip = NULL;
        valve1_line = NULL;
        valve2_line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int activate_valve(struct gpiod_line *line, int duration_ms, const char *name) {
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO line HIGH for %s: %s\n", name, strerror(errno));
        return -1;
    }
    char log_msg[128];
    snprintf(log_msg, sizeof(log_msg), "Valve %s activated", name);
    log_event(log_msg);
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO line LOW for %s: %s\n", name, strerror(errno));
        return -1;
    }
    snprintf(log_msg, sizeof(log_msg), "Valve %s deactivated", name);
    log_event(log_msg);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (program_running) {
        if (activate_valve(valve1_line, VALVE1_DURATION_MS, "Valve 1") < 0) {
            log_event("Error activating Valve 1");
        }
        if (!program_running) break;
        usleep(VALVE1_PAUSE_MS * 1000);
        if (!program_running) break;

        if (activate_valve(valve2_line, VALVE2_DURATION_MS, "Valve 2") < 0) {
            log_event("Error activating Valve 2");
        }
        if (!program_running) break;
        usleep(VALVE2_PAUSE_MS * 1000);
    }

    log_event("Program terminated");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    return EXIT_SUCCESS;
}

