#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

int mpr121_init(int handle) {
    // Soft reset
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); // 10 ms delay

    // Stop mode
    if (mpr121_write_reg(handle, MPR121_ECR, 0x00) < 0) return -1;

    // Configure filter/charge time
    if (mpr121_write_reg(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLT, 0x00) < 0) return -1;

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + 2 * i, 0x10) < 0) return -1; // Touch threshold
        if (mpr121_write_reg(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; // Release threshold
    }

    // Debounce: 3 samples for touch, 3 for release
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    // FFI=6 samples, CDC=16 µA
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;

    // CDT=0.5 µs, SFI=4 samples, ESI=4 ms
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    // Enable 12 electrodes, baseline tracking
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off initially

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t touch_status_l, touch_status_h;
        if (mpr121_read_reg(i2c_handle, MPR121_TOUCHSTATUS_L, &touch_status_l) < 0 ||
            mpr121_read_reg(i2c_handle, MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            gpioDelay(100000); // 100 ms delay before retry
            continue;
        }

        uint16_t touch_status = (touch_status_h << 8) | touch_status_l;

        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Touch detected! Relay toggled to %d\n", gpioRead(RELAY_PIN));
        }

        gpioDelay(100000); // 100 ms delay
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

