#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[64];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s\n", time_buf, ts.tv_nsec / 1000000, event);
    fflush(log_file);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate relay\n");
        return;
    }
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on PIR GPIO\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay state\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    int last_state = 0;
    uint32_t last_unlock_time = 0;

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read PIR GPIO\n");
            break;
        }

        if (current_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_unlock_time >= RATE_LIMIT_MS * 1000) {
                unlock_door();
                last_unlock_time = now;
            } else {
                log_event("Rate limit exceeded");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    log_event("System stopped");
    gpioWrite(RELAY_GPIO, 0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

