#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_PATTERN_STEPS 5
#define MAX_PATTERN_STEPS 15

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signal) {
    (void)signal;
    shutdown_flag = 1;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void stop_motors() {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

void cleanup() {
    stop_motors();
    gpioTerminate();
}

typedef struct {
    int motor1_duty_cycle;
    int motor2_duty_cycle;
    int duration_ms;
} MotorStep;

MotorStep *generate_random_step() {
    MotorStep *step = malloc(sizeof(MotorStep));
    if (step == NULL) {
        fprintf(stderr, "Error: Memory allocation failed for step\n");
        return NULL;
    }

    step->motor1_duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
    step->motor2_duty_cycle = (rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1)) + MIN_DUTY_CYCLE;
    step->duration_ms = (rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1)) + MIN_STEP_DURATION_MS;

    return step;
}

void play_pattern(MotorStep *pattern, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_PIN, pattern[i].motor1_duty_cycle);
        gpioPWM(MOTOR2_PIN, pattern[i].motor2_duty_cycle);
        gpioDelay(pattern[i].duration_ms * 1000);
    }
}

int main() {
    srand(time(NULL));

    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Haptic feedback pattern generator started. Press Ctrl+C to exit.\n");

    while (!shutdown_flag) {
        int num_steps = (rand() % (MAX_PATTERN_STEPS - MIN_PATTERN_STEPS + 1)) + MIN_PATTERN_STEPS;
        MotorStep *pattern = malloc(num_steps * sizeof(MotorStep));
        if (pattern == NULL) {
            fprintf(stderr, "Error: Memory allocation failed for pattern\n");
            cleanup();
            return 1;
        }

        for (int i = 0; i < num_steps; i++) {
            MotorStep *step = generate_random_step();
            if (step == NULL) {
                free(pattern);
                cleanup();
                return 1;
            }
            pattern[i] = *step;
            free(step);
        }

        play_pattern(pattern, num_steps);
        free(pattern);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

