#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_LOG_FILE "weight_log.txt"

#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define WEIGHT_THRESHOLD 10.0
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *out_value) {
    if (gpioSetMode(data_pin, PI_INPUT) != 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) != 0) return -1;
    if (gpioWrite(clock_pin, 0) != 0) return -1;

    uint32_t start_tick = gpioTick();
    while (gpioRead(data_pin) == 1) {
        if (gpioTick() - start_tick > HX711_TIMEOUT_US) return -1;
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(clock_pin, 1) != 0) return -1;
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(data_pin) == 1) {
            value |= 1;
        }
        if (gpioWrite(clock_pin, 0) != 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(clock_pin, 1) != 0) return -1;
    gpioDelay(1);
    if (gpioWrite(clock_pin, 0) != 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    *out_value = value;
    return 0;
}

static int load_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file '%s'. Using defaults.\n", CALIBRATION_FILE);
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data in '%s'. Using defaults.\n", CALIBRATION_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration data loaded: scale=%.4f, offset=%.4f\n", scale_factor, offset);
    return 0;
}

static int save_calibration_data(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file '%s' for writing.\n", CALIBRATION_FILE);
        return -1;
    }

    if (fprintf(fp, "%.4f %.4f\n", scale_factor, offset) < 0) {
        fprintf(stderr, "Error: Failed to write calibration data to file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration data saved: scale=%.4f, offset=%.4f\n", scale_factor, offset);
    return 0;
}

static int calibrate_hx711(int data_pin, int clock_pin) {
    long sum = 0;
    int valid_readings = 0;

    printf("Calibrating HX711 (zero load)...\n");
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        long raw;
        if (read_hx711(data_pin, clock_pin, &raw) == 0) {
            sum += raw;
            valid_readings++;
        } else {
            fprintf(stderr, "Warning: HX711 read timeout during calibration (%d/%d).\n", i + 1, NUM_CALIBRATION_READINGS);
        }
        gpioDelay(10000);
    }

    if (valid_readings == 0) {
        fprintf(stderr, "Error: No valid readings during calibration.\n");
        return -1;
    }

    offset = (double)sum / valid_readings;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return 0;
}

static double convert_to_weight(long raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

static int log_weight(double weight) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error: Failed to get local time.\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

static void control_solenoid(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to solenoid pin %d.\n", pin);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SOLENOID_PIN, 0);

    log_file = fopen(WEIGHT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", WEIGHT_LOG_FILE);
        gpioTerminate();
