#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 50000
#define MOTOR_RUN_TIME_US 5000000
#define CHECK_INTERVAL_US 60000000
#define POST_CLOSE_DELAY_US 60000000

