volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal %d received, shutting down...", signal);
    program_running = 0;
}

int read_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int value = gpioRead(RAIN_SENSOR_PIN);
        if (value == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= 3) ? 1 : 0;
}

