    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "System initialized. Monitoring rain sensor...");

    while (program_running) {
        if (read_rain_sensor()) {
            syslog(LOG_INFO, "Rain detected!");
            close_window();
            if (program_running) {
                gpioDelay(POST_CLOSE_DELAY_US);
            }
        } else {
            gpioDelay(CHECK_INTERVAL_US);
        }
    }

    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    syslog(LOG_INFO, "System shut down.");
    closelog();
    return 0;
}

