#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_LOCK 17

// Define stock level threshold (in grams)
#define STOCK_LEVEL_THRESHOLD 100.0

// Define solenoid lock duration (in seconds)
#define SOLENOID_LOCK_DURATION 5

// Define HX711 timeout (in microseconds)
#define HX711_TIMEOUT 100000

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711(int dt_pin, int sck_pin);
double calculate_weight(int raw_value);
void activate_solenoid(int solenoid_pin, int duration);
void log_event(const char *event_message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from HX711
int read_hx711(int dt_pin, int sck_pin) {
    int i;
    int data = 0;
    int timeout = 0;

    // Wait for DT to go low (data ready) with timeout
    while (gpioRead(dt_pin) == 1) {
        gpioDelay(1); // 1 microsecond delay
        timeout++;
        if (timeout > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 timeout waiting for data ready\n");
            return -1;
        }
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1); // Set SCK high
        gpioDelay(1); // 1 microsecond delay
        data = data << 1; // Shift data left
        if (gpioRead(dt_pin)) { // Read DT
            data++; // Set the bit if DT is high
        }
        gpioWrite(sck_pin, 0); // Set SCK low
        gpioDelay(1); // 1 microsecond delay
    }

    // 25th pulse to set gain to 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1);
    gpioWrite(sck_pin, 0);
    gpioDelay(1);

    // Convert 24-bit two's complement to 32-bit signed integer
    if (data & 0x800000) {
        data |= ~0xffffff; // Sign extend
    }

    return data;
}

// Function to calculate weight from raw HX711 value
// Calibration factor: 100000 for TAL220B with 100g load cell
double calculate_weight(int raw_value) {
    return (double)raw_value / 100000.0;
}

// Function to activate the solenoid lock
void activate_solenoid(int solenoid_pin, int duration) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin high\n");
        return;
    }
    printf("Solenoid lock activated for %d seconds\n", duration);
    gpioDelay(duration * 1000000); // Convert seconds to microseconds
    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin low\n");
    }
    printf("Solenoid lock deactivated\n");
}

// Function to log events to a file
void log_event(const char *event_message) {
    FILE *fp = fopen("stock_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening stock_events.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, event_message);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_LOCK, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Stock monitoring system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read raw HX711 value
        int raw_value = read_hx711(HX711_DT, HX711_SCK);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711, skipping cycle\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Calculate weight
        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f g\n", weight);

        // Check if weight is below threshold
        if (weight < STOCK_LEVEL_THRESHOLD) {
            printf("Stock level below threshold! Activating solenoid lock.\n");
            activate_solenoid(SOLENOID_LOCK, SOLENOID_LOCK_DURATION);
            log_event("Stock level below threshold, solenoid lock activated");
        }

        gpioDelay(1000000); // Wait 1 second before next reading
    }

    // Clean up
    gpioWrite(SOLENOID_LOCK, 0); // Ensure solenoid is off
    gpioTerminate();
    printf("Stock monitoring system stopped.\n");

    return 0;
}

