#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 0.0;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    int i;
    uint32_t start_tick, elapsed;

    *raw_value = 0;

    if (gpioSetMode(data_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set data pin %d as input\n", data_pin);
        return -1;
    }
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set clock pin %d as output\n", clock_pin);
        return -1;
    }

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    start_tick = gpioTick();
    while (gpioRead(data_pin) == 1) {
        elapsed = gpioTick() - start_tick;
        if (elapsed > HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout)\n");
            return -1;
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        *raw_value = (*raw_value << 1) | (gpioRead(data_pin) & 1);
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (*raw_value & 0x800000) {
        *raw_value |= 0xFF000000;
    }

    return 0;
}

static double calibrate_hx711(int data_pin, int clock_pin) {
    double known_weight;
    long raw_value;

    printf("Place a known weight on the load cell and press Enter...\n");
    if (getchar() == EOF) {
        fprintf(stderr, "Error: Failed to read input\n");
        return 0.0;
    }

    if (read_hx711(data_pin, clock_pin, &raw_value) != 0) {
        fprintf(stderr, "Error: Failed to read raw value during calibration\n");
        return 0.0;
    }

    printf("Enter the known weight in kilograms: ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid weight input\n");
        return 0.0;
    }

    if (known_weight <= 0.0) {
        fprintf(stderr, "Error: Weight must be positive\n");
        return 0.0;
    }

    return (double)raw_value / known_weight;
}

static int log_event(double weight) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int control_solenoid(int pin, int duration_ms) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin %d as output\n", pin);
        return -1;
    }

    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin %d high\n", pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin %d low\n", pin);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
        calibration_file = NULL;
    }
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
}

int main(void) {
    long raw_value;
    double weight;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Failed to open calibration file %s. Calibrating...\n", CALIBRATION_FILE);
        calibration_factor = calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (calibration_factor == 0.0) {
            fprintf(stderr, "Error: Calibration failed. Exiting.\n");
            cleanup();
            return EXIT_FAILURE;
        }

        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (calibration_file == NULL) {
            fprintf(stderr, "Error: Failed to open calibration file for writing\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (fprintf(calibration_file, "%.6f\n", calibration_factor) < 0) {
            fprintf(stderr, "Error: Failed to write calibration factor to file\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fclose(calibration_file);
        calibration_file = NULL;
    } else {
        if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error: Failed to read calibration factor from file\n");
            fclose(calibration_file);
            calibration_file = NULL;
            calibration_factor = calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
            if (calibration_factor == 0.0) {
                fprintf(stderr, "Error: Calibration failed. Exiting.\n");
                cleanup();
                return EXIT_FAILURE;
            }

            calibration_file = fopen(CALIBRATION_FILE, "w");
            if (calibration_file == NULL) {
                fprintf(stderr, "Error: Failed to open calibration file for writing\n");
                cleanup();
                return EXIT_FAILURE;
            }

            if (fprintf(calibration_file, "%.6f\n", calibration_factor) < 0) {
                fprintf(stderr, "Error: Failed to write calibration factor to file\n");
                cleanup();
                return EXIT_FAILURE;
            }
            fclose(calibration_file);
            calibration_file = NULL;
        } else {
            fclose(calibration_file);
            calibration_file = NULL;
        }
    }

    printf("Calibration factor: %.6f\n", calibration_factor);

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin %d as output\n", SOLENOID_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to install SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw_value) != 0) {
            fprintf(stderr, "Error: Failed to read HX711 value\n");
            gpioDelay(100000);
            continue;
        }

        weight = (double)raw_value / calibration_factor;

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Weight: %.2f kg\n", weight);
            if (log_event(weight) != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
            if (control_solenoid(SOLENOID_PIN, 5000) != 0) {
                fprintf(stderr, "Error: Failed to control solenoid\n");
            }
        }

        gpioDelay(100000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

