#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define VALVE_LINE_OFFSET 18
#define MIN_DURATION 1
#define MAX_DURATION 3600
#define DEFAULT_DURATION 60

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        if (feof(fp)) {
            fprintf(stderr, "Config file '%s' is empty.\n", filename);
        } else {
            fprintf(stderr, "Error reading config file '%s': %s\n", filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    /* Strip trailing newline */
    line[strcspn(line, "\n")] = '\0';

    char *eq = strchr(line, '=');
    if (!eq) {
        fprintf(stderr, "Config file '%s' does not contain '='.\n", filename);
        return -1;
    }

    *eq = '\0';
    char *key = line;
    char *value = eq + 1;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Config file '%s' contains unknown key '%s'.\n", filename, key);
        return -1;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(value, &endptr, 10);
    if (errno != 0 || endptr == value || *endptr != '\0') {
        fprintf(stderr, "Invalid duration value '%s'. Must be an integer.\n", value);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Duration value '%ld' out of range [%d, %d].\n", val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static int set_valve(struct gpiod_line *line, int on) {
    int ret = gpiod_line_set_value(line, on ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line value to %d: %s\n", on ? 1 : 0, strerror(errno));
        return -1;
    }
    return 0;
}

static void sleep_interruptible(unsigned int seconds) {
    struct timespec req = { .tv_sec = seconds, .tv_nsec = 0 };
    struct timespec rem;
    while (nanosleep(&req, &rem) == -1 && errno == EINTR) {
        if (!program_running) {
            return;
        }
        req = rem;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = DEFAULT_DURATION;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (read_config(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Using default duration of %d seconds.\n", DEFAULT_DURATION);
        duration = DEFAULT_DURATION;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, VALVE_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", VALVE_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", VALVE_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Watering system started. Valve on GPIO%d. Duration: %d seconds.\n", VALVE_LINE_OFFSET, duration);
    fflush(stdout);

    if (set_valve(line, 1) != 0) {
        goto cleanup;
    }
    printf("Valve ON\n");
    fflush(stdout);

    sleep_interruptible((unsigned int)duration);

    if (!program_running) {
        printf("\nInterrupted by signal. Shutting down...\n");
    }

    if (set_valve(line, 0) != 0) {
        goto cleanup;
    }
    printf("Valve OFF\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Watering system stopped.\n");
    }

    return ret;
}

