#define LOG_FILE "trace_log.txt"

// Global variables for cleanup
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_gpio(void);
int read_sensor(int gpio_pin);
void set_motor_speed(int gpio_forward, int gpio_backward, int speed);
void stop_motors(void);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void cleanup(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as inputs
    gpioSetMode(SENSOR_LEFT, PI_INPUT);
    gpioSetMode(SENSOR_MIDDLE, PI_INPUT);
    gpioSetMode(SENSOR_RIGHT, PI_INPUT);

    // Set motor pins as outputs
    gpioSetMode(MOTOR_LEFT_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_LEFT_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_RIGHT_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_RIGHT_BACKWARD, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR_LEFT_FORWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_LEFT_BACKWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_RIGHT_FORWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_RIGHT_BACKWARD, PWM_FREQUENCY);

    gpioSetPWMrange(MOTOR_LEFT_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_LEFT_BACKWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_RIGHT_FORWARD, PWM_RANGE);
    gpioSetPWMrange(MOTOR_RIGHT_BACKWARD, PWM_RANGE);

    return 0;
}

