        if (middle_sensor == 0) {
            // Middle sensor detects line, go straight
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            // Left sensor detects line, turn right
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
