#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define MEASUREMENT_DELAY_MS 180
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fflush(log_file);
}

static int read_lux(float *lux_out) {
    char cmd = 0x10;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        log_message("Error: Failed to write measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        log_message("Error: Failed to read 2 bytes from BH1750");
        return -1;
    }
    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_message("Error: Failed to write relay GPIO");
    } else {
        char msg[64];
        snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
        log_message(msg);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C device for BH1750");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Error: Failed to set relay GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_message("Error: Failed to register SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Grow lamp controller started");

    int relay_state = 0;

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);

            if (lux < LUX_THRESHOLD && !relay_state) {
                control_relay(1);
                relay_state = 1;
            } else if (lux >= LUX_THRESHOLD && relay_state) {
                control_relay(0);
                relay_state = 0;
            }
        } else {
            log_message("Error reading lux, retrying...");
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_message("Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

