#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEBOUNCE_DELAY_US 100000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

void set_servo_position(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            printf("Locking door...\n");
            set_servo_position(LOCKED_PULSE_WIDTH);
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlocking door...\n");
            set_servo_position(UNLOCKED_PULSE_WIDTH);
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

