#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_PORT 5555
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static int setup_gpio(struct gpiod_chip **chip, struct gpiod_line **sensor_line, struct gpiod_line **led_line) {
    *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!*chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    *sensor_line = gpiod_chip_get_line(*chip, SOUND_SENSOR_GPIO);
    if (!*sensor_line) {
        perror("gpiod_chip_get_line (sensor)");
        gpiod_chip_close(*chip);
        return -1;
    }

    *led_line = gpiod_chip_get_line(*chip, ALARM_LED_GPIO);
    if (!*led_line) {
        perror("gpiod_chip_get_line (led)");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_input(*sensor_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input (sensor)");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*led_line, "alarm_led", 0) < 0) {
        perror("gpiod_line_request_output (led)");
        gpiod_line_release(*sensor_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *sensor_line, struct gpiod_line *led_line) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static int setup_zmq(void **context, void **subscriber, void **publisher) {
    *context = zmq_ctx_new();
    if (!*context) {
        perror("zmq_ctx_new");
        return -1;
    }

    *subscriber = zmq_socket(*context, ZMQ_SUB);
    if (!*subscriber) {
        perror("zmq_socket (subscriber)");
        zmq_ctx_destroy(*context);
        return -1;
    }

    *publisher = zmq_socket(*context, ZMQ_PUB);
    if (!*publisher) {
        perror("zmq_socket (publisher)");
        zmq_close(*subscriber);
        zmq_ctx_destroy(*context);
        return -1;
    }

    int linger = 0;
    if (zmq_setsockopt(*subscriber, ZMQ_LINGER, &linger, sizeof(linger)) < 0) {
        perror("zmq_setsockopt (subscriber linger)");
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_setsockopt(*publisher, ZMQ_LINGER, &linger, sizeof(linger)) < 0) {
        perror("zmq_setsockopt (publisher linger)");
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_bind(*publisher, "tcp://*:5555") != 0) {
        perror("zmq_bind (publisher)");
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_connect(*subscriber, "tcp://localhost:5555") != 0) {
        perror("zmq_connect (subscriber)");
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    if (zmq_setsockopt(*subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 12) != 0) {
        perror("zmq_setsockopt (subscriber subscribe)");
        zmq_close(*subscriber);
        zmq_close(*publisher);
        zmq_ctx_destroy(*context);
        return -1;
    }

    return 0;
}

static void cleanup_zmq(void *context, void *subscriber, void *publisher) {
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (publisher) {
        zmq_close(publisher);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
}

static int publish_alert(void *publisher) {
    const char *topic = "SOUND_ALERTS";
    const char *message = "Sound alert triggered!";
    size_t topic_len = strlen(topic);
    size_t msg_len = strlen(message);

    zmq_msg_t topic_msg;
    zmq_msg_t msg_msg;

    if (zmq_msg_init_size(&topic_msg, topic_len) != 0) {
        perror("zmq_msg_init_size (topic)");
        return -1;
    }
    memcpy(zmq_msg_data(&topic_msg), topic, topic_len);

    if (zmq_msg_init_size(&msg_msg, msg_len) != 0) {
        perror("zmq_msg_init_size (message)");
        zmq_msg_close(&topic_msg);
        return -1;
    }
    memcpy(zmq_msg_data(&msg_msg), message, msg_len);

    if (zmq_msg_send(&topic_msg, publisher, ZMQ_SNDMORE) != 0) {
        perror("zmq_msg_send (topic)");
        zmq_msg_close(&topic_msg);
        zmq_msg_close(&msg_msg);
        return -1;
    }

    if (zmq_msg_send(&msg_msg, publisher, 0) != 0) {
        perror("zmq_msg_send (message)");
        zmq_msg_close(&topic_msg);
        zmq_msg_close(&msg_msg);
        return -1;
    }

    zmq_msg_close(&topic_msg);
    zmq_msg_close(&msg_msg);
    return 0;
}

static int read_sound_sensor(struct gpiod_line *sensor_line) {
    int val = gpiod_line_get_value(sensor_line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return val;
}

static void trigger_alarm(struct gpiod_line *led_line) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("gpiod_line_set_value (led on)");
        return;
    }
    sleep_ms(ALARM_DURATION_MS);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value (led off)");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s. Must be sound_sensor or alarm_node.\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction (SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction (SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    void *context = NULL;
    void *subscriber = NULL;
    void *publisher = NULL;
    int ret = EXIT_FAILURE;

    if (setup_gpio(&chip, &sensor_line, &led_line) != 0) {
        goto cleanup;
    }

    if (setup_zmq(&context, &subscriber, &publisher) != 0) {
        goto cleanup;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode started. Polling GPIO%d every %d ms. Press Ctrl+C to exit.\n",
               SOUND_SENSOR_GPIO, POLL_INTERVAL_MS);

        while (running) {
            int val = read_sound_sensor(sensor_line);
            if (val < 0) {
                fprintf(stderr, "Error reading sound sensor. Exiting.\n");
                break;
            }

            if (val == 0) {
                printf("Sound detected! Publishing alert.\n");
                if (publish_alert(publisher) != 0) {
                    fprintf(stderr, "Error publishing alert. Exiting.\n");
                    break;
                }
            }

            sleep_ms(POLL_INTERVAL_MS);
        }
    } else {
        printf("Alarm node mode started. Subscribing to tcp://localhost:%d on topic SOUND_ALERTS. Press Ctrl+C to exit.\n",
               ZMQ_PORT);

        while (running) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc != 0) {
                perror("zmq_msg_init");
                break;
            }

            rc = zmq_msg_recv(&msg, subscriber, 0);
            if (rc < 0) {
                if (errno == EINTR) {
                    zmq_msg_close(&msg);
                    continue;
                }
                perror("zmq_msg_recv");
                zmq_msg_close(&msg);
                break;
            }

            if (rc == 0) {
                zmq_msg_close(&msg);
                continue;
            }

            printf("Received alert message: %s\n", (char *)zmq_msg_data(&msg));
            trigger_alarm(led_line);
            zmq_msg_close(&msg);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup_gpio(chip, sensor_line, led_line);
    cleanup_zmq(context, subscriber, publisher);
    printf("Exiting cleanly.\n");
    return ret;
}

