    int val = gpiod_line_get_value(sensor_line);
    if (val < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return val;
}

static void trigger_alarm(struct gpiod_line *led_line) {
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("gpiod_line_set_value (led on)");
        return;
    }
    sleep_ms(ALARM_DURATION_MS);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("gpiod_line_set_value (led off)");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s. Must be sound_sensor or alarm_node.\n", mode);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction (SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction (SIGTERM)");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *led_line = NULL;
    void *context = NULL;
    void *subscriber = NULL;
    void *publisher = NULL;
    int ret = EXIT_FAILURE;

    if (setup_gpio(&chip, &sensor_line, &led_line) != 0) {
        goto cleanup;
    }

    if (setup_zmq(&context, &subscriber, &publisher) != 0) {
        goto cleanup;
    }

    if (strcmp(mode, "sound_sensor") == 0) {
        printf("Sound sensor mode started. Polling GPIO%d every %d ms. Press Ctrl+C to exit.\n",
               SOUND_SENSOR_GPIO, POLL_INTERVAL_MS);

        while (running) {
            int val = read_sound_sensor(sensor_line);
            if (val < 0) {
                fprintf(stderr, "Error reading sound sensor. Exiting.\n");
                break;
            }

            if (val == 0) {
                printf("Sound detected! Publishing alert.\n");
                if (publish_alert(publisher) != 0) {
                    fprintf(stderr, "Error publishing alert. Exiting.\n");
                    break;
                }
            }

            sleep_ms(POLL_INTERVAL_MS);
        }
    } else {
        printf("Alarm node mode started. Subscribing to tcp://localhost:%d on topic SOUND_ALERTS. Press Ctrl+C to exit.\n",
               ZMQ_PORT);

        while (running) {
            zmq_msg_t msg;
            int rc = zmq_msg_init(&msg);
            if (rc != 0) {
                perror("zmq_msg_init");
                break;
            }

            rc = zmq_msg_recv(&msg, subscriber, 0);
            if (rc < 0) {
                if (errno == EINTR) {
                    zmq_msg_close(&msg);
                    continue;
                }
                perror("zmq_msg_recv");
                zmq_msg_close(&msg);
                break;
            }

            if (rc == 0) {
                zmq_msg_close(&msg);
                continue;
            }

            printf("Received alert message: %s\n", (char *)zmq_msg_data(&msg));
            trigger_alarm(led_line);
            zmq_msg_close(&msg);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    cleanup_gpio(chip, sensor_line, led_line);
    cleanup_zmq(context, subscriber, publisher);
    printf("Exiting cleanly.\n");
    return ret;
}

