#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MAX_PULSES 100
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_lengths[MAX_PULSES];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0 && level != 1) return;
    uint32_t diff = tick - last_tick;
    last_tick = tick;
    if (pulse_count < MAX_PULSES) {
        pulse_lengths[pulse_count++] = diff;
    }
}

static int decode_nec(const uint32_t *pl, int count, uint32_t *addr, uint32_t *cmd) {
    if (count < 34) return -1;
    if (pl[0] < 8000 || pl[0] > 10000) return -1;
    if (pl[1] < 4000 || pl[1] > 5000) return -1;
    uint32_t raw = 0;
    for (int i = 0; i < 32; i++) {
        int mark_idx = 2 + i * 2;
        int space_idx = mark_idx + 1;
        if (mark_idx >= count || space_idx >= count) return -1;
        if (pl[mark_idx] < 400 || pl[mark_idx] > 700) return -1;
        if (pl[space_idx] < 400 || pl[space_idx] > 1800) return -1;
        raw <<= 1;
        if (pl[space_idx] > 1200) raw |= 1;
    }
    *addr = (raw >> 24) & 0xFF;
    *cmd = (raw >> 8) & 0xFF;
    uint8_t addr_inv = (raw >> 16) & 0xFF;
    uint8_t cmd_inv = raw & 0xFF;
    if ((*addr ^ addr_inv) != 0xFF || (*cmd ^ cmd_inv) != 0xFF) {
        syslog(LOG_WARNING, "NEC checksum failed: addr=0x%02X cmd=0x%02X inv_addr=0x%02X inv_cmd=0x%02X",
               *addr, *cmd, addr_inv, cmd_inv);
        return -1;
    }
    return 0;
}

static void publish_json(uint32_t addr, uint32_t cmd) {
    char payload[128];
    int len = snprintf(payload, sizeof(payload),
                       "{\"address\":%u,\"command\":%u}", addr, cmd);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        syslog(LOG_ERR, "JSON formatting failed");
        return;
    }
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, len, payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder on GPIO%d", IR_GPIO);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register signal handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialized");

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO%d", IR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Alert callback registered on GPIO%d", IR_GPIO);

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioSetAlertFunc(IR_GPIO, NULL);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioSetAlertFunc(IR_GPIO, NULL);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "Connected to MQTT broker at %s:%d", MQTT_BROKER, MQTT_PORT);

    while (running) {
        if (pulse_count >= 34) {
            uint32_t addr, cmd;
            if (decode_nec(pulse_lengths, pulse_count, &addr, &cmd) == 0) {
                syslog(LOG_INFO, "Decoded NEC: addr=0x%02X cmd=0x%02X", addr, cmd);
                publish_json(addr, cmd);
            }
            pulse_count = 0;
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioSetAlertFunc(IR_GPIO, NULL);
    gpioTerminate();
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

