#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define BH1750_ADDR_1  0x23
#define BH1750_ADDR_2  0x24
#define BH1750_ADDR_3  0x25
#define BH1750_ADDR_4  0x26
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS  180
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(uint8_t addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read failed: got %zd bytes, expected 2: %s\n",
                r, r < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(const char *data) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "socket() failed: %s\n", strerror(errno));
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL) failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);
    if (sendto(sock, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto() failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }
    close(sock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    int fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        uint8_t addr = (i == 0) ? BH1750_ADDR_1 :
                       (i == 1) ? BH1750_ADDR_2 :
                       (i == 2) ? BH1750_ADDR_3 : BH1750_ADDR_4;
        fds[i] = i2c_open(addr);
        if (fds[i] < 0) {
            fprintf(stderr, "Failed to open sensor %d at 0x%02X\n", i + 1, addr);
            for (int j = 0; j < i; j++) close(fds[j]);
            return EXIT_FAILURE;
        }
    }
    while (g_running) {
        char packet[256];
        int len = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux;
            if (bh1750_read_lux(fds[i], &lux) == 0) {
                len += snprintf(packet + len, sizeof(packet) - len,
                                "%d,%.2f", i + 1, lux);
            } else {
                len += snprintf(packet + len, sizeof(packet) - len,
                                "%d,NaN", i + 1);
            }
            if (i < NUM_SENSORS - 1) len += snprintf(packet + len, sizeof(packet) - len, ";");
        }
        if (send_multicast(packet) < 0) {
            fprintf(stderr, "Multicast send failed; continuing\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }
    for (int i = 0; i < NUM_SENSORS; i++) close(fds[i]);
    return EXIT_SUCCESS;
}

