                       (i == 1) ? BH1750_ADDR_2 :
                       (i == 2) ? BH1750_ADDR_3 : BH1750_ADDR_4;
        fds[i] = i2c_open(addr);
        if (fds[i] < 0) {
            fprintf(stderr, "Failed to open sensor %d at 0x%02X\n", i + 1, addr);
            for (int j = 0; j < i; j++) close(fds[j]);
            return EXIT_FAILURE;
        }
    }
    while (g_running) {
        char packet[256];
        int len = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux;
            if (bh1750_read_lux(fds[i], &lux) == 0) {
                len += snprintf(packet + len, sizeof(packet) - len,
                                "%d,%.2f", i + 1, lux);
            } else {
                len += snprintf(packet + len, sizeof(packet) - len,
                                "%d,NaN", i + 1);
            }
            if (i < NUM_SENSORS - 1) len += snprintf(packet + len, sizeof(packet) - len, ";");
        }
        if (send_multicast(packet) < 0) {
            fprintf(stderr, "Multicast send failed; continuing\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }
    for (int i = 0; i < NUM_SENSORS; i++) close(fds[i]);
    return EXIT_SUCCESS;
}

