#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_US      1000000
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read 14-bit flow data from the AWM7300V.
 * The sensor returns 2 bytes on a zero-length write:
 *   [MSB, LSB]
 * The 14-bit value is masked with 0x3FFF.
 * Returns 0 on success and stores the flow rate in *out_slpm.
 * Returns -1 on persistent failure.
 */
static int read_airflow(int fd, float *out_slpm)
{
    uint8_t buf[2];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == (ssize_t)sizeof(buf)) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            raw &= 0x3FFF;
            *out_slpm = (float)(raw - 3277) * 0.1f;
            return 0;
        }
        if (n < 0) {
            fprintf(stderr, "I2C read failed: %s (errno=%d)\n",
                    strerror(errno), errno);
        } else {
            fprintf(stderr, "I2C read short: got %zd of %zu bytes\n",
                    n, sizeof(buf));
        }
        retries--;
        if (retries > 0)
            usleep(RETRY_DELAY_US);
    }
    return -1;
}

static void log_flow(FILE *fp, float flow)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(fp, "%s, Flow: %.2f SLPM\n", ts, flow);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, AWM7300V_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float flow;
        if (read_airflow(g_i2c_fd, &flow) == 0) {
            log_flow(g_log_fp, flow);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; "
                            "continuing.\n", MAX_RETRIES);
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

