#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"

#define AS7341_REG_ENABLE 0x80
#define AS7341_REG_ATIME 0x81
#define AS7341_REG_WTIME 0x83
#define AS7341_REG_CONFIG1 0x8D
#define AS7341_REG_CONFIG2 0x8E
#define AS7341_REG_ID 0x24
#define AS7341_REG_STATUS 0x93
#define AS7341_REG_CDATAL 0x94
#define AS7341_REG_CDATAH 0x95
#define AS7341_REG_RDATAL 0x96
#define AS7341_REG_RDATAH 0x97
#define AS7341_REG_GDATAL 0x98
#define AS7341_REG_GDATAH 0x99
#define AS7341_REG_BDATAL 0x9A
#define AS7341_REG_BDATAH 0x9B
#define AS7341_REG_F1DATAL 0x60
#define AS7341_REG_F1DATAH 0x61
#define AS7341_REG_F2DATAL 0x62
#define AS7341_REG_F2DATAH 0x63
#define AS7341_REG_F3DATAL 0x64
#define AS7341_REG_F3DATAH 0x65
#define AS7341_REG_F4DATAL 0x66
#define AS7341_REG_F4DATAH 0x67
#define AS7341_REG_F5DATAL 0x68
#define AS7341_REG_F5DATAH 0x69
#define AS7341_REG_F6DATAL 0x6A
#define AS7341_REG_F6DATAH 0x6B
#define AS7341_REG_F7DATAL 0x6C
#define AS7341_REG_F7DATAH 0x6D
#define AS7341_REG_F8DATAL 0x6E
#define AS7341_REG_F8DATAH 0x6F
#define AS7341_REG_NIRDATAL 0x70
#define AS7341_REG_NIRDATAH 0x71
#define AS7341_REG_CLEARDATAL 0x72
#define AS7341_REG_CLEARDATAH 0x73
#define AS7341_REG_CFG6 0xAF

#define AS7341_ENABLE_PON 0x01
#define AS7341_ENABLE_SP_EN 0x02
#define AS7341_CFG6_SMUX_SP 0x01

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, reg_low, &low) < 0) return -1;
    if (i2c_read_reg8(fd, reg_low + 1, &high) < 0) return -1;
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, AS7341_REG_ID, &id) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (id != 0x19) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x19, got 0x%02X\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_REG_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_REG_WTIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_REG_CONFIG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_REG_CONFIG2, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_CFG6_SMUX_SP) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_sensor_data(int fd, uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4,
                            uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8,
                            uint16_t *clear, uint16_t *nir) {
    if (i2c_read_reg16(fd, AS7341_REG_F1DATAL, f1) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F2DATAL, f2) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F3DATAL, f3) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F4DATAL, f4) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F5DATAL, f5) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F6DATAL, f6) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F7DATAL, f7) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_F8DATAL, f8) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_CLEARDATAL, clear) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_NIRDATAL, nir) < 0) return -1;
    return 0;
}

static float calculate_lux(uint16_t clear, uint16_t nir) {
    if (clear == 0) return 0.0f;
    float ratio = (float)nir / (float)clear;
    float lux = 0.0f;
    if (ratio <= 0.52f) {
        lux = (0.0315f * clear) - (0.0593f * clear * powf(ratio, 1.4f));
    } else if (ratio <= 0.65f) {
        lux = (0.0229f * clear) - (0.02916f * nir);
    } else if (ratio <= 0.80f) {
        lux = (0.0157f * clear) - (0.0180f * nir);
    } else if (ratio <= 1.30f) {
        lux = (0.00338f * clear) - (0.00260f * nir);
    }
    return lux;
}

static int log_data(FILE *fp, uint16_t f1, uint16_t f2, uint16_t f3, uint16_t f4,
                     uint16_t f5, uint16_t f6, uint16_t f7, uint16_t f8,
                     uint16_t clear, uint16_t nir, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AS7341_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }

    printf("Starting spectral data logging. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
        if (read_sensor_data(i2c_fd, &f1, &f2, &f3, &f4, &f5, &f6, &f7, &f8, &clear, &nir) < 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            sleep(1);
            continue;
        }

        float lux = calculate_lux(clear, nir);
        if (log_data(log_file, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(5);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, AS7341_REG_ENABLE, 0x00);
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
    return 0;
}

