#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define ACCEL_REG 0x28
#define ACCEL_SCALE 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int interval = DEFAULT_INTERVAL;
static char filename[256] = DEFAULT_FILENAME;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    if (!error_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_file, "%s: %s (errno: %d - %s)\n", ts, message, errno, strerror(errno));
    fflush(error_file);
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        log_error("I2C write failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write (register select) failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, len) == (ssize_t)len) return 0;
        log_error("I2C read failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(i2c_fd, ACCEL_REG, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(data_file, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(data_file);
}

static void cleanup(void) {
    if (data_file) { fclose(data_file); data_file = NULL; }
    if (error_file) { fclose(error_file); error_file = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': strncpy(filename, optarg, sizeof(filename) - 1); filename[sizeof(filename) - 1] = '\0'; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        perror("Failed to open error log");
        return EXIT_FAILURE;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        log_error("Failed to open data file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        log_error("I2C initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic data logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            log_error("Failed to read acceleration data after retries");
        }
        sleep(interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

