#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define READ_BUFFER_SIZE 4096
#define MAGIC_WORD_SIZE 8
#define MAX_OBJECTS 100

static const uint16_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x0204, 0x0306, 0x0805, 0x0709};

static volatile sig_atomic_t terminate = 0;
static int uart_handle = -1;
static FILE *csv_file = NULL;

typedef struct {
    uint16_t magic_word[MAGIC_WORD_SIZE];
    uint32_t version;
    uint32_t total_packet_len;
    uint32_t platform;
    uint32_t frame_number;
    uint32_t time_subframe;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
    uint32_t subframe_number;
} __attribute__((packed)) MmwDemo_OutputMessageHeader;

typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) MmwDemo_OutputMessageTLV;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
} __attribute__((packed)) MmwDemo_DetectedObject;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        return -1;
    }
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

static int find_magic_word(const uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        int match = 1;
        for (int j = 0; j < MAGIC_WORD_SIZE; j++) {
            if (buf[i + j] != (MAGIC_WORD[j] & 0xFF)) {
                match = 0;
                break;
            }
        }
        if (match) return i;
    }
    return -1;
}

static int process_frame(const uint8_t *frame, int frame_len) {
    if (frame_len < (int)sizeof(MmwDemo_OutputMessageHeader)) {
        fprintf(stderr, "Frame too short for header\n");
        return -1;
    }

    const MmwDemo_OutputMessageHeader *header = (const MmwDemo_OutputMessageHeader *)frame;
    uint32_t num_tlvs = header->num_tlvs;
    uint32_t total_packet_len = header->total_packet_len;

    if (total_packet_len > READ_BUFFER_SIZE) {
        fprintf(stderr, "Invalid total packet length: %u\n", total_packet_len);
        return -1;
    }

    if (frame_len < (int)total_packet_len) {
        fprintf(stderr, "Frame incomplete (got %d, expected %u)\n", frame_len, total_packet_len);
        return -1;
    }

    int offset = sizeof(MmwDemo_OutputMessageHeader);
    int obj_idx = 0;

    for (uint32_t t = 0; t < num_tlvs; t++) {
        if (offset + (int)sizeof(MmwDemo_OutputMessageTLV) > (int)total_packet_len) {
            fprintf(stderr, "TLV header out of bounds\n");
            return -1;
        }

        const MmwDemo_OutputMessageTLV *tlv = (const MmwDemo_OutputMessageTLV *)(frame + offset);
        uint32_t tlv_type = tlv->type;
        uint32_t tlv_len = tlv->length;

        offset += sizeof(MmwDemo_OutputMessageTLV);

        if (offset + (int)tlv_len > (int)total_packet_len) {
            fprintf(stderr, "TLV payload out of bounds\n");
            return -1;
        }

        if (tlv_type == 1) {
            if (tlv_len < (uint32_t)sizeof(MmwDemo_DetectedObject)) {
                fprintf(stderr, "Object TLV too small\n");
                return -1;
            }
            int num_objects = tlv_len / sizeof(MmwDemo_DetectedObject);
            if (num_objects > MAX_OBJECTS) num_objects = MAX_OBJECTS;

            for (int i = 0; i < num_objects; i++) {
                const MmwDemo_DetectedObject *obj = (const MmwDemo_DetectedObject *)(frame + offset + i * sizeof(MmwDemo_DetectedObject));
                float range = (float)obj->range_idx * 0.043f;
                float velocity = (float)obj->doppler_idx * 0.043f;
                time_t now = time(NULL);
                fprintf(csv_file, "%ld,%d,%.3f,%.3f\n", (long)now, obj_idx, range, velocity);
                obj_idx++;
            }
        }

        offset += tlv_len;
    }

    fflush(csv_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        cleanup();
        return 1;
    }

    uint8_t read_buf[READ_BUFFER_SIZE];
    uint8_t frame_buf[READ_BUFFER_SIZE];
    int frame_len = 0;

    fprintf(stderr, "Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int bytes_read = serRead(uart_handle, (char *)read_buf, sizeof(read_buf));
        if (bytes_read < 0) {
            fprintf(stderr, "UART read error: %d\n", bytes_read);
            gpioDelay(100000);
            continue;
        }

        if (bytes_read == 0) {
            gpioDelay(1000);
            continue;
        }

        for (int i = 0; i < bytes_read; i++) {
            if (frame_len >= READ_BUFFER_SIZE) {
                fprintf(stderr, "Frame buffer overflow, resyncing\n");
                frame_len = 0;
            }
            frame_buf[frame_len++] = read_buf[i];

            if (frame_len >= MAGIC_WORD_SIZE) {
                int magic_pos = find_magic_word(frame_buf, frame_len);
                if (magic_pos < 0) {
                    frame_len = 0;
                } else if (magic_pos > 0) {
                    memmove(frame_buf, frame_buf + magic_pos, frame_len - magic_pos);
                    frame_len -= magic_pos;
                }

                if (frame_len >= (int)sizeof(MmwDemo_OutputMessageHeader)) {
                    const MmwDemo_OutputMessageHeader *header = (const MmwDemo_OutputMessageHeader *)frame_buf;
                    uint32_t total_packet_len = header->total_packet_len;

                    if (total_packet_len > READ_BUFFER_SIZE) {
                        fprintf(stderr, "Invalid total packet length: %u, resyncing\n", total_packet_len);
                        frame_len = 0;
                    } else if (frame_len >= (int)total_packet_len) {
                        process_frame(frame_buf, total_packet_len);
                        int remaining = frame_len - total_packet_len;
                        if (remaining > 0) {
                            memmove(frame_buf, frame_buf + total_packet_len, remaining);
                        }
                        frame_len = remaining;
                    }
                }
            }
        }
    }

    fprintf(stderr, "Radar data acquisition stopped.\n");
    cleanup();
    return 0;
}

