static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_uart_line(int fd, char *buf, size_t buf_size) {
    size_t total = 0;
    while (total < buf_size - 1) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int ret = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            fprintf(stderr, "Timeout waiting for UART data\n");
            return -1;
        }

        ssize_t n = read(fd, buf + total, buf_size - 1 - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }

        total += (size_t)n;

        for (ssize_t i = 0; i < n; i++) {
            if (buf[total - 1] == '\n') {
                buf[total] = '\0';
                return (int)total;
            }
        }
    }

    fprintf(stderr, "Line buffer overflow\n");
    return -1;
}

static int parse_range_data(const char *line, double *timestamp, double *range) {
    if (sscanf(line, "%lf,%lf", timestamp, range) != 2) {
