#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define SERIAL_PORT       "/dev/ttyAMA0"
#define BAUD_RATE         115200
#define LOOP_DELAY_US     100000  /* 100 ms = 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int initialize_serial(void)
{
    g_serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_fd < 0) {
        fprintf(stderr, "Error: failed to open serial port %s: %s\n",
                SERIAL_PORT, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_serial_fd >= 0) {
        serClose(g_serial_fd);
        g_serial_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_serial() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor\n");
    printf("Left=GPIO%d, Middle=GPIO%d, Right=GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Serial port: %s @ %d baud\n", SERIAL_PORT, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int middle = gpioRead(MIDDLE_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Warning: gpioRead failed (left=%d, middle=%d, right=%d).\n",
                    left, middle, right);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        } else {
            snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
        }

        printf("[%s] Left: %d, Middle: %d, Right: %d\n",
               timestamp, left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            const char *emergency_stop = "EMERGENCY STOP!\n";
            ssize_t written = serWrite(g_serial_fd, emergency_stop, strlen(emergency_stop));
            if (written < 0) {
                fprintf(stderr, "Warning: serWrite failed: %s\n", strerror(errno));
            } else {
                printf("EMERGENCY STOP! (sent %zd bytes)\n", written);
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

